  },
  CollectionHall_100442_Desc = {
    Text = "<Title:紹介>\n人間の裕福な商人の家庭に生まれたが、体内には食屍鬼の血が流れている。半人半食屍鬼の血脈は彼に特別な天賦を与え、常人が見ることのできない世界を見ることができる。あの世界は狂気に満ち、荒唐無稽で、鮮やかな色彩に彼は引き込まれていく。\nほとんどためらうことなく、ピックマンは彼が見たすべてを筆で記録することを選んだ。彼はその中に没入し、日々の描写の中で熟練した画技を身につけていった。\n主流の美的感覚はピックマンを完全に排除し、彼の狂気の理論を受け入れる者はいなかった。ピックマンはしばしばそれに悲しみを感じたが、決して諦めたことはなかった。\n最終的に、ピックマンは融蝕を抱き、食屍鬼の血脈を完全に覚醒させた。彼は人間の世界を離れ、食屍鬼の王城へと向かった。いつの日か、彼はリアルな世界に存在する幻想的で狂気的な景色を一つ一つ世の中に示すつもりである。"
  },
  CollectionHall_100442_LockTip = {
    Text = "「ピックマン」を召喚すると解放"
  },
  CollectionHall_100442_Title = {
    Text = "ピックマン"
  },
  CollectionHall_100458_Desc = {
    Text = "悩みはしばし置いて、疲れを遠くへ追いやろう。\n暖かな焚き火のそばで、少しだけ休もうじゃないか。"
  },
  CollectionHall_100458_LockTip = {
