  },
  CollectionHall_100458_Title = {
    Text = "焚き火のひととき"
  },
  CollectionHall_100459_Desc = {
    Text = "燃えろ、燃えろ、お前に属するすべてを、残らず燃やし尽くせ。\nそして、あの果てなき烈火の中で、お前と世界の葬礼を始めるのだ！"
  },
  CollectionHall_100459_LockTip = {
    Text = "意識潜行「不朽の白夜」をクリア"
  },
  CollectionHall_100459_Title = {
    Text = "烈火の葬礼"
  },
  CollectionHall_100460_Desc = {
    Text = "「言ったでしょう、どんな方法であれ、みんなを家に連れて帰ると。」\n「私に属するすべてを燃やし尽くして、そして――」\n「この群星より生まれし業火で、この偽りの、穢れた、混沌の世界を焼き尽くす！」\n「ケティグラの名において宣言する！」\n「夜は明ける！」"
  },
  CollectionHall_100460_LockTip = {
    Text = "意識潜行「不朽の白夜」をクリア"
  },
  CollectionHall_100460_Title = {
    Text = "すべてを焼く払暁"
  },
  CollectionHall_100461_Desc = {
    Text = "狂気じみた死の姿は万華鏡のように渦を巻き、病と屍の甘く鉄臭い香りが、最高の香料となる。\nあなたたちは無数の死者を隔てて、遠くから杯を掲げる——\nもし死が運命なら、喜びをもってこの舞踏会に向かい、最後のステップで共に地獄の門に落ちよう。"
  },
  CollectionHall_100461_LockTip = {
    Text = "意識潜行「燃える饗宴」高難度を完了する"
  },
  CollectionHall_100461_Title = {
    Text = "赤ワイン、花々と華麗なる死"
  },
  CollectionHall_100462_Desc = {
    Text = "はるか昔、彼女は宇宙の独裁者であり、見えるすべてが彼女の支配下にあった。\nそして、はるか未来、彼女の瞳に映るのは、ただ果てしない塵埃のみ。\n彼女が治める世界には、もはや荒廃と孤独だけしか残されていなかった。"
  },
  CollectionHall_100462_LockTip = {
    Text = "意識潜行「燃える饗宴」を完了する"
  },
  CollectionHall_100462_Title = {
    Text = "荒廃を司る女王"
  },
  CollectionHall_100463_Desc = {
    Text = "彼女は傲慢で、残忍で、気まぐれ。\n同時に、寛大で、博識で、英知に満ちている。\n彼女は淫らな暴君であり、子羊の守護者でもあり、愛を与え、死をも与える。\nこの地のすべての生き物は彼女の足元にひれ伏し、彼女の名を尊敬の念を込めて呼ばなければならない。\n女王の舞踏会で思う存分酔いしれ、そして彼女と共に、永遠の黒き炎へと沈みゆくのだ。"
  },
  CollectionHall_100463_LockTip = {
    Text = "意識潜行「燃える饗宴」を完了する"
  },
  CollectionHall_100463_Title = {
    Text = "死への饗宴"
  },
  CollectionHall_100464_Desc = {
    Text = "死の直前に、願いを叶えられるのなら、踊ろう。\n甘美なワインを飲み、香ばしい肉料理を食べ、狂乱の音楽に合わせて心ゆくまで舞い踊ろう。\nたとえこの世界が滅びゆくとしても、この瞳に映る最後の景色だけは、陶酔の金色に輝いていますように。"
  },
  CollectionHall_100464_LockTip = {
    Text = "意識潜行「燃える饗宴」高難度を完了する"
  },
  CollectionHall_100464_Title = {
    Text = "疫病の仮面"
  },
  CollectionHall_100465_Desc = {
    Text = "彼女はいつも湖の中に、かつての栄華の面影を見ていた。\n風化した記憶は偽りの夢のようで、夢の中で彼女は果てしない廃墟に座り、かつて自分のものであったすべてが幻のように滲み消えていくのを見つめていた。\nその夢さえも忘れ去られようとするとき、笛を吹く使者が霧を通り抜けて現れ、彼女を亡者たちの帰るべき道へと導く。"
  },
  CollectionHall_100465_LockTip = {
    Text = "意識潜行「燃える饗宴」を完了する"
  },
  CollectionHall_100465_Title = {
    Text = "湖に映る影"
  },
  CollectionHall_100466_Desc = {
    Text = "群星の間で永遠に消えぬ存在が再び目を開き、不朽の力をこの濁り、穢れ、されど限りなく蒼い星へと投射する。\nあの四十億年前、天を覆い尽くす太陽が降臨した時と、寸分違わぬ姿で。"
  },
