  CollectionHall_117961_Desc = {
    Text = "食べて、エヴァー！見て、エヴァー！\n狂気と真実の間に、色彩と芸術で架けられた橋！\nここにいるのは僕たち二人だけ、真実を見届けられるのは僕たちだけだ！"
