  CollectionHall_117962_Desc = {
    Text = "詩の1節を書くたびに、花弁が1枚生まれるのだろうかと、彼女は思った。\n彼女は命を注いで言葉を育て、最後の詩篇が完成したとき、彼女たちはかつての花園に帰れるのだ。"
