  },
  CollectionHall_117963_Desc = {
    Text = "彼はこちら側を捨て、あちら側へ往くと決めた。\n彼に別れを告げよ、だがあの方を忘れるな。\nあの方はお前に思い出させる、あの方はお前を見つめている――あの狂える愚者、天才の画師、そして夜空に高く懸かる月。"
