  CollectionHall_117963_Title = {
    Text = "彼方へ往く"
  },
  CollectionHall_117964_Desc = {
    Text = "声を張り上げよ、舞い踊れ。\n蜜と乳が炎の明かりのそばで溶け合うとき。\n終焉は、もはや目前に迫っている。\n足で絡み、腕で抱き合い、首を傾けて口づけを——\n繁殖せよ！繁殖せよ！\n母樹の庇護のもと、やがて種子の子孫は、必ずや慈悲を授かるだろう。"
