  CollectionHall_117976_Desc = {
    Text = "陽光が温室のガラスを通してオルラの顔に差し込む。彼女はその光をくぐり抜け、まだ眠気の残るオルラのもとへと歩み寄る。\n彼女は、彼女を目覚めさせるたびに、いつも薔薇を背中に隠していた。"
