    Text = "ロンディニウムの夏"
  },
  CollectionHall_117988_Desc = {
    Text = "君は音楽も謎解きも得意ではない。\nしかし彼は平然と、優雅に君を交響の中へと織り込み、神秘的にして非礼な謎を突きつけた。"
