  CollectionHall_117988_Title = {
    Text = "指揮者の謎かけ"
  },
  CollectionHall_117989_Desc = {
    Text = "哀れで、傲慢で、身の程知らずの狼。\n彼は他の客と共に休憩室に投げ込まれ、束の間の安寧に包まれた賭場に座っていた。\nいつもの幸運を失い、彼は1万スタール以上を失った。"
