  CollectionHall_117989_Title = {
    Text = "悪い手札"
  },
  CollectionHall_117990_Desc = {
    Text = "同じシルクハット、同じ薔薇、同じ笑い声。\n幕は上がり、観客は席に着いた。\nさあ、さあ、探しに来て。\n犯人は黒い霧の中から落ちてきた。\nさあ、誰だ？"
