  },
  CollectionHall_117990_Title = {Text = "小さなN"},
  CollectionHall_117991_Desc = {
    Text = "良い日常は悪夢から始まり、墓地で終わる。\nああ、これが人生。\n甘美な人生。"
  },
  CollectionHall_117991_LockTip = {
