  CollectionHall_117992_Title = {
    Text = "2人の春の日"
  },
  CollectionHall_117993_Desc = {
    Text = "突然の訪問、気遣いの訪問、幸せな訪問。\n似ている友人、似ていない友人。\nああ、友よ、友よ、誰もが友を必要としている。何でもてなそうか、我が友よ？"
