  },
  CollectionHall_117994_Desc = {
    Text = "棺から這い出た賭博の権化、雪の夜に執拗に追いすがる過去。\n勝負、またもう一勝負、狼の毛皮と幸運が、やがて陽光まぶしい来週の月曜日を連れてくる。"
  },
  CollectionHall_117994_LockTip = {
