  CollectionHall_117994_Title = {
    Text = "狼の来週の月曜日"
  },
  CollectionHall_117995_Desc = {
    Text = "アランの民は砂漠を渡り歩いた。\nここで生まれ、ここで育ち、ここで繁栄する運命を与えられ、そしてまた、ここで滅びる運命を背負っていた。"
