  CollectionHall_117996_Title = {
    Text = "聖河へ還す"
  },
  CollectionHall_117997_Desc = {
    Text = "花園の残骸と過去の灰がこの小さな土地に降り積もる。\nそれらは悲しい記憶の中で空に舞い上がり、狂おしい野心の中で煙のように消えていく。"
