  CollectionHall_118000_Title = {
    Text = "狂画奇譚"
  },
  CollectionHall_118001_Desc = {
    Text = "彼らは血縁、兄弟、恋人、親友を抱きしめ、自己を捧げ、黒く甘美な再生に溶け込む。\n彼らの骨は母なる樹に帰り、彼らの肉は聖なる川に流れ込む。"
