  },
  CollectionHall_120466_Title = {
    Text = "無声の電報"
  },
  CollectionHall_121154_Title = {Text = "楽園"},
  CollectionHall_121341_Desc = {
    Text = "<Title:概要>\n「聖婴」の孕育を受け入れた「王女」は、現在では蹈海者教内で重要な「神母」となっています。\n彼女もまた自由を求める貴婦人であり、ミサゴが記録したマーフィーのようにソナニール号の逃亡の旅に踏み出したことがあります。\nしかし、守秘者の存在しない世界では、運命が幼き白鳥の高貴な首を折ってしまいました。\n歪んだ血脈は抵抗することなく彼女を絡め取ります。躯体が死ぬことさえも逃れられません。彼女は無理に表面を保ち、「私は尊貴な神母です」と何度も言い続けることは、自分自身への暗示であり説得に過ぎません。\n従うしかない、ただ従う。虚構の神託に従い、荒唐無稽な運命に従って、無限の苦みの中からようやく幻想の甘さを思い出すしかないのです。"
  },
  CollectionHall_121341_LockTip = {
    Text = "「誕妄・マーフィー」を召喚すると解放"
  },
  CollectionHall_121341_Title = {
    Text = "誕妄・マーフィー"
  },
  CollectionHall_121381_Desc = {
    Text = "あなたは千個のドングリと引き換えに、異界から来た物語を手に入れた。\n英雄と魔神、見守りと信念の物語。\n無念と名残惜しさ、旧友と新たな友の物語。\nかつて訪れたことのある物語。"
  },
  CollectionHall_121381_LockTip = {
    Text = "多次元接続「逆転ラウンド」を完了する"
  },
  CollectionHall_121381_Title = {
    Text = "万象旅館の残響"
  },
  CollectionHall_121382_Desc = {
    Text = "遥か遠い未来、彼と彼はついに語り継がれる吟遊詩を持つことになった。\n死から蘇る救済について、一つの体に宿る双子の魂について。"
  },
  CollectionHall_121382_LockTip = {
    Text = "異夢視界「天の彼方·下」をクリア"
  },
  CollectionHall_121382_Title = {
    Text = "翼なき鳥の詩"
  },
  CollectionHall_121383_Desc = {
    Text = "少年は、束の間のすべてのために、請求された代償を払った。\n今は、静かな権力だけが彼と共にある。\n王は眠りにつく。\n夢の中で、世界の終わりを迎えながら。"
  },
  CollectionHall_121383_LockTip = {
    Text = "意識潜行「戴冠の日」を完了する"
  },
  CollectionHall_121383_Title = {
    Text = "果てしない孤独の王国"
  },
  CollectionHall_121384_Desc = {
    Text = "彼女たちはあなたを囲み、彼女たちはあなたを敬い慕い、彼女たちはあなたに寄り添う。\n彼女たちは創世神へ帆を揚げる。"
  },
  CollectionHall_121384_LockTip = {
    Text = "調査行動9–11をクリアして解放"
  },
  CollectionHall_121384_Title = {
    Text = "創世神へ帆を揚げて"
  },
  CollectionHall_121385_Desc = {
    Text = "それは挫折の中から蘇った翼、それは犠牲と引き換えに自由を得た翼。\n運命の予言はすでに成就した。彼は悔恨の中で誓いを立てた、血の債は血で償うと。"
  },
  CollectionHall_121385_LockTip = {
    Text = "異夢視界「天の彼方·下」をクリア"
  },
  CollectionHall_121385_Title = {
    Text = "嵐が起こる時"
  },
  CollectionHall_121386_Desc = {
    Text = "荒唐と混沌の夢境が始まりし時より、彼の者は宿命と対峙する定めにあった。\nだが彼の者はあまりに多くを経験し、あまりに多くを定義してきた。\n彼の者は人類が保てる最大の理性をもって、己の起源たる至高の神を見据えると決意した。"
  },
  CollectionHall_121386_LockTip = {
    Text = "調査行動9–11をクリアして解放"
  },
  CollectionHall_121386_Title = {
    Text = "原初の宿命の戦い"
  },
  CollectionHall_121387_Desc = {
    Text = "得て、失い、断ち切り、犠牲にする。\n英雄はすべてのすべてを代償として捧げ、秘宝を守護する権能こそが神の報いである。"
  },
  CollectionHall_121387_LockTip = {
    Text = "調査行動9–13をクリアして解放"
  },
  CollectionHall_121387_Title = {
    Text = "無目の瞳"
  },
  CollectionHall_121388_Desc = {
    Text = "彼は王冠を自らにかぶせ、枷を自らにかけた。\nそれは束の間の、虚ろな温もり。\nそれは滅びることを宿命づけられた、過ぎ去りし日の栄光。"
  },
  CollectionHall_121388_LockTip = {
    Text = "意識潜行「戴冠の日」を完了する"
  },
  CollectionHall_121388_Title = {
    Text = "幼き王の孤独な道"
  },
  CollectionHall_121389_Desc = {
    Text = "局面は不利だが、あなたの口元にはすでに微かな笑みが浮かんでいる。\n「私のターン、ドロー！」\n万象旅館でもミサゴでも、\nサポートの火力を甘く見ると痛い目に遭うよ！イグナティス！"
  },
  CollectionHall_121389_LockTip = {
    Text = "多次元接続「逆転ラウンド」を完了する"
  },
  CollectionHall_121389_Title = {
    Text = "私の逆転の瞬間！"
  },
  CollectionHall_121390_Desc = {
    Text = "完全なる伝説には、敵が友となる物語が欠かせない。"
  },
  CollectionHall_121390_LockTip = {
    Text = "調査行動·困難9–10をクリアして解放"
  },
  CollectionHall_121390_Title = {
    Text = "敵、そして友"
  },
  CollectionHall_121391_Desc = {
    Text = "これからは、守秘者の称号を持ち、無数のミサゴの教師や学生と共にいることになる。"
  },
  CollectionHall_121391_LockTip = {
    Text = "調査行動·困難9–11をクリアして解放"
  },
  CollectionHall_121391_Title = {Text = "K–0617"},
  CollectionHall_121392_Desc = {
    Text = "我々は悠久の中の一瞬、激流の中の砂粒かもしれない。\nしかし常世こそが我々にとって尊い永遠である。なぜなら世界がどれほど狂い乱れようとも――\n人類の尊厳は、理性の輝きの上に築かれるのだから。"
  },
  CollectionHall_121392_LockTip = {
    Text = "調査行動9–11をクリアして解放"
  },
  CollectionHall_121392_Title = {
    Text = "常世の頌歌"
  },
  CollectionHall_121393_Desc = {
    Text = "勇者たちは童話の中へ飛び込んだ。どの童話も同じ——動物、悪魔、妖精、そして未知の彼方。\n束の間の自由と偽りの憧憬を越えた先、童話の果てには、彼に押し付けられた偽りの心臓が隠されていた。"
  },
  CollectionHall_121393_LockTip = {
    Text = "異夢視界「天の彼方·下」をクリア"
  },
  CollectionHall_121393_Title = {
    Text = "星河に飛び込んで"
  },
  CollectionHall_121394_Desc = {
    Text = "ここは異世界の時空の裂け目に位置する万象旅館。\n異なる宇宙を繋ぐ転送門が広大な星の光を放ち、あなたの到来を歓迎している。\nちょっと待って…………これは守秘者の仕事と何の関係があるの？"
  },
  CollectionHall_121394_LockTip = {
    Text = "多次元接続「逆転ラウンド」を完了する"
  },
  CollectionHall_121394_Title = {
    Text = "万象旅館へようこそ！"
  },
  CollectionHall_121395_Desc = {
    Text = "ミサゴの刃がこの対局の勝利をもたらす。\nあなたとパートナーの絆は決して壊れない。\nたとえいつか異なる宇宙にいようとも、それだけは変わらない。"
  },
  CollectionHall_121395_LockTip = {
    Text = "多次元接続「逆転ラウンド」を完了する"
  },
  CollectionHall_121395_Title = {
    Text = "ミサゴの刃！"
  },
  CollectionHall_121396_Desc = {
    Text = "「デイリー訓練やってない？まずは万象カードを一局やろうよ！」\n「融災禁域クリアしてない？まずは万象カードを一局やろうよ！」\n「これは位相対局であって、万象カードじゃない！千個のドングリ、必ず集めてみせるから！」"
  },
  CollectionHall_121396_LockTip = {
    Text = "多次元接続「逆転ラウンド」を完了する"
  },
  CollectionHall_121396_Title = {
    Text = "一緒に万象カードで遊ぼう！"
  },
  CollectionHall_121397_Desc = {
    Text = "我が名を呼べ、忘れ去られた黎明の前に。"
  },
  CollectionHall_121397_LockTip = {
    Text = "調査行動·困難9–11をクリアして解放"
  },
  CollectionHall_121397_Title = {
    Text = "忘却より来たる@2"
  },
  CollectionHall_121398_Desc = {
    Text = "「さあ、私と契約してカードマスターになりましょう！」\nこの異世界から来た竜族の美少女が、熱烈かつ意味不明な誘いをあなたに投げかけた。\nこの位相空間の小さなアクシデントを早く元に戻すため、あなたに選択肢はない。"
  },
  CollectionHall_121398_LockTip = {
    Text = "多次元接続「逆転ラウンド」を完了する"
  },
  CollectionHall_121398_Title = {
    Text = "女将、イグナティス！"
  },
  CollectionHall_121399_Desc = {
    Text = "後から来る者は重い贈り物の下で、このような脚注を見つけるだろう。\n英雄になることを避けた唯一の者が英雄となり、友を何よりも大切にした子どもには、ただひとりの友だけが残された。"
  },
  CollectionHall_121399_LockTip = {
    Text = "意識潜行「戴冠の日」を完了する"
  },
  CollectionHall_121399_Title = {
    Text = "余は独りでゆく"
  },
  CollectionHall_121400_Desc = {
    Text = "主から離れ、主と対峙し、主に背く。\nあなたの物語は誰にも知られず、あなたの記憶は永遠に残る。"
  },
  CollectionHall_121400_LockTip = {
    Text = "調査行動9–13をクリアして解放"
  },
  CollectionHall_121400_Title = {
    Text = "創世の痴愚なる主"
  },
  CollectionHall_121401_Desc = {
    Text = "すべてはもはや意味を持たない、だからこそあなたはここに立っている。\nかつてのすべての過去こそが、あなたが定義した全ての意味であり、だからあなたはここに立った。"
  },
  CollectionHall_121401_LockTip = {
    Text = "調査行動9–13をクリアして解放"
  },
  CollectionHall_121401_Title = {
    Text = "実存主義"
  },
  CollectionHall_121402_Desc = {
    Text = "神々へと続く小径、神々から遠ざかる小径。\nすべてが別れを迎え、すべてが終わりを迎え、すべてが始まりを迎える。\n扉の前の影はここから長い待機を始めた──銀の鍵があなたの帰路を導くのを待ちながら。"
  },
  CollectionHall_121402_LockTip = {
    Text = "調査行動9–13をクリアして解放"
  },
  CollectionHall_121402_Title = {
    Text = "神々へと続く小径"
  },
  CollectionHall_121403_Desc = {
    Text = "神々の可能性の線は、分離し、収束し、崩散する。\n唯一の救世主を迎えるその時まで、唯一の終局にたどり着くその時まで。"
  },
  CollectionHall_121403_LockTip = {
    Text = "調査行動·困難9–10をクリアして解放"
  },
  CollectionHall_121403_Title = {
    Text = "唯一の終局"
  },
  CollectionHall_121404_Desc = {
    Text = "幼い王はこの取引を受け入れた。\n彼は言った、余の国は、必ずや安らかであろう。"
  },
  CollectionHall_121404_LockTip = {
    Text = "意識潜行「戴冠の日」を完了する"
  },
  CollectionHall_121404_Title = {Text = "戴冠式"},
  CollectionHall_121405_Desc = {
    Text = "この砕けた時空の裂け目には、かつて伝説の万象旅館があった。\nかつて異なる宇宙を繋ぐ転送門があり、かつて広大な星の光が瞬き、かつてすべてのカードマスターの到来を歓迎していた。\nそしてあなたは、そのすべてが存在した証である。"
  },
  CollectionHall_121405_LockTip = {
    Text = "多次元接続「逆転ラウンド」を完了する"
  },
  CollectionHall_121405_Title = {
    Text = "さようなら、カードマスター！"
  },
  CollectionHall_121406_Desc = {
    Text = "主があなたを見た。あなたは主の眼を貫いた。"
  },
  CollectionHall_121406_LockTip = {
    Text = "調査行動9–13をクリアして解放"
  },
  CollectionHall_121406_Title = {
    Text = "終焉の凝視"
  },
  CollectionHall_121407_Desc = {
    Text = "戦士、復讐者、奴隷、主人、商人。\n同じ立場？異なる立場？同じ立場。"
  },
  CollectionHall_121407_LockTip = {
    Text = "調査行動9–11をクリアして解放"
  },
  CollectionHall_121407_Title = {
    Text = "多重性の戦歌"
  },
  CollectionHall_121408_Desc = {
    Text = "分かっている、何か偉大なもののために戦っているわけではないと。\nサボるため、宿題のため、スイーツのため、友のため、暖炉のため、無為に過ごす時間のため。\nあなたはただ平凡な、日常のために死す者だ。"
  },
  CollectionHall_121408_LockTip = {
    Text = "調査行動·困難9–11をクリアして解放"
  },
  CollectionHall_121408_Title = {
    Text = "日常のために死す者"
  },
  CollectionHall_121409_Desc = {
    Text = "動物、すべての高等動物は、社会行動に支配されることを避けられない。\nしかし彼女は自ら死に赴き、望み通りに真相を解き明かした。\n一人の狂気に満ちた、絶世の天才──彼女は自らの手で滅びを招くことを選び、希望という名の砒素を飲まずに済むよう、衆生に恩寵を与えた。"
  },
  CollectionHall_121409_LockTip = {
    Text = "調査行動9–13をクリアして解放"
  },
  CollectionHall_121409_Title = {
    Text = "社会行動の解構"
  },
  CollectionHall_121410_Desc = {
    Text = "神は高天から絶え間なく苦い水を送り続け、集まり、集まる。\nやがてそれは、我らが血肉融け合う前に、必ず遡らねばならぬ河となって横たわった。"
  },
  CollectionHall_121410_LockTip = {
    Text = "異夢視界「天の彼方·下」をクリア"
  },
  CollectionHall_121410_Title = {
    Text = "苦き河流"
  },
  CollectionHall_121411_Desc = {
    Text = "彼の者たちは再会を期して別れた。\nこれは至愛なる者であるがゆえに、これは運命に定められたものではない至愛なる者の死であるがゆえに。"
  },
  CollectionHall_121411_LockTip = {
    Text = "調査行動9–11をクリアして解放"
  },
  CollectionHall_121411_Title = {
    Text = "一人の至愛なる者の死"
  },
  CollectionHall_121412_Desc = {
    Text = "少し休んで、一息つこう。\n課題が世界の終末であっても、三人もの超重量級の導師に同時に向き合える機会など、誰にでもあるわけではないのだから。"
  },
  CollectionHall_121412_LockTip = {
    Text = "調査行動9–13をクリアして解放"
  },
  CollectionHall_121412_Title = {Text = "幕間"},
  CollectionHall_121413_Desc = {
    Text = "千個のドングリの物語は、最初の一個から始まる。\n位相対局であなたがカードを出すたびに、\nイグナティスの瞳に不思議な金色の記憶の光が過ぎる。"
  },
  CollectionHall_121413_LockTip = {
    Text = "多次元接続「逆転ラウンド」を完了する"
  },
  CollectionHall_121413_Title = {
    Text = "おかわり無限！"
  },
  CollectionHall_121414_Desc = {
    Text = "狂気、滅びの前奏——これは秩序ある世界の根底にある論理。\n彼の者は滅びるのか、世界は滅びるのか？\n誰も知らない。\nだが創世神の前で、狂気は彼の者と世界の新生を育んでいる。"
  },
  CollectionHall_121414_LockTip = {
    Text = "調査行動9–11をクリアして解放"
  },
  CollectionHall_121414_Title = {
    Text = "狂気のフーガ"
  },
  CollectionHall_121415_Desc = {
    Text = "この世で最も理不尽なものとは何か？\n神に目的はなく、恩讐とは無縁で、善悪を弁じない。\n神はただ目覚めた時、夢の中で生じたすべてを塵芥と化したいだけなのだ。"
  },
  CollectionHall_121415_LockTip = {
    Text = "調査行動9–13をクリアして解放"
  },
  CollectionHall_121415_Title = {Text = "塵芥"},
  CollectionHall_121416_Desc = {
    Text = "唯一無二の欠片として、神になるのは簡単だ。\nでは、その代償は何か？"
  },
  CollectionHall_121416_LockTip = {
    Text = "調査行動9–13をクリアして解放"
  },
  CollectionHall_121416_Title = {
    Text = "神になる"
  },
  CollectionHall_121417_Desc = {
    Text = "長い人類文明の中で、我々は多くのものを築き上げてきた。\n物質について、精神について、生存、愛、硝煙と紛争について。\nしかしそれらは、造物主の夢の中の取るに足らないノイズに過ぎず、見破られることのない虚構集に過ぎない。"
  },
  CollectionHall_121417_LockTip = {
    Text = "調査行動9–13をクリアして解放"
  },
  CollectionHall_121417_Title = {Text = "虚構集"},
  CollectionHall_121418_Desc = {
    Text = "ミサゴ史上最も臆病な秘密の守り手は、巨大な幸福の中で死んだ。"
  },
  CollectionHall_121418_LockTip = {
    Text = "調査行動·困難9–11をクリアして解放"
  },
  CollectionHall_121418_Title = {
    Text = "逃げる決心をした英雄"
  },
  CollectionHall_121898_LockTip = {
    Text = "調査星辰篇4-0クリアで解放"
  },
  CollectionHall_121898_Title = {
    Text = "果てなき虚妄の巡礼"
  },
  CollectionHall_121901_LockTip = {
    Text = "調査行動星辰篇4–16をクリアして解放"
  },
  CollectionHall_121901_Title = {
    Text = "神誕七日"
  },
  CollectionHall_122565_LockTip = {
    Text = "期間限定キャラクターイベント「霧境の燔祭：迷える自我」の任意のステージをクリアすると開放"
  },
  CollectionHall_122565_Title = {
    Text = "霧境の燔祭：迷える自我"
  },
  CollectionHall_123756_Title = {
    Text = "銀と血の洗礼"
  },
  CollectionHall_124124_Desc = {
    Text = "あなたは多くの存在と二度目に会う可能性がある。たとえそれが存在すべきではない嬰児であろうと、過ちから生まれた神霊であろうと。"
  },
  CollectionHall_124124_LockTip = {
    Text = "調査行動 星辰篇4-16クリアで解放"
  },
  CollectionHall_124124_Title = {
    Text = "二度目の邂逅"
  },
  CollectionHall_124125_Desc = {
    Text = "ああ…………もっと悪い結末があったとは。"
  },
  CollectionHall_124125_LockTip = {
    Text = "調査行動 星辰篇4-16クリアで解放"
  },
  CollectionHall_124125_Title = {
    Text = "彼女と彼と神の死"
  },
  CollectionHall_124126_Desc = {
    Text = "あまりにも眩しい時に別れた同行者を、どう描写すればいい？\n彼の眩しさを描写するな。彼の腕を描写しろ。彼の身体から漂うシダーウッドの香りを描写しろ。"
  },
  CollectionHall_124126_LockTip = {
    Text = "調査行動 星辰篇4-16クリアで解放"
  },
  CollectionHall_124126_Title = {
    Text = "シダーウッド"
  },
  CollectionHall_124127_Desc = {
    Text = "旅路の果てに、誰があなたを待っているか知っている。\nだがまだ逃れられない、あなたは高空から再び墜ちていく。"
  },
  CollectionHall_124127_LockTip = {
    Text = "調査行動·困難 星辰篇4–10をクリアして解放"
  },
  CollectionHall_124127_Title = {Text = "墜落"},
  CollectionHall_124128_Desc = {
    Text = "子供は母のものではない、あの方はすでに決意した、全員をここに留めると。\nあの方の永遠に続く甘い楽園に。"
  },
  CollectionHall_124128_LockTip = {
    Text = "調査行動·困難 星辰篇4–10をクリアして解放"
  },
  CollectionHall_124128_Title = {
    Text = "甘い楽園"
  },
  CollectionHall_124129_Desc = {
    Text = "あなたは彼女を救うのに間に合わなかった。この彼女は逃げ出せなかった。\n彼女は貪り食われ、彼女は孤立無援で、彼女は偽りの臍帯に繋がれた。"
  },
  CollectionHall_124129_LockTip = {
    Text = "調査行動 星辰篇4-16クリアで解放"
  },
  CollectionHall_124129_Title = {
    Text = "偽りの臍帯"
  },
  CollectionHall_124130_Desc = {
    Text = "3.14159@2、3.141592@3、3.14159265@4…………\n雪原に終わりなき円、残酷な、永遠に終わることのない円周率。"
  },
  CollectionHall_124130_LockTip = {
    Text = "調査行動·困難 星辰篇4–10をクリアして解放"
  },
  CollectionHall_124131_Desc = {
    Text = "あなたはまた少し遅れた。立ち止まるな、もっと速く、もっと速く。\n次の結末へ急げ。"
  },
  CollectionHall_124131_LockTip = {
    Text = "調査行動 星辰篇4-16クリアで解放"
  },
  CollectionHall_124131_Title = {
    Text = "ある一つの結末"
  },
  CollectionHall_124132_Desc = {
    Text = "抱きしめて、私の宝物、私の…………父よ、私の運命よ。"
  },
  CollectionHall_124132_LockTip = {
    Text = "調査行動·困難 星辰篇4–10をクリアして解放"
  },
  CollectionHall_124132_Title = {
    Text = "娘の暗き子宮の中で"
  },
  CollectionHall_124133_Desc = {
    Text = "空がもうすぐ明けようとしている、昨日に別れを告げよう。\n昨日の苦痛、不条理、迷いに別れを告げ、\nより明るい、それぞれの道を行く明日を迎えよう。"
  },
  CollectionHall_124133_LockTip = {
    Text = "調査行動·困難 星辰篇4–10をクリアして解放"
  },
  CollectionHall_124133_Title = {
    Text = "夜明けに別れを"
  },
  CollectionHall_124134_Desc = {
    Text = "彼女と現実の間に、彼女と虚妄の間に、小さな盾が立てられた。\n小麦粉、卵、レモン、蜂蜜、砂糖、ベーキングパウダー、バターで焼き上げた盾。"
  },
  CollectionHall_124134_LockTip = {
    Text = "調査行動 星辰篇4-16クリアで解放"
  },
  CollectionHall_124134_Title = {
    Text = "生地の盾"
  },
  CollectionHall_124135_Desc = {
    Text = "この世界はいつも通り、子は母に頼り、子はまた母に嘘をつく。"
  },
  CollectionHall_124135_LockTip = {
    Text = "調査行動 星辰篇4-16クリアで解放"
  },
  CollectionHall_124135_Title = {
    Text = "虚言者の和弦"
  },
  CollectionHall_124136_Desc = {
    Text = "神が誕生して七日目。\nああ、神よ、神よ…………\nただの荒唐な過ちと虚偽の嘘に過ぎない。"
  },
  CollectionHall_124136_LockTip = {
    Text = "調査行動·困難 星辰篇4–10をクリアして解放"
  },
  CollectionHall_124136_Title = {
    Text = "腐りし神"
  },
  CollectionHall_124137_Desc = {
    Text = "眠れ、眠れ、海の嬰児よ。漆黒の月光がお前の暗き産着を照らすがいい。千年億年の沈んだ夢よ、永遠の虚妄に堕ちるがいい。"
  },
  CollectionHall_124137_LockTip = {
    Text = "調査行動 星辰篇4-16クリアで解放"
  },
  CollectionHall_124137_Title = {
    Text = "黒い月光"
  },
  CollectionHall_124138_Desc = {
    Text = "逃げろ、二匹の魚が水面に飛び込んだ。\nすべてを一時捨て去り、世界に隠れて互いに寄り添い逃亡しようとした。"
  },
  CollectionHall_124138_LockTip = {
    Text = "調査行動 星辰篇4-16クリアで解放"
  },
  CollectionHall_124138_Title = {
    Text = "秘密の逃亡"
  },
  CollectionHall_124139_Desc = {
    Text = "父が娘を産み落とし、娘が父を孕む。\n虚妄、倒錯、彼女が堕ちた繰り返される運命の輪。"
  },
  CollectionHall_124139_LockTip = {
    Text = "調査行動 星辰篇4-16クリアで解放"
  },
  CollectionHall_124139_Title = {
    Text = "虚妄倒錯の孕み"
  },
  CollectionHall_124140_Desc = {
    Text = "死と痛みより恐ろしいものは何か？\nあなたにとって、それは答えに窮する問いではない。"
  },
  CollectionHall_124140_LockTip = {
    Text = "調査行動 星辰篇4-16クリアで解放"
  },
  CollectionHall_124140_Title = {
    Text = "原点に戻る"
  },
  CollectionHall_124141_Desc = {
    Text = "彼女と彼女には彼女と彼女の敬虔があり、彼と彼には彼と彼の反逆と忠誠がある。\n彼女は途方もない嘘を編み上げ、彼と彼と彼女と彼女はその芝居に付き合った。\n家――皆が甘く、切り離せない家を作り上げた。"
  },
  CollectionHall_124141_LockTip = {
    Text = "調査行動 星辰篇4-16クリアで解放"
  },
  CollectionHall_124141_Title = {Text = "我が家"},
  CollectionHall_124142_Desc = {
    Text = "海の底から浮かび上がる神国の名を呼ぼう――レムリア、レムリア。"
  },
  CollectionHall_124142_LockTip = {
    Text = "調査行動 星辰篇4-16クリアで解放"
  },
  CollectionHall_124224_LockTip = {
    Text = "多次元接続「銀と血の洗礼」のいずれかのステージをクリアして解放"
  },
  CollectionHall_124224_Title = {
    Text = "茉夏の異世界調査記録"
  },
  CollectionHall_124395_Desc = {
    Text = "ロータンの生涯で最も苦しくも満ち足りたその日、彼女の手の中の刃は風のように目の前の神明へと襲いかかった。巨剣とリヴァイアサンの星のように壮大な身体は、その嵐の中でともに寸断された。\n鮮血の王冠を騎士団の奴隷であるあの方に贈った後、交換条件として、ロータンはただ一つの要求を提示した。新しい武器が必要だと。\nロータンへの恐怖と崇敬を胸に、新たな王はリヴァイアサンの骨を取り出すよう命じ、彼女のために比類なき一対の巨剣を鋳造させた。六国最高の鍛冶師たちが昼夜を問わず鍛え上げる中で、死した神明の骸骨は、神を弑した者の手の中で新生を果たした。\n記憶に値する相手がかつてこの不滅の双剣刃を証見したことがある。彼の巨槌はロータンの鎧と巨剣を砕き、亀裂は蜘蛛の巣のように剣身に広がり、乳白色の破片が血色の空気の中に飛び散った。まるで彼女がリヴァイアサンを刺し貫いたあの日のように。彼は弱点を見つけたと思った。しかし彼は、ロータンが再び自分の前に立ち上がるのを見た。砕けるはずだったその巨剣が彼の胸を貫き、彼の血肉を呼吸した。新たな骨が砕けた箇所から湧き出し、以前よりも鋭く、より密になった。断面は節を伸ばして成長し、荒野で狂い咲く茨のようだった。彼は明確に感じ取った。自分の生命が、白骨で鋳られた刃に咀嚼され、飲み込まれていくのを。\nかつて星天を捕食した巨獣は、死んでなどいなかった。契約が結ばれた瞬間から、祂は彼女と一つに融合していたのだ。ロータンが巨剣を手にするたびに、剣身の骨棘が花開き、その鋭い尖刺で相手に残酷な歓喜の叫びを放った。\nそれは彼女の武器。彼女はそれの両足。彼女とそれは、最初から最後まで同じ渇望に囚われていた。彼女たちは不死不滅、永遠に飽くことを知らない。\n止まることのない戦場こそが、彼女たちの唯一の帰る家だった。"
  },
  CollectionHall_124395_Title = {
    Text = "不滅の餓骨"
  },
  CollectionHall_124397_Desc = {
    Text = "何年も後、伏せて祈る深海教団を前に、誕妄・マーフィーは「母親」が彼女に青環タコの話をした遠い午後を思い出す。\n瓶の中の低級遺物は柔らかく眩しく、奇妙な幽青が水中に浮かび、幼い彼女を無意識に引き寄せた。\nしかしミリアムは彼女の頭を撫で、拒絶できない力で彼女を暗い船室の隅に向けさせた——そこには深海教団の死体が毒素に吸い尽くされた後の虚無の白さで倒れていた。\n「覚えておきなさい、海で最も静かで致命的なものは、往々にして最も美しいものなのよ。」\nガラス瓶の冷たい光が彼女の慈悲深い横顔を照らし、誕妄・マーフィーは美しさに包まれた恐怖を感じた。\n\n年月は星のリズムに従い静かに過ぎ去り、誕妄・マーフィーは相変わらず傲慢だが、沈黙と観察を学んだ。\n「レムリア、レムリア……」\n祭壇の上で、その穏やかで優しい顔が徐々に狂気に染まるまで、彼女は初めて気づいた。自分はミリアムを本当に理解したことがなかった。彼女の頭を撫でる優しい母の手も、神国の敵に最も厳しい罰を与えるのだ。\nその時、記憶の奥底に封じ込められた恐怖が突然蘇り、最終的に冷たい認識に凝固した——彼女の慈悲は偽装された腕足に過ぎず、優しい外見が変化した美しい青環こそが、血を見て喉を封じる毒素そのものだった。\n\n今日に至り、虚無の神はついに誕妄・マーフィーを戴冠した。彼女は伏せる深海教団を見下ろし、ミリアムの目に消え去らない、ほとんど荒唐無稽な期待を見て、再びガラス瓶の前で美しい生物を見つめて震える、小さな自分を見たかのようだった。"
  },
  CollectionHall_124397_Title = {
    Text = "青環の毒素"
  },
  CollectionHall_124400_Desc = {
    Text = "名も知れぬ疫病が町と村を飲み込み、戦を好む人々は混乱の中で思う存分殺戮を繰り広げ、鉄と血の交響曲が沸き立ち狂乱した。\n恐怖ゆえに、あるいは恐怖を利用して。\n恐怖は目に見えぬ敵、古き敵、致命的な敵。\n彼は失格の騎士だった、恐怖に敗れた騎士だった。\nしかし、かつて厳かに誓った誓いは今もなお耳に響き続け、幾年幾日を経て、すでに虚無と化した故郷を越えて。\n「私は弱き者に慈悲をもって接するだろう、私は強き敵に勇敢に立ち向かうだろう。」\n夜闇が凶行者の足跡を隠し、叫び声と泣き声の奔流が街路を溢れ、群衆はパニックに陥った羊の群れのようだった。\n「私は悪人に対して一切の容赦なく戦い、戦えぬ者のために戦うだろう。」\n槍先は血に染まり、銀の盾は錆び、影は満足げに微笑み、鴉の群れが頭上を旋回し、瞳の中に悪魔の閃光があった。\n「私は助けを必要とする者を助けるだろう。」\n「あいつだ、あいつが来た。」人々は小声で呟き、恐怖が彼らの顔を歪め、「うつろな怪物、復讐の亡霊、死の深淵から帰り来て、その敵を怨恨の黒い沼へと引きずり込もうとしている。」\nそう、彼だ。彼は忘れていなかった、一度も忘れたことはなかった。\nなぜ続けるのか？万物がいつか滅びるのなら、栄光も信仰でさえも。\nなぜ退くのか？どれほど運命に嘲弄されようとも、人はただ膝を屈して従うしかないのなら。\nただ忠誠に忠実であるため、献身に捧げるためだけなのか？\n公国最後の騎士は虚しく問い続け、魂は残骸と同じく荒廃し、恐怖の残滓が奔放に流れ、滅びの大海へと集まっていった。\nしかし空洞の胸腔は依然として沈黙を守り、失われた答えはまだどこにあるかも知れなかった。"
  },
  CollectionHall_124400_Title = {
    Text = "過去は影のように寄り添う"
  },
  CollectionHall_124404_Desc = {
    Text = "それは私と父が海城に移住して二年目のことだった。イヴリンの手紙での泣き言が私を心乱れさせ、彼女と別れる決意をした。ここは絹と黒檀で飾られた豊かな地で、腐肉を食べる者たちはその眠りの混乱を嗅ぎ取った。紙幣の価値は同じ重さの金と交換でき、その航路を掌握すれば、わずかなコストで莫大な富を得ることができる。\nしかしイヴリンは、彼女の曖昧で追いにくい奇妙な血統からくる神経質のせいか、先祖の伝言を信じていた。東方には彼らの分派が信奉する邪悪な神がいて、深海の魚のように美味しそうな餌を垂らして獲物をゆっくりと捕食する。\n彼女は間違っていた。海城には海の塩味は微塵もない。\nただ重なり合い、芳醇で酔わせるが恐怖をもたらす白玉蘭だけだ。\n私と父を同時に陥れた白玉蘭。\n彼女を見たとき、「徐」という名の女性の姿が視界に入った瞬間、私はこの古い土地から永遠に逃れられなくなった。\n彼女は近づきたくなる、彼女は所有したくなる、彼女は@3\n彼女は彼女は彼女は彼女は彼女は彼女は欲しい欲しい欲しい欲しい欲しい\n切り裂き、切り開き、砕き、永遠に永遠に永遠に永遠に永遠に……@2@3@2！！\nああ、なぜここに来たのか？何を持ち去るのか？私は……誰？\nもう重要ではない。彼女が招待し、私はその大邸宅のテーブルに座った。\nすでに私と同じく狂気に陥った父は、従順な笑みを浮かべ、豪華な副菜がテーブルを埋め、金属の蓋付きの皿が不釣り合いに見えた。\n徐は逆光の中に座り、夕日の中で光輪が彼女に金の縁を与え、ゆっくりと黒い扇を下ろした。\nイヴリンのように、幼い頃の友人のように、朦朧とした出会いのように……母のように。\nそれは寺院の金箔の神像のように端正で美しい顔だった。\n私は吸う音も聞こえず、父の体から漂う生臭さも嗅がず、ただその顔を夢中で見つめ、その顔の持ち主が白い手を伸ばし、皿を開け、適切な肉を拾い上げ、二本の細い木の棒でそれをつまみ上げた。\n彼女は私を呼び、焼かれた動物の脂が私の口角に滴った。\n「坊や、何か食べなさい。」\n\n私は従順で無表情に口を開けた。\n玉蘭の花が咲いて、私に向かってそっと垂れ下がっていた。\n——「無名者の手記」\n"
  },
  CollectionHall_124404_Title = {
    Text = "白木蓮の餌"
  },
  CollectionHall_124405_Desc = {
    Text = "「理性を灯にすれば、人生の霧を晴らせる。」\nかつて、茉夏はそんな言葉を聞いたことがある。\nそれはソロー社の技術者が霧除け灯を調整している時にふと漏らした感慨か？それともフィリンゲンのレストランで誰かが冗談で言ったのか？\n茉夏はもう覚えていない。ただ、彼女がその言葉を聞いた時の、顔に浮かべた社交的な微笑みと、その笑顔の裏に隠された嘲笑だけははっきりと覚えている。\n「灯？ハッ、何て古臭い骨董品、今はみんな懐中電灯を使うわよ。」\n彼女はそれが比喩であることを知らないわけではない。ただ理解する気がないだけだ。\nいつか彼女は死ぬ。そして死んだ後には、理性も霧も存在しない——彼女はこの世界から完全に解放される。\nそれは合理的で必然的な推測だ。彼女がすべきことは、この「必然」が訪れる前の過程を楽しむことだけ。\nしかし、誰も彼女に「必然」が「予想外」にも遭遇することを教えてくれなかった。\n似たような霧、似たような困難、しかしここには霧除け灯も調査団も、彼女が知っているものは何もない。彼女の斧は世の敵を断ち切ることができるが、自身の孤独と困惑が変じた霧を断ち切ることはできない。\n彼女は戻れるのか？戻るのか？一体いつ戻れるのか……\n次々と心の中に浮かぶ問いは、無形の深い水のように、彼女の心をゆっくりと飲み込んでいく。今この瞬間、彼女の心にある唯一の、すべての考えは——\n理性を保つこと。\n狂わないで！狂わないで！狂わないで！\nあの世界の霧、この世界の霧、そして自分の心の霧に直面しても。\n再び戻るために。"
  },
  CollectionHall_124405_Title = {
    Text = "理性の灯"
  },
  CollectionHall_124407_Desc = {
    Text = "七歳の誕生日、父は「モイライ」という名の紡ぎ車を彼女の膝に置いた。その名は、もはや誰にも祀られることのない三柱の運命の女神のものだったが、紡ぎ車そのものは滑らかで真新しく、銅の軸は金属の光沢を帯び、冷たく重かった。\nその時からアラクネは運命の輪を手に取った。それは選択によるものではなく、何気なく口にした言葉がいつも後に現実となるがゆえに、この定められた責務から目を背けることができなかったからだ。\nその時から彼女はずっと織り続けた。来る日も来る日も、運命の糸が精密な紡ぎ車の上で静かに回るのを見つめながら、人々のために初めての口づけの震え、軍馬の嘶き、赤子の産声、そして墓石に刻まれた粗い文字を織り上げた。\nその時から彼女は、幾千もの交差する糸の中から「より良い」方向を選び取り、漆黒の疫病を早めに退かせ、歴史を戦火から逃れさせ、文明を廃墟の中から再建させた…………だがそれと同時に、狂気や裏切り、あるいは永遠の闇夜へと通じる糸もまた織り出した。時空を跨ぐ運命の網を維持するために。\n「何がより良いというのだろう？」\n沈黙の紡ぎ車は答えず、ただ回り続ける。良きことも悪しきことも、誕生も死も、同じ一本の糸の上に交互に浮かび上がる。若き日の彼女は自らの宿命が何であるかをまだ知らなかったが、無数の糸の先に、世界の終局をすでに見ていた。\n「もし世界が滅びの宿命から逃れられないのなら…………」\n「いいえ、私はこの世界を愛している。」\nアラクネは紡ぎ車を見つめ、口にしなかった想いを捨て去った。\n「では…………私の宿命は？」\n彼女は呟いた。空虚な反響だけが四方の壁の間を彷徨っていた。\n…………\n数え切れないほどの文明が運命の網の上で興り、そして崩れ去った。ピラミッドは砂の中で眠り、宇宙船は星の海を駆け抜け、言語は季節のように移り変わり、神々の名は埃を被った辞典に記された…………だが彼女はずっとそこに座り、手の中の紡ぎ車を回し、人類が希望と滅びの循環を何度も繰り返すのを見つめていた。\nある日、一つの小さな呼び声が、永遠の牢獄と万古の静寂を超えた。\n「お姉ちゃん…………」\n彼女はようやく終末へと向けていた視線を引き戻し、目を閉じてネフレアを見つめた——彼女の中にいるもう一人の自分を。その新生児のように澄んだ瞳には、裁きも恐れもなく、ただ全幅の信頼だけがあった。まだ何も書かれていない白紙のように。\nその瞬間、アラクネはついに悟った。愛と責任、憎しみと滅び、すべては運命の前では何の違いもないのだと。そして彼女は、自らの手で断ち切り、捨て去った記憶——本来起こるはずだったのに訪れなかった痛み、後悔、喪失を一本の糸に織り上げ、最も重く、最も優しい贈り物として、ネフレアの手首に結んだ。\n「ここを離れなさい、ネフレア。」アラクネは微笑んだ。「あなたは自由よ。」\nアラクネはもう、自らの宿命を見定める必要はなかった。なぜなら七歳のあの日、紡ぎ車を手に取った瞬間に、彼女はすでに未来の行く先を選んでいたのだから。そして宿命の紡ぎ車は静かに回り続け、彼女がこれから身を投じる、終幕なき戦いを見届けるだろう。"
  },
  CollectionHall_124407_Title = {
    Text = "宿命の紡輪"
  },
  CollectionHall_124410_Desc = {
    Text = "食べる食べる食べる食べる…………\n幻惑の魘思。\n砕く砕く砕く砕く…………\n大海の譫言。\n壊せ！壊せ！！壊せ！！！壊せ！！！！\n抑えきれない狂気。\n「モス、おなかすいた。」\n少女は鮮血の滴る肉塊を飲み込んだが、どれだけ食べても胃の空虚は癒えない。\n「モス、のどかわいた。」\n少女は腥く腐った海水を嚥下したが、どれだけ飲んでも喉の渇きは消えない。\n「モス、ねむい。」\n少女は麻痺しながらも覚醒した自分を殴りつけたが、どれだけ眠っても思考の疲弊は抑えられない。\nなぜなら、純粋な破壊だけが、体内のあの方を満たせるから。\n「でも、モスは、やらない！」\nしかし少女は宿命の呼び声を拒んだ。特製の鋼鉄が、彼女の脱げない牢獄となった。\n彼女は自らを難攻不落の監獄に作り上げ、自分自身という名の拘束で、深海からの狂気を閉じ込めた。\n「モス、閉じ込めた、わるいやつ！」\nかくして、AF 1■■に出現し、無数の生命を呑み込んだ大渦メスクスは、AF 31■にて、完全に沈黙に帰した。\n\n\n\n\n"
  },
  CollectionHall_124410_Title = {
    Text = "囚われた狂気"
  },
  CollectionHall_124413_Desc = {
    Text = "本棚には退屈な研究文献の他に子供向けの楽しげな本もいくつかあった。\n『シンデレラ』『白雪姫』『人魚姫』『ラプンツェル』…………それらの所有者がなぜそのようなものを書棚に収めていたのか――今となっては知る術もない。\nそれらの物語には現実とは違う物語が紡がれる。「王子」「姫」「愛」…………それらの言葉は少女の心をときめかせる。\n夜空に輝く無数の光は地上へと降り注ぎ、やがて流れる光の河となるかのよう。\n差し込む月明かりの中で、少女はそっとつま先立ちをし、透明なガラスの靴を履いているふりをした。あたかもこの深く孤独な暗い夜が明けるのをずっと待ち望むかのように…………"
  },
  CollectionHall_124413_Title = {
    Text = "汚泥の中の童話"
  },
  CollectionHall_124414_Desc = {
    Text = "商船と商船の間を渡り歩き、いつも古びた布の上着の影に身を隠している老巫師は、羅針盤は人々をその者が向かうべき場所へと導くと言った。水夫たちはふざけながら、草薬の匂いのする彼女の戯言を笑い飛ばし、五レオフアンを投げ渡して、その精巧な真鍮の装飾品を持ち去った。\nそして彼らは、その後名前を失うことになる小さな町の港に停泊した。ポントスはこの話が好きだった。羅針盤の持ち主はポントスが好きだった。\nもちろん、ユーモアがあって明るく、風のように颯爽と来ては去るポントスを嫌いな者などいなかった。\nそれは本来、素晴らしい記念品になるはずだった。ポントスが愛する甥に譲り渡し、遥か彼方への夢想を開くキーとなるはずだった――しかしそれはポントスに彼の居場所を教えなかった。ポントスは許さなかった。彼の人生に別の可能性など、絶対に存在させるつもりはなかった。\n幾年もの歳月が過ぎ、ポントスが月明かりの中で無数の夜を渡り歩き、エポヤンスへ戻るべきあの姿を探し求めていたとき、彼はそう思っていた。\nああ、あの徒労な、守護の魔法が彼から離れた。ポントスはもう彼を連れ戻せる。\nただポントスはまだ知らなかった。「羅針盤は人々をその者が向かうべき場所へと導く」――すべての船にそれぞれの航路があるように、異なる人はいつも異なる方向を選ぶのだということを。"
  },
  CollectionHall_124414_Title = {
    Text = "岐路を指す羅針盤"
  },
  CollectionHall_124415_Desc = {
    Text = "「燐寸を一本、買っていただけませんか？」冬の夜、手足が真っ赤に凍えた少女がつぶやいた。「一本、一本だけでいいんです。」\n「ごめんなさいね、あなたの燐寸は買わないわ、」純白の影がわずかに身をかがめ、冬の月を遮った。「むしろ、あなたに何かを売ってあげようと思って。」\n「でも、お金が……」\n「大丈夫よ。仙女の祝福を信じなさい、すぐに燐寸が売れるようになるから。」\n白衣の仙女は少女の手に飴を一つ握らせ、それから少女の耳元に顔を寄せた。\n「通りの向こうにいる毛皮のコートを着た中年の女の人が見える？あの人の裾をつかんで、思いっきり泣くの。こう言うのよ、心優しい奥様、こんなに寒いのに、おばあちゃんが重い病気にかかってしまって、一度でもお腹いっぱい食べられなければもうすぐ死んでしまいます、どうかお金を少し恵んでください、って。」\n「でも、おばあちゃんはずっと前に、もういなくなってしまったから……」\n「それならなおさらいいじゃない！その時の気持ちを思い出して、もっと本当らしく泣くのよ……」\n「もしそれでもケチってお金を出さなかったら、私にも手がある。こんな大晦日に外をうろついている人は、家庭が幸せじゃないに決まってる。だからこう付け加えるの、おばあちゃんは私の唯一の家族なんです、今日は大晦日なのに、誰だって一人ぼっちは嫌でしょう、お願いです、きれいな奥様、三文だけでいいんです、早く燐寸を売り切って、おばあちゃんのところへ帰れるようにしてください、って。」\n「燐寸は一文なのに……」\n「残りの二文は、一文が私の取り分、もう一文はあれへの供物よ。」カラブは手の中の魔法の杖を振った。眠っている白い幼虫が水面の波紋のように揺れた。\n「難しく考えないで、仙女の祝福を信じればいいだけよ。この手は必ず効く。覚えておいて、お金を出すまでは絶対に手を離しちゃだめよ。失敗したら、次の孤独なお金持ちの奥様を探せばいいだけ。安心して、この世の中、手元に余裕のある女性はあたし達二人を養えるくらいいくらでもいるんだから。」\n必ず効くはずの方法がなぜ失敗するのか、もはや誰も追及しようとはしなかった。とにかく、百八十二套の話術を更新した末に、少女の燐寸は無事に売り切れた。\n本物の「仙女の名付け親」が現れない物語の中でも、偽りの仙女は同じように、凍え死にそうな、貧しくかわいそうな少女を救ったのだった。\nめでたし、めでたし。"
  },
  CollectionHall_124415_Title = {
    Text = "甘美なる真相"
  },
  CollectionHall_124844_Desc = {
    Text = "<Title:紹介>\nテムラン出身の神秘な少女。彼女の説明によれば、元々は地元の大学の準大学生で、「運命的なロマンティックな出会い」により霧境調査隊の先鋒となった。\n繁星の明けの会の「霧災事件」で、モカは偶然この世に召喚され、その後、銀と血の儀式で洗礼を受け、人間から覚醒体に変わり、「霧災事件」を終結させた。\n自分の世界ではない場所にいる彼女は、帰る方法を求め続けているが、同時にこの世界の未来にも興味を持ち、「世界の結末」を見届けたいと渇望している。"
  },
  CollectionHall_124844_LockTip = {
    Text = "「ムシェット」を召喚すると解放"
  },
  CollectionHall_124844_Title = {
    Text = "ムシェット"
  },
