  CollectionHall_126425_Title = {
    Text = "マーフィーの幻影"
  },
  CollectionHall_126471_Desc = {
    Text = "モシャはとうに霧の存在に慣れていた。\nどんなに厄介な霧でも、どんなに危険な霧でも、彼女はいつもその中から無事に抜け出すことができた。\n今回も同じだ。\n彼女は必ず新世界の霧を抜け出し、自分の次元へと帰る。\nどんな代償を払うことになろうとも。"
  },
  CollectionHall_126471_LockTip = {
    Text = "多次元接続「銀と血の洗礼」を完了する"
  },
  CollectionHall_126471_Title = {
    Text = "新世界の霧を晴らす"
  },
  CollectionHall_126472_Desc = {
    Text = "霧はいつか必ず晴れる。\nその時、霧の中に響き渡る悲鳴は消え、祭壇に流れた血痕は拭い去られる。\n迷える魂は解放され、正しき道を見つけるだろう――\n輝く星々へ向かうか、真実の大地に留まるか。"
  },
  CollectionHall_126472_LockTip = {
    Text = "多次元接続「銀と血の洗礼」を完了する"
  },
  CollectionHall_126472_Title = {
    Text = "霧が晴れる時"
  },
  CollectionHall_126473_Desc = {
    Text = "宇宙は世界を育み、世界は生命を育んだ。そして異なる世界の生命は、異なる規則と理念を生み出した。\nそれらが交わる時、戦うのは二つの肉体、二つの意志、二つの生命だけではない。\nそれは永遠に平行でありながら突如として交差する、二つの宇宙の衝突なのだ。"
  },
  CollectionHall_126473_LockTip = {
    Text = "多次元接続「銀と血の洗礼」を完了する"
  },
  CollectionHall_126473_Title = {
    Text = "信念の激突"
  },
  CollectionHall_126474_Desc = {
    Text = "任務が終わったら、私は過去の自分に別れを告げる。\n懐かしくも戻れないあの日々に、テムランに、そして人間だった頃の自分に別れを告げる。\n私はあの霧に満ちた世界を懐かしむだろう。\nこれからは、新たな身分で、この霧が晴れた世界、この興味深くも恐ろしい世界で生きていく。"
  },
  CollectionHall_126474_LockTip = {
    Text = "多次元接続「銀と血の洗礼」の困難難易度をクリア"
  },
  CollectionHall_126474_Title = {
    Text = "霧語りの新生"
  },
  CollectionHall_126475_Desc = {
    Text = "残酷な世界では、一人の魂はたやすく燃え尽きてしまう。\nだから我々は他者と世界に求めるのだ。親情、愛情、友情、郷愁の念…………\nその触れることのできない感情が、目に見えない力となり、命を繋ぎ、人々をこの世界でもう少し長く、もう少しだけ長く燃え続けさせるのだ…………"
  },
  CollectionHall_126475_LockTip = {
    Text = "多次元接続「銀と血の洗礼」を完了する"
  },
  CollectionHall_126475_Title = {
    Text = "残酷な生存の知恵"
  },
  CollectionHall_126476_Desc = {
    Text = "悠久の星々は世界の誕生、成長、繁栄を見届けてきた。そしてそれは必ずや世界の終焉をも見届けるだろう。\n生存を渇望する人々よ、生き残る唯一の方法は、我々の足元にはない。我々を裏切った大地の上にはない。それは我々の頭上にある、あの永遠に星々が輝く地にあるのだ。"
  },
  CollectionHall_126476_LockTip = {
    Text = "多次元接続「銀と血の洗礼」を完了する"
  },
  CollectionHall_126476_Title = {
    Text = "星々が輝く地"
  },
  CollectionHall_126477_Desc = {
    Text = "世界を救うなんて彼女の流儀ではない。そしてここは、彼女の世界でもない。\nだが彼女は守秘者の声を聞き、守秘者が世界を救うために払った大きな犠牲を目にした。\n命を懸けて守られた世界は、滅びるべきではない。\n少なくともこの瞬間、彼女自身の手で滅ぼすべきではない。"
  },
  CollectionHall_126477_LockTip = {
    Text = "多次元接続「銀と血の洗礼」の困難難易度をクリア"
  },
  CollectionHall_126477_Title = {
    Text = "理解できない選択"
  },
  CollectionHall_126906_LockTip = {
    Text = "意識潜游「扇下夜談」のいずれかのステージをクリアして解放"
  },
  CollectionHall_126989_Desc = {
    Text = "<Title:概要>\n彼女の本当の出自はもはや証明することができず、この古代の「神明」に関する最も古い記録は、数千年前に遡ることができる。\n彼女を見ると、誰もが異なる姿を目にし、実際には知らず知らずのうちに相手の記憶を汚染する能力を持ち、自分のイメージを無意識のうちに相手の記憶に溶け込ませ、最終的に相手が自分を唯一重要な存在として認識するようになる。\n他のほとんどの覚醒体とは異なり、彼女には人間の感情や視点がほとんど存在しない。\n彼女は一つの思念、一腔の狂想、一筋の霧——彼女は徐として認識され、劉、李、錢、張として認識される。彼女は歓喜の中に生まれ、絶え間ない混乱からの歓喜を追い求める。\nしかし、彼女は完全に理解不能で、形容しがたい存在ではない。彼女が選んだ個体、彼女に究極の愉悦をもたらす個体は、他の呼称が変わりやすいのとは異なり、彼女を真に定義することができる名を垣間見る機会を得る。\n「千扇玄女」。"
  },
  CollectionHall_126989_LockTip = {
    Text = "「徐」を召喚すると解放"
  },
  CollectionHall_127110_Desc = {
    Text = "両手剣は長く重く、十分な力があれば人を二つに切ることができる。\n\n短剣は軽くて巧妙で、隠しやすく、不意打ちに最適だ。\n\n湾曲した刀は美しい曲線を持ち、刃が鋭く、切り裂くときに簡単に肉に食い込み、深い傷を開くことができる。\n\n銃器は速くて強力で、クロスボウの矢は無音で迅速だ。さまざまな金属部品が灯りの下で冷たい光を放っている。十歳のラモンナは、壁一面に掛けられた武器の前に立ち、年齢にそぐわない成熟と慎重さを顔に浮かべている。\n\n「どれを選ぶ？」養父——いや、育ててくれた父——の声が背後から聞こえる。「選んだら、先生を見つけてあげるよ」\n\nどれにしよう？大剣の重さは利点でもあり欠点でもある。短剣は長い武器には対処しにくい。湾曲した刀は長いが、切るときに多くの不必要な損傷をもたらす。銃器は音が大きすぎ、クロスボウの矢は弾薬が尽きやすい。\n\nミサゴの訓練場で何日も観察して、彼女は戦う両者の弱点を一目で見抜き、ほぼ直感的に攻撃ルートを計画できることを知っている。それらは大量の経験を積まなければわからないことだが、彼女には一瞬で推測できる。いや、彼女が求めているのはそれではない。彼女は最小の力で最大のダメージを与えることができる、より正確な武器を必要としている。\n\n少女はしばらく考え、横にあった椅子を持ってきて、その上に立ち、高いところに掛けられた細剣に手を伸ばした。\n\n細く優雅で、柔軟で軽く、非常に正確にダメージを与えることができる——そう、これだ。彼女のすべての要求に合っている。"
  },
  CollectionHall_127110_Title = {
    Text = "時を遡る時計"
  },
  CollectionHall_127111_Desc = {
    Text = "「世界が終末に向かうとき、どんな楽しみがあるのだろう？」\nムシェットは知らないが、期待している。\nこの期待は以前とは違い、今回はいくつかの古物を扱う小さな楽しみではなく、世界を尺度とした研究と調査である。そしてこの研究と調査の中で、最も重要で核心となるのは一人の人間——\nミサゴの守秘者。\n「私はこの世界を救う……」\n「この世界は、決して崩壊の運命に向かわない……」\nその理想を抱き、世界の興亡を背負った人がこう約束する。応じて、ムシェットは感動の表情を見せるべきだと知っているが、これは人間社会の暗黙の社交礼儀である。\nしかし、彼女はもう偽装したくない、あるいは、守秘者が@4に直面し、自らを犠牲にして世界を救うのを見た後、宇宙の恐怖を経験した人に対して偽装する必要はないと感じた。\n「偽装」は人間社会のゲームルールで、体面だが退屈であり、宇宙は……宇宙は真実で率直だ——\n生存するか、滅びるか。\nだから、彼女は守秘者への答えも真実で率直だ。\n「私はこの世界が救われるか、滅びるかは気にしない……それよりも、あなたに興味がある。」\n私はあなたが理想を実現できるのか、それとも理想を追求する道で挫折するのかに興味がある。\nまた、この世界があなたの願いに応えるのか、それとも避けられない滅びに向かうのかにも興味がある。\nどちらにしても、それは壮大で貴重な楽しみになるだろう。\n私はその日を常に期待している……\n私の目で、私の斧で、待っている。"
  },
  CollectionHall_127111_Title = {
    Text = "狂乱が世界の果てまで"
  },
  CollectionHall_127112_Desc = {
    Text = "「記憶とは何？」\n「それはあなたが忘れたもの」\n\nリリーには物忘れのひどい母がいる。\n\n一緒にご飯を食べるのを忘れ、薬を与えることを忘れ、時にはリリーの名前さえ忘れる。\n\n「どうしたらいいんだろう？」\nリリーは病床に座り、深刻そうに、大きくため息をついた。\nこんな母親では、本当に手がかかる。\n\nその後、リリーは自分の名前を木の札に書き、毎日首からぶら下げるようになった。\nこれなら、きっと覚えていてくれるかな？\n\n最初は、母も笑って「そんなことする必要はない。これはただの長期的な疲労による合併症」と言っていた。\n\nしかし、次第に、母は困惑し、いらだち始める。\n\n「リリー……リリーって何？」\nリリーを見つめる、その琥珀色の瞳には、わずかに警戒心さえ帯びていた。\n\n文字の意味さえ忘れられると、言葉によりかろうじて保たれていた穏やかな関係は、ついに終わるのだとリリーは悟った。\n\nリリーは母を抱きしめた。\n母娘の心臓の鼓動はほんの数インチしか離れていないのに、彼女はこの上ない孤独を感じた。\n\nその日以来、リリーは木の札をしまい、母に甘えるのをやめ、何日も食べていないことを思い出させることもなくなった。\n\n彼女は死にかけの患者として麻痺したまま死神の宣告を待つ。\n\n彼女は対岸の火事を眺める観客として、自分が注射され、麻酔をかけられ、母が望むどんな姿にでもいじくり回されるのを遠くから見ていた。\n\n母娘の間の楽しい会話や、やわらかな抱擁……\n\n夢のような泡のようにきらめく楽しい思い出を、リリーは心の中に大切に閉じ込めた。\n\nそして、疲れた夜にだけ、それをそっと取り出して、優しくなでるのだった。"
  },
  CollectionHall_127112_Title = {
    Text = "痛みを越えて"
  },
  CollectionHall_127113_Desc = {
    Text = "高くそびえ立つ塔が轟音とともに崩れ落ちる。\n異なる時空の異種族の学者が書いた書籍が散乱する。\n一瞬にして大小さまざまな黒い三角形がすべての本やレンガに広がり、連鎖反応を起こして四方へ拡散した。\n\n黒い液体が溶岩のように整然とした街路を流れでる。\n人々は悲鳴と叫びをあげ、この恐ろしい災厄から逃れようとした。\n\n多くの人が乗り物での脱出を試みたが、建物や他の事故車に衝突する。\nさらに多くの人は反応が遅れ、徒歩で粘液から逃れようとしたが、恐怖に駆られた者たち押し倒され、みな液体に飲み込まれた。\n\n子どもが街角で大声で泣き叫び、数人の若者が残された建物に身を潜めていたが、死を逃れられるという妄想にすがるだけだった。\n\n「予兆なんてなかったのに、なぜ、なぜ！」\n「なぜ誰も警告しなかった！」\n\n「@1、これは融蝕だ！助けて！」\n「意識転送を急げ！それしかない——ああ！」\n「@2、早く装置を！」と誰かの声。\n\n「時間を稼ぐ！」\n「いや！私は——」\n「私たちはもう@1されているが、君にはまだ希望があるんだ」\n優しい声が答えた。\n「生き延びろ、@2、そして——」\n\nウインクルは目を見開いた。\n周りには積み重ねた書物、幾つかのコーヒー渋のついたカップ。\n\n近くの黒板には大小さまざまなメモやノートが貼られ、途中まで書かれた数式も残されていた。\n\n乱雑な部屋の隅、中央、そして彼女の乗る巨大な装置の横には複数のランプが置かれ、オフィス全体がまばゆいほど明るく照らされている。\n\n彼女はしばらく黙り込み、より深く測位システム装置に身体を預けると、途切れていた演算に再び向き合った。"
  },
  CollectionHall_127113_Title = {
    Text = "計算不能な演算"
  },
  CollectionHall_127114_Desc = {
    Text = "痛み、激しい痛みが彼女の全感覚を満たしていた。\n\n金属製の潜水服は水圧の下で無力で、外殻が内側にへこみ、ネジが崩れ、何かが彼女の腹腔を押し、何かが彼女の腕を貫いた。冷たい海水が潜水服の破損部分から押し寄せ、厚い金属を使用したヘルメットだけがかろうじて形を保ち、彼女にわずかな酸素を残していた。\n\nヘルメットの唯一の覗き窓を通して、彼女は外の海水が碧から墨色に、そして漆黒に変わるのを見た。呼吸による水蒸気がガラスに凝結し、渦の轟音の響きが徐々に遠ざかり、耳に残る幻影となった。彼女は徐々に自分の四肢を感じなくなり、呼吸もますます重くなった。\n\n彼女は自分が気を失ったのだろうと推測した。寒さ、失血、酸素不足、どれも彼女の意識を曖昧にするのに十分だった。同時に彼女は確信が持てなかった。なぜなら、どれだけ瞬きをしても、直面するのは同じ暗闇だったからだ。\n\nここは光が届かない場所、海の深部、未だ誰も探知していない領域だ。\n\n鈍い興奮が最後に彼女の血液をかき混ぜた——未知の領域、最後の冒険。彼女はこれで夢を叶えたと言えるのだろうか？たとえ今何も見えなくても。\n\n足首に奇妙な感触が伝わり、彼女は無意識に下を向いた。暗闇の中で、何かが彼女のふくらはぎを登っているように見えた。それは奇妙な深海生物なのか、海水よりも冷たいのはなぜだろう？どうして……この暗闇の中で、その輪郭が見えるのだろうか？\n\n漆黒で、蠕動する、泥のような……\nこれは何？彼女はどこにいる？彼女……は誰？"
  },
  CollectionHall_127114_Title = {
    Text = "記憶螺旋"
  },
  CollectionHall_127115_Desc = {
    Text = "（以下の回答はクレメンタインの診療手帳からの抜粋で、参考用である）\n\n1. カエクス。\n2. 16、17……？誰が知るか。\n死んだ後、こんな無意味なことを気にして何になる？\n3. ぼろぼろの漁村だ、地図には載っていない。\n4. 言いたくない。\n5. 奇妙な奴、醜い化け物、愚か者、馬鹿@1……よくあることだ。 \n6. 黄金に輝くナマズのような顔、ナマズ顔だよ。\n7. 雨の日。\n8. わからない。雨の日には浜辺を歩き回る……\n何年もそうしてきた。ただ遠くを見ているだけ。\n9. 言っただろう、#¥%わからないんだ@1消えろ！！\n-------\n14. うーん……もしかするとアウン叔父さんが言ってたことが頭に残っているのかもしれない。\n「雨の日に大帆船で、お前を『家』に迎えに行く」って……\n15. そうだ、彼は約束を果たした……\n僕は数日間、海底を漂っていた。喉が渇き、腹も減って、全身が痛んだ……\nそして、白い大帆船とアウン叔父さんの姿が見えた。\nいや、正確には帆船のマストにぶら下がっているのは彼の骨だった——彼も変異に失敗したんだ。\n最後の力を振り絞って、船へと泳ぎ、マストの上で彼に寄り添った。\n16. 僕たちは、一緒に家へ帰ると約束したんだ。"
  },
  CollectionHall_127115_Title = {
    Text = "疼痛の鰭"
  },
  CollectionHall_127116_Desc = {
    Text = "「人々は潮が来るときに生まれ、潮が引くときに死ぬ」\nこれはニムフィーアの故郷でずっと伝えられている伝説だ。\n\nセヴァダの村人たちは死を恐れない。彼らにとって、生命の芽生えと枯れは潮の満ち引きのように自然の一部だ。\n彼らは青空、海、群れ飛ぶカモメ、朝日に咲くカラーリリーを愛している。\n彼らは蒸気、鉄道、そして人工的な干渉の痕跡が強すぎるもの——生命への干渉も含まれる——を嫌っている。\n自らの命を人工的に断つことは、セヴァダ人にとって受け入れられない。\n\nニムフィーアは典型的なセヴァダ人ではない。\n例えば、彼女はいつも沈船の雰囲気に惹かれている。\n死んだ沈船は無数の生命の家だ：魚、水草、さまざまな貝類……\nここでは、生と死が神秘的で神聖な方法で交錯している。\nニムフィーアは静かに沈船に近づき、まるで荘厳な大聖堂に足を踏み入れるかのようだ。\n\n父が彼女を旅行に連れ出して気晴らしをさせていた時代、ニムフィーアは五幕劇を見たことがある。\nその劇の内容はすでにぼんやりしているが、古代の帝王の生涯を描いたもののようだった。\n彼は生前、戦争に明け暮れ、南北を征服したが、恥ずべき陰謀で死んだ。\n彼女はその中の一つのセリフを覚えている：\n<Italic:臆病者は死ぬ前に何度も死んでいる；勇者は一生に一度だけ死ぬ。>\n\n何年も後、ニムフィーアが冷たい海水に足を踏み入れたとき、生への執着から苦しんでいるとき、その言葉が頭をよぎった：\n「勇者は一生に一度だけ死ぬ……」\nそして彼女は涙を拭い、最後に両親に別れを告げ、心の中の沈船に向かって進み続けた。\n彼女は自分自身の勇者になるのだ。"
  },
  CollectionHall_127116_Title = {
    Text = "腐朽の贈り物"
  },
  CollectionHall_127117_Desc = {
    Text = "@1年6月5日\nアルビノが融蝕の裂け目から、いくつか希少なシルバーコアを持ち帰った。さすがだ。\n\n精製方法を少し改良した。\n今回は二酸化炭素と塩素を充分通し、低温で蒸発、結晶化……\n機械的な工程ばかりで、記録するほどのことはない。\n\n@1年6月6日\n実験体024の内臓と四肢を切除した。これはアルビノが診療所から持ち帰った素材だ。\n13個の融蝕孔が生成されており、最大直径は8mm。\n\nOS-106号融蝕の怪物の、腫瘍を切除。各種テストデータの比較によると、024との共鳴相性が最も高いようだ。\n\n唯一の問題は……触腕が少々「活発すぎる」こと。\nしばらくタコは食べたくない。\n最終結果が失望に終わらないことを願う。\n\n@1年6月6日\n接合実験成功、実験体の生命兆候はすべて消失。\nこれはよくあることで、接合部に感染の拡散がないことだけ確認すればよい。\n\n観察室に送って一週間観察。\nあとは私の仕事ではない。\n\n今日「内部ジャーナル」で、生体覚醒体実験を批判する檄文を2本読んだ。\n言うまでもなく、署名を見ればミサゴの古い友人たちだとすぐ分かる。\n\n滑稽だ。あの古臭い連中が少しでもその肥えた尻を動かして、実験室を覗きに来れば、私の結論が揺るぎないことなどすぐに分かるのに。\n\n024の実験は、彼らへの絶好の反撃となるだろう。\n\n@1年6月22日\n2週間が過ぎたが、024の各種徴候は依然として不安定——\nいや、こう言うべきか。彼女の体内の人格が細胞分裂の速度で狂ったように増殖している。\n\n実験は、常識を超えた形で失敗を宣告された。\n\n024は蝋人形館に送ろう。\n私のそばに置いて、毎日、己の愚かさと軽率さを思い出させる必要はない。"
  },
  CollectionHall_127117_Title = {
    Text = "奇体の反噬"
  },
  CollectionHall_127118_Desc = {
    Text = "それは銀白で、澄んでいて、汚れのない心だった。\n純銀でできており、機械の心臓の中で秩序正しく鼓動していた。\n血肉に侵食され、泥に染まったこともあった。\nしかし、死の陰が覆うとき、それはついに元の姿に戻った。"
  },
  CollectionHall_127118_Title = {
    Text = "純銀の初心"
  },
  CollectionHall_127119_Desc = {
    Text = "時間が流れ、星が生まれた時の記憶を、ロータンはもうあまり覚えていない。\n彼女はただ、自分が選ばれた生き物であることを覚えている。\n\nそれはすべての概念が生まれる前の物語。\n「生命」がまだ根付いておらず、「神」は遥か遠くにあった。\nこの無秩序な星雲の中で、混沌と混沌が衝突し、物質は衝撃と攪拌を経て形を成した。\n塵を集めた星が山の形に隆起し、大気が大きな水域を形成した。\nそして、「惑星」として宣言された。\n\n混沌の魂は時の牢獄に囚われ、新たな大地に衝突した。\n暴虐の本性を制御できず、破壊欲に操られ、無数の山を崩し、無数の川を埋めた。\nその時、「神」は遠い星を越えて荒廃した惑星に降臨した。\n\n「神」は文明の種をもたらし、混沌の魂を「秩序」の体に封じ込めた。\n「私と…契約をしよう」\n轟く混沌の魂に向かって、白いヴェールをまとった「神」は囁いた。\n「偉大な文明がここで生まれる」\n「あなたは無為の智者に出会い、彷徨う刃と対峙する…未来には、破壊と滅亡に支配されることはない」\n「その日が来るまで…再会するまで、ここを守っていてくれ」"
  },
  CollectionHall_127119_Title = {
    Text = "星天の獣"
  },
  CollectionHall_127120_Desc = {
    Text = "彼が大公に騎士として指名された時、彼はまだ世界で七つの四季を見ただけだった。 \n\n大公が子供をからかうために言った冗談が、皆に本気にされてしまった。\n騎士たちは彼に騎射の技を教え、女官は彼に礼儀を教え、公女もこの小さな騎士を信頼し頼りにしていた。\n\nアクイダンと峡谷の広野高原を歩きながら、若い騎士は公女の馬を引いていた。公女は馬の背に力なく伏せ、見えない闇が彼女の体を蝕んでいた。\n\n「公女様、これ以上進むことはできません」\nこの峡谷を越え、この川を渡れば、彼らを育んだ土壌を離れることになる。\n戦火が外界に広がり、敵は対岸から豊かな土地を狙っていた。\n天堑を隔てて、小さな土地はかろうじて生き延び、「国家」の尊厳を保っていた。\n峡谷のこちら側で、彼らは対岸の滅亡と苦痛を目撃した。\n無実の者たちの祈りと悲しみが川に落ち、勝者の詩篇の一部となった。\n\nどんなに偉大な国でも、歴史に巻き込まれることを阻止することはできない。\n\n敵は幼い手を切り落とし、彼はもう銃や盾を持ち上げることができなくなった。\n敵は脆弱な膝を踏み砕き、彼はただ目を見開いて宮殿の門が鉄騎に打ち破られるのを見ているしかなかった。\n騎士は敵軍の戦馬の脚に噛みついても、敵の暴行を止めることはできなかった。\n\nそして、彼は初めて公女の口から「黒い疫病」を見た。\n\n洪水のような黒い液体が宮殿の門から流れ出し、鉄騎の脚甲を覆ったが、誰一人としてそれで止まることはなかった。\n激しい「黒い疫病」が口鼻に入り、肺にまで達したが、彼はここで倒れたくはなかった。\nそして、その非常に馴染みのある声が直接脳内に響いた。\n「あなたはもう十分にやった……私の最も忠実な騎士よ」\n\n最後に、目の前にはただ白い空間が残った。"
  },
  CollectionHall_127120_Title = {
    Text = "騎士の心"
  },
  CollectionHall_127121_Desc = {
    Text = "彼らは未知への人間の想像から生まれたが、想像のようなヒステリックさや攻撃性はない。\n\n彼らは理性的で、冷静だ。\n\n彼らは未来のために、存続のために来た。\n\n彼らは最も異常で、信じがたい奇跡だ。\n\n初めは彼らの声は虫の鳴き声のようだった。しかし、彼らの思考を完全に理解した後、その声は静かになった。\n\nしかしその後、声の主たちは彼女のすべての決定を左右しようとした。\n\n覚醒体として目覚めた最初の年、彼女は頭の中の声と共存することを学んだ。\n\n彼女は意識に潜り、ゲシュタルトの一部となり、必要な情報と知識を獲得し、最後には無事に現実に戻った。\n\n「黒い疫病」がこの身体を襲ったときも、彼女は同じことをした。\n\n彼女は身体と知識、記憶、魂を分離し、脳を不滅の個体にしようとした。\n\n手術が終わった後、彼女は生き生きとした不思議な眠りに入る寸前だったが、数秒で思考が再び動き始めた。\n\n彼女は、形式、力、対称性を超えた混沌の中の絶対的な破壊に近づいていることをはっきりと知っていた。"
  },
  CollectionHall_127121_Title = {
    Text = "死を超える"
  },
  CollectionHall_127122_Desc = {
    Text = "人々はいつも自分の尺度で枠を決め、シンボルを確定したがる。\n世界は人間の肉体に限られており、なんと狭く、愚かで悲しいことか。\n彼女は早くに肉体を捨てたが、依然として真の境界に触れることができなかった。\n知識の流れは混乱し尽くし、黒い虚無が再び彼女に追いついた。\n彼女は静かにそれを見つめ、もし有形の面が世界の全貌を覗けないなら、虚無の背後こそが真の答えではないか？\n彼女は自分の命を賭けてこの生涯で最も狂気的な賭けをした。\n彼女はついに終焉を見た。\n真実の扉が開かれ、世界の姿が瞬時に逆転した。\nなるほど、なるほど。\n彼女はすべての人にこの虚無の真実を見せ、無駄なもがきから解放したいと切望した。\nかつて彼女は波の頂に立ち、世界を導いた。\n今も彼女は羊飼いの鞭を振り、軽やかに世界を深淵に導いている。\n人々は恐れて彼女を追放し、彼女を邪悪な狂人と見なした。\nなんて奇妙だ、と彼女は思った。\nでも私の目にはあなたたちも同じだ。\n"
  },
  CollectionHall_127122_Title = {
    Text = "虚無に堕ちた人形"
  },
  CollectionHall_127123_Desc = {
    Text = "死を恐れる必要はない。それは肉体が魂を夜に返す過程であり、潮が引くように、深い安らぎに帰ることだ。完全に融蝕に消え、誰にも知られず、無意味な存在になることこそが本当の恐怖だ。\n彼女は安らかに死んだわけではない。\n枯れた体はすでに冷たく、血液と融蝕液が混ざり、暗赤色のガラスのように凝結していた。しかし彼女の若い魂は喉の奥で震え、その一筋の消えない意識は、煙のように骨の隙間に留まっていた。まるで脆弱で翼を折られた美しい蝶のように。\nデュルセインは静かに部屋に入り、足音は埃を驚かせなかった。彼は彼女の傍に跪き、視線は彼女の閉じた目、開かれない指節、そして不安に揺れる魂を優しくなぞった。\n「私はまだ生きているの？」\n「この暗闇が私を飲み込むの？」\n彼は言葉を発さず、ただ手を伸ばし、彼女のひび割れた指を一本一本開き、震える花びらの折れ目をなだめるようにした。憐れみも責めもなく、ただ平和で静かな忍耐があり、まるで世の中で最も公正で荘厳な神が、彼女に安らぎの権利を与えるかのようだった。瞬間、彼女は永遠の静けさに達したかのように感じた。\nそして純粋な芳香が彼らの握った手から逸れ、彼は身をかがめ、満足し荘重に彼女の指の背に一吻を落とした。その吻が落ちた瞬間、死の最後の共鳴が少しずつ伸び、空中に漂う一筋の清風と溶け合い、暴風後の湖のように、完全に静寂となった。疑問も恨みも恐れもない。彼女はついに死そのものに帰属した。\n「私はあなたを忘れない。」\n彼は身を起こし、今や完全に静けさに帰した彼女の姿を見つめた。ぼんやりと、鋭い牙が皮膚に刺さり、彼はセリーヌの声を聞いた。\n「私はあなたを信じている、兄。」\n彼女は幸運だった。デュルセインの記憶の中で、彼女は永遠の安息を得るだろう。"
  },
  CollectionHall_127123_Title = {
    Text = "安息の口づけ"
  },
  CollectionHall_127124_Desc = {
    Text = "あなたが初めて生きたゴーレムを見たのは、女学者の家だった。\n「今でも彼女には驚かされるの。私にとって、彼女は宇宙そのものですわ」\n彼女——そのゴーレムは機械的な微笑を見せ、口からは不明瞭な呟きを漏らす。\nその灰色の瞳を見つめると、荒れ狂う灰色の海の中で波の光が地平線から別の地平線へと移ろうようだった。\n\n家を去る前、女学者はあなたにゴーレムの製作法が記された古びた手記を手渡した。  \nその夜、あなたはそれを広げ、乱雑に記された術式や呪文を読み込む。  \nしかし、脳裏にはゴーレムの不可解な微笑が焼き付いて離れない——  \nあなたは、彼女を決して忘れることができなかった。  \n\n数日後、あなたは口実を作り、再びその家を訪れる。 \n山積みの書籍、器具、骨格を越え、厚いカーテンと絡みつく蜘蛛の巣をかき分けて、最後にゴーレムの前に跪いた。\n隅に身を丸めた女学者は、わずか数日で痩せ衰え、瞳から光を失っていた。  \n「やはり来たのね……他の者たちと同じように」  \n彼女は弱々しく咳をする。  \n\n「ええ……僕はきました」\nあなたはゴーレムの手を拾い、繰り返し唇を押し当てる。  \n冷たい指先があなたの首筋を優しく撫でると、微細な痛みが伴い、あなたはゆっくりと瞼を閉じた。  \n\n——目覚めた時、あなたは柔らかな海の波に揺られ、白い陽光に包まれていた。  \n身体は軽く、まるで魂が肉体を捨て去ったような浮遊感に襲われる。  \nあなたは振り返り、そこに無数の灰黒色の頭部があるのを見た。  \nそれらは泣き叫び、歪み、まるで黒い野花のように密集して、灰色の原質の海に咲き乱れていた。  \n\n「いやだ——」\n喉から黒い粘液が吐き出される。あなたはもう動けなくなっていた。\nあなたもまた、彼らの一員となったのだ。  \n\n「@2年6月、著名な錬金術師ロマリン・ルートヴィヒが、書斎で謎の死を遂げた。  \n彼の首は忽然と消え去り、あの神秘的な錬金術の手記も同時に行方不明となった……」  \n\n（この記録はミサゴ図書館の《錬金術逸話》第二巻に記載されています）"
  },
  CollectionHall_127124_Title = {
    Text = "至高の秘蔵品"
  },
  CollectionHall_127125_Desc = {
    Text = "カストルは自由の意味を理解できないまま、退屈な修行生活から抜け出そうとする。弟のポリュクスと共に教会に抗うことを決めた。そして二人は自由の代償を体験する。"
  },
  CollectionHall_127125_Title = {
    Text = "耐え難き自由"
  },
  CollectionHall_127126_Desc = {
    Text = "嵐が吹き荒れる夜、神の娘は舷窓の下にひとり静かに座っていた。\n冷たい月光が産着を照らし、その中では、黒い粘液を滴らせる聖なる赤子が安らかに眠っている。\n\n神の娘は、子守歌を口ずさみ始めた。\n「眠れ眠れ、海の赤子よ」\n「黒き月影、揺りかごに」\n「星を呑み込み、夢の中」\nその歌声は同時に祈りでもあり、深海の魚群はそれに呼応して集まってくる。\n\n船全体が巨大な祭壇のようで、まるで彼女が聖なる赤子を産んだ日と同じだった。\n彼女は自らの胸を切り裂き、血に濡れた骨と肉を取り出し、育てられた恩と、種族に課せられた宿命に、己の命をもって報いた。\nだが、その犠牲が、彼女の切望した自由をもたらすことはなかった。\n死は永遠の安眠ではなく、ただ悲劇の始まりにすぎなかったのだ。\n\nそれ以来、彼女の安らぎは夜からしか得られなかった。\n「眠れ眠れ、海の赤子よ」\n\n偉大なる神の国は海面を突き破り、荒れ狂う大洋の中から浮上するだろう。\nそんな虚ろな幻想を胸に抱きながら、マーフィーもそっと目を閉じた。"
  },
  CollectionHall_127126_Title = {
    Text = "暗闇の中の安眠"
  },
  CollectionHall_127127_Desc = {
    Text = "彼は常に自分を責め続け、その苛烈さで仲間を遠ざけてきた。音楽の頂を目指すために、独りで歩み続けるつもりでいた。\n\n高みは孤独なもの——彼はそう定めた運命を受け入れた。\n\nある人の演奏を耳にするまでは。\n\n完璧とは程遠い、奔放な音楽だった。その人自身を映すように、時に楽譜を外れ、ふと一節を忘れる。だがその瞬間、両手は即興で鮮やかな音を紡ぎ、聴衆から驚きと喝采を引き出した。\n\n彼はその人を見つめ続けた。音楽の精霊が音符の間を気ままに遊ぶ様を見ているように。\n\nこれが父の言う、天賦の才というものか。彼もまた、深く魅了された。しかし、歩みを変えることは彼にはできなかった。\n\n彼はあまりにも凡庸で不器用な人間で、ただ苦労して敷き詰めた道を歩むことしかできなかった。\n\n皆がその人の後を追い、彼だけが、少しずつ遠ざかっていった。\n\n近づきたかった。だが彼には、演奏以外に何もなかった。\n\nどう声をかければいいのか。どんな楽譜なら、彼の心に届くのか。\n\n彼は楽譜を編み続けた。挨拶の言葉を何度も書き直すように。そして気づけば、もう声をかける機会は永遠に失われていた。\n\n深い後悔が彼を溺れさせ、すべてが一瞬にして意味を失った。\n\n目に映るのは未完の楽譜だけ——すでに去った魂へ、届くことのなかった手紙。\n\n彼は心血を注ぎ、そしてその楽譜の前に倒れた。夢の中でさえ、道の果ての光には触れられなかった。\n\nもし道の終わりにたどり着けないなら、この一生の執着は何のためだったのか。\n\n遠い笛の音が、光の中から響いてきた。問いに満ちた彼の魂を、静かに慰めるように。\n\nぼんやりとした意識の中で、彼は笛を拾い上げた。そして知った——彼の真の使命を。\n\n永遠に止まることなく演奏し続けること。永遠の安らぎを、もたらすために。"
  },
  CollectionHall_127127_Title = {
    Text = "永遠の鎮魂歌"
  },
  CollectionHall_127128_Desc = {
    Text = "たとえそれ以前の人生の記憶を失っていたとしても、発達しているとは言い難いあなたの筋肉を見れば、かつてのあなたが、運動や暴力を好むタイプではなかったことは容易に想像がつく。\n\nそれなのに、ミサゴ大学が調査員に課している戦闘基準は、あまりにも高く、あまりにも万能を求めすぎる。\nどうしてこんなにも徹底しているのか、どうしても理解できなかった。\n\n調査員にとって重要なのは「調査」ではないのか。\n鋭い知性、緻密な論理、そして少しばかりの、ちょうどいい幸運。\nそれこそが本分ではないのだろうか。\n\n毎朝きっかりと、ラモンナに寮の布団から引きずり出され、がらんとした訓練場に立たされ、幾度となく繰り返される攻撃を受けるたびに、あなたはドール教授の皮肉に満ちた論理学の講義を恋しく思った。\n山のような課題も、髪が抜け落ちそうな試験問題でさえ、戦闘訓練で何度も殴られ、倒される痛みに比べれば、ずっと優しいものだった\n\n19回目、すべての動線を封じる細剣に追い詰められ、あなたはついにバランスを崩し、尻もちをつくように地面へ倒れ込んだ。\n全身の骨がばらばらになりそうな感覚に襲われる。\n荒い息をつきながら、額の汗を力なく拭い、もう二度と立ち上がるものかと、頑なに地面に座り込んだ。\n\nラモンナは、少しも意外そうな顔を見せなかった。\n美しい剣の花を描いて剣を収め、小気味よい靴音を響かせながら、あなたの方へ歩み寄ってくる。\nあなたはぎゅっと目を閉じ、あらゆる叱責と批判を覚悟して頭を抱えた。\n\nだが、不思議なことに、、叩かれたり罵られたりすることはなく、3秒後に目を開けると、そこには淡い微笑みを浮かべた顔があるだけだった。\n\nラモンナは少し腰をかがめ、白い手袋に包まれた手をあなたに差し出す。\n「本当によく頑張っているわ。私はちゃんと分かってる。でも、私たちが向き合うのは、いつだって未知の恐怖と危険よ。私でさえ、思いがけない事態に目が届かないことがあるんだから」\n「だから……私を少し安心させると思って、もう一度だけやりましょう。ね、私のパートナー。」"
  },
  CollectionHall_127128_Title = {
    Text = "パートナーの特訓"
  },
  CollectionHall_127129_Desc = {
    Text = "人間は歌うのが好きな生き物で、荒星人も同じだ。\n旋律は喉から自由に湧き出し、意図や目的はない。\n風により音符は散り、感情と共に消えていく。\n砂漠では、すべての流浪部族が自分たちの歌を持っているという。\nしかし、荒星人は自分たちの歌を失った。\n\n歌と共に失われたのは名前も同じ。\n誰も荒星の元の名前を知らない。\nこれは呪われた星だ。干ばつ、嵐、飢饉……\nさまざまな災厄が次々と現れ、ついに荒星を完全に崩壊させた。\n華やかな衣装の大人物たちは方舟に乗って去り、荒星は名実ともに荒星となり、祝福されない底辺の人々だけが残された。\n彼らは皆、見捨てられた。\n\nそれ以来、荒星人は決めた。彼らには笑いも詩も歌も必要ないと。\n彼らは見捨てられた苦しみと痛みを忘れず、白い砂漠を這い続ける。星が滅びるその時まで。"
  },
  CollectionHall_127129_Title = {
    Text = "縛られた歌"
  },
  CollectionHall_127130_Desc = {
    Text = "ほとんどの場合、死は静かにやってくる。人間の意識がまだ反応する前に、死神は静かに近づき、その若く脆弱な生命を奪う。\nしかし、知られていない砂漠のどこかに、琥珀色の死神がいるという伝説がある。彼女は宣告を発した後、琥珀の火、琥珀の銃で琥珀色の死をもたらす。\n男は月夜の砂海に立ち、銃を握る手が絶えず震えている。彼はケティグラの琥珀色の姿をじっと見つめ、少しも油断しない。\n冷や汗が彼の額から滴り、彼が連れてきた人々の心に落ちた。彼が連れてきた人は多いが、今はほとんど役に立たない。\n彼は理解できなかった。ただの無人の倉庫を襲撃する依頼に従っただけなのに、なぜ伝説の死神に出会うのか。\n「その死神？ただの退屈な噂話だよ。」\nケティグラは何事もないように言った。\n「私はそれらを琥珀色に塗ったことがあるかもしれない。もしかしたら、まだ剥がれていない塗料が見つかるかも？」\n彼女は目の前の人に手に持った二丁の銃を見せた。\n「銃口の琥珀色の火は、ある種の特殊な物質を撒いたものだ。」\n彼女の指が銃口に入り、一周回転して少しの不明な粉末を取り出した。\n「いわゆる死神は、かつての私が作り上げたイメージだ。」\n「それは強大で、神秘的で、万能だ。」\n「それは無能な小悪党を威嚇するのに役立つ。」\n彼女は傲慢に言い、目の前の人のますます凶悪な目つきを全く気にしなかった。\n彼女は誰も気にせずに話し、危険が近づいていることに全く気づかなかった。\nその銃弾が彼女に向かって降り注いだとき、彼女の目には驚きと混乱が浮かんだ。\n潜在意識の中の興奮と狂気を隠すためだけに。\n…………………………\n銃声が止み、すべてが彼女の思った通りになった。\n彼女は戦場の中央に立ち、周りのすべてが焦げ跡で満たされていた。\nケティグラは二つの動作をしただけ——銃を上げ、射撃した。\n彼女が長銃を上げたとき、死神はすべてのものの背後に舞い降り、平等に死の予兆を降ろした。\n彼女が引き金を引いた後、火はすべてを覆い、世界に琥珀色の花海を捧げた。\n「それらは私と共に多くの年月を過ごし、無数の血と死を目撃した。」\n「それらはかつて嘘の衣をまとわされ、私の弱さを隠すために使われた。」\n「今、それらはもはや噂ではない。」"
  },
  CollectionHall_127130_Title = {
    Text = "琥珀色の死"
  },
  CollectionHall_127131_Desc = {
    Text = "「後悔しているの？」\n琉璃の杯から蘇った古の神が彼女を嗅ぎ、虚無のように彼女の肩に漂い、窓を開け、淡い香りを伴う夜風を送った。\n「私が眉をひそめれば、連なる城壁に狼煙が上がる。私が微笑めば、四方の流水が珍品と異獣、蜜酒と珍味を運んでくる。私は王朝で最も貴重な宝物なのに、なぜ後悔する必要があるの？」\n彼女は微酔のために顔を赤らめ、クスクス笑いながら、絹と毛皮の積み上げられた高いベッドの枕に埋もれてうとうとしていた。\n…………\n「後悔しているの？」\n線香の煙に宿る古の神が彼と対話し、かすかな煙が楼閣を流れ、開いた花の蕾を描いた。\n「彼らは争いに疲れ果て、私はただ座って利益を享受するだけ。高く登るほど、落ちるのも激しい。私のように、何でも持っている者には、後悔する暇などない。」\n彼はにやにや笑いながら酒を満たし、手近な枝を取り、籠の中で鳴く虫をからかった。\n…………\n「後悔しているの？」\n井戸から這い出た古の神が彼女の耳元で笑い、漂う霧が彼女の髪を撫で、一輪の白玉蘭を枝から揺らした。\n「私は愛があり、絆があり、日没に帰る時の温かい粥があり、集まり祝う時の美酒がある。どうして後悔するの？もちろん後悔なんてしないわ。」\n彼女は花を摘んで鬢に飾り、暖かい黄の蝋燭の影が彼女のスカートの裾に揺れ、彼女の目は窓辺に張り付き、待ち人を見つめていた。\n…………\n「後悔しているの？」\n逃亡する彼女のスカートは宮門前の汚れた泥で汚れ、昨日は親切に贈り物をした衛兵は彼女の哀願を聞かず、二本の冷たい剣戟が交差して彼女の唯一の逃げ道を封じた。\n霧は静かにため息をつき、一輪の紅梅が雪地に咲き、次の雪で完全に埋もれた。\n…………\n「後悔しているの？」\n檀木の箱からこぼれた南海の真珠が青い煉瓦に砕け、地に落ちる音はかつての音楽よりも心地よかった。\n彼が最も愛し、毎日鑑賞していた書画が堂前に転がり、妙手絶筆の墨痕山水が刀の先で破られ、彼が見て見ぬふりをしていた戦火に焼かれた国土のようだった。\n霧は嘲笑しながら漂い、そして火が起こり、彫刻された梁と画棟は前朝の余燼に消えた。\n…………\n「後悔しているの？」\n彼女が舌先で呼んだ名前の主は二度と戻らず、遠くの川辺には枯れた骨、枕には美人。\n彼は天子の門生で公主の婿になったのか？彼は花の中に十年も留まり帰らなかったのか？彼は流民の腹に葬られ、災後の余糧となったのか？\n霧は曖昧に低吟し、彼女の苦しい問いに答えを与えなかった。\n\n王朝が栄える時の最も貴重な宝物は、王朝が傾く時の最も貴重な副葬品となる。\n家族が繁栄する時の最も悠々たる寵児は、家族が衰退する時の最も理想的な捨て子となる。\nそして最後の物語は、世の中にはあまりにも多すぎる。"
  },
  CollectionHall_127131_Title = {
    Text = "無駄に眉をひそめる"
  },
  CollectionHall_127132_Desc = {
    Text = "陰鬱な雲がロンディニウムの空を覆い、月光を遮っている。真夜中の鐘が鳴り、高い煙突はまだ高温の黒煙と水蒸気を噴き出している。雪の結晶は風に舞い、地面に落ちる前に灰色に染まり、街灯に落ちてすぐに灯火の熱で溶け、通り過ぎる少女の上に滴り落ちる。\n少女は茶色のドレスを着て、袖が大きすぎて無造作にまくり上げられ、痩せた腕が露出している。彼女は苦労して小走りし、時折袖を引き上げ、前を行く女性を追いかけようとする。\n女性は少女を横目で見て、舌打ちした。「早くしなさい、遅く歩けば行かなくていいと思わないで」\n「はい、ママ、」少女は急いで女性のそばに走り、息を切らしながら言った、「ごめんなさい、ママ」\n「ママと呼ばないで！」女性は少女の腕を掴み、引きずるように歩調を速めた、「血を吸う穀潰し、あなたがいなければこんなところに落ちぶれることはなかった」\n「ごめんなさい……」\n「黙れ、役立たずめ」女性の爪が少女の腕に食い込み、深い痕を残した、「言っておくけど、これからは工場がお前の家だ、私を探しに来るなんて考えないで、死んでも会いたくない、わかった？」\n「わ……わかりました」少女は頭を下げ、落ちた涙が靴に踏まれ、汚れた雪水と共に石畳に消えた。遠くの工場が終業の笛を鳴らし、一匹の野良猫が路地を駆け抜け、細かい音が二人の足音に消えた。彼女たちは角を曲がり、洗濯物が干され湿気を放つ裏庭を通り、金属の門がある建物の前で立ち止まった。\n「ここで待ってなさい、」女性の声は非常に落ち着いていて、少し無表情だった、「夜が明ければ中の人が出てくる、彼らがあなたを受け入れてくれる。\nついて来ないで、さもないと殴り殺すわよ」\n女性は振り返り、同じく痩せて少し猫背の姿がすぐに暗闇に消えた。少女は無力に自分の手を握りしめ、女性が去った場所を見つめながら、袖で顔の涙を拭った。\n彼女の背後から薄暗い光が現れ、鉄の門と彼女の影を長く引き伸ばし、一つの手が少女の肩に落ち、少女を驚かせた。\n「かわいそうな子、一人でここにいるの？」来たのは若い女性で、修道女のような服を着ていた、「さあ、サラお姉さんが中に連れていってあげるわ。すぐに寒くなくなるよ」"
  },
  CollectionHall_127132_Title = {
    Text = "冬の夜の追憶"
  },
  CollectionHall_127133_Desc = {
    Text = "「私の代表作ですか？うーん——そんなに気になるの？まあまあ、VVIPのリクエストですからね。でも、普通の話し方では私のマジックマスターの名にふさわしくありません。壮大なショーでお見せしましょう！\nさあさあ、VIP席にお座りください。金と裏切りに満ちたミステリー・ハッピーマジック・リコレクションショーが始まります！」\n-------\n指を鳴らすと、ライトが点灯し、カーシアのマジックハットが空中に浮かび、黄色い口が開閉し、カーシアの声が聞こえてきた。\n「昔々、そんなに遠くない場所に、サーカスがありました。サーカスにはウサギ、道化師、ライオン、象がいました——」\n帽子の揺れに合わせて、中からウサギ、道化師、ライオン、象が落ちてきた。伴奏のドラムビートがますます速くなり、礼砲の爆発音が響く中、豪華な衣装を着たカーシアが帽子から飛び出し、帽子を自分の頭にかぶせた。\n「最も重要なのは、才能に恵まれたマジシャンの見習いがいたことです！」\n-------\n見習いの成長は拍手に伴い、豪華な服を着た投資家をも引き寄せた。奇妙なことに、投資家が彼らと一緒に旅を始めてから、ウサギ、道化師、ライオン、象……多くの人や動物が次々と姿を消した。舞台は半分空になり、見習いはそれに気づかないかのように、元の生活を繰り返していたが、投資家が彼女に一杯の酒を差し出すまでだった。\n見習いは酒を飲み、気を失い、舞台は暗転し、微かなため息が闇の中に漂う。\n「それが初めて後悔を知った時でした」\n-------\n「でも、後悔だけじゃ足りない。私はもっと知りたい。投資家が泣くときの感情、観客が笑うときの感情、もっともっと知りたい。その時——\n私は目を開けました」\n紙製の花火が空中で炸裂し、紙吹雪が舞う。\nカーシアが突然舞台中央に現れ、帽子の縁を叩くと、礼帽が口を開き、眩しい光を放った。\n「私は目を開け、すべての感情が光であり、私のマジックハットに収められることを発見しました。\nさあ、リラックスしてください、親愛なるゲスト、次のステージは少しも痛くありません。ただ少し麻痺し、生活が少し退屈に感じるだけです……」"
  },
  CollectionHall_127133_Title = {
    Text = "マジックショー"
  },
  CollectionHall_127134_Desc = {
    Text = "クレメンタインは体の強い子ではなかった。奇病にかかり、病痛と迫り来る死に苦しむとき、彼女はいつも深夜に目を覚まし、無言で泣いていた。\nそして泣いた翌日には、彼女の枕元に「贈り物」が現れるのだった。\n豪華に包装されたキャンディー、流行の髪飾り、愛らしいぬいぐるみの熊……\nしかし、彼女に最も印象深かったのは、虫の蛹の標本だった。\nその時、彼女はすでに重病で、ベッドから起き上がれず、標本を持ち上げて光を透かして見るのが精一杯だった。\nその命はすでに眠っていたが、永遠の命を得ていた。\nそして彼女は、真の死に瀕していた。\nそう考えると、彼女の涙は静かに流れ落ちた。しかし、ある手が彼女の涙を拭ってくれた。\n「泣かないで、クレメンタイン。いつか君もこの蛹のように、新たな命を得るんだ。」\n「僕が君に新たな命を与えるよ。」\n父は決して嘘をつかない、少なくとも彼女には嘘をつかないので、クレメンタインはこの言葉を信じて疑わなかった。\n彼女は父を信じていたので、その冒涜の山に入るとき、迷わず進み、血肉が溶けるような激痛に耐えるとき、何の不満もなかった。\n彼女はこれが新たな命を得るための代償であり、必要な過程だと信じていたから。\nすべての苦痛と絶望が過ぎ去ったら、彼女は治り、「家」と呼ばれる場所に戻り、唯一の家族と再会するのだ。"
  },
  CollectionHall_127134_Title = {
    Text = "隠された痛み"
  },
  CollectionHall_127135_Desc = {
    Text = "彼女は夢を見ない。\n\n若い彫刻家の見習いは、絶対的な理性と秩序を信じていた。それは彼女の冷たい作品のように。\nしかし、それを初めて見た瞬間から、彼女は魅了された。\n柔らかく、純粋——それは完璧な着色素材だった。\n彼女は月光の下で忙しく働き、乱葬地から黒い粘液をアトリエに持ち帰った。\n\n一週間後、《@2》という名の彫刻が博覧会で展示された。\nその夜、彼女は遠くからの波の音を聞いた。\n彼女は初めて夢を見た。\n静かな朝の光の中で、埃に覆われた海底の宮殿が眠っていた。\n彼女は白いサンゴの中を歩き、孤独と忘却の息吹を感じた。\n\n目覚めると、彼女の指は縮こまり、黒くなり、最後には白いサンゴが生えていた。\n彼女は何度も嗅ぎ、そこに古代からの無数の生物の囁きを感じた。\nそれは本当に柔らかい化石だった。\n彼女は神経質に笑った——これが夢を見ることなのか。\n彼女はアトリエに閉じこもり、夢中で創作を始めた。\n型取り、粘土細工、着色……\n混沌とした、有序な。無機的な、有機的な。\n\n彼女は永遠に夢を見る。"
  },
  CollectionHall_127135_Title = {
    Text = "珊瑚の女の死"
  },
  CollectionHall_127136_Desc = {
    Text = "母親、お母様。\n\nマーフィーはそれに関するほとんどの記憶を、とうに失ってしまっている。\n\nある人は言った。瀕死の母親は彼女を庇い、隠したが、母親の血で窒息寸前であったのだと……\n\nそして人々が駆け寄り、無理やり彼女たちを引き離したのだと。\n\nマーフィーは、その瞬間の母の顔を見ていた。\nその顔は狂気に満ちていたが、とても美しかった。\n\n物心ついてから、彼女には新しい「母親」ができた。\n\n彼女は穏やかで思慮深く、マーフィーのあらゆる無茶な要求も満たしたが、つかず離れずの距離を保った。\n\n彼女たちの関係は——ミリアムの表情が永遠に変わらないように——このまま続いていくとマーフィーは思っていた。\n\nしかし、そんな折、彼女は高く掲げられて漆黒の王座に座らされ、夢の中でリン光を放つ「卵」を見た。\n\nそれは暗闇の中でキラキラと輝き、目のようであり、星のようでもあった。\n\n聖域の周囲には、幽玄な歌声が響き渡っていた。\n\n<Italic:その娘の@1から、@1の神が@1へと降臨する……>\n\n彼女は、自分に関係しない偉大な使命を与えられた。\n神を復活させるための母親となることだった。\n\n本当に不思議だ。彼女はまだ、母親とは何か、娘とは何かを理解していないのに、「母親」になることを学ばなければならない。\n\nマーフィーは母親の狂気に満ちた美しい顔を思い出し、舌の上の甘く苦い味を思い出した。\n\nあの美しい人は、わたくしがこのように墓に落ちることを望んでいないのでは？\nそうでしょう？"
  },
  CollectionHall_127136_Title = {
    Text = "秘められた誕生"
  },
  CollectionHall_127137_Desc = {
    Text = "ワンダの正確な素性について、カンブリアの村人たちは様々な説を唱えている。\n\nある者は、ワンダが巨大な石に乗って湖に落ちてくるのを見たと言った。\n\nある者は、彼女はヴォルムワヒ出身の女ファラオで、ミイラの針の様な脊椎が彼女の背中にもあるのを見たと言った。\n\nまたある者は、彼女はフラン高地から来た女公爵で、4人の夫を次々亡くして、巨額の財産を相続したと言った。\n……\n\n噂は風のように消え、村人たちは耕作し、織物をし、そして粉を挽き続ける。\n\n苦しい年月、重い税金は頭上にぶら下がる刃のようであり、あらゆる余計なものや夢想を断ち切った。\n\nただ……女王が住む湖の森を通るたびに、木々の間から聞こえる音楽が、村人たちの心をたやすく捉えた。\n\nそれは、ここにあるべきではない旋律だった。\n\nあまりに快く、怠惰であり邪悪にさえ聞こえる、悪魔のささやきのようだった。\n\n「おいで、すべてを捨てて」\n\n「慈悲深き王は湖の中央に座し盲目の僕の奉仕を静かに待っている……」\n\n\nそして風のない夜、ある疲れた村人が農具を置き、忍び寄る好奇心を満たすことを決意した。\n\n彼は森を回り込んで、小さな橋を渡った。\n道端には花が咲き乱れていたが彼は見向きもしない。\n\n彼は緑色の湖面を見た。\nその湖は低く垂れ下がる星空とつながるかのようで、その縁の中に古城がそびえ立っていた。\n\n\n棘茨の冠をかぶった女王は湖の城の中央に座り、巡礼の民を辛抱強く待っていた。\n\n彼女は手を差し出し、人間からの口づけと崇拝を楽しんだ。\n\n雲は散り、月が昇る。\n\n女王は彼の背骨に脊椎針を突き刺した。\n\n麻痺させる液体が血管に沿って広がり、彼は地面にひざまずいた。\n\n四肢を切り落とされ、両目を抉り取られた。\n\n\nこうして、大地の重力は彼を引きつけることができなくなり、彼のすべての詩と夢は、ただその女王だけに捧げられた。\n\n彼はついに自分の運命を迎えたのだ。"
  },
  CollectionHall_127137_Title = {
    Text = "女王の戒律"
  },
  CollectionHall_127138_Desc = {
    Text = "「終日の苦行を続ける者よ、この贈り物があなたの魂を温めますように。父なる神の慈愛が胸の苦しみを癒やし、甘美な夢をもたらしてくれますように。」\n銀霜夜も終わるころ、蝋燭の火は低く垂れていた。久しぶりに重い石板を脇へ置き、サルバドルは厳かな法衣を脱いで、あたたかな赤い毛織の装いに着替える。明日の冬渡節のため、彼はわざわざダフォダイルの小さな店へ出向き、ミサゴの学生たちに向けたサプライズプレゼントを用意してきたのだ。\n「これが最後のプレゼントですね…………」\nサルバドルは学園の片隅にある古い椅子に腰を下ろし、疲れのあまり無意識のうちに夢の底へ落ちていった。\nそれは温かく甘い夢だった。足元のプレゼントの箱がいつの間にかそっと開き――四体のジンジャーブレッドマンがぱっと飛び出す。アイシングで描かれた瞳はきらきらと輝き、シナモンとクローブの香りが冷たい空気の中で輪を描くように舞い踊る。\nその香りが封じられていた記憶を呼び覚まし、彼は幼い頃の教会の回廊へと戻った気がした。舌先で溶けたタフィーの甘さがさらに過去を思い出させた。苦痛と疫病に侵された祝福の数々が、この濃厚で甘い円舞曲とともに、静かに息を吹き返していく。\n…………\nその頃、四つのこそこそした影が、眠りに落ちたサルバドルへそっと近づいていた。\n「ご主人…………ご主人は、私たちを悪い子だって思うかな…………」\n「ふふーん――オレッタは気になりすぎるの！早く開けようよ〜。ひとつ、ふたつ…………わあ、ジンジャーブレッドマンがいっぱい！」\n「だ、だめ…………名前を言っちゃったら、もしかして…………みんなに嫌われちゃう…………！」\n「へへっ、盗もうと思ってるわけじゃないよ！やったのは全部ブラウンってことで！」\nサルバドルは小さなジンジャーブレッドマンたちがぺちゃくちゃと話し合うのを耳にし、ひとつが膝の上に飛び乗るのを感じた。シナモンの香りがする息遣いが、皺だらけの手の甲をくすぐる。\nいや、夢の中のジンジャーブレッドマンではない。現実の、いたずらっ子たちだ。プレゼントの箱をこっそり開けたときの、子どもたちの幸せそうな笑顔が目に浮かぶ。その一瞬の美しさと幸福、そして安らぎのためなら、彼はあらゆる苦しみを背負うことも厭わない。\n「おや…………私の髭が。髭と髪を結んで遊んでいるのですか？」\nサルバドルはまだ眠っているふりをして、子どもたちの楽しい「秘密の作戦」をそのまま続けさせた。"
  },
  CollectionHall_127138_Title = {
    Text = "箱の中の童心"
  },
  CollectionHall_127139_Desc = {
    Text = "あなたとラモンナは再会の約束を交わしたことはなかった。\n扉が目の前でゆっくりと閉じていく刹那、二人の胸に定められた別離の期限は、すでに永遠として確定していた。\n\nだから、時の裂け目の中、瞬きのように過ぎ去る邂逅の中で、彼女がそっとあなたの小指に指を絡めたとき……\nそれは予期せぬ、そしてこの上なく幸運な再会だった。\n「あなたは全然変わっていないわ」彼女は言った。\n\nその一言のために、指先の微かな温度のために……たとえ二つの世界に隔てられていようとも、あなたはすべてを投げ打ち、銀河を越えて彼女に会いに行くことを厭わない。\n来年の今日、小指を絡め、再び誓いを交わそう。"
  },
  CollectionHall_127139_Title = {
    Text = "再び会う運命"
  },
  CollectionHall_127140_Desc = {
    Text = "「撤退、撤退！」\n「@3に向かって撤退！急げ！」\n「助けて、助けてくれ！置いていかないで！」\n「彼は放っておいて、早く撤退しろ——アルバ！」\n銃剣を持った兵士が一気に飛び出し、砲火が彼女の側で炸裂し、兵士の戦いの声、悲鳴、急な戦争の号角が一体となって響き渡る。血液が土を黒く染め、硝煙の匂いすら覆い隠せない濃厚な血の匂いを放ち、倒れた兵士たちの目は空洞で、どの色の軍服もこの瞬間には眩しい赤に変わっていた。\nアルバは歯を食いしばり、次々と彼女に攻撃してくる者たちに向かって進んだ。彼女は見えていた、助けを求める若者が、地面に押さえつけられ、両手で高い敵軍のナイフを必死に防いでいる。\n爆発する銃声と激しい痛みが同時に襲い、近くの敵がゆっくりと倒れ、アルバはすぐに振り返って刀を振り、足の痛みに耐えながら前に力強く突進し、敵がバランスを失った瞬間に相手の胸を貫き、同時に引き金を引いた。\n弾丸が体に入り血肉を飛び散らせ、彼女は顔を適当に拭い、若者の安全を確認しようと振り返ったが、彼はいつの間にかいなくなっていた。\n彼女は下を見て、ナイフが左膝の上から彼女の脚を貫いているのを見た。温かい血液がどくどくと流れていた。\n彼女はマントから布を裂いて脚の根元に巻きつけて血流を何とか抑え、銃剣を仮の杖として足を引きずりながらチームに追いついた。"
  },
  CollectionHall_127140_Title = {
    Text = "不屈の意志"
  },
  CollectionHall_127141_Desc = {
    Text = "歴史とは常に勝者の独壇場だ。\n母樹の消滅、国家の転覆など、過去に関するすべては、静かに姿かたちを変えられている。\n\n詩人はニニバーの美女の物語を歌い継ぎ、旅人たちは焚き火を囲んで耳を傾ける。\n\n「銀色の砂漠を越え、異国の美女がニニバーに踏みいる——\n\n天の川の水が、その肩を滑り落ち。シナイの真珠が、その瞳からこぼれ落ちる——\n\n黄金の瞳の奥には異国の過去が映り。蜜色の肌には、ニニバーの未来が記されていた——」\n\nその後どうなったのか？\nこの美女は王妃になったのか？\n\n年老いた詩人は七弦琴を爪弾きながら、長いため息をついた。\n\n「彼女は媚薬——\n人々は皆、彼女に酔いしれる。\n\n彼女は猛毒——\n王と臣下の肺腑に染み渡る。\n\n彼女は洪水——\n人々は皆、逃れられぬ。\n\n彼女は黒い疫病の使者——\n疫病と、悪夢と、死、そして、ニニバーの終焉をもたらした」\n\n琴がまだ置かれぬうちに、酒卓のそばから一人が立ち上がり、酒客たちの視線を集めた。\n\nその人物の細い指の間から数枚の酒銭がこぼれ落ちる。金銀が転がり、チリンと音を立てた。 \n\n彼女の歩む先を視線が追従し、灯火がきらめいた。\n\n「時は流れゆく……\nだけど構わない、あのお方はこんな戯言には応えない……\n\nいつかあなた達も、あのお方の慈悲と寛容を理解する……\n私がそう理解したように……」\n\n彼女は酒場の古びた小さな扉を押し開けた。まるで宝石箱を、開けるように。\n\n月の光が露わな肩に降り注ぎ、きらめく光を映し出した。\n\nその月の光に愛された美女は、まさに蜜色の肌をしていた。"
  },
  CollectionHall_127141_Title = {
    Text = "慈悲の育み"
  },
  CollectionHall_127142_Desc = {
    Text = "温室で目を覚ましたとき、すでに大火は庭全体を覆い、彼女の目の前に迫っていた。\n温室のドアは外から鍵がかけられ、空気には強い酒精と油脂の匂いが漂う。彼女はコレットの名前を大声で呼び続け、声が煙でかすれるまで叫んだが、応えるのは大火の轟音だけだった。\n\n彼女は安堵した。\nよかった。コレットは外出している。\nこんな火事では彼女も危険だった。\n\n彼女は悲しかった。\n人生の最期の瞬間に、親友に会えなかったことが。\nコレットが戻ってきて、焼けた庭と自分を見たら、きっと悲しむだろう。\n\n彼女は後悔した。\n2人の生活は良くなり始めていたのに、この炎がすべてに終止符を打とうとしている。\n\n燃える。\n家が燃える。空が燃える。葉が燃える。花が燃える。\n庭園で過ごした数々の光景が、彼女の眼前で次々と浮かんでいき、流れていく。\n彼女が庭に連れてきてくれたこと。\n彼女が薔薇を渡してくれたこと。\n彼女が一日の労働の末に柔らかいパンを持ってきてくれたこと。\n彼女たちが遊び、追いかけ、静かな陽光の下で寝そべり、伯爵夫人の部屋に住む日を夢見てたこと。\n\n燃える。\n過去が燃える。未来が燃える。\n庭はすべての物語と感情を抱えて、狂ったように燃えている。\n\n涙が彼女の頬を滑り落ち、炎の熱で消えていった。\n\n彼女は美を感じていた。詩の中では、痛みも後悔も美しいのだ。\n彼女は周囲を見渡し、炎に侵された紙とペンを見つけた。\n\n感謝、愛着、未練、祝福、美。\nその美しさすべてをコレットに残したい。\n\n「……コレットへ。オルラ、炎の中より」\n詩の結びに、彼女は最後の署名を残した。\n\n100メートル先、庭園の向かいの道で、コレットは何かを感じたように足を止める。\n彼女が顔を上げると、激しい炎が彼女の顔を照らしていた。\n\n涙が彼女の頬を滑り落ち、炎の熱で消えていった。"
  },
  CollectionHall_127142_Title = {
    Text = "詩の結び"
  },
  CollectionHall_127143_Desc = {
    Text = "彼らは暗い川を漕ぎ進み、青白く、静かで、疲れ果てていた。\nぼんやりとした霧が触腕を伸ばし、彼らを暗闇に引き込み、終わりのない夜をさまよわせた。\n\nやがて、彼らは一筋の光を見た。\nそれは遠くの岸辺からの日の出で、ちらつきながらも、暗い魂を照らすには十分だった。\n彼らはその光を頼りに、不器用に暗闇を抜け、夜明けの前にたどり着いた。\nそしてあなたたちの前にも。\n\nそれは短い出会いかもしれないが、彼らは力強く手を振り、必死に叫んだ。\n皆が神聖な曙光を浴び、皆が笑っていた。\n彼らは言った——\nすべての出会いの瞬間が祭りのように貴重でありますように。\n誠実な心が永遠に鼓動し続けますように。\n銀の鍵が道を照らさんことを"
  },
  CollectionHall_127143_Title = {
    Text = "極夜と暁"
  },
  CollectionHall_127144_Desc = {
    Text = "風が四方から吹き寄せ、あなたは蝋燭を持って迷宮の入口に立っている。\n少し混乱している。\nついさっきまで、ミサゴの食堂でシャーロットが図書館の地下迷宮の伝説を話していたのを聞いていたようだ。\nそして今、あなたはパジャマを着て、眠そうに次々と通路を歩いている。\n「シャーロット、シャーロット……」\nささやかな音と共に、白い蜘蛛が波のように押し寄せる。\nそれらは白い少女に凝結し、肉塊で作られたブランコに座って揺れている。\n\n「来たのね」彼女は言った。\n「シャーロットを探しに来たんだ、友達なんだ。彼女は迷子になった、見つけなきゃ……」\nあなたはほとんど泣きそうになっている。\n少女はくすくす笑い、ブランコから飛び降りてあなたの前に来た。\n「忘れたの？あたしたちの取引……」\n少女は手を伸ばしてあなたのお腹に触れ、はっとした。\n「そうだね。もうあたしの奴隷になっているから、何も覚えていないんだ」\n「奴隷……？」\nあなたは肌が触れ合う場所を感じた。\n温かい感触が蜘蛛の巣のように皮膚の下に入り込み、血管の奥深くまで広がっていく。\n少女は神秘的にウインクし、あなたの耳元でささやいた：\n「シャーロットは、あなたのお腹の中にいるのよ」"
  },
  CollectionHall_127144_Title = {
    Text = "蒼白の末裔"
  },
  CollectionHall_127145_Desc = {
    Text = "大きな舞台で、一人の少女が踊っている。\n彼女の髪はきつくまとめられ、白い羽と小さな王冠が飾られている。純白の舞踏服は彼女の動きに合わせて広がり、哀愁漂うバイオリンの音色に合わせて回り続ける。\n腕を伸ばし、つま先を地に付け、白鳥は長い首を垂れ、王子に悲しみと憂いを語る。\n幼いリッツは口を開けて舞台上の軽やかで優雅な少女を見つめていた。それは彼女の従姉妹で、彼女が生まれる前から家に来て、祖母の下で厳しい訓練を受けていた。普段は質素で静かな従姉妹が今日ほど生き生きとしていることはなかった。彼女はまるで羽ばたこうとする白鳥のようで、彼女も、彼らも、劇場の全員が彼女の影に魅了されていた。\n彼女の心臓はどんどん速くなり——なんて羨ましい！彼女もあの白鳥になりたい、永遠の舞台に自分の影を長く残したい。彼女は自分ができると知っていた。祖母が彼女の足を長くてまっすぐだと褒めたことがあるではないか？長年首席を務めた従姉妹が彼女に舞踊の才能があると言ったことがあるではないか？そう、彼女が始めれば、彼女がトウシューズを履けば、人々は遠くの街から公演を見に来るだろう。彼女は今世紀最大の舞踊家、バレエ芸術の輝かしい星となるだろう！\nその時の彼女はまだ知らなかった、自分を待っているのは熱い炎だけだ。"
  },
  CollectionHall_127145_Title = {
    Text = "回れ回れ"
  },
  CollectionHall_127146_Desc = {
    Text = "それは、あなたがミサゴへ来てから一年目のことだった。\n\nあの大爆発から目覚め、初めてこの学校の門をくぐった日のことは今もよく覚えている。\n整った制服が支給され、自分だけの寮部屋が与えられ、初めて食堂を訪れて二皿分の食事をぺろりと平らげた。\n楽な時間はその日限りで終わった。\n知識が貧弱すぎることと、乳児並みに滑らかな脳回路とやらのおかげで、予科クラスへの一年間の強制入学が告げられる。\n\n言語学習、体力訓練、シルバーコア能力の測定、特殊生物の知識補習……多くの試験を経ても、成績はまちまち。\nライ国共通語は赤点だったが、一度に三人の覚醒体とリンクを成功させたという話で一躍キャンパスの有名人になった。\n\n幸運にも、あなたの特異な能力と優れた素質のおかげで、調査員としての基準にはすぐに達し、予科課程の延長は免れた。\n足りない部分は、次第に絆を深めてきた仲間たちが補ってくれた。\nここには魔物のような教師も多いが、信頼できて優しい魔物たちだ。\n\nこの地は曇天と雨が多く、晴れの日は少ない。\n忘れられた者たち、そしていずれ忘れられる者たちが、それでも立ち続け、犠牲を払い、前へ進み続けている。\n\nそんな何気ない一日に、ミサゴはまた新たな一年の始まりを迎える。\n鏡の前で制服の襟を整え、皺をひとつひとつ撫でる。\n寮のドアを開き、外へ踏み出す。\n\n「ふぁ〜……ようやく来たな。我は、眠ってしまう所だったぞ」\n「寮の中で巣作りでもしてたの？新入生くん」\nあなたはロータンにぎこちなく笑い返し、生理的な恐怖を感じるピンク色の姿に思わず首をすくめて、ラモンナとオジールの後ろにそっと隠れる。\n\n早朝のキャンパスで、五つの影が並んで揺れながら伸びていく。\n「行きましょう、パートナー」\n「今日からあなたも、正式にミサゴの一員よ」"
  },
  CollectionHall_127146_Title = {
    Text = "入学の日"
  },
  CollectionHall_127147_Desc = {
    Text = "テムズ川沿いを下り、右に曲がってベックマン通りに入り、約100フィート進むと、その目立たない角に「ライカー探偵事務所」が見えてくる。\n\nロンディニウムで最も解決率の高い探偵事務所でありながら、ここには専門書でいっぱいの大きな本棚も、切り抜きが貼られた壁も、優雅なアフタヌーンティーもない。\n大抵の場合、あなたが出会うのは「外出中」の看板と、そばで寝そべる疲れた老犬だけだろう。\n\n運が良ければ、晴れた日曜の朝に、二日酔いで帰ってくる名探偵に会えるかもしれない。\nその時、彼は賭け事を終え、ポケットにはほとんどお金が残っていないので、あなたは無理な依頼を思い切り頼むことができる。猫探し、カルトに入った母親の救出、夫の浮気の証拠集め……\nあなたが持っている限り、彼は受けてくれる。\n\n「死の間際の瞬間を楽しむから、俺はギャンブラーになる運命なんだ」\n「じゃあ、探偵になるのは？失礼ながら、猫探しと死の間際の関連性が見えないんだが」\n「いや、君は分かってない……真実を探す過程自体がすでに魅力的なんだ、大きさに関係なく。それはまるで……」\n「死とのデートに向かうようなものさ」"
  },
  CollectionHall_127147_Title = {
    Text = "幸運の時"
  },
  CollectionHall_127148_Desc = {
    Text = "ポリュクスは夢を見た。\n彼は銀色の鎧をまとい、威厳ある王から月のように光る長剣を受け取った夢を見た。\nそして彼は高い白馬に乗り、洞窟へと向かい、地底に入ると洞口の木々が微かに囁く音を立てた。\n洞窟の奥には暗緑色の影が潜んでおり、それは肉山のように巨大な敵で、奇妙な目から緑の光を放っていた。\n「国を害する敵よ、私はあなたが我々の神聖な国を脅かすことを許さない。今日、私はこの正義の剣であなたを滅ぼす！」\nその怪物は震え、まるで応えるかのように恐ろしい叫び声を上げた。\nポリュクスはその言葉を理解できず、理解しようともせず、剣を振り上げ、邪悪な気を放つ敵と戦い始めた。敵の触腕が洞窟の暗い境界に広がり、光る長剣とぶつかり合い、鋭い音を立てた。\nすべての英雄物語の結末のように、勇敢な騎士は敵の背に乗り、怒りの中で剣の先を敵の胸に突き刺した。\n敵は崩れ落ち、ポリュクスは安堵の息をつきながら、剣の下でゆっくりと広がる痕跡を見つめた——その醜く邪悪なものの体から、どうしてこんなに温かく鮮やかな赤い血が流れるのか？\n彼は夢から突然目を覚まし、その血が手に付いた粘り気が消えないように感じ、彼の視界の端にカストルが大切にしていた古い本がベッドの後ろの隙間に慎重に隠されているのを見た。\n彼はその本を無造作に開き、ちょうどカストルがよく読んでいた騎士の物語のページに当たった。ページの中央にはこんな予言が書かれていた：\n「邪悪な敵が勇者に倒されたとき、誰もが空に異変を見、太陽は暗くなり、月は血に変わる。」\nポリュクスは眉をひそめ、軽蔑してその古い本を元の場所に投げ戻し、月光の下で呟くように祈り始めた。\n「神の僕がここに遣わされ、あなたたちに祝福を与え、罪を洗い流し、暗闇から光へと導き、すべての純潔な義人と共に浄土に入る……」\n灯を持つ者は彼の敬虔な従者に目を向けず、悪夢がもたらす不安はその心臓の奥深くで震え続け、それは彼の熟睡する魂が夢の中で静かに泣いているのだった。"
  },
  CollectionHall_127148_Title = {
    Text = "歪んだ騎士詩"
  },
  CollectionHall_127149_Desc = {
    Text = "<Bold:1月24日>\n体が臭い。\n今日はテレサ家政婦と一緒に帰る途中、サウサンプトン区を通った。\n楽しい体験ではなかった。\nそこは危険な場所@2奇妙な傷がある人がいた、三角形の穴のような。\nテレサ家政婦は、これは異教徒への神の罰だと言った。\n\n<Bold:2月22日>\n1ヶ月の発熱。\n今日はやっと何か食べた。新鮮なステーキ、柔らかくてジューシー……\nそう、ジューシー。\n赤い@2生臭くて@2美味しい\n家の鏡は全部片付けられ、ボビーさえも私を見ようとしない。\nふふ。彼らは知らない、夜になると窓の影で自分の姿が見えることを。\n顔、首、胸……上から下まで、びっしりと、\n黒い@2三角形が生えている\n\n<Bold:3月17日>\n目の膜が赤いヴェールで覆われたようだ。\n世界が血の色に@3\n父が血の霧の中で私に叫んでいる、こんなに大声で話すのは初めてだ。\n彼は近くにいるのに、声は遠くに感じる。絶望、嫌悪、血の匂いがする。\n連れていかないで@2、連れていかないで……"
  },
  CollectionHall_127149_Title = {
    Text = "暴食寓話"
  },
  CollectionHall_127150_Desc = {
    Text = "エリウィン人は灰色の石の街に住み、緑の大湖の隣にいる。\n\n大湖には名前がなく、エリウィン人の記憶が始まる前から存在していた。\n伝説によれば、邪悪な妖精が湖の深くに封印されている。\n彼女は湖と同じくらい古く、宇宙の始まりに粗雑に作られた恐ろしい存在だ。\n純真で臆病なエリウィン人は妖精を恐れ、彼女を喜ばせて湖底に静かに留まらせようとした。\n\n「何かしなければならないのでは？」\n「そうだね、何かしよう」\n「じゃあ踊ろう！何があっても、踊るのはいいことだ」\n\nこうして、満月のたびにエリウィン人は湖畔に集まり、紙草で作られた偶像の前で踊った。\nその時、月は明るく星は少なく、すべてが平和だった。\n\n数百年後、エリウィン人は歴史を忘れ、寓話を忘れ、偶像も忘れた。\n石の街の千年記念祭で、彼らは思い切り笑い、美酒を飲んだ。\n騒がしい声が湖に投げ込まれ、石が水に落ちるように、無限の円が湖の中央から広がり、最終的に深い存在に触れた。\nこうして、満月の時にエリウィン人は音の範囲外の音を聞き、視覚の範囲外の月と炎を見た。\n彼らは最終的に静寂の一部となった。\n\nこの無限の空間の中の永遠の静寂はエリウィン人を恐怖で満たした。\n彼らは神秘主義者のようにじっと座り、新しい人々が彼らの前で思い切り笑い、美酒を飲み、行き来するのを見た。\nだから宇宙は永遠に膨張し続け、銀河はますます遠くなり、すべてのものが消えていく。\nそれが現実だ。\nエリウィン人がそれで孤独を感じるかどうかはまったく重要ではない。"
  },
  CollectionHall_127150_Title = {
    Text = "無声の宴"
  },
  CollectionHall_127151_Desc = {
    Text = "少女は目を開け、暗闇の中にいることに気づいた。\n「おい！」彼女は叫んだ、「誰かいる？」\n声は見えない境界の中で揺れ動き、徐々に消えていき、少女は深呼吸して再び叫んだ：「お姉ちゃん、ブラウン、西区！」\n「誰かいるの——」\n前より大きな声の問いかけが遠くに漂い、ゆっくりと戻ってきた。いくつかの青白い光が共鳴に引き寄せられ、遠くから近づいてきた。それらは無数の浮遊する微細な粒子で構成され、蛇のように空中を進み、波のようにうねる。光の帯が次々と立ち止まることなく少女の周りを通り過ぎ、瞬く間に天地を星の海に変え、微細な粒子が少女の指や髪の間を通り抜け、痕跡を残さなかった。\n「これは……何？」\n光る塵が彼女の周りで微かに揺れ、答えはなかった。\n「蝋人形館を覚えている、お姉ちゃんを覚えている、私は……死んだみたい、ここは天国？」彼女は周りを見回し、「天使もいないなんて、地獄じゃないよね！」\n彼女の声は自分の耳に届き、今回は共鳴すら現れなかった。\n説明しがたい孤独感が彼女の心に生まれ、ぼんやりと、彼女はお姉ちゃんやブラウンに出会う前に戻ったようだった。暗い下水道の臭いが漂い、彼女は寒くて空腹だったが、誰かが彼女を押し込んだ後、下水道の上に大きな桶を置いたため、出られなかった。\n彼女は自分の顔を軽く叩き、歩き始めた。\n塵は彼女の前で分かれ、後ろで再び集まった。足を上げ、足を下ろし、足を上げ、足を下ろし。彼女はずっと歩き続け、どれだけ歩いたかも、どれだけ遠くに来たかもわからなかった。彼女の前にはさらに多くの塵と暗闇があり、彼女の後ろには、来た方向も歩いた道も、何の痕跡も残っていなかった、そして——\n「召喚成功、ジェンキン、ジェンキン、聞こえる？」"
  },
  CollectionHall_127151_Title = {
    Text = "迷いの道"
  },
  CollectionHall_127152_Desc = {
    Text = "創生の父なる神は星空より降り立った。\n\nその時、大地は赤く燃える熱土であり、烈火がが燃えていた。父なる神は炎の上に足を踏みしめた。\n\n父なる神は言った「火はやがて鎮まる」火はそうあった。\n\n流れる土は地となり、父なる神はその地に神言を刻んだ——\n『地は生ける物の基となる』\n\n谷は谷となり、平原は平原となった。\n\n神言は揺ぎ無く、これが第一の石板である。\n\n父なる神は厚い雲を見て言った「雲はやがて雨を降らせる」\n雲はそうあった。\n\n雨は流れとなり、父なる神はその上に神言を刻んだ——\n『水は命の温床となる』\n\n水は湖となり、海となった。\n海は地を覆った。\n\n神言は揺ぎ無く、これが第二の石板である。\n\n父なる神は水の暗さを見て言った「光が降りるべきだ」\n光はそうあった。\n\n光はが水に降り注ぎ、父なる神は光の上に神言を刻んだ——\n『光は命を育む』\n\n光は暖かさをもたらした。\n\n神言は揺ぎ無く、これが第三の石板である。\n\n父なる神は揃った地、水、光を見て言った「生命は訪れる」\n\n父なる神は自身の血を流し、その上に神言を刻んだ——\n『血は新たな命を生む』\n\n父なる神の血は広がり、生命あるものとなり、海で繁殖した。\n\n神言は揺ぎ無く、これが第四の石板である。\n\n父なる神は生命の誕生を見て言った「生き物は永遠に変化する」\n生き物はそうあった。\n\n微細な存在が引いた海の地を這い上がった。\n父なる神は変化するものに神言を刻んだ——\n『変化は止まることがない』\n\n陸に上がったものは根を張り、四肢を持ち、様々な姿へと変化した。\n\n神言は揺ぎ無く、これが第五の石板である。\n\n父なる神は生があり、変化もあるのを見て言った「死は訪れる」\n死は訪れた。\n\n老いた者は死に、病弱な者は死んだ。父なる神は死の上に神言を刻んだ——\n『死者は始まりへと還る』\n\n死者の体はゆっくりと消え、父なる神の懐に戻った。\n\n神言は揺ぎ無く、これが第六の石板である。\n\n父なる神は生、死、変化がすべてあるのを見て言った「これらは我が遺物であり、我は祝福を残す」\n\n父なる神は自身の骨を取り出し、その上に神言を刻んだ——\n『万物の終わりに、我が骨を使い、我が権を代行せよ。\n血肉の代価により生を与える』\n\n神言は揺ぎ無く、これが第七の石板である。\n\n父なる神はすべてが整ったのを見て、休むことにした。\n水は父なる神を包み、光は父なる神を暖かくし、地は父なる神を覆った。\n\nそして父なる神は永き眠りにつき、万物は父なる神の残された神言に従い生きる。\n\nそれが今の世界である。"
  },
  CollectionHall_127152_Title = {
    Text = "神言の石板"
  },
  CollectionHall_127153_Desc = {
    Text = "彼は万事を知る王であり、リモリアの至高である。\nラピスラズリは彼の王座であり、黄金は彼の冠である。魂は彼の権威であり、彼は最上で安眠する。\n神に仕える祭司も彼に仕え、彼の前にひれ伏す。\n彼らは彼の忠実な臣下であり、彼の敬虔な信徒である。\n\n神は夜に月光を送り、彼を永遠の眠りの宮殿に招く。\nそこでは、神々が彼と魂の食事を分かち合い、神の知恵を授ける。\n神々は彼に終わりなき夢を与え、彼は万物の始まりと時間の終わりを観る。\n彼はこうして知るのである――万物の始まりは混沌であり、神々はその中で目覚め、暗闇に浮かぶ宮廷を築いたことを。\n彼はこうして知るのである――時間の終わりは暗闇であり、すべてが混沌に帰ることを。\n\n王の中の王よ、神の寵児よ、\n誰があなたに匹敵しようか？\n誰があなたのように夢から統治し、誰があなたのように威厳を持つであろうか？\n\n尊き神王よ、若き支配者よ、\nどうか存分に熟睡あれ。\nあなたの臣民と信徒は、あなたが神の予言を持ち帰るのを辛抱強く待つのだ。\n\n敬愛なるルルイエの支配者よ、深淵の主よ、\nどうか我らがあなたの御名を呼ぶことを許し、庇護を与え給え。\n――トゥルー、トゥルー。"
  },
  CollectionHall_127153_Title = {
    Text = "神王の讃歌"
  },
  CollectionHall_127154_Desc = {
    Text = "長年、私はユウハシュを思い続けてきた。\nしかし、この神殿の廃墟で初めて彼をはっきりと見た。\n彼は重い鎖に纏着され、地面に伏せ、首を伸ばして腐った食物に近づこうとしていた。\nまるで犬のように。\n\nカリグラの死後、暴君の共犯者として、彼は神殿の廃墟に縛られ続けている。\n私は手の鎖を引き、トレスの奴隷を連れてきた。\n彼はすぐに立ち上がり、瞳孔が広がり、喉から急な飲み込み音を出した。\n\n「待て」\n私は鎖を引き、奴隷を彼が届かない距離に引き寄せた。\n「一人を殺してくれ」\n彼は口を開け、鋭い牙を見せて笑った。\n「君は19人目だ、人間よ、だが断らざるを得ない」\n私は失望を隠し、顔を引き締めた。\n「なぜ？」\n「千人を殺せと言うなら喜んでやる。一人？君の条件は足りない」\n「その一人が、今の皇帝ならどうだ」\n私は深呼吸をした。\n「この条件で十分か？」\nユウハシュは大笑いした。\n「それは数学の問題だ、古い友よ。一は一、千は千だ」\n\n「火事だ、金宮が燃えている！」\n遠くで炎が燃え上がった。\n暴君、暴君……\n私は絶望して泣いた、セネカのためにも、廃墟となる豪華な宮殿のためにも。\n「そんなに悲しいのか？」\nユウハシュが近づいてきた。\n彼はトレスの奴隷を楽しんだ後で、満足そうに口をすぼめていた。\nそう、私は彼に約束した、暴君を殺せば、自由の他に千の無実の命を楽しむことができると。\n彼はこの火事が何を意味するか理解できるのか？\n彼は治らない暴君に仕えることが何を意味するか理解できるのか？\n恐らくできない。\n彼はただの獣だ。\n\n「ローマは廃墟のようだ」獣が言った。\n「あるいは、君たちの国、世界……\n私には、意味もなく終わりもない廃墟に見える。\n君たちはそれのために涙を流し、互いに殺し合い、無駄で意味のないことをしている……\n正直、理解できない」\n\n私は彼の傷だらけの体を見た。\nそれは数百万の血肉で作られたゴーレムで、数百年の間に何度も壊され、再構築されてきた、まるでローマのように。\n「では君は？君も廃墟なのか？」\n「多分ね」\n彼は伸びをし、細長い目に遠くの金色の炎が躍っていた。\n「でも気にしない」"
  },
  CollectionHall_127154_Title = {
    Text = "血肉の宴"
  },
  CollectionHall_127155_Desc = {
    Text = "ルルイエの主よ、どうか私の祈りをお聞きください。\n\nあなた様の予言を授け、啓示をお与えください——あなた様の王国を復元できますよう。\n\nさすればこの信仰なき地、この海に囲まれた氷原にて、石柱を立て、あなた様の神殿を築きましょう。\n\n深淵を統べる主よ、祭壇に捧げたるはあなた様への供物。\n\n純なる肉体は満月の子羊より、強き心は成牛より、鋭き眼は空を翔る雄鷹より、堅き骨は巡洋の鯨より。\n\nラピスラズリはあなた様の王座、黄金はあなた様の冠。\n\nどうか私に夢を授け、神の言葉をお告げください——あなた様の御身を復元できますよう。\n\nさすればこの氷下の深淵にて、この海底の領域にて正しき刻に生まれる母体を捧げましょう。\n\n万象を知りたるリモリアの王よ私の祈りにお応えください。\n\nあなた様が海に沈み、眠りにつかれ、幾千年が過ぎました。\n\n私はあなた様の御名のもとに、あなた様の御業を広め、その尊き御名を讃え続けてきました。\n\n揺るぎなきは、私の信仰。\n誠実なるは、私の心。\n\nあなた様こそ、唯一の神王。\n不朽なる者の化身。\n\nこの、待ち望む時を終わらせ、再びこの世に降臨し、どうか、あなた様の叡智の言葉を、再び私にお聞かせください。"
  },
  CollectionHall_127155_Title = {
    Text = "信仰の力"
  },
  CollectionHall_127156_Desc = {
    Text = "オレッタが生まれた時、大洪水の影響は都市から完全に消えていたが、遠くの村では人々が生き延びるために奮闘していた。\n\n洪水は人々に海や川への恐怖を植え付け、去れる者は去っていった。今もこの小さな漁村に残っているのは、外で居場所を見つけられない女性や子供たちだけだった。\nこの静かで冷え切った場所で、オレッタは唯一の子供だった。\n\n彼女は祖母が語る童話を頑なに信じていた——両親は海に戻り、オレッタが成長するのを待っている。彼女が成長すれば、皆が再び幸せな家族として再会できると。\n\n彼女がまだ話せなかった頃、温かい抱擁の中で眠ったことがあるようだが、他の両親に関する記憶はオレッタにはほとんどない。\nしかし、静かな場所で生まれ育った子供として、オレッタは「孤独」や「寂しさ」を理解していなかった。彼女には独自の友達がいた。\n\n洪水に怯えた大人たちとは違い、オレッタは海を恐れたことがなかった。\n海の王国の住人として、自然と海と友達になった。\nオレッタは「同郷」の仲間たちと遊ぶことを覚えた。\n彼女はハマグリの動きを真似て踊り、クマノミのように海草の間を泳ぎ回った。\n彼女はオサガメの背に乗り、波に乗って遠くの海まで漂流した。\n満月の光が注ぐ海で、クラゲたちと海中で戯れた。\n\n彼女は幸せで、想像力豊かで、精霊のようだった。\n\n彼女は夢だった。\n"
  },
  CollectionHall_127156_Title = {Text = "海の夢"},
  CollectionHall_127157_Desc = {
    Text = "田舎の娘が派手なドレスや金銀の装飾品、羽扇を身にまとい、上流社会に潜り込むなんて……\nこれ以上不適切なことはない。下克上、まさに下克上……！\n私の意見では、下層の者には相応の識別マークやバッジを強制的に付けさせるべきだ。\nそうすれば我々と混同されることはない。\n——フィリップ・ハロルド公爵\n\nもしロンディニウムに住んでいるなら「ソレール効果」について聞いたことがあるだろう。\n自分の服が売れないことに悩んでいる？\nそれならソレール夫人の目に留まることを祈るべきだ——\nそう、たとえそれが愚かしい豚の尻尾帽子でも、ソレール夫人が被れば大ヒットする。\n彼女は新時代の大衆アイドルなのだから。\n——「ソレール夫人の人気テスト」《淑女の心得》\n\nそれは晴れた夏の夜だった。\n私たちは大理石のテラスに座り熟成された貴腐ワインを飲みながら詩と世界平和について語り合った。\nそして@4が起こった——要点を言え？\nこほん、すまない……\nとにかく、この女性は私から3000スタール、スリランの不動産2件、そして誠実な心を騙し取った！\n——匿名希望の心痛の子爵"
  },
  CollectionHall_127157_Title = {
    Text = "薔薇の名において"
  },
  CollectionHall_127158_Desc = {
    Text = "分かれる。経験する。群がる。侵略する。\n\nペリシテ人のセム語の語根「p-l-sh」の真の意味について、学者たちは常に意見が分かれている。\n生まれて初めて、ゴリアテはこれらの学者たちが少しは本物の知識を持っていると感じた。\nこれらの四つの短い言葉は、彼のペリシテ人としての人生をほぼ要約しているからだ。\n\nペリシテ人は名実ともに海の民だ。\n彼らは群れを成す長尾のサメで、血の匂いを頼りに住む島を見つけ、そこにいるすべての原住民を殺す。\n\nペリシテ人は疲れを知らない。\n彼らは決して留まらず、すべてが終わると、落ち着かない遺伝子が彼らを駆り立て、新たな獲物を探しに行く。\n\nペリシテ人は明日を気にしない。\n彼らは驚くべき速さで略奪した富を浪費し、最後の一滴のワインを飲み干し、繁殖し、争い、裏切る……\n\n出航の時、ゴリアテは船が海面に残した軌跡を振り返る。\nペリシテ人の血、原住民の血、敵の血、海鳥の血……\nそれらは一つに混ざり、暗赤色のインクが無限の青に流れ込むようだ。\n\n翌日、太陽はいつも通り昇り、海水は無数の金の破片のように揺れ輝き、すべては跡形もなくなる。\n彼らは海にいるが、海はすでに彼らを忘れている。"
  },
  CollectionHall_127158_Title = {
    Text = "巨人の刃"
  },
  CollectionHall_127159_Desc = {
    Text = "カシュリアには沈没文明の伝説が伝わっている。\n\n歴史記録以前に、星辰の異常な移動がある先史文明を海底に沈めたとされ、カシュリア人はその文明の子孫だという。\n商業や漁業の他に、カシュリア人が海に出る大きな目的は、失われた祖先の文明を探すことだった。\n特定の星辰の位置の刻に生まれた少女が祖先の文明と感応し、沈没文明の位置を指し示し、船団を風浪から守ると彼らは信じていた。\n\nシレストはそのように選ばれた。\n彼女は白い帆を高く掲げたマストに縛り付けられ、下の人々の忙しさを見ていた。\n彼女は関心も興味も持たなかった。\n\nシレストは海風や海鳥の動きから海上の天気を感じ取ることができ、時には遠く眠る地からの気配を探知することもあった。\n彼女は生まれつき海に、航海に属しているのだろう——シレストはよくそう思い、拘束されている事実は彼女の心に何の波紋も起こさなかった。\n時々彼女はマストを離れ、海空を飛ぶ白い鳥を追いかけ、その時船は彼女を追い続けた。\n人々は少女が航海の順調の象徴であり、祝福された船は無事に帰港し、多くの富と先進的な文明をもたらすと信じていた。\nしかし、彼女はそれを何も知らなかった。"
  },
  CollectionHall_127159_Title = {
    Text = "導きの帆"
  },
  CollectionHall_127160_Desc = {
    Text = "トントン、トントン。\n足音が遠くから近づき、シルクハットをかぶった紳士が廃墟を通り、瀕死の看守の前に立った。\n紳士：ここで何をしている？\n\n（紳士は重度の吃音症で、看守は話を引き延ばすのが好きだ。読みやすくするため、会話の要点のみを抜粋した）\n\n看守：私は監獄を見張っている。\n紳士は周囲の誰もいない荒野と、融蝕に染まりゆっくりと崩壊する廃墟の残骸を見渡した。\n紳士：しかしここには監獄も囚人もいない。君の王国はもう存在しない。\n看守：私は監獄を見張っている。\n紳士：なぜ？\n看守は顔を上げ、幼さの残る顔に茫然とした決意を浮かべた。\n看守：わからない……家に帰りたい。\n看守：あの方のために監獄を見張っている。あの方が喜べば、私は家に帰れる。\nその方が誰で、なぜ見張るのか、彼女自身もわからない。\n紳士は追及せず、それが当然のことのように振る舞った。\n紳士：君の故郷はどんなところ？\n看守：そこには冬と夜だけがあり、果てしない森と海がある。\n紳士：住むには適していないようだ。\n看守：私は昼が嫌いだ。見ての通り、私は蝋でできているので、太陽に触れると消えてしまう。\n看守：だからここに隠れているしかなく、自分で帰ることはできない。\n紳士は考え込んで頷いた。そして突然興奮した。\n紳士：偶然だね、君は蝋でできていて、私はちょうど蝋人形師だ。\n紳士：約束しよう——君を日光の下で歩かせ、帰り道を見つける手助けをする。代わりに、君は私の助手になってほしい。\n看守：助手って何をするの？\n紳士：私の蝋人形館を見張ってほしい。こことは違って、それは芸術だ。芸術は崩れない。\n看守：芸術ってそんなにすごいの？\n紳士は嬉しそうに笑った。\n紳士：そうだ、そんなにすごいんだ。\n\n物語の結末、看守は紳士について行った。彼女がこの監獄に来たのと同じように、成り行き任せの性格だった。\n彼女はいつも成り行きに任せるタイプだった。"
  },
  CollectionHall_127160_Title = {
    Text = "欲望の海"
  },
  CollectionHall_127161_Desc = {
    Text = "あなたは、人影ひとつない荒れ果てた原野へと足を踏み入れた。\n人類の営みの痕跡はとうに失われ、魂の干からびた生き物たちが、灰と塵の中を苦しげに彷徨っている。\nここでの生は、羨むに値しない。\n旅路の終着点を知る者はおらず、ただ果てなき循環の光景の中で、彷徨い、彷徨い、彷徨い続ける。\nやがて歩みは重く鈍り、彼らは地に倒れ伏し、天を仰いで、呼び求める手を差し伸べる——\n\nどうか、私の彷徨が終わったその先で、\n屍と化した骨が沃土となり、養分となり、源泉となって、か弱き新芽が再び大地を突き破りますように。"
  },
  CollectionHall_127161_Title = {
    Text = "滅土からの再生"
  },
  CollectionHall_127162_Desc = {
    Text = "彼女は闇の底で幾度となく問いかけた。なぜこれほどの苦しみを負わねばならないのか、と。\n答えるものは誰もいなかった。\nその声は、神の耳に届くこともなかった。\n\n痛みは日に日に増し、より濃く、より黒い憎しみへと変わっていった。\nある日突然、彼女は気づいた。周囲の者たちから滲み出す黒い液体が、自分の血と寸分違わぬことを。\n彼らは、たちまち狂い果てた。まるで、かつての自分のよう。\n彼女はただ冷ややかに眺め、悦んだ。\n\nしかし、それが苦しみであるなら、自分とて、とうに呑まれていたはずではないか。\n彼女は残された黒い泥へと近づいた。そして、自由を得た。\n\nだが自由は解放をもたらさなかった。地獄に千年を流された悪鬼のように、かつて抱いた願いはすでに憎しみによって腐り果てていた。\n肉は枷に食い込み、魂は鉄球につなぎ止められていた。\n\nただあの凄烈な叫びだけが、彼女の重い魂を洗い、その胸を満たした。\n\n「さあ、私が味わったものを味わうがいい。おまえも——この紅に、染まれ。」\n\n紅は、これほどまでに美しい色だったのか。\n痛みに理由などない。彼女はついにそれを悟った。\n\n自ら飲み干すか、他を誘うか。\n今夜、彼女は血の杯をなみなみと注ぎ、街ごと宴に招いた。\n"
  },
  CollectionHall_127162_Title = {
    Text = "深紅に沈む"
  },
  CollectionHall_127163_Desc = {
    Text = "船が何かにしっかりと纏着され、プロペラが苦しそうに回転し、恐ろしい音を立てていた。\n積乱雲が頭上に集まり、黒い雲の中で雷が渦巻いていた。\n雷がマストに落ちた瞬間、プロペラは束縛を解かれ、再び回転を始めた。\n私は安堵の息をついたが、機関長は叫び始めた。\n\n海水に混じった粘り気のある液体が、嵐の野外で風に乗って遠くへ運ばれ、私の鼻には死の匂いしか感じられなかった。\nしかし、私はその蛍光を放つ液体が何らかの血液であることに気づいた。\n私の最愛の仲間、最も信頼する船は、沈む前に全力を尽くした——彼女の海を切り裂くはずのブレードは、敵の触腕を激しく切り落とした。\n\nこれは幸運の兆しだ！私たちはすぐに嵐を抜け出せる！\n私はこれで船員たちを安心させようと思ったが、顔を上げた瞬間、暗い海の中央に光が現れた。\nそれは灯台だろうか？そんなはずはない。いや、あり得ない。\nここは大洋の中央で、最も近い陸地は数百海里も離れている。どうして人が、どうしてここに灯台を建てられるのか？\n\n私の水夫たちは泣き始め、祈り始め、故郷の歌を一斉に歌い始めた。\nそして、その灯台は突然消えた。\nすべての光が消え去り、荒れ狂う嵐も静かな小雨となって甲板に降り注いだ。\n水夫たちは慈悲深い主を讃え、生き延びた喜びに浸っていた。\nしかし、私ははっきりと見た。\n\nその光の中に消えたのは、確かに優雅な女性の姿だった。"
  },
  CollectionHall_127163_Title = {
    Text = "暴風雨の中で"
  },
  CollectionHall_127164_Desc = {
    Text = "英雄がついに偉大な旅を終え、人々は絵本の最後のページを閉じ、深い眠りに落ちる。\n\n長い夜が訪れ、ヘロットの物語は始まったばかり。\n\n彼女は長い海岸線を北へ進み、小川を渡り、高山を越え、極寒の地の果てまで行った。\n世界を驚かせた反抗から何年も経ち、ヘロットが訪れる場所は風も雨も順調で、すべてがうまくいっていた。奴隷と主人の間には微妙なバランスが保たれ、激しい反抗は滑稽に見えた。\n彼女は疑われ、嘲笑され、最後には忘れ去られた。\nしかし彼女は決して弁解しなかった。\n\n戦士ヘロットは姿を消し、自由の種を地中海の奥深くに埋めた。五年、十年、百年……\nいつかそれらは土を破り、力強く成長するだろう。\n\nこのスパルタの殺し屋の最期の埋葬地を知る者はいないが、かつての親友イバミノンダが彼女の遺体を収めたと言われている。\n何年も後、ジャスミンの花が咲く草原を通り過ぎるとき、小さな墓碑が見えるかもしれない。そこにはこう書かれている：\n\nこの草の下には戦士が眠っている、または\n彼女はかつて戦士だった\n彼女は古いペリクレスの娘であり、デロス島の誇り\n詩人フラカスは彼女の勇敢な戦いを称賛した\n黒髪のスパルタ人は彼女の功績をよく知っている"
  },
  CollectionHall_127164_Title = {
    Text = "鎖を断ち切る日"
  },
  CollectionHall_127165_Desc = {
    Text = "A. F.@1年@1月@1日\n\n08:00\n\n部品107から133の組み立てを行う。\n\nCタイプの部品はこれで最後、完成後はオートマタ「チクタクマン」のエネルギーコアとして使用される。\n\n自分で組み立てたかったが、@2が言うには、責任者は仲間を信頼することを学ぶべきだと。\n\nよく言うよ、彼女こそが部品を夜中までチェックしているのに。\n\n-------\n\nA. F.@1年@1月@1日\n\n00:21\n\nモーターMF311000の組み立て完了、ギアは合っていて、パイプも通っている。現在すべての機能は正常。最終調整を行う。\n\n13:07\n\n特殊エネルギーSを接続、モーターMF311000は良好に動作し、EA307850号の人工体と適合、人工体は正常に動作。\n\n@2は楽観的で、今回は前よりも進めると思っている。私は彼女に第五回覚醒試行時のことを忘れないようにと注意したが、彼女は耳を塞いで聞こえないと言った。あの時、私が素早く反応しなければ、エネルギーコアの自燃の火が彼女の髪を焼き尽くしていただろう。\n\n彼女に一度スキンヘッドを味わわせるべきだ、そうすれば慎重さを学ぶかもしれない。\n\n-------\n\nA. F.@1年@1月@1日\n\n14:55\n\n最終準備完了、エネルギー準備完了、拘束装置が起動、拘束状態：良好。胴体は覚醒完了後に取り付ける。\n\n15:00\n\n「チクタクマン」第13回起動試行開始。\n\n15:05\n\n胴体EA307853は正常に動作、モーターMF311000も正常。「チクタクマン」の首関節は正常に動き、頭部部品も正常に動作。\n\n15:15\n\n「チクタクマン」は瞬き、視線追従、口開け指令を成功。モーターに発熱現象があるが、許容範囲内。\n\n四肢部品の取り付けを行う、神よ、どうか今回うまくいきますように。\n\n18:07\n\n歩行指令を実行中に、モーターコアが溶解、配線が焼損。特殊エネルギーSは無傷。\n\n@2はこの特殊エネルギーを非常に大切にしており、私でさえ触れることを禁じられている。理解できる、それは確かに神秘的な物体で、見た目は普通の銀の金属のようで、エネルギーを蓄える能力があるようには見えないが、本当にオートマタにエネルギーを供給でき、高温でも損傷しないのは驚くべきことだ。\n\nもしこれが大量生産または大量採掘できれば…………\n\nいつか彼女に再度尋ねるべきかもしれない、彼女がこの人形にどれだけの時間を費やすのかもわからない。いつか彼女自身が人形になっても驚かないだろう。\n"
  },
  CollectionHall_127165_Title = {Text = "核溶解"},
  CollectionHall_127166_Desc = {
    Text = "「私たちは凡庸な金と鉄で星の軌道を測るが、深淵は独自の計算を持つ」ケッパーサントが巨大な船上で詠む。彼女は船の引導者として死を迎えたが、今は永遠に光を与える稲妻のような存在となった。"
  },
  CollectionHall_127166_Title = {
    Text = "聖火の導き"
  },
  CollectionHall_127167_Desc = {
    Text = "彼女は死と共に生まれた呪われた子、不祝福の娘と呼ばれた。\n\n彼女と妹の「産着」が破れた瞬間、輝かしい光が割れ目から溢れ、地に根を下ろした。\n瞬く間に草が枯れ、花が灰になり、遠くの木や湖の魚さえも彼女に生気を吸い取られ、無魂の殻となった。\n\n彼女の一族の者は驚愕し、他のすべての繭を急いで移した。\n彼女は雛鳥が殻を破るように、己の繭を破ろうとした。\nしかし、差し出したその手は、嫌悪の表情に避けられる。\n\nただ一人、後から生まれ、先に成熟した彼女の妹だけが、いつでも彼女を抱きしめてくれた。\n\n彼女は霊鳥のさえずりのように子守唄を歌ってくれる。\n\n眠れ、眠れ、愛しい姉さま。\n眠れ、眠れ、きっと良い夢が、訪れる。\n\n彼女は存在するべきでなかった。彼女がいなければ、妹が罪の影に染まらことはなかった。\n\n私のかわいそうな妹……あの子は常に思っている「姉さまが背負った、本来負うべきでない生の代価を、私は知ってる」\n\n私はかわいそうな妹……あの子は常に思っている「姉さまのために、私は必ず力を尽くす」\n\n眠れ、眠れ、愛しい妹。\n眠れ、眠れ、夢の中でも、愛している。"
  },
  CollectionHall_127167_Title = {
    Text = "捕食者の子守唄"
  },
  CollectionHall_127168_Desc = {
    Text = "彼は教会の尖塔が蝋燭のように溶け、神父の白い翼に滴り落ちるのを見た。ステンドグラスの聖人像は瞬く間に骸骨に腐り、また瞬時に赤子に戻る。鋭い幾何体と柔らかな幾何体が信者の口から唱えられ、ホールを埋め尽くす。\n彼は駅の空間が非ユークリッド空間に折り重なり、遠くのプラットフォームがすぐ近くに、近くの改札口が遥か彼方にあるのを見た。ホールの時計は逆回転し、骸骨のような群衆が見えない線に引かれて後退し、濃厚な紫の煙が雲から列車の煙突に漂い込む。\n彼は森の「空」が実体化し、木々、岩、蔓が「空」の境界線で描かれた半透明の輪郭線に過ぎないのを見た。白鳥の羽は絶えず変化するモザイクの色ブロックで、彼らが泳ぐ場所では湖水が半透明のステンドグラスに凝固する。恋人たちが寄り添うベンチの下で、鮮やかなオレンジ色の影が主人の足首を噛もうとしている。\n彼はオペラハウスの音符が雨のように観客席に降り注ぐのを見た。墓地が微かに起伏し、まるで呼吸する巨大な怪物の皮膚のように……\n彼は多くのものを見た。それを母親、教師、友人に伝え、見たものを絵に描いた。彼は自分の目に映る世界を人々に見せたかったが、彼の周りの人々はますます少なくなり、世界は彼から遠ざかっていった。\nしかし、なぜだろう？彼はただ見たものを記録しただけだ。ピックマンは理解できなかった。\n悲しむピックマンは鏡の前に立った。彼は食屍鬼が彼に向かって鋭い歯をむき出しにしているのを見た。\n「真実を目撃することほど重要なことはない。狂気、混沌、貪欲……見に行くかい、ピックマン？」\n悟ったピックマンは微笑み、鏡の中に足を踏み入れた。\n彼はただ、最も極端な狂気の真実を目撃し、それを忠実にキャンバスに描きたかった。\n彼は人間でも食屍鬼でもない。\n彼はただの写実主義の画家、ピックマンだ。"
  },
  CollectionHall_127168_Title = {
    Text = "写実主義の逆説"
  },
  CollectionHall_127169_Desc = {
    Text = "すべての過去と未来を知ることができる者に待つのは、全知の喜びではなく、無限の悲しみと絶望。\n彼女の目は万物に繋がる糸を見通す。糸の片方は過去に、もう片方は未来に繋がっている。\nその糸は運命と呼ばれる。\n彼女は周囲の人々をどう見ているのだろう？\n人々は善良で慈愛に満ち、人々は傲慢で疑い深い。\nだが彼らの運命と人類の運命は出会った瞬間に既に決まっている。\n彼女は彼らを愛しているに違いない、でなければ何度も手を差し伸べ、火種を与えることはない。\n彼女は彼らを期待しているに違いない、でなければ破滅の中で輪廻の影に進むことはない。\n愛ゆえに、彼女は悲しみを抱く。\n期待ゆえに、彼女は何度も失望する。\n彼女は黒い泥沼に沈み、無数の黒い糸を絶えず解きほぐし、飽きることなく。\n運命の札は何度も回転する。\n彼女は貪欲の炎が空を覆うのを見た。\n彼女は盲目的な偏執が自滅に向かうのを見た。\n彼女は狂気の妄念が破滅を加速するのを見た。\n無秩序の混沌はいつも遅れてやってくる。\n希望と絶望は無駄に回転し、終わりがない。\n彼女は暗闇の中で一瞬の星光を見た。\nその光は微弱だが、彼女は暗闇に長くいた。\n直視した瞬間、涙を流した。"
  },
  CollectionHall_127169_Title = {
    Text = "隠世の転輪"
  },
  CollectionHall_127170_Desc = {
    Text = "新しい年を迎えるにあたり、あなたは今までにない儀式を執り行うことに決めた。時の移ろいを、これ以上ないほど厳かに迎え入れるために。\nそのために、あなたは長い時間をかけて準備を重ねた。蝋燭に火を灯し、あたたかな光で冬の夜の学園を照らす。訓練場の中央には高台を設け、柄の入った深紅のベルベットの絨毯を敷き詰めた。さらに、金箔と銀の薄絹を合わせた無数のリボンを自らの手で作った。ただ、このカウントダウンの瞬間が別れの侘しさを超えて、年の暮れと新年が抱き合うときの、決して色褪せない印となるようにと。\nしかし…………まだ何かが足りない。\nあなたは古い倉庫の奥へと入り、幾重もの埃を払い落として、ついに一台のアンティーク時計を見つけた。外装はまだらに剥げ、針は時の侵食で折れて落ちてしまっている。明らかに、もう使えるものではなかった。\n途方に暮れかけたそのとき、タイスが現れた。彼女の背後には、いつの間にか真新しい時計が静かに立っていた。\nその時計には、見覚えがあった。彼女は相変わらず軽薄そうに笑うが、その瞳の奥にはどこか優しい確信が宿っている。\n「どう？この時計に私の踊りを添えれば、きっと最も盛大な儀式になるわ」\n「まさか…………タヴィの時計じゃないよね？」\n「あら、あなたも知ってるでしょう？あの子、池の水の中でひとりきりじゃ、あまりに退屈だわ」\n「こうして私たちの儀式に加えて、私の愛を感じさせてあげれば、少しは気分が晴れるかもしれないでしょ〜」\n真夜中がそっと訪れる。タイスが巨大な時計の前に立つ。まるで時間そのものに丁寧に包まれた贈り物のようだった。\nリボンは燃え残る花火のように彼女の身体に絡みつき、巡る灯りの下で金色の混じる赤と銀色の混じる青の波紋を揺らす。腰元のふっくらとした蝶結びは、新年が自ら結んだ最後の結び目――彼女こそが年の瀬最大の捧げものなのだ。歓びの絹に包まれ、時間に封を解かれるのを待っている。\n彼女はゆっくりと腕を上げ、指先で光と影をなぞりながら、背後に垂れ下がる時計へと指を向けた。文字盤の12の数字が光の輪となって繋がり、彼女の指先で踊る。\nミサゴの人々は、タイスの奔放な舞を仰ぎ見た。歓喜の空気に染められたように、彼女のリズムに合わせて皆の心も揺れ動いていく。\nそして鐘の音が落ちる瞬間、彼女の指先がそっと触れたのは永遠の始まりだった。縛られていた贈り物はその両腕を広げ、年の瀬に蓄えられたすべての祝祭を、空いっぱいに舞い散る祝福へと姿を変えて、人の世へ降り注がせた。"
  },
  CollectionHall_127170_Title = {
    Text = "カウントダウン"
  },
  CollectionHall_127237_Title = {
    Text = "海城旧聞"
  },
  CollectionHall_127239_Title = {Text = "磐龍国"},
  CollectionHall_129601_Desc = {
    Text = "<Title:紹介>\n世間から隔絶された海島に住む、明るく野性的な少女。\n活発な性格と生まれつきの怪力のため、初めて接触する人々は彼女の過剰な親しみやすさに適応するのが難しい。しかし、一緒に過ごすうちに、彼女は友人をできる限り助けたいと思っているだけだと気付く。\n時には彼女の助け方が常人とは異なることもあるが、結果的にはほとんどの場合、助けられた側の問題を解決しているのだろう？\n抑制を解除した状態では自身の能力を制御できず、実験室がしばしば爆発する。\n必要な教育が不足しているため、時にはモスクが手振りを交えながら相手に自分の意図を理解させるのに時間がかかる。しかし、モスクは相手が手振りをする必要はなく、彼女の卓越した直感がこの問題をうまく解決してくれる。\nノウティラと守秘者に非常に親しい。彼女の言うところによれば、三人の間には一緒に冒険する約束があったが、ノウティラはそのことを全く覚えておらず、守秘者はその経験について口を閉ざしている。\n時折、モスクのそばにミサゴの帽子をかぶったカワウソが見られ、モスクはそれを「小さな石炭球二世」と呼んでいる。その時には、あるはずの宿題がなぜか消えてしまうことがある。"
  },
  CollectionHall_129601_LockTip = {
    Text = "「モス」を召喚すると解放"
  },
  CollectionHall_129601_Title = {Text = "モス"},
  CollectionHall_129803_LockTip = {
    Text = "期間限定キャラクターイベント「疾走する陥落特急：出発進行」の任意のステージをクリアすると開放"
  },
  CollectionHall_129803_Title = {
    Text = "疾走する歓楽特急：出発進行"
  },
  CollectionHall_129810_Desc = {
    Text = "記録されえないある周回の中で、巡環のラモーナは鐘楼の裏の花壇を踏み越えた。\n視界の端に、薔薇園の中で花々が鮮烈に咲き誇っているのが映った。\n稀に見る一瞬の停滞の後、彼女はすべての無用な空想を振り捨て、最後の戦場へと駆け出した。\n泥濘が血のように濃い花弁に飛び散り、たちまち漆黒の融蝕漿に呑み込まれ、風の中に毅然たる後ろ姿だけが残された。"
  },
  CollectionHall_129810_Title = {
    Text = "泥濘を踏み越えた薔薇"
  },
  CollectionHall_130218_LockTip = {
    Text = "期間限定イベント「流転の新生：隠し部屋の手記」の任意のステージをクリアすると開放"
  },
  CollectionHall_130218_Title = {
    Text = "流転の新生：隠し部屋の手記"
  },
  CollectionHall_130219_Desc = {
    Text = "ここは、どの海図にも記録されていない島です。\nこの島が誕生して以来、「文明」と呼ばれるウイルスはこの清らかな土地に一度も足を踏み入れたことがありません。\nここには砂浜とジャングル、果てしなく広がる海、そして…………小さな少女が一人います。\n………………………………………………………………\n「パパ、ママ、魚！」\n「アオ〜〜」\n二匹のイルカがのんびりと少女の足元に泳いできて、美しい澄んだ声を発します。\nそのうちの一匹が少女を担ぎ上げ、もう一匹が少女の手にある気絶した魚を受け取り、一口で飲み込んでしまいました。\n「アオ〜〜」\n「へへ、モスク！すごい！」\n世間知らずの子供のように、少女は「パパ」「ママ」の褒め言葉に応えるように、とても力強い動作をしました。\n「今日は、太陽！いいね！」\n「モスク！パパ！ママ！散歩！」\n少女の言葉を聞いたイルカは軽く鳴き声を上げ、島を回りながらゆっくりと泳ぎ始めました。\n温かい日差しが少女に降り注ぎ、数日前の湿気と寒さを追い払い、優しい風が少女の髪を撫で、海の怠惰な息を運んできます。\n笑い声、水を叩く音、戯れ声が響く中、世間から隔絶されたこの島には「文明」がもたらす悩みはなく、最も原始的で純粋な笑いだけが残っています。\n二匹の獣と一人は、いつも通り、原始的で無邪気な一日を過ごしました。\n………………………………………………………………\nその無限の呼びかけが、この静けさを完全に飲み込むまで。\n「帰ってきて…………帰ってきて…………」\n「@1が必要だ…………@2…………@4…………必要だ…………」"
  },
  CollectionHall_130219_Title = {
    Text = "遠いエデン"
  },
  CollectionHall_130220_Desc = {
    Text = "タンポポの種は、鳥よりも小さく、そよ風よりも軽い。\n\nタンポポが最初の荒野を通りかかったとき、そこで風に転がる草たちに尋ねた。\n「君たちはどうやって繁殖するの？」\n\n風に転がる草たちは言った。\n「種をいろんなところに転がして、根を下ろせる土を見つけるまで旅をさせるのさ」\n\n彷徨う旅人には家がない……\nそうつぶやきながら、タンポポは別の風に乗って飛び去った。\n\nタンポポが次に砂漠を通りかかったとき、まばらに生えるサボテンに尋ねた。\n「君たちはどうやって生きているの？」\n\nサボテンは言った。\n「根を深く地中に伸ばし、わずかな水を吸い上げて生きるんだ」\n\n厳しい環境でもたくましく生きてるものだ。さらにタンポポは砂漠を後にする。\n\nやがてタンポポは都市の上空を通りかかる。闇夜に浮かぶ光は人の営みの証。\n長い旅の果てに、ついにタンポポの種はその地上へと舞い降りようとしていた。"
  },
  CollectionHall_130220_Title = {
    Text = "花香る世界を願って"
  },
  CollectionHall_130221_Desc = {
    Text = "アラクネは、自分が失敗する運命にあることを知っていた。\n彼女は静かに紡ぎ車を回し、日々人間の悲喜、王朝の興亡、星火のような詩と愛を、時空を超えた巨大な網に織り込んでいた。\n彼女は非常に上手に、正確で、抑制され、優しく行っていた。「間違った」ものを排除し、「正しい」ものを選んでいた。\n何世代もの人々が新たな笑顔を見せ、無数の文明が灰燼の中で新しい歴史を書いた。しかし、編織によって生まれた喜び、編織によって生じた疲労、そしてすべての柔らかな感情は、永遠の苦役の摩耗の中で静かに枯れ果てていた。彼女は自ら脆弱を断ち切り、冷静な意志だけを残し、すべての選択が責任から生じるように、弱さではなく確実にするためだけに。\nしかし、最も深い悲劇は、苦役そのものではなく、彼女がどれほど修復し、編織しようとも、世界は依然としてその静寂な虚無へ向かうことを彼女が明確に知っていることだった。文明は脆弱な砂の城のようで、潮流は必ずやってくる。彼女の努力は、観客のいない演劇であり、決して反響のない見守りだった。\n「運命はすでに私たちを永遠の孤独に定めており、なぜこの残酷な罰を受け入れなければならないのか？」\n「引き裂け、破壊せよ…………そうすればこの苦役から逃れられる…………」\n彼女は目を伏せ、余計な考えを静かに断ち切り、退屈で集中して編み続け、維持し、泣き、耐え続けた…………\nすべての無駄な抵抗、すべての解決のない運命はすでにこの網の中に織り込まれていた。\nそして網の中心で、彼女は自分自身を見つけた。"
  },
  CollectionHall_130221_Title = {
    Text = "永世に紡ぐ網"
  },
  CollectionHall_131000_LockTip = {
    Text = "期間限定キャラクターイベント「メルスケスの呼び声：モスと海」の任意のステージをクリアすると開放"
  },
  CollectionHall_131000_Title = {
    Text = "メルスケスの呼び声：モスと海"
  },
  CollectionHall_131388_Desc = {
    Text = "絢爛豪華な倶楽部の入口で、白シャツを着た案内係が片手を上げ、礼儀正しくライカ―を制した。\n「申し訳ありません、旦那様。招待状をお持ちでなく、当倶楽部の会員でもない方はご入場いただけません」\n「そうか……それは困った……」\n\nライカ―は顎を触り、考えているふりをした。\n実際には、彼は待っているだけだった。\n自分が追っている事件の容疑者を。\nそして、運命の加護を——\n\nかくして、待ち続けた甲斐はあった。\n「これはこれは、ロンディニウムで名高い幸運探偵殿ではありませんか！さあさあ、私があなたの紹介人になりましょう」\n「ぜひ一度、あなたの伝説的な運の強さを拝見したいものだ。どうか期待を裏切らないでくださいよ……」\n紳士はそう言って、穏やかそうでいて悪意を秘めた笑みを浮かべた。\n\nそんな表情はこの倶楽部では珍しくない。\n狂気を追い求めるギャンブラーたちが品行方正であるはずもないのだ。\n自分が仕組まれた罠に嵌められたと悟っても、ライカ―は気にも留めない。\nただ口元をわずかに吊り上げ、悠然とホイストのカードを手に取った。\n\n焦ることはない。\nゲームは、まだ始まったばかりだからね？\n\nそして、第一局、第二局、第三局……勝負は次から次へと続き、やがてライカ―はすべてのチップを失った。\n「幸運探偵殿、今日はついていないようですね。まあ当然でしょう、誰だって永遠に運命の寵愛を受けられるわけではない……」\n「まだ続けますか？とはいえ、あなたはもう何も持っていないようですが」\n「何も持っていない？そうとも限らないさ」\n連敗を喫した探偵は微笑み、自分を指差した。\n「この仕立てのいい服がある。高価なステッキもね。それに……」\n言葉を切り、胸ポケットから小型の装置を取り出す。\n声を落とし、にこやかにそれを弄びながら続けた。\n「君のイカサマの手口は実に見事だったよ。倶楽部の主人でさえ見抜けず、私に助けを求めたほどにね。だがどれほど巧妙でも、手口には時間がいる。操作もいる。そして……共犯も」\n「残念ながら、このミサゴ大学製の小さな装置は、君と仲間が先ほど行った不正の証拠を、すべて鮮明に記録している」\n\n紳士は一瞬凍りつき、驚愕と怒りを滲ませる。\n共犯者たちは逆上し、探偵に一発食らわせてやろうと身を乗り出す。\nしかし、多くの目が見守る中、紳士は軽率な行動を取ることはできなかった。\n何より探偵は、彼に拒むことのできない選択肢を差し出していた。\n「もう一度、賭けてみるのはどうだい？君が勝てば、この装置も、私の命も、すべて君のものだ。意味は分かるだろう？」\n「もし私が負けたら？」\n「自首してもらおう」\nライカ―は笑って肩をすくめ、輝く牙を見せた。\n「自分が負けるとでも？本当のギャンブラーは、自分の勝ちしか信じない」\n\nそう、すべてのギャンブラーは自分が勝つと思っている。\nだから誰もがこの賭けを拒めない。\n\n再びホイストのカードが卓上を巡る。\n配り、差し込み、すり替え、そして、決着。\n\n「うん、ラッキーだね」\n敗者を一瞥もせず、ライカ―は笑いながら札束を空中に放り投げる。\nもともと騒然としていた倶楽部が、さらに熱狂に包まれた。\n奪い合う叫び、富を掴んだ歓声、狂気じみた笑い。\n\nその喧騒の中で、ライカ―はミサゴ大学から支給された、誰もが持つ装飾品を胸ポケットに戻し、自分の名が記された招待状をズボンのポケット越しに軽く叩き、帽子を押さえて口元を緩めた。\n\n本当のギャンブラーは、自分の勝ちしか信じない。\n\n彼は信じている。\n何をしても、運命の寵愛は常に自分と共にあると。"
  },
  CollectionHall_131388_Title = {
    Text = "ギャンブルの知恵"
  },
  CollectionHall_131663_LockTip = {
    Text = "意識潜游「沈溺」のいずれかのステージをクリアして解放"
  },
  CollectionHall_131663_Title = {
    Text = "O–1841研究報告"
