  CollectionHall_133769_Title = {Text = "沈没"},
  CollectionHall_133770_Desc = {
    Text = "ご乗車の皆様、こんにちは！\n祈歳佳節がまもなく訪れます。家族が集い、旧年を送り新年を迎えるこの素晴らしい時に、本列車の全乗務員一同、遠路帰郷され旅の疲れを抱えるあなたへ、最も誠実なブレスをお贈りします――\n祈歳の喜びと、ご家族の歓喜と、疾走する旅路と、万事如意をお祈り申し上げます！<(￣︶￣)↗[GO!]"
  },
  CollectionHall_133770_LockTip = {
    Text = "特務記録「祈年祭行きの列車」を完成しました"
  },
  CollectionHall_133770_Title = {
    Text = "疾走：歓喜エクスプレス"
  },
  CollectionHall_133771_Desc = {
    Text = "旅客の皆様、こんにちは。誠に申し訳ございませんが、車掌の個人的な気分により、この歓喜専用列車はただいま一時的に停車いたします。具体的な発車時刻につきましては、自滅の殺し合いが終了次第、随時放送にてお知らせいたします。\n停車中も、列車の空調・照明・トイレは通常通りご利用いただけます。殺戮のご要望に応じてご利用ください。危険が生じないよう、どうぞご注意ください。\nなにしろ、歓喜専用列車の使命とは、すべての旅客の皆様に笑顔をお届けすることですから～(￣▽￣～)(～￣▽￣)～"
  },
  CollectionHall_133771_LockTip = {
    Text = "特務記録「祈年祭行きの列車」を完成しました"
  },
  CollectionHall_133772_Desc = {
    Text = "ご注意ください：列車は間もなく磐龍古国に到着いたします。磐龍古国でご下車のお客様は、あらかじめ『なんと美しいジャスミンの花』の歌唱技術をご習得ください。\nなぜなら、皆様にはもう下車する機会がないからです φ(≧ω≦*)♪"
  },
  CollectionHall_133772_LockTip = {
    Text = "特務記録「祈年祭行きの列車」を完成しました"
  },
  CollectionHall_133772_Title = {
    Text = "なんと美しいジャスミンの花"
  },
  CollectionHall_133773_Desc = {
    Text = "光は海に沈み、蒼よりも深い蒼を照らす。"
