  },
  CollectionHall_133773_Title = {
    Text = "蒼とより深い蒼"
  },
  CollectionHall_134293_Desc = {
    Text = "<Title:紹介>\n運命劇場の主人、脚本家、役者、運命の永遠なる紡ぎ手にして永遠の囚人…………\n生まれた時から、アラクネは運命の糸を見る力を持っていた。「モイライ」と名付けられた紡ぎ車を用い、彼女は絶え間なく世界の運命を紡ぎ、その脆い均衡を守り続けている。そのために、彼女は自らの中にあるすべての美しさと脆さを追放し、あらゆる運命に対して最も正しい選択を下し、すべての運命の罪責をただ一人で背負ってきた。\n彼女はとうに知っていた――運命の網の果てに、滅びは決して逃れられないと。それでも彼女は悠久の時を紡ぎ続け、深く愛するすべてのものが、万物を消し去る終焉へとゆっくり堕ちていくのを見つめていた。\n彼女は紡ぎ、待ち続ける。自らが一度も予見したことのない、運命の網を深淵から救い出す一本の糸を。"
  },
