  },
  CollectionHall_139856_Title = {
    Text = "メッセンジャー"
  },
  CollectionHall_140337_Desc = {
    Text = "あなたは星雲の間を歩き、流星が一つまた一つと墜ちるのを見届ける。\n灼熱のもの、眩いもの、冷たいもの、暗いもの――別れを告げる間もなく、長い尾を引きながら、天幕から一つずつ消えていく。\nあなたは灰を掬い上げ、存在の痕跡を心に刻もうとする。\nだがその映像はやがて指の隙間をすり抜け、薄れゆく記憶をすり抜け、無限の時空へと散っていく。\nあなたもまた、万千の星雨の中の一粒に過ぎなかったのだ。\nだがあなたは立ち止まらない。歩み続ける、長い寂滅を越えて、次の紀元まで。\n満天の星が輝くその時まで。"
  },
  CollectionHall_140337_Title = {
    Text = "群星に捧ぐ"
  },
  CollectionHall_140428_LockTip = {
    Text = "調査行動・星辰篇5-1にて解放可能"
  },
  CollectionHall_140428_Title = {
    Text = "運命の舞台"
  },
  CollectionHall_141369_LockTip = {
    Text = "期間限定イベント「永遠のエポヤンス·高所巡狩」のいずれかのステージをクリアする必要あり"
  },
  CollectionHall_141369_Title = {
    Text = "永遠のエポヤンス·高所巡狩"
  },
  CollectionHall_141453_LockTip = {
    Text = "多次元接続「忘れられた愛の種：血ﾝ肉ｲw世ｮ」のいずれかのステージをクリアで解放"
  },
  CollectionHall_141453_Title = {
    Text = "悠久なる旅の歌"
  },
  CollectionHall_141528_Desc = {
    Text = "おとぎ話では、子供が森で野ウサギを追いかけると、異世界へと続く木のうろに落ちてしまうことがあるという。\nリリーの滑らかな素足が、丸石を敷いた小道を踏みしめた。\n\n「リリー、ここが好き…………地面にガラスの破片はないし、空気に消毒液の匂いもしない。」\n\nリリーは新鮮な空気を深く吸い込んだ。林を吹き抜ける風が、花の香りを運んでくる。\n頭上では木の梢がステンドグラスのような天蓋を織りなし、こぼれ落ちる木漏れ日は地面を跳ねる宝石のようだ。絢爛で幻想的な光景にリリーはどこを見ればよいのかわからなくなった。\n「あ、さっきのウサギさん！」\n草むらに見覚えのある灰色の長い耳が揺れた。リリーは急いで追いかける。\n踏み出すたびに足元の苔が小さな銀の花を咲かせたが、リリーにそれを気にする暇はなかった。ウサギさんに伝えなければならないことがある。\n\n蜂蜜色の光が流れる小川を渡り、歌声のする葦の茂みをくぐり抜けた。\n息を切らしたリリーは、ついにウサギさんの毛玉のような尻尾をつかまえた。\n\n「ウサギさん、リサと友達になってくれる？」\n「リサはわたしの友達なの。でも今は、みんなが彼女を怖がっていて…………ウサギさんなら、きっと友達になれると思うから！」\n\nウサギさんが振り返った瞬間、無数の蛍の光が空へと舞い上がった。\n\n「もちろん、@2はみんなの友達だよ。でも今は、もう休む時間だよ。」\n\nリリーは友達になったウサギさんを抱きしめ、森の奥にそびえる大きな古木の下まで歩いた。\n漂う蛍の温かな光に包まれながら、リリーは巨木の根に寄り添い、静かに眠りついた。\n\n「被験者：リリー。臨床所見：呼吸安定、眼球運動正常。第359回意識干渉実験、成功。」\nそれは夢のように美しい、幻想の世界だった。"
  },
  CollectionHall_141528_Title = {
    Text = "夢遊の異界"
  },
  CollectionHall_141832_LockTip = {
    Text = "期間限定イベント「新月と深雪：ウマーパティの宝物」の任意のステージをクリアする必要があります"
  },
  CollectionHall_141832_Title = {
    Text = "新月と深雪：ウマーパティの宝物"
  },
  CollectionHall_142131_Title = {
    Text = "忘れられた愛の種子"
  },
  CollectionHall_142154_Title = {Text = "町"},
  CollectionHall_142155_Desc = {
    Text = "理解もできない。識別もできない。\nおぞましい異形の存在が迫るとき、身を守るために牙をむく。\nそれは生き物としての本能なのだ。\nゆえに、それは決して罪ではない。"
  },
  CollectionHall_142155_LockTip = {
    Text = "多次元接続「忘れられた愛の種」の困難難易度をクリアする"
  },
  CollectionHall_142155_Title = {
    Text = "無辜の暴虐"
  },
  CollectionHall_142156_Desc = {
    Text = "「聞こえますか　風に姿が溶けても」\n風に乗って届く遥かなる呼び声。\nそれは時を越え、広く冷たい冬の夜、忘却の彼方から響く、探求の声。"
  },
  CollectionHall_142156_LockTip = {
    Text = "多次元接続「忘れられた愛の種」をクリアする"
  },
  CollectionHall_142156_Title = {
    Text = "忘却の彼方"
  },
  CollectionHall_142157_Desc = {
    Text = "記憶は幾度となく燃え上がる。結末はいまだ霧の中。\nだが、結末を知ることは本当に重要なことだろうか？\nすべての物語は愛をもって始まり、そして死をもって終わるのだから。"
  },
  CollectionHall_142157_LockTip = {
    Text = "多次元接続「忘れられた愛の種」をクリアする"
  },
  CollectionHall_142157_Title = {
    Text = "4度目の記憶"
  },
  CollectionHall_142158_Desc = {
    Text = "ある日、あなたも私と同じように、\n血と肉が崩れた、腐臭に満ちる惨状の中へと堕ちたのなら。\nそのときは、きっとあなたにも分かるはず――\nあの小さな指先に触れた一瞬こそが、この世の奇跡であったのだと。"
  },
  CollectionHall_142158_LockTip = {
    Text = "多次元接続「忘れられた愛の種」をクリアする"
  },
  CollectionHall_142158_Title = {Text = "奇跡"},
  CollectionHall_142159_Desc = {
    Text = "凡庸で、単調で、退屈で、変化のない毎日に飽きていないだろうか？\n少し刺激を求めてみてはどうだろう。\nあなたの知らない世界が今、血まみれの口を開いて歓迎している。"
  },
  CollectionHall_142159_LockTip = {
    Text = "多次元接続「忘れられた愛の種」をクリアする"
  },
  CollectionHall_142159_Title = {
    Text = "血の領域"
  },
  CollectionHall_142160_Desc = {
    Text = "愛は崇高で、貪欲で、祝福で、呪いでもある。\n愛は水とともに生まれ、水とともに去っていく。\nだが、雨季は二度と訪れない。"
  },
  CollectionHall_142160_LockTip = {
    Text = "多次元接続「忘れられた愛の種」の困難難易度をクリアする"
  },
  CollectionHall_142161_Desc = {
    Text = "あらゆる生命は何も知らぬままに生を受ける。\n万物より糧を得て、環境を作り変えて、生命を搾取して、己の命を育む。\nそれは決して逃れることのできない原罪なのだ。"
  },
  CollectionHall_142161_LockTip = {
    Text = "多次元接続「忘れられた愛の種」をクリアする"
  },
  CollectionHall_142162_Desc = {
    Text = "タンポポは風に乗って漂い続ける。\n綿毛は風に流され、故郷を離れて遥か遠くへ旅立つ。\nただひとり漂うその種は、いつか自らの帰る場所を見つけられるのだろうか。\nそれはきっと、砂漠でたったひとりの、そのタンポポを愛してくれる人に出会ったとき。"
  },
  CollectionHall_142162_LockTip = {
    Text = "多次元接続「忘れられた愛の種」をクリアする"
  },
  CollectionHall_142162_Title = {
    Text = "タンポポの行方"
  },
  CollectionHall_142163_Desc = {
    Text = "広い空に、果てなく続く砂の海。\nそこは、あなたと私だけの無人の境界。\nそこは、自由と愛が永遠に彷徨う場所。"
  },
  CollectionHall_142163_LockTip = {
    Text = "多次元接続「忘れられた愛の種」をクリアする"
  },
  CollectionHall_142163_Title = {
    Text = "砂の海に漂う"
  },
  CollectionHall_142164_Desc = {
    Text = "「May I call your name, though the world all fades」\n記憶が消えて、跡形もなく失われるなら、昏き忘却は偲ぶことも叶わぬ過去まで飲み込むだろう。\nどうか手を取って。銀色の輝きが、あなたと私を繋ぐように。\n新たな夢幻で、柔らかな種が芽吹く春の日に。"
  },
  CollectionHall_142164_LockTip = {
    Text = "多次元接続「忘れられた愛の種」をクリアする"
  },
  CollectionHall_142164_Title = {
    Text = "Song of Memento(忘却の彼方-Emi Ver.)"
  },
  CollectionHall_142165_Desc = {
    Text = "歌え、高らかに。\n輝く生命は自由を讃え、希望の羽根の種を、遍くすべての地へと撒いていく。"
  },
  CollectionHall_142165_LockTip = {
    Text = "多次元接続「忘れられた愛の種」の困難難易度をクリアする"
  },
  CollectionHall_142165_Title = {
    Text = "始まりの讃歌"
  },
  CollectionHall_142868_Desc = {
    Text = "<Title:簡介>\nポントスは、家族の歴史を知った日の気持ちをずっと覚えている。それ以前、彼は何かの責任を負う覚悟など一切していなかった。誰もが彼を好いていた。彼は美しく、面白く、何の憂いもなかった。\n@1王港を年中往来する船々のおかげで、彼は単調な日常と向き合わずに済んだ。あまりにも多くの話を聞いてきたため、多くの人が彼を博識だと言い、それゆえ彼はみんなと同じ凡人に成り下がることを認めたくなかった。\nだから、予想外でありながらも必然的な、巨大な狂喜に飲み込まれた。しかも、家族が代々使役してきた魇の背後にある、さらに計り知れない偉大な存在が彼を認めた――彼は生まれながらにして特別だったのだ。\nしかし「N」のひとつの冗談が、狂信者たちをして無差別の沿岸襲撃を引き起こし、村全体を壊滅させた。\n突如として降りかかった災難に向き合えず、深淵の力を得るために、ポントスは@3に自らの身体を捧げることを選んだ――そして自らのすべての可能性をも捧げた。\nだが、それが何だというのか。もう何も彼の制御を超えることはない。\n彼はもう、何も失うことはないのだから。"
  },
  CollectionHall_142868_LockTip = {
    Text = "「ポントス」を覚醒させると解錠"
  },
  CollectionHall_142868_Title = {
    Text = "ポントス"
  },
  CollectionHall_142901_Title = {
    Text = "永遠のエポヤンス"
  },
  CollectionHall_143468_Desc = {
    Text = "弔鐘はすでに鳴り響き、背信者は最も発狂した演出を捧げる。\n無数の糸が、いかなる結末を織りなすのか――\nあなたが決める。"
  },
  CollectionHall_143468_LockTip = {
    Text = "調査·難しい 星辰篇5-11をクリアして解錠"
  },
  CollectionHall_143468_Title = {
    Text = "共に終局を織る"
  },
  CollectionHall_143469_Desc = {
    Text = "さあ来て、さあ来て、すべての人があなたを待っている。\n長い回廊を歩み、永遠の舞台へと踏み上がれ。\nあなたこそが、この劇全体の唯一の主役なのだから。"
  },
  CollectionHall_143469_LockTip = {
    Text = "調査 星辰篇5-16をクリアするとアンロック"
  },
  CollectionHall_143469_Title = {
    Text = "無限螺旋"
  },
  CollectionHall_143470_Desc = {
    Text = "彼らは共に歌い、それぞれの役を果たす。\nしかし彼らはみな、彼女だ。\nこれは彼女だけの、永遠にフィナーレを迎えない一人芝居。"
  },
  CollectionHall_143470_LockTip = {
    Text = "調査 星辰篇5-16をクリアするとアンロック"
  },
  CollectionHall_143470_Title = {Text = "独楽劇"},
  CollectionHall_143471_Desc = {
    Text = "Act I:糸を紡ぐ\nAct II:量る\nAct III:裁断する\nかくして繰り返し、かくして繰り返し......"
  },
  CollectionHall_143471_LockTip = {
    Text = "調査·難しい 星辰篇5-11をクリアして解錠"
  },
  CollectionHall_143471_Title = {Text = "三幕劇"},
  CollectionHall_143472_Desc = {
    Text = "ただ一人の狂熱的な青年が、ありふれた街角で銃を放っただけのこと。\n少なくともその時は、すべての人がそう思っていた。"
  },
  CollectionHall_143472_LockTip = {
    Text = "調査 星辰篇5-16をクリアするとアンロック"
  },
  CollectionHall_143472_Title = {
    Text = "戦火の序"
  },
  CollectionHall_143473_Desc = {
    Text = "きしきし、きしきし。\n運命よ、あなたの輪盤は回り続ける。\n貧困も権力も、あなたに氷のように融解させられる。\nあなたは自らを覆い隠し、その顔を隠しながら、\nそれでも私へと輝きかける……"
  },
  CollectionHall_143473_LockTip = {
    Text = "調査·難しい 星辰篇5-11をクリアして解錠"
  },
  CollectionHall_143473_Title = {
    Text = "運命よ、なんと残酷なことか"
  },
  CollectionHall_143474_Desc = {
    Text = "さらばよ、最後の旋律の中で。\nさらばよ、運命の眼差しの下で。\n物語の主人公は、新たな旅へと踏み出す。"
  },
  CollectionHall_143474_LockTip = {
    Text = "調査·難しい 星辰篇5-11をクリアして解錠"
  },
  CollectionHall_143474_Title = {
    Text = "それでも私は歌い続ける"
  },
  CollectionHall_143475_Desc = {
    Text = "ねえ、お酒の勢いを借りて、もう一曲一緒に踊りましょう。"
  },
  CollectionHall_143475_LockTip = {
    Text = "調査 星辰篇5-16をクリアするとアンロック"
  },
  CollectionHall_143475_Title = {
    Text = "微酔の舞踏会"
  },
  CollectionHall_143476_Desc = {
    Text = "観客は別れのために涙を流し、再会のためにも涙を流す。\nそして舞台の中央に立つ囚人たちも、互いのために拍手を贈るべき時が来た。"
  },
  CollectionHall_143476_LockTip = {
    Text = "調査·難しい 星辰篇5-11をクリアして解錠"
  },
  CollectionHall_143476_Title = {
    Text = "囚人たちは幕を下ろす"
  },
  CollectionHall_143477_Desc = {
    Text = "世の人々は一つの戦争を一発の銃声のせいにしたがる。\nしかし運命は嗤う——それは全人類の自己欺瞞だと。"
  },
  CollectionHall_143477_LockTip = {
    Text = "調査 星辰篇5-16をクリアするとアンロック"
  },
  CollectionHall_143477_Title = {
    Text = "蝶が羽ばたく時"
  },
  CollectionHall_143478_Desc = {
    Text = "後日談のない演出は不完全だ。\n台詞を少し変え、舞台装置を調整し、演者を入れ替える――アンコールのたびに、それは新たな一幕となる。"
  },
  CollectionHall_143478_LockTip = {
    Text = "調査·難しい 星辰篇5-11をクリアして解錠"
  },
  CollectionHall_143478_Title = {
    Text = "アンコールの変奏"
  },
  CollectionHall_143479_Desc = {
    Text = "ペン先が白紙の上を駆け抜け、文字を追いかける。そして文字は、すでに定められた結末へと続く。\nすべては、あなたが一冊の本を開く前に起きていた。"
  },
  CollectionHall_143479_LockTip = {
    Text = "調査 星辰篇5-16をクリアするとアンロック"
  },
  CollectionHall_143479_Title = {
    Text = "定まるべきこと、すでに定まったこと"
  },
  CollectionHall_143480_Desc = {
    Text = "少量のビターズ、20mlのスイートベルモット、シェリー酒少々、氷をたっぷり加えてかき混ぜる——上質な食前酒であり、五百回上演された一幕の物語でもある。"
  },
  CollectionHall_143480_LockTip = {
    Text = "調査 星辰篇5-16をクリアするとアンロック"
  },
  CollectionHall_143480_Title = {
    Text = "アドニス"
  },
  CollectionHall_143481_Desc = {
    Text = "運命を道化と見なせば、運命に縛られることはない。\n絶えることなき哄笑でもって祂を迎えよ、共に祂の名を呼び出そう――\n歓喜。"
  },
  CollectionHall_143481_LockTip = {
    Text = "調査·難しい 星辰篇5-11をクリアして解錠"
  },
  CollectionHall_143481_Title = {
    Text = "道化師の来臨"
  },
  CollectionHall_143482_Desc = {
    Text = "「あなたが憎い、自ら繭に閉じこもることが憎い、どうにもならないことが憎い、自分を捨てることが憎い。」\n「……でもその憎しみは私自身をも焼き焦がしている、なぜなら、私もあなたを愛しているから。」"
  },
  CollectionHall_143482_LockTip = {
    Text = "調査·難しい 星辰篇5-11をクリアして解錠"
  },
  CollectionHall_143482_Title = {
    Text = "復讐鬼の悲歌"
  },
  CollectionHall_143483_Desc = {
    Text = "世界はあなたに無数の分かれ道を与えるが、それらはすべて同じ一点に集める――破壊という名、終焉という名の。"
  },
  CollectionHall_143483_LockTip = {
    Text = "調査 星辰篇5-16をクリアするとアンロック"
  },
  CollectionHall_143483_Title = {
    Text = "世界の複本"
  },
  CollectionHall_143484_Desc = {
    Text = "幕が上がり下り、演目が移り変わっても、彼女はなお劇場の中にいる——彼女は劇作家であり、観客であり、また演者でもある。\n運命の女主人よ、あなたはかくも残酷で、永遠に沈黙しながら、なぜ涙を流すのか？"
  },
  CollectionHall_143484_LockTip = {
    Text = "調査 星辰篇5-16をクリアするとアンロック"
  },
  CollectionHall_143484_Title = {
    Text = "命定同織の戯れ"
  },
  CollectionHall_143485_Desc = {
    Text = "もし破壊が結局避けられないのなら、運命の網を引き裂いてこそ、真の救済を迎えられるのだろうか？\n誰も答えられない、いかなる神も答えられない。\nしかし少なくとも、果てしない苦難もともに消え去るだろう。"
  },
  CollectionHall_143485_LockTip = {
    Text = "調査 星辰篇5-16をクリアするとアンロック"
  },
  CollectionHall_143485_Title = {
    Text = "冒涜の演目"
  },
  CollectionHall_143486_Desc = {
    Text = "この世を歩む、あれほどリアルで、自由に見える顔々も、舞台上の固定された装置に過ぎない。\nその一挙一動は、すべて運命の糸に引かれている。"
  },
  CollectionHall_143486_LockTip = {
    Text = "調査 星辰篇5-16をクリアするとアンロック"
  },
  CollectionHall_143486_Title = {
    Text = "衆生の糸"
  },
  CollectionHall_143487_Desc = {
    Text = "夢が覚めれば、すべては消え去り、完全に忘却される――邸宅、花壇、歌謡、絵画......\nそれは存在しない春だった。"
  },
  CollectionHall_143487_LockTip = {
    Text = "調査 星辰篇5-16をクリアするとアンロック"
  },
  CollectionHall_143487_Title = {
    Text = "春を紡ぐ幻夢"
  },
  CollectionHall_143488_Desc = {
    Text = "弦楽が徐に奏で始め、メイドが詠唱する。\n幕の裏にいた人物が舞台前へと現れ、あなたに礼をして、この定められた運命の軌跡を証見するよう招く。"
  },
  CollectionHall_143488_LockTip = {
    Text = "調査 星辰篇5-16をクリアするとアンロック"
  },
  CollectionHall_143488_Title = {
    Text = "彼女のヴェールを剥ぐ"
  },
  CollectionHall_143489_Desc = {
    Text = "これは一生に一度しか演じられない即興の踊りだ。\nでも構わない、それは幸いにも標本となり、永遠に刻まれるのだから。"
  },
  CollectionHall_143489_LockTip = {
    Text = "調査 星辰篇5-16をクリアするとアンロック"
  },
  CollectionHall_143489_Title = {
    Text = "舞踊劇：『白鳥の死』"
  },
  CollectionHall_143490_Desc = {
    Text = "幕が開き、荒唐な役たちが次々と登場する。\n彼らは高らかに歌い、彼女たちは踊り、運命が降り来る前に、執着をもって演目を舞台へと捧げる——たとえ結末がすでに書かれていたとしても。"
  },
  CollectionHall_143490_LockTip = {
    Text = "調査 星辰篇5-16をクリアするとアンロック"
  },
  CollectionHall_143490_Title = {
    Text = "幕開け二重唱"
  },
  CollectionHall_143491_Desc = {
    Text = "すべてを正しい軌道に乗せるために、常に何かが排除され、切り捨てられなければならない。\n選ばれなかった存在は、ことごとく漆黒の深淵へと堕ち、その嘆きと罵る声は、結局誰にも聞かれることはない。"
  },
  CollectionHall_143491_LockTip = {
    Text = "調査 星辰篇5-16をクリアするとアンロック"
  },
  CollectionHall_143491_Title = {
    Text = "見捨てられた「私」"
  },
  CollectionHall_143492_Desc = {
    Text = "こんな死に方、本当に美しい。彼女はそう思った。"
  },
  CollectionHall_143492_LockTip = {
    Text = "調査 星辰篇5-16をクリアするとアンロック"
  },
  CollectionHall_143492_Title = {
    Text = "至上の美の贖い"
  },
  CollectionHall_143592_LockTip = {
    Text = "意識潜行「永遠のエポヤンス」の任意のステージをクリアすると解錠"
  },
  CollectionHall_143592_Title = {Text = "依存"},
  CollectionHall_144377_Desc = {
    Text = "長い駐守の時の中で、タヴィもかつてある土地に足を踏み入れたことがあった。\n彼女はすべての生き物の行動を注意深く観察し、人間の世界の端を静かに歩いた。\n\nある平凡な日の夜、郊外に密集した灯りが彼女の眼差しを引きつけた。\n舞台の背景、歌や踊、菓子を売る露店、笑い騒ぐ子供たち、杯を傾ける暇人たち。それは生命の息吹、束の間の安らぎだった。\nその光景があまりにも魅力的で、彼女は思わず姿を現した。\n\n「こんにちは、飴細工を一つください。」\n「はい、少々お待ちを。何を描きましょうか？」\nタヴィはそっと首を傾けた。彼女は偶然拾った持ち主のない貨幣を渡す必要があることは覚えていたが、自分が望むものを伝えられることをすっかり忘れていた。\n「もしお決まりでなければ、あなたのお姿を描いてみましょうか？まるで仙女のようにお美しい。」\nタヴィは微笑んでうなずき、露店主は声を上げ、糖勺を持ち上げて描き始めた。\n\nぽたり。ぽたり。\n石板に落ちたのは、蜜色の糖蜜ではなかった。\n雨だった。黒い雨だった。\n黒い粘液が目に見えない高空から滴り落ち、空に目を覆いたくなるような亀裂を溶かし開いた。\n\n\nそして、タヴィは上への墜落を始めた。\nそれは世界が沈んでいくことだった。露店主の笑顔はタヴィの記憶の中で静止した一コマに凝固し、そして万物とともに黒い大海に飲み込まれ、無数の逝きし星々の中のとるに足らない一粒となり、彼女にとって遥か遠い過去へと変わった。\nこれは彼女が引き起こした震動であり、彼女が受けるべき懲罰でもあった。\n彼女は遠くを見つめ、静かに黙していた。彼女はただ上へと墜落していく。\nこれこそが彼女の守るべき場所、「時空を超える」銀の扉なのだ。\n彼女はここで永遠に見下ろし続けるだろう。"
  },
  CollectionHall_144377_Title = {
    Text = "上への墜落"
  },
  CollectionHall_144448_Desc = {
