  CollectionHall_144476_Desc = {
    Text = "この短い踊を、流れゆく時の中で永遠へと変えよう。\n次の祈歳の夜、私たちはきっと月明かりの下で再会する。\n*父と娘の深い絆、心を打つ感動の物語 (ノへ￣、)"
