  CollectionHall_147491_Title = {
    Text = "一時的なテキスト"
  },
  CollectionHall_147860_Desc = {
    Text = "ロンディニウムの最も秘めやかな裏路地の片隅に、誰もが知る話がある。人々の口から口へと語り継がれてきた話が。\nそれは決して、奥様方のアフタヌーンティーの席で揺れる羽根扇やレース扇の下には現れないし、紳士たちが夕食後に絹のハンカチで口元を拭いながら何気なく持ち出すこともない。\n最も難解で古めかしい呪文を唱える魔術師や、最も奇妙で入り組んだ任務をこなす放浪者だけが、ほんのわずかにこの秘密を知り得るかもしれない。\nえ？それなのになぜ誰もが知っているのかって？\nああ、それこそがこの話全体の肝なのだ！この話に関わり、語り継いできた者たちは皆、なんと偉大で慈愛に満ちていることか。祂たちの心には私欲のかけらもなく、もし本当にあるとすれば、それはきっと、この世で懸命に生き延びているすべての人が、真に苦難から解き放たれ、雪のように白く穢れなき浄土へと帰ることを願う気持ちだけだろう。\nこの世のすべては、一つの真っ赤で香り高く、誰もが見れば一口かじりたくなるようなリンゴに始まる。\nその果汁は極めて豊かで、一口飲めばどんな飢えも渇きも満たされる。\nその香りは比類なく濃く、一嗅ぎするだけでどんな言葉にならない苦しみも払拭される。\nそれは普通のリンゴの姿をして、すべてのリンゴの中に紛れ込み、あらゆる善と悪、因と果を記録している。リンゴにまつわるすべての神話伝説は、かつてのその偉業の数々だ。\n最も肝心なのは、それがかくも無私で平等であるがゆえに、その教えを信奉する教派に加わるのに何の洗礼も必要ないということ。リンゴ神教の教義の一つを心に刻め――真の神明は形式にこだわらない！\nリンゴ神教の名を初めて耳にした時、脳裏に初めて一つの豊かで真っ赤な、よだれが出るほど美しいリンゴが浮かんだ時、ただそれを信じるだけで、あなたはリンゴ神教の一員となれる。\nそれは他のいかなる教派とも相容れないことはない。真の神明はその懐に飛び込もうとするすべての子を歓迎する。心の片隅にリンゴ神教の居場所がある限り、永遠の安らぎに帰した後、もし先の教義が効かず、それらの教義にある福地に入れないと気づいたとしても、「最終的にあなたはそれが必然だと気づくだろう、しかしリンゴ神教はあなたを愛しており、この点について争うつもりはない。」、リンゴの天国はわだかまりなくあなたを受け入れ、長くそれに寄り添ってきた白雪の妖精が、リンゴの香り漂う永遠の甘き帰り処へとあなたを導いてくれるだろう。\n「今、このすべての福音が無償で広められている。たった一枚のレオフアンで、何の縛りもない保険のプランと、リンゴ神教に祀られているリンゴである可能性のある一つのリンゴが手に入る。*この世のすべてのリンゴがそのリンゴである可能性があり、白雪の妖精がその意志を代行しているため、より高い確率で入手できる。とにかく、リンゴをたくさん食べてください。」\n……………\n「まったく、私たちはただちょっとの間、過度な唆しと欺きでカラブの一週間分の小遣いを差し引いただけじゃないの！」\n「これがあの子の小さな頭で考え出した新しいやつ？？？！」"
  },
  CollectionHall_147860_Title = {
    Text = "甘美な欺瞞"
  },
  CollectionHall_147986_Desc = {
    Text = "縄はその舌を押さえつけ、綱はその鼻を貫き、釣り針はその顎の骨を突き破るだろう。\nかくして、誇り高き王も墜ち、天空もまた墜ちる。"
  },
  CollectionHall_147986_LockTip = {
    Text = "意識潜行「天の鯨が堕ちるまで」をクリア"
  },
  CollectionHall_147986_Title = {
    Text = "瀕死の鯨の歌"
  },
  CollectionHall_147987_Desc = {
    Text = "荒れ果てた大地の上で、目を剥いた獣たちが徘徊している。皆が機を窺っている――鋭い牙を喉元に突き立て、相手を完膚なきまでに引き裂く、その一瞬を。"
  },
  CollectionHall_147987_LockTip = {
    Text = "意識潜行「天の鯨が堕ちるまで」をクリア"
  },
  CollectionHall_147987_Title = {
    Text = "牙を向ける"
  },
  CollectionHall_147988_Desc = {
    Text = "その退屈な王冠をしまえ、私は一度たりとも眼中に置いたことはない。刀を抜け、世界は今や鮮血に狂っている！\nそのためだけに、ただそのためだけに――\n弑せよ！蝕め！滅びよ！"
  },
  CollectionHall_147988_LockTip = {
    Text = "意識潜行「天の鯨が堕ちるまで」をクリア"
  },
  CollectionHall_147988_Title = {
    Text = "天を屠る狂舞"
  },
  CollectionHall_147989_Desc = {
    Text = "あの頃、私はまだ最も卑しい童僕に過ぎず、残酷とも言うべき征途を目の当たりにしたことがある。\nかの伝説の主人は、力がその骨肉を鋳造し、熱き血潮が不滅の炎と化し、その炎がまた彼女の瞳に火を灯した――\nどうかこの記憶を、私の代わりに語り継いでほしい、わが子よ。……彼女はついに勝利し、星空を征服した。"
  },
  CollectionHall_147989_LockTip = {
    Text = "意識潜行「天の鯨が堕ちるまで」をクリア"
  },
  CollectionHall_147989_Title = {
    Text = "征伐は止まらない"
  },
  CollectionHall_147990_Desc = {
    Text = "パンと見世物、世の人々はこの二つのためだけに歓喜する。\n祂はそれを眺め、気にも留めない。\n彼女はそれを経験し、気にも留めない。"
  },
  CollectionHall_147990_LockTip = {
    Text = "意識潜行「天の鯨が堕ちるまで」をクリア"
  },
  CollectionHall_147990_Title = {
    Text = "権欲に飼育されたアンデッド"
  },
  CollectionHall_147991_Desc = {
    Text = "死者は瀕死の者の後ろに倒れ、強者はさらなる強者の前に平伏す。\n冷たく鋭い刃の上には、立ち続ける者の影だけが映し出される。"
  },
  CollectionHall_147991_LockTip = {
    Text = "意識潜行「天の鯨が堕ちるまで」をクリア"
  },
  CollectionHall_147991_Title = {
    Text = "猩紅を渡る"
  },
  CollectionHall_147992_Desc = {
    Text = "勝利への道には、いつだって多少なりとも褒められない手段がつきものだ。"
  },
  CollectionHall_147992_LockTip = {
    Text = "意識潜行「天の鯨が堕ちるまで」をクリア"
  },
  CollectionHall_147992_Title = {
    Text = "呟きの蛇"
  },
  CollectionHall_148015_LockTip = {
    Text = "意識潜行「天の鯨が堕ちるまで」の任意のステージをクリアして解锁"
  },
  CollectionHall_148015_Title = {Text = "原則"},
  CollectionHall_148138_Desc = {
    Text = "がらんとした実験室の中、各種の精密な機器が整然と並べられ、無数の管線だけが入り乱れ、まるでうねり絡まる蛇のように床を這い、空中に吊り下がっている。\n思考の信号は誰の目にも見えない川のようなものだが、天才はとうにそれと向き合うことに慣れていた。脳はその源であり、機械の管線を流れ、最終的にこの新たに造られた躯体へと注ぎ込まれる。\n意識が伝達されると同時に、久しく封じられていた多くの記憶も引き出された。家族、ミサゴ、未完の実験……ぼんやりとした意識の中で、天才は何年も前のことを思い出した。まだ最初の肉体という桎梏から脱していなかった頃、退屈そうな学生が一人、興味深そうに彼女の周りをうろうろしながら、好奇心という名の光を瞳に宿していた。\n「先生は、人工の躯体が真の魂を宿せると思いますか？」\n凡人はいつも自分たちの視野をはるかに超えた事柄を夢想したがる。陳腐な問いだ。しかし教師として、彼女は目も上げずに、それでも一言二言答えを返した。\n「あなたの身体だって人工の産物と言えなくもない。心臓、四肢、五感といった器官の働きが機械と何が違うというの？」\n「いいから、そんな妄想に時間を費やすくらいなら、その錆びついた頭脳を鍛えることに時間を使いなさい。さもなければ、血液が流れているだけのその肉体はますます無用の長物になるわよ。」\n今となっては、問いを発した者はとうに時の砂に埋もれ、もはや存在しない。知性を宿した脳槽だけが今も思考し続け、永遠に思考し続ける。\n世人が言うところの魂とは、860億個のニューロンが交錯して生まれる電気化学的活動に過ぎない。血肉であれ機械であれ、素材の違いはそれらが単なる器に過ぎないという本質を変えはしない。\nそう、凡人には無理でも、天才たる彼女には可能であり、すでに成し遂げた――そうでなければ、世界の真理を解き明かし、知識の頂点に到達することなどできない。\n視覚とは、光線が眼球を通り、最終的に網膜に像を結ぶに過ぎない。\n嗅覚とは、匂い分子が受容体と結合し、神経を走る化学的知覚経路に過ぎない。\n聴覚とは、音波が蝸牛で変換され、皮質へと送られる電気信号となるに過ぎない。\n人形のいる場所はあまりにも薄暗く、か細い灯りが揺れ、影さえも映し出せない。彼女はそっと目を閉じた。たとえ開けたところで、映るのは変わり映えのない光景だとわかっていたから。\n部屋は塵一つなく掃き清められ、瓶や缶の中の薬液も固く封じられている。機体に呼吸は必要なく、感覚を試すためにこの無味な空気を取り込む必要もない。\nただ一つ、冷たい機械的な通知音だけが、がらんとした実験室に響き渡る：\n「意識同調完了、機体起動確認。」\n十分だ。\n無機質な音声ではあるが、どこか親しみを感じさせる。物質世界の現実を錨のように固定してくれるようでもあり、あるいはただ単純に、短い休息が終わり、新たな研究に身を投じる時が来たと告げているだけのようでもあった。"
  },
  CollectionHall_148138_Title = {
    Text = "霊魂同調"
  },
  CollectionHall_148140_Desc = {
    Text = "<Title:簡介>\n氷風が骨身に刺さる雪の夜、裸足の少女は魂を蠕虫に捧げた。\nこんな安物を売り渡すことで、多くの人が手に入れられない幸福と引き換えられるなら、躊躇う理由など何もなかった。\nそれからは白い影のように、荒れ果てた人の世をさまよい、嘘で聖殿を織り上げ、飴細工で祝福を偽り、糊口をしのぐための供物を得た。\n彼女と蠕虫は、まるで最高の相棒のようだった。\nやがて山頂から新たな知らせが届き、あらゆる願いを叶える聖地の存在を世に告げた。\nその燐寸に火が灯された。\n彼女はそれで、雪山ごと溶かしてみせるだろう。"
  },
  CollectionHall_148140_LockTip = {
    Text = "調査星辰篇第6章「山の宴」をクリアして解锁"
  },
  CollectionHall_148140_Title = {Text = "カラブ"},
  CollectionHall_148143_Title = {
    Text = "終北大陸"
  },
  CollectionHall_148163_Title = {Text = "山の宴"},
  CollectionHall_149045_Desc = {
    Text = "「花冠をきちんと被りなさい、これがあなたへの叙勲式よ、愛しき小さな騎士よ。」\n雛菊が野原一面に咲き誇る頃、怠惰な兵士たちはいつも護衛という名目を借りて、少年を連れてここをぶらついていた。\nアキタニア公国で最もよく見られる花で編まれた飾りが、そっと金色の髪の上に置かれた。\n「閣下、もしかして……訓練をすべきでは？」\n少年はそう言いながらも、素直に白い花冠を正しく被り直した。\nこの小さな植物は常に光の中に沐浴し、少年の国では希望の象徴でもあった。\n再び目を開けた時、あの鮮やかな光景はもはや存在しなかった。\n軍馬が嘶き、敵は侮蔑の眼差しで一斉に押し寄せ、千軍万馬の中に彼はただ一人だった。\nそして、耳障りな喧騒が突然止まった――\n黒い潮が彼の魂へと流れ込んだ。\n続いて響いたのは、長槍が皮肉を貫く断裂音、血が溢れ出す音、敵の哀号だった。\nあの顔々に浮かんでいた軽蔑は跡形もなく消え去り、代わりに天を覆うほどの恐怖と後退が広がった。\n少年はただ機械的に手を上げ、刺し、引き抜き、また振り上げた。\n最後の一人の兵士が倒れるまで。\n煙塵が無数の顔を覆い隠し、征服者と征服された者の残骸が地に積み重なり、もはや区別もつかなかった。\n影が彼の背に絡みつき、嘲笑いながら言った。「続けなさい。槍を振り下ろせ、もう一度。」\n「守護者と破壊者の間には、元々一線しかない。今や、お前はすでに選択を下した。」\n闇が空を覆い、血が大地に染み込んだ。\n彼は遠くの郊野を見やった――たった一夜のうちに、そこはもう永遠に往日の色彩を失っていた。\n風が少年の衣の裾を吹き上げ、辛うじて残ったあの草地をも掠めていった。\n音のない夜の中で、悪魔さえも知らぬ片隅に、かすかな純白がまだ彼の瞳の奥に残っていた。\nそれはこの国の最後の雛菊で、誰も気に留めない場所でひっそりと育っていた。\n赤に染まり、茎は折れ曲がっていても、それでもまだ倒れていなかった。"
  },
  CollectionHall_149045_Title = {
    Text = "それでもデイジーは開花する"
  },
  CollectionHall_149759_Desc = {
    Text = "<Title:紹介>\nオジールはついに認めた。自分の年齢と力では、まだ護国の騎士となるには足りないと。\nこの世界では、彼はあの肝心な一言の支持を得られなかった。\nそして、王女の説得を受け、父の領地へと戻り、普通の貴族の若君として暮らすことにした。\n\n戦火が押し寄せた時、騎士の身分を捨てきれないオジールは王宮へと駆け戻ったが、すでに手遅れだった。\n王女は最も残酷な形で自らを滅ぼし、見知った同僚たちは誰一人生き残らなかった――彼らは最後の瞬間まで持ち場を守り続けた。\n敵軍がすでに荒廃した宮殿へ押し入り、ここを略奪し尽くそうとした時、彼は怒りと悲しみを抑えきれず、誘惑に満ちた闇の力に身を委ねることを選んだ。\n敵は陣形を立て直す間もなく、ことごとく彼の手によって倒された。しかし復讐を果たした後も、少年は何一つ解放された気持ちになれなかった。\n\n漆黒の影が彼の肉体を占め、魂を侵し、その茫然自失の日々の中で、彼は多くの過ちを犯した。\n\n――殺戮、破壊、誓いに背くあらゆる行為……一筋の光が彼を果てしない虚無から覚醒させるまで。\n\nあるいは、今から後悔してもまだ間に合うかもしれない。\n彼にはまだ、槍と盾を再び手に取り、美徳を守るために戦う機会がある。"
  },
  CollectionHall_149759_LockTip = {
    Text = "「誓いの否定·オジール」を覚醒させると解錠"
  },
  CollectionHall_149759_Title = {
    Text = "負誓·オジール"
  },
  CollectionHall_149927_LockTip = {
    Text = "調査星辰篇6-1をクリアして解锁"
  },
  CollectionHall_149927_Title = {
    Text = "無願の尖峰"
  },
  CollectionHall_149928_LockTip = {
    Text = "調査星辰篇6-17をクリアして解锁"
