  CollectionHall_149928_Title = {
    Text = "吹雪の夜"
  },
  CollectionHall_48609_LockTip = {
    Text = "調査1-8中で解放可能"
  },
  CollectionHall_48609_Title = {Text = "扉の鍵"},
  CollectionHall_48611_Desc = {
    Text = "<Title:物質次元>\n物質が存在する次元、人間の日常生活が行われる「現実世界」。\n物質次元では、空間は三次元、時間は線形、物質は感知可能、感情や精神は抽象的で見えない。\nすべてが自然で、理解不能な事物は存在しないかのように感じられる。\n\n<Title:精神次元>\n精神が存在する次元、別名「幻夢次元」。\n精神次元では、感情、記憶、執念などが異なる個体を形成することがある。\n物質次元の個体の精神以外にも、ここにはさまざまな精神次元の生物が住んでいる。これらの生物は肉眼では観測しにくく、特殊な装置や密境でのみ感知できる。"
  },
  CollectionHall_48611_Title = {Text = "次元"},
  CollectionHall_48612_Desc = {
    Text = "<Title:定義と特性>\n物質が特異な消解や融蝕を起こす現象。\n少数個体を除き、多くの人間は融蝕現象を肉眼で観測できない。\n融蝕が進行すると、対象の存在自体が消去され、生活痕跡や書面記録、関連記憶がすべて消える。\n彼らは世界から忘れ去られる。\n\n<Title:融蝕の伝播>\n未知の伝播経路。\n融蝕の発生と消失は完全にランダムかつ予測不可能である。現在、特定の方法や手段、例えば特別な儀式や遺物を通じてのみ融蝕を拡散させることが可能である。\n\n<Title:融蝕の干渉>\nシルバーコアおよびシルバーコア製品を使用してのみ干渉治療が可能。\n大部分の個体は融蝕に侵されやすく、完全に消解される前にシルバーコア製品で干渉できる。\n極少数の個体は融蝕に対して一定の耐性を持つが、精神に不可逆的な損傷を受け、シルバーコア製品で修復できない有効な干渉手段は未だ見つかっていない。"
  },
  CollectionHall_48612_Title = {Text = "融蝕"},
  CollectionHall_48614_Title = {Text = "扉"},
  CollectionHall_48616_Desc = {
    Text = "<Title:創設日>\nA.F.187、前身ミサゴ学院創設はA.F.90\n\n<Title:創設者>\nワード・フィリップス、クラークシュ、タヴィ\n\n<Title:紹介>\n融蝕に対抗するための特別な大学。\n各国政府から完全に独立した第三者機関で、政治的な争いには関与せず、どの派閥にも属さない。\n全体の教師と学生を合わせて千人余りで、経済、人文、科学などの一般的なコースに加え、調査員、守秘者、覚醒体向けの特別コースも設けている。\nメインキャンパスはレオ王国にあり、世界各地で融蝕現象が発生した際には、調査隊と調査員、守秘者を派遣して解決にあたる。\n理論と実践を重視する特別な組織で、落第の結果も非常に厳しい。"
  },
  CollectionHall_48616_LockTip = {
    Text = "序章をクリアで解放"
  },
  CollectionHall_48616_Title = {
    Text = "ミサゴ大学"
  },
  CollectionHall_48618_Title = {Text = "序章"},
  CollectionHall_48619_Desc = {
    Text = "<Title:創立日>\nA.F.186\n\n<Title:創設者>\n《ミスティア協定》署名国\n\n<Title:紹介>\n一般人によるグローバルな組織。\n各国政府の出資により設立され、政府とは独立して存在し、融蝕現象の公式管理者および最初の対応者です。\nメンバーは多くがオカルトや超自然的な力を持たない普通の人々であり、融蝕との戦いを第一の使命と唯一の目標としています。\n各国には複数のオフィスがあり、それぞれ異なる地域を担当しています。\n厳粛で堅苦しい印象が全員に共通しており、過度に漂白された白い制服は、彼らの背筋のようにピンと伸びています。"
  },
  CollectionHall_48619_LockTip = {
    Text = "調査第2章「蝋人形の名において」クリアで解放"
  },
  CollectionHall_48619_Title = {
    Text = "ミスティア協定審査会"
  },
