  },
  CollectionHall_48625_LockTip = {
    Text = "意識潜行「一歩の距離：その涙は雨のようで」クリアで解放"
  },
  CollectionHall_48625_Title = {
    Text = "命の残影"
  },
  CollectionHall_48628_Desc = {
    Text = "アオォーン、アオォーン！\n孤独な狼は仮面を被り、咆哮とともに襲いかかる。"
  },
  CollectionHall_48628_Title = {
    Text = "荒野の狼"
  },
  CollectionHall_48629_Desc = {
    Text = "白くてふわふわの兎は、可愛いアリスと共に愛される。"
  },
  CollectionHall_48629_Title = {
    Text = "呪いのウサギ"
  },
  CollectionHall_48630_Desc = {
    Text = "刺さないように気をつけて。"
  },
  CollectionHall_48630_LockTip = {
    Text = "調査で解放"
  },
  CollectionHall_48630_Title = {
    Text = "<WhiteQuality:名無しの肢体>"
  },
  CollectionHall_48631_Desc = {
    Text = "この小さな黄色いカタツムリは高貴な出自を持ち、完璧で非の打ち所がない。"
  },
  CollectionHall_48631_LockTip = {
    Text = "調査で解放"
  },
  CollectionHall_48631_Title = {
    Text = "<WhiteQuality:黄色い小さな貝>"
  },
  CollectionHall_48635_Desc = {
    Text = "<Title:紹介>\nミサゴ大学の学長代理。\nクロウリー・マッキノンに師事し、ハーバートの直系の後輩。\nハーバートの師殺しの目撃者の一人で、師の死後、大学の関連事務を代行している。\n絶対的な効率至上主義者で、遅刻は一切せず、髪を短く切るのは梳かす時間を節約するため。\n戦乱のため祖国エルクからレオ王国に密航。\n右手の人差し指が正常に曲がらないのは、収容所で残酷な扱いを受けた証拠と言われている。"
  },
  CollectionHall_48635_LockTip = {
    Text = "序章をクリアで解放"
  },
  CollectionHall_48635_Title = {Text = "ハレト"},
  CollectionHall_48636_Desc = {
    Text = "<Title:紹介>\n三大創始者の一人で、ワード・フィリップスとクラークシュと共にミサゴ大学の前身であるミサゴ学院を設立した。\n最初の「覚醒体」であり、覚醒体技術を提供する存在。\n長年昏き海を守る彼女の顔を見た人間は、ほとんどいない。ミサゴ大学の最高機密の一つ。\n「シーッ……@2を試してはいけない」"
  },
  CollectionHall_48636_LockTip = {
    Text = "序章をクリアで解放"
  },
  CollectionHall_48636_Title = {Text = "タヴィ"},
  CollectionHall_48941_LockTip = {
    Text = "調査1-8中で解放可能"
  },
  CollectionHall_48941_Title = {
    Text = "錆びた扉"
  },
  CollectionHall_48942_Desc = {
    Text = "私の魂は墓だ。"
  },
  CollectionHall_48942_Title = {Text = "追放"},
  CollectionHall_48943_Desc = {
    Text = "深呼吸して、ドミニク。"
  },
  CollectionHall_48943_Title = {Text = "吸う"},
  CollectionHall_48944_Desc = {
    Text = "不朽不敗。"
  },
  CollectionHall_48944_Title = {Text = "庇護"},
  CollectionHall_48945_Desc = {
    Text = "死に際に、生への渇望が爆発する。"
  },
  CollectionHall_48946_Desc = {
    Text = "目で確認する。"
  },
  CollectionHall_48946_Title = {Text = "洞察"},
  CollectionHall_48947_Desc = {
    Text = "私たちは空っぽの人間であり、わら人形です。"
  },
  CollectionHall_48948_Desc = {
    Text = "嘘……ここまで、僕だけに。\nその出所を探らないで。"
  },
  CollectionHall_48948_Title = {Text = "強欲"},
  CollectionHall_48949_Desc = {
    Text = "ホムンクルスの名において、あなたに無垢なる肉体を捧げよう。"
  },
  CollectionHall_48949_Title = {
    Text = "少女の蛹"
  },
  CollectionHall_48950_Desc = {
    Text = "致命的な甘美が、鼻腔に広がっていく。\n気をつけて——粘つく死がやって来る。"
  },
  CollectionHall_48950_Title = {
    Text = "ナメクジプリン"
  },
  CollectionHall_48968_Desc = {
    Text = "デクスター卿の杖について、ミサゴキャンパスには多くの噂が流れています。\n\n「間違いなく、卿の杖には彼の笑顔と同じくらい秘密が隠されています。\nシルバーコアが入っていて覚醒体の力を引き出せるのか、それとも火薬が仕込まれていて銃に変わるのか？\nデクスター卿にその秘密を明かしてもらいましょう！」\n\n開幕の言葉を読み上げながら速記し、ハンナはカメラをデクスター卿に向け、持ち主本人の言葉を待ちました。\n\n「それですか？特に特別なものではなく、デクスター家のカスタム日用杖です。\n私の杖に使われている宝石は、兄のものほど貴重ではありません。\nもし特別な点があるとすれば……\nそれは両親と兄弟の血が染み込んでいることです。これでいいですか？」"
  },
  CollectionHall_48968_Title = {
    Text = "貴族の杖"
  },
  CollectionHall_48969_Desc = {
    Text = "ロンディニウムの地下世界にはこんな話が伝わっています。\n\n忙しい港で、静かな路地で、賑やかな酒場で……\nあなたは、カメラを持ち、メガネをかけたユニフォームを着た少女がいつどこにいるのかわからないですが、彼女を見つければ、欲しい情報を何でも買うことができます。その代価はたった一つ——\n\nあなたしか知らない秘密を提供すること。\n\nある人は酒バーで聞いた酒飲みの真実を使って、競争相手の致命的な弱点を手に入れました。\n別の人は自分の弱点と引き換えに、恋人の口にしない過去を得ました。\n少女は無数の情報を握っていますが、一つだけはどんな秘密でも交換できないものがあります。\n\n「私のこと？ごめんなさい、これは非売品よ」"
  },
  CollectionHall_48969_Title = {
    Text = "情報は命"
  },
  CollectionHall_48970_Desc = {
    Text = "ミサゴキャンパスで最も関わってはいけない人物は、ドールが二位だとしたら、シルヴィア氏が一位である。\n\nミサゴ唯一の精神科医として、彼女は驚いた調査員を慰め、覚醒体の興奮を鎮める役割も担っている。\n覚醒体を恐れず、精神的に対抗できる—それはどれほど強力な人物か。\n\n新入生は好奇心に駆られ、深夜にシルヴィア氏の診察室に忍び込んだ。\n\nそして意識を失った。\n翌朝、キャンパス広場で目覚めた時、彼らは激しい頭痛に襲われながらも、心はかつてないほど明晰だった。\n彼らのポケットから飛び出たメモを拾い上げた者もいた。\n\n「心理相談が必要な場合は、エリカ氏に事前申請を——\nシルヴィア」"
  },
  CollectionHall_48970_Title = {
    Text = "心の障壁"
  },
  CollectionHall_48971_Desc = {
    Text = "貴族夫人が哀れみと嫌悪の入り混じった表情でハンカチで鼻を覆い、不要な宝石を召使いに渡すとき、彼女は思う：\n素晴らしい、ワークハウスの子供たちが肉を食べられる。\n\n自分の食事をすべて子供たちに分け与え、長い飢えで廊下に倒れたとき、彼女は言う：\n大丈夫、医者を呼ばないで、診察料はパン数個分の価値がある。\n\n親切な芸術家が知り合いの医者を連れて訪れ、長期的な協力を提案したとき、彼女は思う：\nまず私で試してもらわないと、子供たちにこの治療を受けさせるのは安心できない。\n\nサラは何でも耐えられるが、唯一耐えられないのは、すべてが悲劇に終わることだ。"
  },
  CollectionHall_48971_Title = {Text = "臨界点"},
  CollectionHall_48972_Desc = {
    Text = "手が暗闇の中を探し回り、主人を探している。\n\nあの血塗られた夜、手は主人から無情に引き離された。\n今、この瞬間、手を奪った犯人が周囲を流れ、奇妙な音を発している。\n \n「諦めて、私たちと一緒に行こう。蝋人形師は君を忘れるだろう」\n\n手は動じず、誇りに思っている長い指を動かした。\n\n「主人は私を忘れない。\n私は彼の芸術の唯一の手段だ——\n君たちは私が彼にとって何を意味するか理解していない」\n\n「人は恋人や時間を忘れるが、自分を忘れない」\n\n暗闇から同情の笑い声が聞こえた。\n「逆だよ、人はまず自分を忘れる。\nでも大丈夫——」\n\n時間がすべてを説明する、手はいつか理解するだろう：\n忘れられないものはない。\n彼らは何世紀も流れ続け、人間の物語が彼らの周りで起こり、翌日には忘れられる。\nそれでも彼らは流れ続ける。"
  },
  CollectionHall_48972_Title = {
    Text = "忘却の手"
  },
  CollectionHall_48973_Desc = {
    Text = "ワード・フィリップス氏に保護されて以来、アリステアは彼と共にミサゴの幹部会議に何度も出席してきた。\n\n幹部会議とは名ばかりで、実際には毎月一度の討論会のようなものだった。\nフィリップス氏は穏やかな口調で説得し、\nクラークシュは辛辣な言葉で一歩も譲らない。\n彼らはミサゴの未来や来月の覚醒学部の予算配分について、交互に肯定側と否定側を務め、激しく議論した。\nタヴィ嬢は沈黙の傍観者で、決して自分の意見を簡単に述べることはなかった。\n彼自身は正直なスコアラーを務め、時には審判役も兼ね、さらには一度、会議テーブルを守るために格闘技を使わなければならなかったこともあった。\n\n今では、会議のメンバーは二人だけになり、一人は永遠に昏き海を離れることができず、もう一人はその「未来」を勝ち取るために地下から出られなくなった。\nあのテーブルは、あの事件以来、二度と見つからなかった。"
  },
  CollectionHall_48973_Title = {
    Text = "集会の時"
  },
  CollectionHall_48974_Desc = {
    Text = "タヴィは昏き海の底で眠っている。\n\nそこは一年中、音も光もなく、絶望的な暗闇だけが広がっている。\nここを訪れる客人はなく、音も届かない。\nここは破滅が及ばない場所——\n\nなぜなら災厄がすでに降りてきたから。\n\n時の管理者として、彼女は多くの悲惨な終局を目撃してきた。\n規則の一員として、彼女もまた夜の到来を阻止できない。\nだからこそ、存在しない場所で、存在しない姿で「変数」と呼ばれる者の到来を待つしかない。\n\nその人は必ずやってくる。"
  },
  CollectionHall_48974_Title = {
    Text = "存在しない場所"
  },
  CollectionHall_48975_Desc = {
    Text = "科学はスペクトル分析、芸術は光合成。"
  },
  CollectionHall_48976_Desc = {
    Text = "回転して、忘れる——それが彼女の人生のすべて。"
  },
  CollectionHall_48976_Title = {
    Text = "36の廻る部屋"
  },
  CollectionHall_48977_Desc = {
    Text = "私は、お前の墓を唾棄する。\nなぜならお前は、死の中で得難い安らぎを見出したのだから。"
  },
  CollectionHall_48977_Title = {
    Text = "墓地の囁き"
  },
  CollectionHall_48978_Desc = {
    Text = "永遠なる啓示の中から注がれる、一筋のまなざし。\nそれは、純潔で、無垢で、そして真実である。"
  },
  CollectionHall_48978_Title = {
    Text = "無垢の啓示録"
  },
  CollectionHall_48979_Desc = {
    Text = "臍帯は母体と繋がり、胎児に尽きることなき未来を吸い上げさせる。"
  },
  CollectionHall_48979_Title = {
    Text = "生命力搾取"
  },
  CollectionHall_48980_Desc = {
    Text = "還せよ、いずれ再び現れる、失われた都よ。\n還せよ、@3！"
  },
  CollectionHall_48980_Title = {
    Text = "深海航路"
  },
  CollectionHall_48981_Desc = {
    Text = "鱗翅目は孤独、愛、絶望に死す。"
  },
  CollectionHall_48981_Title = {
    Text = "有機形態"
  },
  CollectionHall_48982_Desc = {
    Text = "彼は18@2年の春に埋葬された。\n墓が林立し、無言の讃歌のようだ。"
  },
  CollectionHall_48982_Title = {
    Text = "四月の賛歌"
  },
  CollectionHall_48983_Desc = {
    Text = "千年前、5分は40オンスの細砂に等しかった。"
  },
  CollectionHall_48983_Title = {
    Text = "薬となる夢"
  },
  CollectionHall_48984_Desc = {
    Text = "必然、偶然。有限、無限。"
  },
  CollectionHall_48985_Desc = {
    Text = "学長代理はミサゴ大学の異端者です。\n\n異能を持つ怪物が横行するミサゴ大学の調査員の中で、彼女は人間の基本能力を超えない数少ない個体の一人ですが、学長代理という重要な役割を担っています。\nエルク王国の普通の家庭に生まれた彼女は、地元の文化に影響されて勇猛で凶暴な性格を形成しました。\n\nその後、捕虜収容所の仲間ソフィアが彼女の学術研究への情熱を燃やしました。\n優れた学術成果により、彼女はミサゴ大学生物学部の前任学部長である師匠の最も認められた弟子となりました。\nしたがって、師匠が失踪した後、彼女は自然に学長代理の職務を引き継ぎました。\n彼女の庇護のもと、生物学部の研究は順調に進んでいます。\n\n「暴力を恐れず、覇権を恐れず、当然、職務も恐れない」"
  },
  CollectionHall_48985_Title = {Text = "職責"},
  CollectionHall_48986_Desc = {
    Text = "調査員の間には不文律がある：\n\n鍵塚の儀式の後の夜、ベテランの調査員が新任の調査員を宿舎の裏庭に集める。\n彼らはキャンドルを灯し、シルバーキーの周りに円を作って座る。\nベテランの調査員は各新人に、手にしている唯一無二の番号を持つキーが持っているストーリーについて語る。\n\nこのようなイベントは最終的に何らかの物語会議になるが、I-0001およびK-0001、この二つの「初代」を代表するキーは当然ながら討論の中心となる。\n誰も知らないのは、初代の守秘者の手で作られたK-0001シルバーキーは今、主人とともに地下に永住し、昼夜を問わない長い待機の中で、その人が既に亡くなっている人にささやく言葉を聴いているということ。\n\n「君は彼が本当にここにいるわけではないことを知っているだろう、アリステア」ドールが言った。「それは君の先生のシルバーコアで作られたかもしれないが、彼の魂として見なすことはできない」\n「これは精神に集中する一つの方法に過ぎない、ドール」アリステアは笑い、「安心して、私はとても安定していて、私たちの新任守秘者が成長する前に倒れるわけにはいかない、そうだろう？」"
  },
  CollectionHall_48986_Title = {
    Text = "精神集中"
  },
  CollectionHall_48987_Desc = {
    Text = "彼の人生の前半は混沌と、闇、血にまみれていた。\n\n食べては寝て、寝ては食べ……やがて彼は目を開け、意識を持った。\n\n彼は自らの兄弟姉妹をすべて食べ尽くし、唯一生き残った者だと言われた。\n彼は偉大な蛇神と人間との間の子だとも言われた。\n\n彼の首には黒い呪縛の輪が刻まれ、それが彼の命を保ち、教会に逆らえないようにしている。\n\n彼は世界に疑問と好奇心を抱いていたが、生まれた時からすべての可能性を奪われていた。\n\n美しく、危険で。\n隠され、目立つ。\nそれらはすべて、彼の一部だ。\n\nだが、残念ながら、これらの供述は彼の本質の一割にも触れていない。\n\nこの供述に基づきアルビノへ同情を抱いたなら、それは、あなたを破滅に導くだろう。"
  },
  CollectionHall_48987_Title = {
    Text = "苦しみの呪縛"
  },
  CollectionHall_48988_Desc = {
    Text = "医者の使命は、患者を治すことでした。\n\nだが、不運にもある治療法は最も鋭い刃で皮膚を切り裂き、筋肉を突き刺し、胸を開き、病巣を摘出し、人体が自然治癒の力を借りて再生することを願うものでした。\n\nこれは彼女の罪ではないはずでした。\nしかし、手術が終わるたび、彼女は補償するようにその少女に物語を語ってしまうのでした。\n彼女は上手な語り手ではなく、話は断片的でしたが、その架空の物語は少女を真剣に聞き入らせました。\n彼女が切り取った場所は、ゆっくりと、しかし確実にその言葉の力を吸収し、自然に癒されていくようでした"
  },
  CollectionHall_48988_Title = {
    Text = "切断と危害"
  },
  CollectionHall_48989_Desc = {
    Text = "巨獣は夜闇に潜伏していた。\n\n小屋の中では、愛娘を失った悲しみが毎夜白昼の忍耐と抑制を破って爆発した。\nすすり泣きから叫び声に至り、最後にはもはや巨獣に属さない名前を悲痛な声で呼び続けた。その声は巨獣の人間と変わらない心を貫いた。\n\n家に帰ろう、リサ。\nああ、私のリサ。\n巨獣は無言で夜闇に潜み、身を丸めて深い眠りに落ちた。\nいつの日か彼女は戻るのだ、その名を「家」と呼ばれる場所に。"
  },
  CollectionHall_48989_Title = {
    Text = "夜に伏す"
  },
  CollectionHall_48990_Desc = {
    Text = "誰も生まれつき船長ではない、少なくともエルトンは違った。\n\n船長になる前、彼は海軍と商船の間を転々としていた。何度も海賊になりかけたが、最終的に探検船で落ち着いた。\n\n探検船は極地大陸を巡り、上陸するたびに新たな冒険が待っていた。\n彼の役割は体の弱い科学者の荷物を運ぶことだった。それを誇りに思っていた——荷物には世界を変えるかもしれないものが入っていた。\n彼らは歴史を変えるかもしれない人々だった。\n\n氷嵐が彼らを氷洞に閉じ込める前、神秘的な教徒たちが夜襲をかける前、エルトンはそう思っていた。"
  },
  CollectionHall_48990_Title = {
    Text = "旅の荷物"
  },
  CollectionHall_48991_Desc = {
    Text = "彼はいつも無口で勤勉な学生だった。\n\n朝8時、他の研究員がたちがパンをくわえて、慌ただしく研究棟へ駆け込んでくるころには、彼は既に実験報告を書き終えていた。\n夜12時、実験棟の灯りがすべて消えると、重い腰を上げて静かに帰る。\n\nそういえば、彼は毎日近くの野良猫に餌をやっていた。\nだが、ある日、野良猫は姿を消した。誰もどこに行ったのか知らない。\n\n指導教官のクロウリーは彼の実験記録と報告を分析した。\n簡潔で細かく、特に目立つ点はないが、欠点もなかった。\n\nこの学生は彼に疑念を抱かせた。\nもっとも「疑念」とは決して悪いものではない。\nそれはしばしば「好奇心への扉」となる。\n\nもちろん、その時のクロウリーは思いもしなかった。\nそれが「死への扉」にもなりうることを——"
  },
  CollectionHall_48991_Title = {
    Text = "死の分析"
  },
  CollectionHall_48992_Desc = {
    Text = "「知らぬ間に、君はもうこんなに長く離れている。\n\n夢の中でよくあの日に戻る。左腕の銃傷の痛み、失血による幻覚、暴れ回る鼠の群れ……\nその混乱の中、ミサゴの制服を着た君が現れ、不吉な古城から私を連れ出してくれた。\n\n夢の最後で、君は病床の前に立ち、調査員にとって死は常に影のように付きまとうと警告した。\nそれが現実か幻想か、もう判断できない。\nそんな時、左腕に触れる。冷たい金属の表面を感じれば、それが現実だ。\n\nしかし、ほとんどの夢では、私はただ虚空を掴むだけだ」"
  },
  CollectionHall_48992_Title = {Text = "親友へ"},
  CollectionHall_48993_Desc = {
    Text = "クロウリーは在職中ずっと「一番人気の教師」の称号を保ち続けた。\n\nややぎこちないコンスタン西部訛りと、誠実な笑顔は、多くの学生たちの好感をもたらし、ハーバートもその一人だった。\n\nA.F.2@1年、クロウリーは反対意見を押し切り、目立たない存在だったハーバートを自分の弟子として迎え入れた。\n\nハーバートは彼と共に山を越え、川を渡り、砂漠を横断し、いくつもの融蝕裂け目の傍らに足跡を残していった。\n\n彼は初めて融蝕の裂け目を見た時の衝撃を今でも覚えている。\nクロウリーが黒煙のように立ち上る霧の前に立っていた。\n彼の姿はとても小さく見えた。\n\n「しっ——聞こえるか？」\nハーバートは目を閉じ、静かな海の波音のような響きを聞いた。\n世界が遠く離れていくかのようだった。\n\nクロウリーは非常に興奮して言った。\n「これは詩だ。宇宙で最も神秘的で、最も深い詩だ」\n\nそれから何年も経ち、ハーバートの中でクロウリーとの記憶はすでに曖昧になっていた。\nどのように共に働き、争い、そして——自分がどうやって彼を「誤って」殺してしまったのかも。\n\nしかし、彼はあの黒い霧の下の笑顔を永遠に忘れない。\nその瞬間、彼は詩を見た。"
  },
  CollectionHall_48993_Title = {
    Text = "記憶障害"
  },
  CollectionHall_48994_Desc = {
    Text = "私たちの脳が謎である限り、中に触腕が生えていても驚くことはない。"
  },
  CollectionHall_48994_LockTip = {
    Text = "調査で解放"
  },
  CollectionHall_48994_Title = {
    Text = "<WhiteQuality:裂頭条虫>"
  },
  CollectionHall_48995_Desc = {
    Text = "夢は星の海！"
  },
  CollectionHall_48995_LockTip = {
    Text = "調査で解放"
  },
  CollectionHall_48995_Title = {
    Text = "<WhiteQuality:潜水ヘルメット>"
  },
  CollectionHall_48996_Desc = {
    Text = "見えない者を見、聞こえない者を聞く。"
  },
  CollectionHall_48996_Title = {Text = "悟り"},
  CollectionHall_48997_Desc = {
    Text = "すべての悪の根源。"
  },
  CollectionHall_48997_Title = {Text = "懲罰"},
  CollectionHall_48998_Desc = {
    Text = "万物を自分のものにする。"
  },
  CollectionHall_48999_Desc = {
    Text = "過去を見ず、未来を思わない。"
  },
  CollectionHall_49000_Desc = {
    Text = "愛と死を世界に捧げる。"
  },
  CollectionHall_49000_Title = {Text = "寵愛"},
  CollectionHall_49001_Desc = {
    Text = "長い間蓄え、ここに宣言する——"
  },
  CollectionHall_49001_Title = {Text = "湧出"},
  CollectionHall_49002_Desc = {
    Text = "名前を呼ぶ：エリックス。"
  },
  CollectionHall_49002_Title = {Text = "錯乱"},
  CollectionHall_49003_Desc = {
    Text = "「彼」との対話。"
  },
  CollectionHall_49003_Title = {Text = "呟き"},
  CollectionHall_49004_Desc = {
    Text = "萌芽と胚胎の祝福を授ける。"
  },
  CollectionHall_49004_Title = {Text = "希望"},
  CollectionHall_49015_Desc = {
    Text = "災厄が突然消え、危機から一時的に解放された後、ミサゴの特別行動隊は「思わぬ収穫」をアクートから持ち帰える事になった。\nデクスター嬢が最後に爆発の中心の大穴を振り返った時、見知らぬ植物の芽がいつの間にか土を破っていた。\n彼女は安堵の息をつき、心が少し晴れた。\nアクートの森は春を迎える。\n柳は次の春にも芽を出し、スズランは次の雨季の後に静かに咲くだろう。すべての生命が新生を迎える。\nそして彼らの未知への旅も新たな始まりを迎える。"
  },
  CollectionHall_49015_Title = {
    Text = "アクートの春"
  },
  CollectionHall_49018_Desc = {
    Text = "A.F. 314年、冬の深夜、爆発音がアクート林地に響き渡った。\n大地が震え、林地は昼のように明るくなった。生命の叫び声と自然の嘆きと共に、村や町は平地となった。\n「アクート災厄調査」に参加した覚醒学部予科生デクスターによると、その夜の火光の中で、黒と銀の色が輝いていたという。"
  },
  CollectionHall_49018_Title = {Text = "落日"},
  CollectionHall_49025_Desc = {
    Text = "濃く黒き血の祭儀。\n双子があなたの肉体を庇護せんことを。"
  },
  CollectionHall_49025_Title = {
    Text = "歪みの双子・黒"
  },
  CollectionHall_49026_Desc = {
    Text = "霧白の祈り。\n双子があなたの魂を守護せんことを。"
  },
  CollectionHall_49026_Title = {
    Text = "歪みの双子・白"
  },
  CollectionHall_49027_Desc = {
    Text = "存分に宴を楽しめ、歌声の中で滅び去った故郷を祝え。"
  },
  CollectionHall_49027_Title = {
    Text = "遠くの宴"
  },
  CollectionHall_49028_Desc = {
    Text = "伝説に語られる最初のゴーレム創造主は、血によってゴーレムを育てた。"
  },
  CollectionHall_49028_Title = {
    Text = "深紅の鼓動"
  },
  CollectionHall_49029_Desc = {
    Text = "機械は絶対に純粋であり、神は至高無上である。\n降臨したのは糸ではない。\n偉大なるアリアドネだ。"
  },
  CollectionHall_49029_Title = {
    Text = "機神降臨"
  },
  CollectionHall_49030_Desc = {
    Text = "繁殖せよ、繁殖せよ。母樹の血が流れる魂を世界中に広めよ。"
  },
  CollectionHall_49030_Title = {Text = "再進化"},
  CollectionHall_49031_Desc = {
    Text = "伝説に語られる最初のゴーレム創造主は、自らの手でゴーレムを殺した。"
  },
  CollectionHall_49031_Title = {
    Text = "深紅の抱擁"
  },
  CollectionHall_49033_Desc = {
    Text = "時間の弦が次々と切れ、流れる鍵盤が砕け散る。\n彼らは現実の外に立ち、現実を素材に欠けた部分を縫い合わせ、永遠に終わらない楽章を再び高天に響かせる。\nその一瞬の夢から覚めた涙がどこに流れたのか、誰も知らない。"
  },
  CollectionHall_49033_Title = {
    Text = "魂の誕生"
  },
  CollectionHall_49082_Title = {
    Text = "ロンディニウム屋外"
  },
  CollectionHall_49084_Title = {
    Text = "02 蝋人形の名において"
  },
  CollectionHall_49104_LockTip = {
    Text = "調査6-1クリアで解放"
  },
  CollectionHall_49104_Title = {
    Text = "倒錯した星々"
  },
  CollectionHall_49105_LockTip = {
    Text = "特務記録「血の色：懺悔」クリアで解放"
  },
  CollectionHall_49105_Title = {
    Text = "霊魂の牧人"
  },
  CollectionHall_49740_LockTip = {
    Text = "調査7-0クリアで解放"
  },
  CollectionHall_49740_Title = {
    Text = "無数の子孫の母"
  },
  CollectionHall_49747_Desc = {
    Text = "融蝕の傷痕から生えた腫瘍。\n今のところ、腫瘍の成長や種類の分布には規則性が見られない。\nそれは追加の四肢や触手、あるいは歯車や金属などの無機物かもしれない。"
  },
  CollectionHall_49747_Title = {
    Text = "融蝕思念体"
  },
  CollectionHall_49748_Desc = {
    Text = "<Title:定義と特性>\n直径5メートル以上で拡大の可能性がある巨大な融蝕痕。\n融蝕の裂け目の大きさにより、C、B、A、S、SS、SSSに分類される。\n時間が経つにつれ、拡大し続け、融蝕の拡散に加え、津波やハリケーン等の異常自然現象を引き起こす。\n\n<Title:対処法>\nシルバーコアから精製されたシルバーキーで裂け目の進行を抑制または「閉鎖」できる。\n守秘者は、シルバーキーを使って自身の精神を拡大し、精神次元と共鳴して高次元バリアを形成し、一時的に裂け目を「閉鎖」する。"
  },
  CollectionHall_49748_Title = {
    Text = "融蝕の裂け目"
  },
  CollectionHall_49749_Desc = {
    Text = "融蝕の裂け目の核心は、外勤中の守秘者が解決すべき主要な敵だ。\n拡散する融蝕現象は、自身の特性に基づいて周囲の融蝕現象に影響を与え、地域特有の特性を持つ。"
  },
  CollectionHall_49749_Title = {Text = "災厄"},
  CollectionHall_49750_Desc = {
    Text = "<Title:定義と特性>\n融蝕現象による個体の異変、融蝕、死亡の現象。\n人間や動植物等の有機体だけでなく、鉱物、金属等の無機物にも発生する。融蝕の裂け目近くの個体は融蝕に侵される可能性が高い。\n融蝕に免疫を持つ物質は未発見。\n\n<Title:各期の特徴>\n初期：体表に逆三角形の黒い融蝕痕が現れ、融蝕液が分泌される。\n中期：融蝕痕が拡大し、融蝕液の分泌が続き、個体の精神が損なわれる。融蝕思念体が発生する場合もある。\n後期：融蝕痕が急速に拡大し、融蝕液の分泌が加速する。多くの個体はこの段階で理性を完全に失う。\n末期：個体が崩壊し、身体的に死亡し、精神が侵食され尽くすと消滅し、召喚の可能性が完全に失われる。\n\n<Title:特殊ケース>\n身体的ケース：融蝕された個体に体・感覚増強現象が現れる。他に、腫瘍や災厄などの影響を受け、飛行や精神影響、思考制御等の能力を持つ個体がいる。\n精神的ケース：融蝕された個体の精神が融蝕から比較的影響を受けにくく、基本的な理性を保つ。一部の個体は正常に見え、未融蝕の個体と変わらない。"
  },
  CollectionHall_49750_Title = {
    Text = "融蝕侵蝕"
  },
  CollectionHall_49751_Desc = {
    Text = "<Title:定義と特性>\n個体が融蝕で体を失い、融蝕液や粉塵になる現象。\n消解された個体は存在自体が抹消される。\n\n<Title:各期の特徴>\n初期：融蝕された個体の存在を知らない者がその存在を忘れる。\n中期：融蝕された個体の記憶が薄れ、関連する書面記録が融蝕痕で曖昧になる。\n後期：融蝕された個体の記憶がさらに退行し、曖昧な印象だけが残り、完全に忘れ去られる。\n\n<Title:存在の消失>\n消解が最終段階に達すると、融蝕された個体の存在痕跡が完全に抹消される。\nその存在を示す証拠は一切なくなる。"
  },
  CollectionHall_49752_Desc = {
    Text = "シルバーコアは融蝕の終点かもしれない：それは生命が融蝕されるときに確率的に析出する銀のような物質だ。それは巨大な物理エネルギーを含むだけでなく、精神次元とも一定の関係を持つ。場合によっては、この関係が「精神次元」に干渉することさえある。シルバーコアは人類が融蝕と戦う鍵の一つだ。しかし、その形成方法の特殊性から、シルバーコアは数が少なく、非常に貴重だ。"
  },
  CollectionHall_49752_Title = {
    Text = "シルバーコア"
  },
  CollectionHall_49753_Desc = {
    Text = "<Title:概述>\nすべてのシルバーコアを利用する技術は、シルバーコアテクノロジーと総称される。\n世の大多数の人々はシルバーコアの存在を知らない。ミサゴ大学だけがシルバーコアテクノロジーを掌握し、シルバーコアの研究と応用専門課程を設置し、研究開発を続けている。\n《ミスティア協定》に基づき、ミサゴ大学はミスティア協定審査会にシルバーコアテクノロジーを提供し、融蝕とその危機に対抗している。\n\n<Title:覚醒体？>\nミサゴ大学の覚醒体技術では、覚醒体の作成はシルバーコアを中心に行う必要がある。\nしかし覚醒体の作成は《シルバーコアテクノロジーマニュアル》に記録されていないが、多くの覚醒体は冗談めかしてこう言う——\n「僕たちもシルバーコアテクノロジーの一種だよね？」\n\n<Title:融蝕観察装置>\n眼鏡、仮面など、多様な形状がある。シルバーコアで作られ、装着者が密境を観測し、融蝕を視認することが可能になる。\n\n<Title:ミサゴ大学通信機>\n最も一般的な形状は校章のバッジである。その中心は特別に処理されたシルバーコアで、通信機は相互に接続できるだけでなく、ミサゴ大学内部と超長距離通信を実現できる。信号は安定しており、<Italic:一般的な状況では>自然現象による影響を受けない。\n\n<Title:ミサゴ入校許可証>\nシルバーコアを含む特別な許可証で、許可証を持つ者だけが、ミサゴ大学の霧のバリアで迷わず入ることができる。\n許可証を持たない者は、大学外の森林で無限の知覚失調に陥り、巡回調査員による排除を待つことになる。"
  },
  CollectionHall_49753_Title = {
    Text = "シルバーコアテクノロジー"
  },
  CollectionHall_49754_Desc = {
    Text = "<Title:原理>\nシルバーコアから覚醒するか、実験改造を受けるか、あるいは偶然の産物であるか……\n彼らは古くて新しい。古いものは、何世紀も前のパピルスに魔法使いが覚醒体の存在を記録していたからだ。\n新しいものは、私たちがまだ彼らを完全に理解していないのに、共に世界を救おうとしているからだ。\n信頼を除いて、無防備にしないことを忘れずに。\n\n<Title:特性>\n覚醒体は完全な人格と「生前」の記憶を持ち、特殊な能力のために一度は人形兵器とみなされた。\n俗世間の安定を維持するために、覚醒体の存在は各国で極秘である。\n現在、《協定》はミサゴ大学が召喚した覚醒体のみを承認しており、他の覚醒体は《協定》違反とみなし、公式に記録して収容する必要がある。\n\n<Title:界域>\n覚醒体の能力はそれぞれ異なるが、研究者はそれらの間に一定の相似を見つけることができる。\nこの相似に基づき、ミサゴ大学は人為的にいくつかの覚醒体界域を分類した。\n同じ界域の覚醒体はよりよく協力できるが、異なる界域間には一定の排斥が存在する。混沌界域だけはこの現象がない。\n界域間の排斥の原因は不明だが、ミサゴ大学の覚醒学部ドール教授によると、ある未知の存在が精神次元に影響を与えている可能性がある。しかし、いまだ証拠はない。"
  },
  CollectionHall_49754_Title = {
    Text = "覚醒体認知基礎"
  },
  CollectionHall_49755_Desc = {
    Text = "<Title:概述>\nシルバーコアを唯一の材料とするキー型アイテム。使用者の精神を集中的に拡大し、精神次元と連結し影響を及ぼす能力を持つ。\nシルバーキーはミサゴ調査員と守秘者の身分の象徴であり、各シルバーキーにはユニークな番号が割り振られている。通常の調査員の場合、そのシルバーキーの番号は「I」で始まり、守秘者の場合は「K」で始まる。\n調査員が何らかの理由で外勤活動を続けられない場合、ミサゴ大学はその所持するシルバーキーを回収し、将来他の調査員に配布する。\nしかし残念ながら、回収記録によると、百年間で正常に稼働するシルバーキーは十本しか回収されていない。大半のシルバーキーは、所有者の死と共に破壊されている。\n\n<Title:製造と配布>\n■■機密文書第■■■号\nシルバーキーの製造は、昏き海で■■■■■によって行われる。\n■■■が製造された後、番号の刻印を施し、鍵塚の儀式で相応の利用者に与えられる。"
  },
  CollectionHall_49755_Title = {
    Text = "シルバーキー"
  },
  CollectionHall_49756_Desc = {
    Text = "<Title:概述>\n密境は、現実世界と精神次元が一体となって構築された特別な領域。\nミサゴ大学のフィリップス氏は、その手記の中で次のように記している。世界のすべての異常は、もしそれが人心から来ないのであれば、密境から生まれたものである。\nここには生と死、現実と夢幻が交錯し、真実を排斥し、隠す。\n\n<Title:定義と特徴>\n密境は人類が肉体で入れる最も精神次元に近い空間だが、人々はそれについてはなおも理解していない。人々が融痕について一知半解であるように。\nしかし確かなことは、融蝕と密境は常に同時に現れる：融蝕の現象が深刻であるほど、密境次元の範囲は広がる。\n\n<Title:密境の領域にあるもの>\n脆弱な境界帯として、密境は簡単に影響を受けやすい。\n密境に現れる特別な存在、例えば幻影、融蝕、霧などは、感情と思考の投影と見なされている。この特殊な投影メカニズムを利用して、ミサゴは密境に一部の休憩所を投影し、調査員の精神を安定させ、覚醒体の傷を癒合した。\nしかし、現実に存在する物体、例えば地面、建物などは、密境では通常影響を受けない。（心配しないで、密境の道は<Italic:大部分>の時間は安全です）"
  },
  CollectionHall_49757_Desc = {
    Text = "<Title:創設日>\n洪積暦以前\n\n<Title:創設者>\n不明\n\n<Title:紹介>\nローラシア大陸全域でもっとも広く信仰されている宗教。\n信者が多く、規模も大きい。毎年特定の時期に各地で祝祭が行われ、その中でも最も広く知られているのは「フロストデイ」と「冬渡節」である。\n組織内の聖職者は「父なる神の代行者」と自称し、父なる神の意志を実行し、世界の苦難を取り除くことを使命とする。\n人は死後、父なる神の懐に戻り、永遠の楽園に住むことができ、現世の苦難から解放されると信じている。\nこのような普遍的な教義であるため、人々から広く受け入れられている宗教となっている。"
  },
  CollectionHall_49757_LockTip = {
    Text = "特務記録「血の色：懺悔」クリアで解放"
  },
  CollectionHall_49757_Title = {
    Text = "生命教皇庁"
  },
  CollectionHall_49758_Desc = {
    Text = "<Title:創設日>\n洪積暦以前\n\n<Title:創設者>\nミリアム\n\n<Title:紹介>\n旧大陸からの古い組織。\nメンバーは上半身が魚、下半身が人間の特徴を持ち、主に海洋や沿岸で活動し、内陸には入らない。\n彼らは王の足跡を追うために海を渡り、王の国をもたらすために海を渡ってくると言われている。\nすべての犠牲は失われた国リモリアとその眠れる王のためである。"
  },
  CollectionHall_49758_LockTip = {
    Text = "調査第5章「嵐の眼」クリアで解放"
  },
  CollectionHall_49758_Title = {Text = "海踊人"},
  CollectionHall_49759_Desc = {
    Text = "<Title:創設日>\n洪積災変期\n\n<Title:創設者>\n不明\n\n<Title:紹介>\n秘密の宗教組織。\n融蝕を神の贈り物とし、シルバーコアを神の体と見なし、融蝕が罪を浄化し、人々を無罪の浄土へ導くと信じている。\n人数は多いが行動は隠密で、融蝕のある場所には必ず彼らの影が見える。\n古い名家から発祥したと言われ、その家族のメンバーが集団で消えた理由は今も歴史家の議論の的である。"
  },
  CollectionHall_49759_LockTip = {
    Text = "調査第4章「無音の中で」クリアで解放"
  },
  CollectionHall_49760_Desc = {
    Text = "<Title:霊性指数>\nシルバーコアにおける精神破片の安定性を数値化したもの。\n霊性指数が高い覚醒体ほど、精神破片の安定性が強く、狂乱の程度が低く、制御不能になるリスクが低い。制御不能になっても被害が少ない。\n覚醒体ごとに霊性指数は異なる。特殊な状況では指数の変動や正確な測定が困難な場合もある。\n\n<Title:覚醒体制御不能>\nシルバーコアは覚醒体に不自然な力を与えると同時に狂気の種を植え付ける。\n覚醒体は多くの場合、制御不能な狂気に陥るが、調査員の迅速なリンクにより、世界への破壊を防ぐことができる。リンクは「増幅器」であり「安定器」でもある。\nミサゴ大学の記録では、初期から理性を保ったのはドール・@2のみ。\nさらに「扉内の者」タヴィと初代守秘者アリステアがL-01号融蝕の裂け目下の巨大シルバーコアの安定を維持し、ミサゴ大学内で覚醒体が長期に渡り理性を保つことができる。リンクが切れても制御不能にはならない。\n\n<Title:覚醒体の死亡>\n覚醒体は人間よりも肉体機能が優れているが、変異体、災厄、融蝕の裂け目や融蝕自体の脅威に晒されればダメージを受け、肉体が破壊される可能性がある。\n研究員は覚醒体の肉体が破壊されると、その意識は精神次元に戻り、二次召喚を待つと信じている。\nシルバーコアの破損は、真の「死」を意味するかもしれない。\n\n<Title:二次召喚>\n二次召喚後も、覚醒体の外見、性格、好み、能力は変わらず、記憶も保持される。しかし、一部の覚醒体は、現在の自分とは別の個体だと考える。ミサゴ大学はそれらの声に保持意見を持っている。"
  },
  CollectionHall_49760_Title = {
    Text = "覚醒体認知進級"
  },
  CollectionHall_49761_Desc = {
    Text = "<Title:概述>\nいくつかの覚醒体は、能力、形態の異変特性が非常に似通っていることが判明している。そのため研究者たちは、召喚中に何らかの未知の存在（ある人は汚染と見なしている）がこれらの覚醒体の精神に影響を与え、彼らに強力な力を与えたと推測している。\n現在、研究者たちはこの影響を及ぼした覚醒体の力を「真貌」と呼んでいる。\n\n<Title:真貌覚醒体>\n真貌覚醒体は、同名の覚醒体である「もう一人の自分」だ。\n彼らは類似した特質を持っているが、人生の経験、性格、趣味、行動、さらには力も「同源」の特色がより多く含まれている可能性がある。\n真貌覚醒体についての記録は限られており、ミサゴ大学もこの種の現象の原因をほとんど知らない。研究者たちは真貌覚醒体の出現から、「平行世界」の存在を推測し、発展させたが、この理論は現在公開されておらず、さらなる研究は行われていない。"
  },
  CollectionHall_49761_Title = {Text = "真貌"},
  CollectionHall_49762_Desc = {
    Text = "<Title:核心>\n覚醒体の核心はシルバーコアです。たとえ体が完全に解体されても、シルバーコアが残っていれば、その覚醒体を再召喚させることができます。\n\n<Title:躯体>\n覚醒体の躯体はさまざまな材料で構成される可能性があり、具体的な構成材料と構造は覚醒体自身の好みおよび特性に関連しています。\n覚醒体の躯体はミサゴ大学の職員によって事前に提供されることはなく、召喚儀式において、シルバーコアの精神エネルギーによって物質から融蝕されて形成されます。したがって、召喚儀式においては、必要なシルバーコアおよびシルバーキーを除いて、大量の材料を準備し、覚醒体が躯体を合成するために使用します。一般的な材料については、付録第3号を参照してください。\nまた、ミサゴ大学には覚醒体の躯体の損傷を維持する専門の部門および研究者がいます。"
  },
  CollectionHall_49762_Title = {
    Text = "覚醒体構成"
  },
  CollectionHall_49763_Desc = {
    Text = "<Title:日常>\n覚醒体はミサゴ大学で教職員と同等の権利を享受でき、施設の使用や調査報酬の取得が可能。\nパートナー調査員が外勤任務を持っていない場合、覚醒体はキャンパス内で自由に活動できる。ほとんどの覚醒体は生前の趣味や習慣を続け、自分のやりたいことを見つける。また、授業に参加して時代を学んだり、調査員と交流する者もいる。\n特別な状況を除き、覚醒体は食事や睡眠を必要としない。しかし、望む場合はそれを行っても問題ない。\n\n<Title:戦闘>\n戦闘指揮とリンク維持の消耗をバランスさせるため、ミサゴ大学は「霊知の転写器」という特別な装置を開発した。\n外勤用スーツケースに内蔵されている「霊知の転写器」は、覚醒体の能力をカードとして転写し、覚醒体の指揮を行うための道具となる。"
  },
  CollectionHall_49763_Title = {
    Text = "覚醒体行動"
  },
  CollectionHall_49764_Desc = {
    Text = "<Title:創設日>\nA.F.306\n\n<Title:創設者>\nハーバート・ローゼンタール\n\n<Title:紹介>\n急進的な民間の研究組織。\n人間と融蝕物を融合させて進化を目指し、災厄の世界で生き残ることを目標としている。\n20人以上の急進的メンバーで構成され、無実の人々を実験材料として扱う残酷な手段を取る。\n創立者はミサゴ大学の悪名高い反逆者ハーバート・ローゼンタールで、提灯教会と密接な関係を持つ。\nシンボルは彫刻用の平頭のノミで、像を愛したキプロスの王を称えて選ばれたと言われている。"
  },
  CollectionHall_49764_LockTip = {
    Text = "調査第3章「猛犬注意」クリアで解放"
  },
  CollectionHall_49764_Title = {
    Text = "彫刻家協会"
  },
  CollectionHall_49765_Desc = {
    Text = "<Title:概述>\nミサゴ大学が特殊な過程で育成するプロフェッショナルは、強い精神力を持ち、覚醒体とのリンクによる消耗に耐え、その精神指令に従う。\n彼らは融蝕に立ち向かい、人類存続のために戦うが、その存在は広く知られていない。融蝕で死亡した調査員の名前や記録さえ完全には残らない。\n彼らの名前は誰も知らないが、その功績が永遠に記憶されることを願っている。\n\n<Title:選抜>\n《調査員の精神構成とその潜在能力》の理論に基づき、ミサゴは個体とシルバーキーの精神的共鳴強度を観察し、強い精神力を持つ個体を選別して育成する。\n\n<Title:助成>\n選別後、調査員は予科に入り1年間の研修を受ける。\n研修内容には、融蝕の基礎理論、シルバーコアテクノロジー入門、覚醒体理論などの基礎科目と、基本体力訓練、覚醒体リンク、覚醒体指揮などの作戦関連訓練が含まれる。\n\n<Title:鍵塚の儀式>\n1年間の学習を終え審査に合格すると、調査員は創立記念日に行われる「鍵塚の儀式」に参加する。\n儀式で調査員たちは誓いを読み、名前を墓石に刻む。\nその後、各調査員に「I」で始まる独自の番号が付いたシルバーキーが授与される。\nこれで彼らは元の自分と別れ、死亡後は名前が刻まれた石が彼らの存在証明となる。\n\n<Title:辞任>\n調査員が何らかの理由で外勤任務を遂行できない場合、ミサゴは彼らを尊重し、後方支援部や情報支援部などの比較的安全な部門に転属させる。\nそれでも、退任した調査員たちはしばしば心身の苦痛に苦しんでいる。\n世界の一端を垣間見た彼らにとって、安穏な余生は贅沢な幻想である。"
  },
  CollectionHall_49765_Title = {Text = "調査員"},
  CollectionHall_49766_Desc = {
    Text = "<Title:概述>\n調査員の中でも特別な存在で、他の調査員より強い精神力を持っている。\n調査員より高い権限を持ち、より深い秘密に接触でき、最も難しい任務を受け持つことが多い。\n融蝕との戦いの最前線に立つ彼らは、人類の盾となる。\n\n<Title:選抜>\n通常、ミサゴが調査員選別時に選ばれる特別個体が守秘者である。\nシルバーキーに特に強い反応を示す個体は、《調査員の精神構成とその潜在能力》の理論と規定に基づき評価と観察が行われ、その後守秘者として育成される。\n\n<Title:助成>\n基礎理論と戦闘訓練に加えて、守秘者には追加の精神力訓練が行われる。\n他の調査員より早く覚醒体と接触し、外勤任務を遂行することで自身の能力を磨く。\n\n<Title:鍵塚の儀式>\n審査に合格した守秘者は、調査員と共に「鍵塚の儀式」に参加し、シルバーキーを取得する。\n調査員とは異なり、守秘者のシルバーキーの番号は「K」で始まる。\nこれが守秘者の身分証となり、外勤任務での強力な助けとなる。\n\n<Title:守秘者与覚醒体>\n守秘者は覚醒体の力を借りて融蝕に対抗する。したがって、覚醒体の指揮能力は極めて重要だ。\n予科段階で厳しい指揮訓練を受け、鍵塚の儀式の後、担当の覚醒体と共に教師の監視の下で外勤任務を遂行し、独自に外勤任務を遂行できる能力を確認する。\n\n<Title:辞任>\n守秘者が外勤任務を遂行できない場合、ミサゴは彼らを尊重し、後方支援部や情報支援部などの比較的安全な部門に転属させる。\n守秘者はキーを返却し、記録を封印し、機密保持契約を結ぶことで退任できるが、これまでにそうした者は少ない。"
  },
  CollectionHall_49766_Title = {Text = "守秘者"},
  CollectionHall_49767_Desc = {
    Text = "<Title:覚醒体リンク>\n覚醒体は形成過程で未知の汚染を受けやすく、狂気に陥りやすいため、調査員は精神リンクが必要です。ほとんどの調査員にとって、シルバーキーの力を借りて覚醒体とリンクを行います。\nシルバーキーは持ち主の精神を強化し、長時間覚醒体とリンクし、戦闘指揮や精神力サポートを可能にします。また、持ち主はシルバーキーを通じて覚醒体に一定の支援を提供できます。\n理論上、持ち主の精神力が強いほど、より多くの覚醒体とリンクできますが、複数の覚醒体とリンクできる人は現在一人だけです。\n\n<Title:召喚儀式>\nシルバーキーを使った召喚儀式はすべての調査員が必修しなければいけません。\n儀式中、シルバーキーは使用者と対象シルバーコアの感覚を増幅し、シルバーコアの形成を助け、最終的に特殊能力を持つ覚醒体にします。\n\n<Title:精神追跡と定位>\n覚醒体と離散した時、持ち主はシルバーキーを使い、「精神追跡」で覚醒体の精神特徴をおおよそ特定できます。\nただし、見つけた精神が必ずしも味方であるとは限りませんので、「精神追跡」時には冷静を保つことが大切です。\n\n<Title:裂け目の閉鎖>\n持ち主はシルバーキーを使って融蝕の裂け目を閉じることができます。詳しくは「融蝕の裂け目-対策」をご覧ください。"
  },
  CollectionHall_49767_Title = {
    Text = "シルバーキー使用"
  },
  CollectionHall_49768_Desc = {
    Text = "<Title:概述>\n守秘者それぞれが異なる特別な能力を持っている。\nミサゴの記録によれば、現在判明している守秘者の能力には記憶の読み取り、感情の共有、心理感知などがある。\n\n<Title:初代守秘者>\n最初の守秘者はアリステア・オーウェンスだ。\n彼は歴史の隙間に存在する影のような存在で、ほとんどの人には知られていないが、少数の者は彼が今でもミサゴの地下にいるという事実を知っている。\n彼はミサゴのために「必要な犠牲」を払って直立歩行ができないという。\n最も経済的なツールである彼の胃は切除されており、食べる必要も飲む必要もないので、大幅に食費が節約されている。\n\n<Title:新任守秘者>\n新たな守秘者は最も独特な能力を持っている。\n物体、感情、記憶を通じてシルバーキーの新しい力を引き出すことができ、この能力は専門家や歴史家の認識を覆すものだ。\n皆が知っているように、この守秘者は新たな嵐を引き起こすだろう。\n問題は、その嵐がどこへ導くかである。"
  },
  CollectionHall_49768_Title = {
    Text = "特殊守秘者と能力"
  },
