  CollectionHall_51019_Desc = {
    Text = "<Title:創設日>\n洪積暦以前\n\n<Title:創設者>\n不明\n\n<Title:紹介>\nアッシリア帝国から分化した遊牧民族。\n一年中激しいヴォルムワヒ砂漠の嵐に隠れ、原始的な生活を送っており、外部との通信はほとんどない。アラン族は「豊穣母樹」を信仰し、豊穣母樹と聖河の水の異常な繁殖能力に頼って集団を維持している。\n「ヴォルムワヒ作戦」後、アラン族は姿を消し、その後の消息は不明である。"
  },
  CollectionHall_51019_LockTip = {
    Text = "調査第7章「欲望の川」クリアで解放"
  },
  CollectionHall_51019_Title = {
    Text = "アラン族"
  },
  CollectionHall_51038_Title = {
    Text = "07 欲望の川"
  },
  CollectionHall_51373_Title = {
    Text = "未知のもの"
  },
  CollectionHall_51374_Desc = {
    Text = "<Title:紹介>\nミサゴ大学教授、社会活動家、貴族。\nかつては金遣いの荒い遊び人で、大した罪はないが、裏と表で名を馳せていた。\n後に家族が邪教徒に皆殺しにされ、唯一の生存者となった。その後に起きたことは本人しか知らない。\nラモンナの養父であるが、その出自については口を閉ざしている。\n若い頃すべての科目で不合格だったが、ミサゴの教授になった。\n奔放であるが、女性や男性とのスキャンダルはない。\n矛盾だらけの男である。"
  },
  CollectionHall_51374_LockTip = {
    Text = "序章をクリアで解放"
  },
  CollectionHall_51374_Title = {
    Text = "デクスター"
  },
  CollectionHall_51375_Desc = {
    Text = "<Title:紹介>\nデクスターの養女、主人公の信頼する調査パートナー。\n幼少期から学内の各教室を巡り、融蝕現象や覚醒体に関する知識を習得。\n\n幼い頃、ラモンナは「両親」に憧れたが、デクスターと教師たちの愛情により、学院を真の家と感じるように。\n\n冷静で理性的な性格が、怪異の多いミサゴでは逆に目立つ。\n彼女の冷やか顔は「天才」の疲れを示すに過ぎないと、知る者は語る。"
  },
