  },
  CollectionHall_56359_LockTip = {
    Text = "特務記録「薔薇の住処：故郷」クリアで解放"
  },
  CollectionHall_56359_Title = {
    Text = "春に捧げる花束"
  },
  CollectionHall_56369_Title = {
    Text = "詩の世界"
  },
  CollectionHall_57597_Desc = {
    Text = "<Title:紹介>\nロンディニウム大区の現任の司教で、先代の司教によって偶然召喚された覚醒体。\n創生の父なる神の敬虔な信徒で、命をもって父なる神の教えを実践し、仁愛と寛容の心で世の中に接してきた。\nそのため、民衆の間でも高い評価を得ている。\n一部の信徒からは「ロンディニウムの聖徒」とも呼ばれている。\n　\nしかし、皮肉なことに、かつてこの万物への愛と慈悲が彼の命を奪った。\n生前は、融蝕を治療しようと試み、自身の血肉を生命の石板に捧げることで、教区内の「患者」の苦痛を和らげ、彼らの命を延ばしていた。\n彼の死後、石板は行方不明になった——彼が覚醒体として再び目覚めるまで。\n　\n黒い眼帯で覆われた目は魂の輝きを見ることができる。\n守秘者を見たとき、守秘者が父なる神の予言した蒼白の使者であり、この暗闇に陥る世界を救う存在であると確信した。"
  },
  CollectionHall_57597_LockTip = {
    Text = "特務記録「血の色」クリアで解放"
  },
  CollectionHall_57597_Title = {
    Text = "サルバドル"
  },
  CollectionHall_57598_Desc = {
    Text = "<Title:紹介>\n史前文明リモリアの最年少の幼王。\n幼少時より才能に恵まれ、一日20時間以上眠り、目を覚ましても常に倦怠感がある。\n時に神々の喜怒哀楽を感じ、異なる時空の断片を夢見ることで崇拝され、畏怖され、王として敬われる。\n幼い王はそれを気にせず、ただ神の啓示と予言を避け続ける。\n\nリモリアの破壊の宿命を予見しながらも、変える術を知らず、黙っていた。\n災厄が訪れたその日、人々は絶望の中で彼に期待を抱いていたため、彼は偽りの予言をでっち上げた。\n不朽の王と再び降臨する予言についての。\n最終的に旧世界は洪水に沈み、新たな人類が陸上で繁栄し、史前のことは誰も知らなくなった。\n彼もまた、自分の無意識の予言が信仰により繰り返されるとは思っていなかった。\n彼は結局、信仰の力を過小評価していた。"
  },
  CollectionHall_57598_LockTip = {
    Text = "「トゥルー」を召喚すると解放"
  },
  CollectionHall_57598_Title = {
    Text = "トゥルー"
  },
  CollectionHall_57599_Desc = {
    Text = "<Title:紹介>\nアラン族の異郷の使者、夢の啓示を受けてヴォルムワヒにやってきたと自称。\nアラン族の隊を率いて、嵐の壁外で長くさまよい、アラン族の聖樹である豊穣母樹の復活の可能性を探る。\n実際は提灯教会に属している。彼女の慈悲に隠された真の動機は誰も知らず、旅が続けばその一端が明らかになるかもしれない。"
  },
  CollectionHall_57599_LockTip = {
    Text = "調査第7章「欲望の川」クリアで解放"
  },
  CollectionHall_57599_Title = {
    Text = "ジュリエット"
  },
  CollectionHall_57600_Desc = {
    Text = "<Title:紹介>\n先史文明リモリアに生きていた彼女の家族は虔敬な神の信徒であった。\n幼い頃から熱心に修行し、首都の神殿で祭司となることを夢見た。\n神の奇跡を渇望し、神秘を追求したものの、それが彼女に訪れることは一度もなかった。\n　\nトゥルーが王位に就いたとき、彼女はその傍らに仕える祭司となった。\n新たな王に初めて会ったとき、彼女は極度の恍惚と喜びを感じ、彼こそが求めていた地上の神の化身だと悟った。\n彼女の存在意義は、この少年王に仕えることであった。\n　\n大洪水で大陸とリモリアの文明が海底に沈むまで、彼女の信念は一度たりとも揺るがなかった。"
  },
  CollectionHall_57600_LockTip = {
    Text = "異夢視界「冒涜」をクリアで解放"
  },
  CollectionHall_57600_Title = {
    Text = "ミリアム"
  },
  CollectionHall_57601_Desc = {
    Text = "<Title:概要>\n種を広めるために次元の壁を越え、愛のために種に刻まれた繁殖本能を捨てた。\n偶然にもこの宇宙へ流れ着いた沙耶は、星々を旅するティンクトによってシルバーコアから呼び覚まされた。\n戸惑いながら行き先を探し続けて、荒廃した惑星に留まっていた彼女は、やがてミサゴ大学の守秘者と出会う。\n探求の中で、そして対話の中で――\nまったく異なる2つの存在は、「愛」とは何かという問いに、同じ答えを見出した。\n記憶はいずれ曖昧になるだろう。\nそれでも、大切な誰かと結ばれた絆は、再び彼女の進む道を照らしてくれる。\n忘却に満ちたこの世界で、彼女は愛という病を抱き続ける。"
  },
  CollectionHall_57601_LockTip = {
    Text = "「沙耶」を召喚すると解放"
  },
  CollectionHall_57602_Desc = {
    Text = "<Title:紹介>\n古い伝説によると、世界には二匹の巨獣が存在し、それぞれ水底の深淵とエデンの東に座している。\nこの二つの巨獣は、時間が尽きる時にのみ出会うことができ、彼らは生命の母ティアマトに生け贄として捧げられ、生命の輪廻を得ることになる。\n\nロータンは伝説の裏に隠された「獣」である。\n彼女は惑星の自然の産物である。\n伝説とは異なり、彼女は深淵の水でもあり、エデンの魂でもある。\n彼女は純粋な混沌の力であり、自由な魂であり、未定義の秩序そのものだ。\n破壊と法則は世界が与えた権能であり、対照的な二つの本能がロータンの中で衝突する。\n彼女を引き裂く力のバランスを取るためには、戦闘を通じて破壊の欲望を解放する必要がある。\nロータンは惑星に歴史を守る使命を託されている。\n彼女の「仕事」は惑星の意志に従い、惑星の運命に影響を与える者を一掃し、討伐することだが、そのような者は千年に一度出るか出ないかだ。\n終わりのない使命が下るのを待つ退屈の中で、ロータンは敵の出現を渇望している。\n\nそのため、彼女は若い幼王に目を向け、さらには陥落の災厄さえ呼び込んだ。\nしかし、すべては彼女の激しい戦闘意志に何ら影響を与えない。\n彼女の復活によって、それはますます激しさを増すばかりだ。"
  },
  CollectionHall_57602_LockTip = {
    Text = "「ロータン」を召喚すると解放"
  },
  CollectionHall_57602_Title = {
    Text = "ロータン"
  },
  CollectionHall_57603_Desc = {
    Text = "<Title:概要>\n葬骸城のかつての王子は、今や神明として奉られる食屍鬼の王です。\n彼は聡明で公正な青年ですが、独特な食事の「趣向」――死体を食べるため、王室から忌避されています。\n父王は退位の前夜に彼を毒殺しました。解体されて捕食される過程で、彼の意識は神殿に奉られた彼と融合し、自らの肉体の味を味わうことになりました。その驚くべき甘美さが彼の心を惹きつけます。\n彼は食事をロマンティックなアートと見なしており、それは単なる口腔の欲求の満足にとどまらず、忘れられた記念のためでもあるのです。\n融蚀はすべてを破壊し、過去を風に散らしますが、彼はすべての生者の伝説と平凡を目撃し、自らの記憶に血と肉を留め、永遠に残します。"
  },
  CollectionHall_57603_LockTip = {
    Text = "「ドゥルセイン」を召喚すると解放"
  },
  CollectionHall_57603_Title = {
    Text = "ドゥルセイン"
  },
  CollectionHall_57604_Desc = {
    Text = "<Title:紹介>\nかつてはある地区を統治していた領主であった。\n母星が融蝕により破壊された後、巨大な隕石に乗ってカンブリア渓谷に堕ちてきたと言われている。\n家畜の管理、土地の併合、そしてリスク投資の運営に長けている。\n外出のたびに、必ず大勢の不死者の従者たちを連れ歩く。\n1人は足台、2人は吟遊詩人として主を楽しませ、さらに4人は馬車の運転手……\nその豪奢な行列を見れば、教皇ですら自分の粗末な見栄えに恥じ入ることだろう。"
  },
  CollectionHall_57604_LockTip = {
    Text = "意識潜行「燃える饗宴」クリアで解放"
  },
  CollectionHall_57604_Title = {Text = "ワンダ"},
  CollectionHall_57605_Desc = {
    Text = "<Title:紹介>\nティンクトの大好きな双子の姉。\n孵化時から異なる「才能」を持ち、制御不能な能力のため、ファイントは「繭」の中で成長できなかった。\n不幸をもたらす存在とされ、ティンクトと共に追放された。\n\n妹は上流階級の施しを受けて生活必需品を得て、大部分の物資をファイントのために使った。\nある災厄の後、妹は唯一の「チケット」を手に入れ、ファイントを騙して荒れ果てた惑星から飛び立とうとした。\n出発時、ファイントは最初で最後の抵抗を示した——繭を離れ、すべての生命エネルギーを吸収する代償でティンクトを脅したのだ…………\n自身が「欠陥品」であることを非常に卑下している。\n\nかつて食事を拒否し、ティンクトの負担を減らそうとしていたこともあり、その結果、偏食の悪習がついた。\n\n暗い場所を好む。通常、地下室などでしかファイントを見つけられない。"
  },
  CollectionHall_57605_LockTip = {
    Text = "「ファイント」を召喚すると解放"
  },
  CollectionHall_57605_Title = {
    Text = "ファイント"
  },
  CollectionHall_57606_Desc = {
    Text = "<Title:概要>\nケティグラは砂漠地域に生まれた孤児で、少女の頃から多くの地元の同様に不幸な子供たちを引き取りました。\n彼女はこれらの子供たちがこの世界で生き延びるために、悪意から身を守るための虚構の外殻を精密に創り上げました。\n多くの人にとって、彼女は残酷で狂った存在として映ります。\nどのような衝突でも、彼女は最も狂った情熱と最も残酷な手段で、彼女の銃口の前に立つ敵に応じます。\n時が経つにつれ、地元の幼子たちでさえ、無辺の沙海の上に琥珀色の死神が存在することを知っています。\nNとの一戦で、彼女は思い通りにそのゲームに敗北し、すべてを失いました。\nしかし、Nさえも彼女がすでに星々の中の誰かに注目されていることを知りませんでした。\n運命的な死を経験した後、彼女は約束通り彼の力と、彼の自分のために定めた使命を継承しました。\n彼女の体には星々の中の存在が宿り、彼女は早くに彼らの一員になることができるのです。\nもしその最終の時が訪れ、阻止できない運命であれば、彼はすべてを投げ捨て、再び極天に帰るでしょう、それが最初であり、最後の港となります。"
  },
  CollectionHall_57606_LockTip = {
    Text = "意識潜航を通過「不朽の極昼」後解放"
  },
  CollectionHall_57606_Title = {
    Text = "キャティグラ"
  },
  CollectionHall_57607_Desc = {
    Text = "<Title:紹介>\n溶壊・ドールは元々ミサゴや人類の科学の誇りでしたが、融蝕との長い対抗の中で彼女は、融蝕現象が体を解消する一方で、真理への道を開くことを認識しました。\n偶然にも謎の格言が刻まれた古代の石板に接触した後、彼女はこの暗黒無境の道を歩くことを決意し、人形の身体を変えることで命を延ばすことを放棄し、融蝕に脳缶を侵食させることを選びました。\n最終的に彼女は望みを叶え、融蝕の本質を洞察しますが、同時に完全に破壊と虚無の道を辿ります。\n人々が彼女を導く明かりのような信念と理性が消え去った後、溶壊・ドールは学校の教師と学生が見えないところで破壊の道を進め、「支援」する形でいくつかの悲劇的事件を引き起こした後にミサゴに発見され、最高の監視と抑圧が施されました。\n崩壊した人形の背後には、天才の不滅の魂が、今もなお世界の奥深く暗い場所に、遠く響いているようだった。"
  },
  CollectionHall_57607_LockTip = {
    Text = "「溶壊・ドール」を召喚すると解放"
  },
  CollectionHall_57607_Title = {
    Text = "溶壊・ドール"
  },
  CollectionHall_57608_Desc = {
    Text = "<Title:紹介>\n貧しい生まれだが、美貌で上流階級に上り詰めた歌姫。\n\n災害が起きた時、幾ばくかの同情と恩恵で脱出の「チケット」を手に入れた。\n\n皆がそれは彼女のものと考えたが、彼女は密かに姉のファイントを送り出すことを決意していた。\n\nだが、最後の瞬間、姉は力を使って彼女を強引に席に括りつけ、脱出させた。\n\n目覚めた後、ティンクトは無限の罪悪感に苛まれた。姉はきっと生きている、もしくは自分と同じように復活したと信じていた。\n\n以来、姉の行方を探し続けていた、すべてを犠牲にしてでも。"
  },
  CollectionHall_57608_LockTip = {
    Text = "「ティンクト」を召喚すると解放"
  },
  CollectionHall_57608_Title = {
    Text = "ティンクト"
  },
  CollectionHall_57609_Desc = {
    Text = "<Title:紹介>\n「ミサゴの脳」と称される天才学者、ミサゴ外勤顧問の一人。\n14歳でミサゴに入学。アリステアの生命維持装置を改良した経験がある。\nある外出途中に融蝕に感染し、80ページにわたる召喚手順の説明を書き残し、静かに息を引き取った。\n死後、仲間がその説明に従い、彼女のシルバーコアを召喚装置に投入し、「ドール覚醒体」を製作。\n召喚後、彼女は平静に起き上がり服を着ると、平静に研究室に入り、平静に以前からの研究を続けた。\nそう、天才の世界はいつも退屈で平凡なのだ。"
  },
  CollectionHall_57609_LockTip = {
    Text = "「ドール」を召喚すると解放"
  },
  CollectionHall_57609_Title = {Text = "ドール"},
  CollectionHall_57610_Desc = {
    Text = "<Title:紹介>\n融蝕された星から逃れた異星種族の霊体が、死んだ少女の体を占有し、両親のように死ぬ運命を逃れる。\nしかし、人間の体に融蝕の症状が現れ、霊体も体内に固定され、再び逃げることができなくなる。\n融蝕の恐怖から精神崩壊し、自らミサゴに連絡して、覚醒体にするよう要請し、種族の知識技術を提供することを約束。\n覚醒体となり、アカデミーで機械、電学、精神研究をするが、融蝕に対する恐怖から融蝕研究ができず、心理的な影響で暗闇を恐れ、睡眠を避け、毎日敏感で神経質に過ごす。"
  },
  CollectionHall_57610_LockTip = {
    Text = "「ウインクル」を召喚すると解放"
  },
  CollectionHall_57610_Title = {
    Text = "ウインクル"
  },
  CollectionHall_57611_Desc = {
    Text = "<Title:紹介>\n霊的次元に生まれた霊体、広大で無の灰色の海を漂い、訪れた霊界の旅人と共に地球へ来てさまざまな願いを体験し、彼らの頭を斬り収集、知恵と感情を吸収。\n1600年前に召喚し、召喚者に取り憑いてその頭を斬る。精神力を吸収する特性により、頭を集め永続し、さらに多くの頭を乱獲。真の店主に出会い、従がえられ、交換に応じ助手として共に過ごす。\n店主と真の友情を築き、本当の願いに気付き、店主の頭を斬り、その姿と店を受け継ぐ。今は頭を乱獲せず、店で依頼を解決することで頭を交換、顧客と交流し店主を失った孤独を癒す。\n今の願いは店と店主が愛した街を守ること。"
  },
  CollectionHall_57611_LockTip = {
    Text = "特務記録「雨の町に潜む影」クリアで解放"
  },
  CollectionHall_57611_Title = {
    Text = "ダフォダイル"
  },
  CollectionHall_57612_Desc = {
    Text = "<Title:紹介>\n生前、彼女は世界を巡るマジシャンだった。\n幼少期をサーカス団で過ごし、その生活には多くの「異端者」が存在した——盗賊、逃亡者、捨て子、奇形……\n\nカーシアもまた「異端者」の一人だった。\n彼女には感情を感じ取ることも、自然に生み出すこともできなかった。\nしかし、彼女は紛れもない天才的なパフォーマーであり、常に観客の喝采を浴びた。\n\n——やがて@2の惨禍に遭い、異端の犠牲者として亡霊となった後も、彼女は生前と変わらぬマジックを披露し、観客を「幻想の奇跡の世界」へと誘った。\n\n奇妙なことに、彼女のマジックショーを見た者は皆「何かが欠けている」と感じ、次第に生活の色合いを失っていった。\n困惑し、麻痺し、やがて絶望へと落ちていく——\n\nその舞台裏で、マジシャンの彼女は満足げに身を潜める。\n自ら手に入れた甘美な「報酬」を貪りながら。\n\n華麗な舞台には莫大なコストがかかる。\n彼女はただ、それを持続可能なものにしているだけなのだ——"
  },
  CollectionHall_57612_LockTip = {
    Text = "「カーシア」を召喚すると解放"
  },
  CollectionHall_57612_Title = {
    Text = "カーシア"
  },
  CollectionHall_57613_Desc = {
    Text = "<Title:紹介>\n偶然にも世界線の障壁を越えてきた神秘的な存在であり、ラモンナのもう一つの可能性。\n「あの事件」では、守秘者の安全のために、覚醒体の力に体を制御させなければならなかった。\n\n事件の後も、@2 がラモンナに与えた影響は消えることはなかった。\n@2 の意識は彼女の体の中に残り、日ごとに意識のスペースを圧迫している。\nそのため、彼女は終わりのない苦悩と苦痛に陥っている。\n\n心配させたくないから、何も問題が無いふりをする。\n髪と身の回りを整える。\n時々、意識が失われ、空虚な状態になる。\nもしくは、別の口調で話していることもある。\nだが、これについては心配する必要はない。\n彼女の来た場所が違っても、その行動はすべて守秘者とこの世界の平和のためだ。"
  },
  CollectionHall_57613_LockTip = {
    Text = "意識潜行「一歩の距離」クリアで解放"
  },
  CollectionHall_57613_Title = {
    Text = "環行・ラモンナ"
  },
  CollectionHall_57614_Desc = {
    Text = "<Title:紹介>\n彼女は詩と薔薇の国で生まれた詩の精霊だった。\n精霊は言葉で編まれた夢の中を彷徨い、陽光の煌めきが花開くことに喜び、花が枯れ落ちるたびに涙を流した。\n彼女は思いに沈み、心を痛め、そして自らの魂と寄り添ってくれるものを渇望していた。\n\n後に、花の咲き誇る庭で、若い庭師が1輪の薔薇を彼女の前に差し出した。\n彼女ははにかむように微笑み、そっとその花を受け取った。\n「もう、独りじゃない」\nそのとき、彼女はそう信じていた。"
  },
  CollectionHall_57614_LockTip = {
    Text = "特務記録「薔薇の住処」クリアで解放"
  },
  CollectionHall_57614_Title = {Text = "オルラ"},
  CollectionHall_57615_Desc = {
    Text = "<Title:紹介>\n古代より存在する、アラン族唯一の女王。\n幼少期に樹の使者として崇められ、王に命令を伝える役割を果たした。初めての反抗後、生贄としてアラン族の聖河に投げ込まれるが、そこで樹の意志に目覚める。\n彼女の血肉は母樹の乳と一体化し、樹の根には彼女の血が流れる。彼女は豊穣母樹であり、豊穣母樹は彼女そのものである。\nしかし、融蝕の力がアラン族の血脈を汚染した際に、彼女は自らの体を使って母樹の代わりに汚染を受け入れ、アラン族の存続を図った。\nアラン族が歴史の流れの中で消滅した今、地より現れ、崩壊した豊穣母樹だけが彼女にまつわる物語を見守っている。"
  },
  CollectionHall_57615_LockTip = {
    Text = "「タイス」を召喚すると解放"
  },
  CollectionHall_57615_Title = {Text = "タイス"},
  CollectionHall_57616_Title = {
    Text = "星々の間"
  },
  CollectionHall_57617_Desc = {
    Text = "<Title:紹介>\nミサゴ大学の心理学教師で、調査員たちの心理ケアを担当。\n優しく親切で校内の教師や学生から愛されているが、一部のミサゴメンバーは彼女を恐れている。\nその正体不明の紅茶はさておき、笑顔を絶やさない姿は不気味とさえ言える。"
  },
  CollectionHall_57617_LockTip = {
    Text = "序章をクリアで解放"
  },
  CollectionHall_57617_Title = {
    Text = "シルヴィア"
  },
  CollectionHall_57618_Title = {Text = "愚者"},
  CollectionHall_57619_Title = {
    Text = "ハイブリッド"
  },
  CollectionHall_57620_LockTip = {
    Text = "「ピックマン」を召喚すると解放"
  },
  CollectionHall_57620_Title = {Text = "異郷人"},
  CollectionHall_57621_Desc = {
    Text = "<Title:紹介>\nミサゴのベテラン調査員、守秘者から「先輩」と敬称される存在。\nかつては、説明のつかない理由で外出を恐れていたため、校内で学びながら情報部員を務めていた。\n親友の死後、彼の行動を追憶するため前線に身を投じ、新たな道を歩む。\n破損したシルバーキーを携帯し、薄れる友の記憶を辛うじて繋ぎとめる。"
  },
  CollectionHall_57621_LockTip = {
    Text = "序章をクリアで解放"
  },
  CollectionHall_57621_Title = {
    Text = "ウィリアム"
  },
  CollectionHall_57622_Desc = {
    Text = "<Title:紹介>\nシディの庭師で、オルラの幼馴染み、そして親友。\nオルラが最も困窮した時期に、コレットは庭園を利用して、彼女に忘れられない幸せな時間を与えた。\nオルラの才能が芽生えたとき、コレットは火事によって彼女の財産、名声、そして命さえも奪った。\n彼女はハーバートと協力し、オルラの詩集で詩の世界を創り出した。\nそれが追悼のためだったのか、支配のためだったのか、誰も知るものはいない。\nコレットは常に、美しい詩の中で理解できたのは「欲望」だけだったと語っていた。\n彼女は欲望のために苦しんだ。\nしかし、それを誇りにもしていた。"
  },
  CollectionHall_57622_LockTip = {
    Text = "特務記録「薔薇の住処」クリアで解放"
  },
  CollectionHall_57622_Title = {
    Text = "コレット"
  },
  CollectionHall_57623_Desc = {
    Text = "<Title:紹介>\nミリアムは2人の「デボラ」に出会ったことがある。\n1人はリモリアの祭司、1人はアウン族の侍女。片方は彼女の親友であり、もう片方も彼女の親友だった。\n1万年以上の時を隔てた2つの時代、2人の異なる人物、同じ名前、同じ容貌、同じ善良な心を持っていた。\nこれはミリアムにとって、稀有な偶然であり、神聖な予兆でもあった。\n　\nミリアムは二人のデボラの結末を見届けた。\n一人はリモリアと共に海底に沈み、一人は彼女の手で祭壇に送られ、腹を裂かれて死んだ。\nこの神の国に関する壮大な物語の中で、デボラの物語は2つの短い赤い注釈に過ぎない。"
  },
  CollectionHall_57623_LockTip = {
    Text = "異夢視界「冒涜」クリアで解放"
  },
  CollectionHall_57623_Title = {Text = "デボラ"},
  CollectionHall_57624_Desc = {
    Text = "<Title:紹介>\nミサゴ大学の第一情報ブローカー、校内推理協会のメンバー。\n唯一無二の情報収集と発掘能力でロンディニウム中で名を馳せる。\nアグロ共和国出身だが家庭の事情でロンディニウムに移住し、ミサゴの秘密を握り秘密裏に入学。\n彼女の明るい笑顔に惑わされないように——ミサゴについての知識は一般の想像以上に深い。"
  },
  CollectionHall_57624_LockTip = {
    Text = "調査第1章「東区の秘め事」クリアで解放"
  },
  CollectionHall_57624_Title = {Text = "ハンナ"},
  CollectionHall_57625_Desc = {
    Text = "<Title:紹介>\n元グリーン財団の研究員で、ライ療養所の院長。\n夫と娘が亡くなった後、娘を復活させる方法を探し続けていた。\n長い探求の過程で、彼女は娘の姿を忘れ、彼女を支え続けた愛と温もりも忘れてしまった。\n彼女が覚えていたのは、苦しみそのものだけだった。"
  },
  CollectionHall_57625_LockTip = {
    Text = "調査第4章「無音の中で」クリアで解放"
  },
  CollectionHall_57625_Title = {
    Text = "フランシス"
  },
  CollectionHall_57626_Desc = {
    Text = "<Title:紹介>\nソナニール号の船長。\n彼の故郷は融蝕に呑み込まれ、人々の記憶から消え去った。\nただ一人、彼だけがすべてを覚えていた。\nだからこそ人々は彼を狂人と呼んだ。\n海辺の小さな町、親しい家族、兄弟姉妹……それらはすべて、彼が必死に取り戻そうとしている過去である。\n\n彼はミリアムと取引をし、彼女が必要とする品物を届ける代わりに、彼女は彼だけが覚えている過去を呼び覚ます手伝いをする、と。\n\nそして彼は見たのだ。そよ風と白い鳥に囲まれた、一人の少女の姿を。\n「私の名前はシレスト。あなたが求める限り、ここに居続けるわ」\n彼女は、かつて存在した故郷の痕跡であり、幼き日に老人から聞かされたおとぎ話そのものだった。\n\nそう、彼が夢にまで見たあの過去は、確かに現実に存在していたのだ。"
  },
  CollectionHall_57626_LockTip = {
    Text = "調査第6章「倒錯した星々」クリアで解放"
  },
  CollectionHall_57626_Title = {
    Text = "エルトン"
  },
  CollectionHall_57627_Desc = {
    Text = "<Title:紹介>\n「救世の大聖堂」の事務員。\n司教や他の聖職者が大聖堂の日常的な運営を維持するために補佐する責任を負っている。\n　\n父が亡くなった後、有能な姉が家業を引き継ぎ、小さな成功を収めた商人となった。\nすべては順調で、幸福な日々が続くはずだった——\n綿密に計画された詐欺が起こるまでは。\n　\n一夜にして、母と二人の娘は何もかもを失った。\nしかし、それは大きな問題ではなかった。\nロンディニウムの司教が彼女に手を差し伸べてくれたから。\n彼女は家族がそばにいる限り、どんな困難も恐れなかった。\n　\nしかし、それからほどなく彼女の姉が亡くなる。\n彼女の母は悲しみに打ちひしがれ、鬱病を患った。\n　\n同じ頃、彼女の先祖代々の家を占拠していた恥知らずな男はアートサロンを開いて楽しんでいた。\n　\n混乱、怒り、理不尽……\n数え切れない感情が胸に詰まり、彼女を灰に帰そうとする程の憎悪に変わっていった。\n　\nしかし、彼女はそんな風になってはいけないと考えた。\n司教が言ったように、過去にとらわれていると、決して前進することはできない。\n赦しだけが自由をもたらすことができると。\n　\nだが、彼女は赦すことはできなかった。\n　\n「無理に寛容にならなくてもいいのですよ」\nふと、提灯教会の貴婦人と呼ばれる女性が彼女の耳元で囁いた。\n「赦しはただそのままにしているだけよ。\nでも善人は報われるべきだわ。\nそして悪人は当然の罰を受けるべきよ」\n　\nそこで彼女は鏡を取り、審判の儀式を始めた。"
  },
  CollectionHall_57627_LockTip = {
    Text = "特務記録「血の色」クリアで解放"
  },
  CollectionHall_57627_Title = {
    Text = "ソフィア"
  },
  CollectionHall_57628_Desc = {
    Text = "<Title:紹介>\n出自不明の奴隷、かつてゴリアテの後を継ぎ部族長となる。\n8歳で主人を殺し、樽の中に隠れてペリシテ人の島に漂着。\n卑賎な血を引き、弱く卑劣で野心的。\n首領就任から一ヶ月で処刑され、在任期間は13代目。\nペリシテ人の首領の地位は、簡単に維持できるものではなかった。"
  },
  CollectionHall_57628_LockTip = {
    Text = "意識潜行「巨人の陥落」クリアで解放"
  },
  CollectionHall_57628_Title = {Text = "グレン"},
  CollectionHall_57629_Desc = {
    Text = "<Title:紹介>\n\n\n彼女は永遠の国の中継所であり、王国と外部世界の出入口を握り、迷える臣民を故郷へと導いていた。\n王国が眠りに入り、海渦の深みへと落ちていくとき、ファロスと故郷のリンクが断たれた。\n彼女は王都と連絡が取れず、広大な海で何の手がかりも見つけられなかった。\n\n海上灯台でありながら帰郷の道を照らせないとは、何と皮肉なことか。\n\n孤独な時間の中で徐々に狂気に陥り、多くの海洋災害を引き起こし、力尽きた後、古代の英雄に討伐された。\n\n後の研究で、ファロスの狂気がオセアニアの沈没を引き起こしたとする学者もいた。\nすべては推測に過ぎない。彼女の過去は今もなお謎に包まれている。"
  },
  CollectionHall_57629_LockTip = {
    Text = "「ファロス」を召喚すると解放"
  },
  CollectionHall_57629_Title = {
    Text = "ファロス"
  },
  CollectionHall_57630_Desc = {
    Text = "<Title:紹介>\nある公国の小貴族の息子。貴族出身だが、父は何の功績もなく、彼の未来も凡庸なものとして誰の目にも映っていた。\n\nクリスマスの晩餐会で病気の公女を世話したことで、大公に騎士予備隊として見いだされ、彼の冗談めいた誘いがきっかけで、騎士団訓練を開始。\n\nしかし、戦争が勃発し、脆弱な公国軍は侵攻を防げず、オジールは公女を守る最後の騎士となる。\n彼は大き過ぎる槍を握り、公女の前に立ちはだかった。"
  },
  CollectionHall_57630_LockTip = {
    Text = "意識潜行「騎士の願望」クリアで解放"
  },
  CollectionHall_57630_Title = {
    Text = "オジール"
  },
  CollectionHall_57631_Desc = {
    Text = "<Title:紹介>\n炎の中で踊る天才ダンサー。\n数百年にわたり、彼女の家族は宮廷ダンサーとして存在していた。そのため、王国が変わっても、学校がなくなっても、彼女は優雅で美しいダンスの魂を失うことはなかった。\n18歳の時、彼女は地元のバレエ団に加入し、すぐに首席ダンサーとなった。\n\nしかし、初演の成功後、トロープマネージャーは「紹介」の名目でリッツを富豪の部屋に送った。\n実は、バレエはもはや純粋ではなく、高雅な背景が少女たちの価値を高める資本となっていた。\n彼女は逃げ出し、捕まり、再び逃げ出し…………ついに彼女の「清高」は権力者たちを怒らせた。\n彼らはリッツを身体的にも精神的にも苦しめ、彼女は足の先が裂け、黒い血が滴り落ちても、止まることなく踊り続けなければならなかった。\n\nついに、ある普通の公演で、ダンスが最高潮に達した時、炎が彼女の足元から拡散し始めた。\n彼女はすべての不正と罪を焼き尽くす。"
  },
  CollectionHall_57631_LockTip = {
    Text = "「リッツ」を召喚すると解放"
  },
  CollectionHall_57631_Title = {Text = "リッツ"},
  CollectionHall_57632_Desc = {
    Text = "<Title:紹介>\n奴隷にされ、養子にされ、捨てられ……ここまでの話は別の世界線のヘロットと変わらない。だが同じ血は別の枯れ枝へと分かたれた。\n牢獄へと落とされてからが、本当の地獄の始まりだった。彼女は恐怖に震えながら気づいた——奴隷主をともに憎むはずだった仲間たちもまた、自分を憎んでいることを。いや、それをも上回るものだった。\n来る日も来る日も、終わりのない責め苦に溺れた。命運の贈り物は何倍にも膨れ、彼女の精神を余すことなく打ち砕いた。\n本来は奴隷主へと向けられるべき憎しみは、万人への憎しみへと変わった。彼女もまた万人から憎まれ、自分の居場所を失った。\n融蝕を利用して監獄から逃げ出したとき、彼女の心には狂気しか残っていなかった。突然手に入れた力を握りしめ、尽きることのない憤怒を一刻も早く解き放とうとした。\nその夜、城全体に赤い血の雨が降り注いだ。彼女は赤い川の中に立ち、天を仰いで高らかに哄笑した。"
  },
  CollectionHall_57632_LockTip = {
    Text = "「血ノ鎖・ヘロット」を召喚すると解放"
  },
  CollectionHall_57632_Title = {
    Text = "血ノ鎖・ヘロット"
  },
  CollectionHall_57633_Desc = {
    Text = "<Title:紹介>\n彫刻家協会の創設者、会長。\n\n幼少期に脊髄炎を患い、自宅で独学を余儀なくされたことから、人間の肉体的限界を自覚するようになる。\n\n成長後、ミサゴ大学へ進学。\n指導教官の支援を受けて研究の方向性を見出し、自身の病を治癒した。\n\n常に穏やかな笑みをたたえているが、実際には人間の感情に無関心。\n外見の管理が疎かで、髪も机も乱れている。\n\n彼の机の引き出しには一冊のファイルがあり、クロウリーが歴年発表した論文が整然と収められている——これはハーバートが行った中で最も几帳面な行為だった。"
  },
  CollectionHall_57633_LockTip = {
    Text = "調査第1章「東区の秘め事」クリアで解放"
  },
  CollectionHall_57633_Title = {
    Text = "ハーバート"
  },
  CollectionHall_57634_Desc = {
    Text = "<Title:紹介>\nペリシテ人の中で、史上最も勇猛な首領。\n大柄で力強く、短期間でペリシテ人を率いて周囲の部族を圧倒し、未だ敗北を知らない。\n称賛と花の中で、彼の名声は広まり、族人の忠告を無視して油断する。\n小さな過ちでペリシテ人は壊滅。彼は罰を受け入れ、唯一の追随者と共に海上に逃亡。\n憤りと不満……この恥辱の瞬間は忘れられず、彼は「魔女」に脆弱な首を差し出し、すべてを取り戻すことを求める。\n彼は血の復讐の道を歩み始めた。"
  },
  CollectionHall_57634_LockTip = {
    Text = "意識潜行「巨人の陥落」クリアで解放"
  },
  CollectionHall_57634_Title = {
    Text = "ゴリアテ"
  },
  CollectionHall_57635_Desc = {
    Text = "<Title:紹介>\n元々は卑しい奴隷で、幼い頃からの聡明さと美貌が彼女の悲惨な運命を予感させていた。\nしかし、突然の幸運により、統治官夫婦の亡くなった娘の代わりに彼らの従順な養女となり、もはや奴隷として見られることはなかった。\n彼女は幼い頃に家を離れ、長年の付き合いでその優しい夫人を本当の母親と思っていたが、偶然にもかつての奴隷仲間に手を差し伸べたことで、奴隷を極度に嫌う統治官夫婦にすぐに捨てられた。\n運命は残酷に変わらない本性を見せ、一夜にして囚人となり、檻の中で憎しみを募らせつつ、青春を過ごした。\n融蝕が刑務所で発生したとき、彼女はこの黒い液体が手錠を融蝕させることに気づき、復讐の女神はついに牢獄を離れ、再び現れたとき、統治官の首を持ってデロス人の全面解放を勝ち取った。\n彼女の余生はかつての奴隷主を追い詰めることに費やされ、無名の賛歌が刻まれた墓となるまで続いた。"
  },
  CollectionHall_57635_LockTip = {
    Text = "「ヘロット」を召喚すると解放"
  },
  CollectionHall_57635_Title = {
    Text = "ヘロット"
  },
  CollectionHall_57636_Title = {
    Text = "暗闇の住人"
  },
  CollectionHall_57637_Desc = {
    Text = "<Title:紹介>\nその時代の多くの女性が医療従事者として戦場に立つ中、彼女は勇敢な戦士として生き、そのことを誇りにしていました。\n祖国が神聖であり、他の土地を征服することで世界により良い未来をもたらすと信じていました。\n激しい戦闘中、新兵を救うために重傷を負い、辛うじて生き延びたものの、後遺症で歩行困難になりました。それでも軍を離れず、前線チームから新兵訓練官に転職しました。\n\n時が経つにつれ、訓練生たちは「障害者」の教官に不満を抱くようになり、軍内で彼女への陰口が広まりました。\n彼女は、少佐になった過去に救った兵士に意見を求めましたが、彼もまた他の者と同じように彼女の傷を嘲笑しました。\nこの侮辱に耐えかねて軍を去りました。\n軍と戦場の外で、彼女は世界の全貌を見ました。「戦争英雄」は同胞に裏切られ、誇りに思っていた「解放」は現地住民に苦難をもたらしました。\n彼女の心は揺れ動き、真の解放に身を投じ、正義感と罪悪感に駆られて「正しいこと」を行うようになりました。\n残念ながら、傷は治らず、贖罪を果たす前に苦しんで死にました。\n再び召喚した後、タイスの恩に感謝し、アラン部族の存続に尽力しました。"
  },
  CollectionHall_57637_LockTip = {
    Text = "「アルバ」を召喚すると解放"
  },
  CollectionHall_57637_Title = {Text = "アルバ"},
  CollectionHall_57638_Desc = {
    Text = "<Title:紹介>\n彼はかつてローマのゴーレムであり、スター剣闘士であり、最後のそして唯一の戦士だった。\nカリグラ皇帝の狂気の意志を遂行するために生まれた彼は、叔父、兄弟、姉妹など、皇帝の政敵全員を排除した。\n若い皇帝は親族の死体の山の前でひざまずき、両腕を上げて泣き笑いした。\nユウハシュは困惑した。ゴーレムは泣くことも笑うこともできたが、同時に泣いて笑うことはできなかったのだ。\nその後、暴君皇帝は処刑された。彼は処刑される前に、ユウハシュを抱きしめた。\nしかし彼は何も言わなかった。\n持ち主を失った武器は、次の持ち主に出会うまで彷徨い続ける。\n彼はまだ人間に困惑していた。"
  },
  CollectionHall_57638_LockTip = {
    Text = "意識潜行「血と砂」クリアで解放"
  },
  CollectionHall_57638_Title = {
    Text = "ユウハシュ"
  },
  CollectionHall_57639_Desc = {
    Text = "<Title:紹介>\n「ロンディニウムの最も輝く宝石」と讃えられ、その一挙手一投足が、人々の視線を集める。\n最も邪悪な神と契約を結び、自らの「死」を代償に、新たな命を得た。\n彼女の素性については、諸説入り乱れている。\n名家の令嬢、情婦、商人、政治家、流行牽引のクイーン……\nその真の姿は、すでに霧の中。\nあるいは、この変わり続ける姿こそが、彼女の本質なのかもしれない。"
  },
  CollectionHall_57639_LockTip = {
    Text = "特務記録「薔薇の讃歌」クリアで解放"
  },
  CollectionHall_57639_Title = {
    Text = "ソレール"
  },
  CollectionHall_57640_Desc = {
    Text = "<Title:紹介>\nかつて古ローマの貴族の娘で、父親は剣闘士訓練所を経営していた。\n周りに強力な剣闘士の奴隷を従え、カプアで横行し、傲慢に振る舞っていた。\n皮肉なことに、結局は一番嫌っている奴隷に自分を殺してくれるよう懇願する羽目になった。\nさらに皮肉なことに、覚醒体となった後、不幸にもその「奴隷」と大学で再会することになる。\n想像に難くないが、彼らを待ち受けるのは、決して穏やかな場面ではないだろう。"
  },
  CollectionHall_57640_LockTip = {
    Text = "意識潜行「蒼白の末裔」クリアで解放"
  },
  CollectionHall_57640_Title = {
    Text = "アグリッパ"
  },
  CollectionHall_57641_Desc = {
    Text = "<Title:紹介>\n船乗りたちの愚かな伝統の下で作られた船の聖女、実際は貧しい家庭から売られた娘で、航海の守護として日々マストに縛られていた。\n自由も選択もない人生は彼女を無感情にし、ほとんど自己を失い、船だけが彼女にとって最も馴染みのある居場所となった。\n無力な人生に美しい祈りが託され、船員との会話を禁じられたため、ぼんやりすることに慣れ、最も強い願望とマストのそばを飛ぶ海鳥だけが彼女の目を引いた。\n最後に守護していた船が融蝕に遭い、多くの死傷者が出たため、怒りをぶつける人々に溺死刑に処された。"
  },
  CollectionHall_57641_LockTip = {
    Text = "「シレスト」を召喚すると解放"
  },
  CollectionHall_57641_Title = {
    Text = "シレスト"
  },
  CollectionHall_57642_Desc = {
    Text = "<Title:紹介>\nシディ出身の倫理なき芸術家。\n名門出身だが、芸術を追求するため家族と決別し、一人でシディに渡り、著名な彫刻家オーギュストの弟子となる。\n類まれな才能を持ちながらも、芸術史に名を残すことはなかった。\n覚醒体となった後、彫刻と塑像への新しい理解を得て、皆に知られる「狂気の芸術家」となった。\n守秘者を新しいインスピレーションの源とし、守秘者を見る目には常に奇妙な優しさが宿る。\nああ、それは一片の曇りもない、愛おしい素材を見つめる眼差しだった。"
  },
  CollectionHall_57642_LockTip = {
    Text = "意識潜行「歌のような彫刻」クリアで解放"
  },
  CollectionHall_57642_Title = {
    Text = "サンガー"
  },
  CollectionHall_57643_Desc = {
    Text = "<Title:紹介>\nかつて古代アケメネス朝の侍女だった。\n百周年記念の晩餐会で客をもてなす役に選ばれなかったため、同伴者を湖に沈めて彼女の代わりを務めた。\n最終的に宴会中に醜い緑の怪物に変えられてしまった。\n柔軟な頭脳と体を持ち、同時に十の皿を運びながら人々の中を縫うように移動できる。\n美食の定義は現代の食文化とは大きく乖離している。\n時折、自分が殺人のために罰を受けて怪物になったのではないかと疑うこともある。\nしかし、教訓を引き出すことはなく、すぐに何もなかったかのように装うだろう。\n結局、エリウィン人が歴史から引き出せる唯一の教訓は——エリウィン人は決して教訓を得ないということだ。"
  },
  CollectionHall_57643_LockTip = {
    Text = "「カレン」を召喚すると解放"
  },
  CollectionHall_57643_Title = {Text = "カレン"},
  CollectionHall_57644_Desc = {
    Text = "<Title:紹介>\n@2の刑務官で、囚人を拷問することを楽しんでいる。\n上司は彼女に3年後にロンディニウムに戻すと約束したが、融蝕現象の悪化と地脈の変動により、彼女はこの遠い土地に忘れ去られた。\n少女は気を落とさず、廃墟を守り続け、召喚される日を待っていた。\n最後の囚人が亡くなるまで、彼女は島で唯一の生き物となった。\n囚人のいない刑務官は、囚人と何が違うのだろうか？\n少女は考えることを拒み、召喚される日を待ち続けた。"
  },
  CollectionHall_57644_LockTip = {
    Text = "「パンディア」を召喚すると解放"
  },
  CollectionHall_57644_Title = {
    Text = "パンディア"
  },
  CollectionHall_57645_Title = {
    Text = "万古の超越"
  },
  CollectionHall_57646_Desc = {
    Text = "<Title:紹介>\nフランシスが飼う「ペット」。\n元々は「リサ」という明るい少女で、彫刻家協会の改造で人獣縫合法の歪んだ姿に変わり、リリーに引き取られ一時的に精神病院で生活している。\n人間の姿と声を失っても、クムはリサの一部の知性を保ち、簡単な体の動きで意図を伝えられる。\n彼女は自分の選択をした。"
  },
  CollectionHall_57646_LockTip = {
    Text = "調査第4章「無音の中で」クリアで解放"
  },
  CollectionHall_57646_Title = {Text = "クム"},
  CollectionHall_57647_Desc = {
    Text = "<Title:紹介>\n出自不明の薬剤師、今は彫刻家協会の科学顧問。\n母は田舎の農婦で、大蛇神の子を宿すよう選ばれる。\n母の色素欠乏症と優しい性格を受け継ぎ、ハーバートの唯一信頼する友。\n解剖学、芳香族炭化水素、ベラドンナの香りに熱中。\n多くの著作を持ち、代表作は毒理学のバイブル《薬物誌》。\n毒物に浸かり続けたため、吐く息も毒を含む。彼には近づくな——それは筆者からの唯一の忠告。"
  },
  CollectionHall_57647_LockTip = {
    Text = "調査第2章「蝋人形の名において」クリアで解放"
  },
  CollectionHall_57647_Title = {
    Text = "アルビノ"
  },
  CollectionHall_57648_Desc = {
    Text = "<Title:紹介>\nワード・フィリップスの弟子で、ミサゴの最初の守秘者。\n長年地下の秘密区域に住んでおり、その存在を知る者はごくわずか。\n精神力が卓越しており、特別な秘法で生命を維持し、ミサゴの安全を守っていた。\n守秘者が未来の変局において非常に重要であると予感し、例外的に守秘者がいつでも自分と接触できるようにした。\nそれは育成であり、観察でもあった。"
  },
  CollectionHall_57648_LockTip = {
    Text = "調査第2章「蝋人形の名において」クリアで解放"
  },
  CollectionHall_57648_Title = {
    Text = "アリステア"
  },
  CollectionHall_57649_Desc = {
    Text = "<Title:紹介>\n海踊人の血を引く薄い人間、古いアウン族出身。この家族は昔変異に見舞われ、一部は成人後に容貌が醜悪な怪物に変身し、最終的に苦しんで死ぬ。父はその変異に耐えられず、彼の誕生後に自殺。\n幼い頃から母親の嫌悪と同世代の仲間たちのいじめの中で育ちながら、性格は陰鬱で孤独になった。\n十六歳の時、叔父の遺した資料に家族の高貴な血統が書かれていることを知り、精神的勝利を得て、いつか超然とした力を得ることを夢見てきた。その後、いじめを選ばれし者にとって避けられない試練として受け止め、周囲の人々が自分に媚びる日を期待していた。\n成人時には洞窟にこもり変異を迎えようとしたが、半人半魚の姿で止まってしまい、母に叫ばれ追い出され家に戻れなかった。\n最終的には海に飛び込み、仲間を探そうとしたが、未発達のエラのため溺死した。"
  },
  CollectionHall_57649_LockTip = {
    Text = "「カエクス」を召喚すると解放"
  },
  CollectionHall_57649_Title = {
    Text = "カエクス"
  },
  CollectionHall_57650_Desc = {
    Text = "<Title:紹介>\n王国最古のキャヴェンディッシュ家出身、元々は親の宝だったが融蝕に感染。\n地下に三年閉じ込められ、血への欲求が増す。\n兄は東区の孤児や売春婦を集め、妹の「食物」として提供。\n街は恐慌に陥り、警察が全力で捜索し、兄妹は逮捕された。\nロンディニウムを震撼させた「吸血鬼事件」はこうして終わった。"
  },
  CollectionHall_57650_LockTip = {
    Text = "「レーア」を召喚すると解放"
  },
  CollectionHall_57650_Title = {Text = "レーア"},
  CollectionHall_57651_Desc = {
    Text = "<Title:紹介>\nロンディニウムの東区出身の織工。\n融蝕に感染し、彫刻家協会に拉致されて、蝋人形にされる。\n「24」は実験番号であり、初めて診断された際に確認した人格の数でもある。\nこの記録を書いている最中にもその人格数は増え続けている。\nやがて時が経てば、「24」たちの王国が人でにぎわい、壮観になることは間違いない。"
  },
  CollectionHall_57651_LockTip = {
    Text = "特務記録「静かな分裂」クリアで解放"
  },
  CollectionHall_57652_Desc = {
    Text = "<Title:紹介>\n生前、父と共に融蝕に感染し、一家の苦しみの中でずっと大人しく治療に耐え続けていた。\n母親は夫と娘を同時に失ったことで、性格が一変。アイズルワースの探索中に偶然、提灯教会の儀式に迷い込み、偶発的にリリーを覚醒召喚した。\n異常な覚醒により、リリーは無表情な人形と化し、命令を聞いたときだけ行動するようになった。\n母は融蝕によりリリーの姿を忘れ、覚醒したリリーを怪物と見なし、本物の娘が蘇ることを期待して実験を繰り返した。\n最終的に守秘者と共にミサゴへ向かい、守秘者のことを母と呼び、非常に依存している。"
  },
  CollectionHall_57652_LockTip = {
    Text = "特務記録「物語の魔法」クリアで解放"
  },
  CollectionHall_57652_Title = {Text = "リリー"},
  CollectionHall_57653_Desc = {
    Text = "<Title:紹介>\nロジャーズの蝋人形の人形。\n\n車両の中で大声で騒ぐ子供たちと同じく、甘やかされた奴だ。\n頼みの綱は、あの灰緑色の目——それは「ロウソクの男」がロジャーズに残した唯一のもの。\n「24」の人工密境で抗いがたい力に遭遇し、ぺしゃんこのジョージになって、見事にロジャーズの怒りを買った。"
  },
  CollectionHall_57653_LockTip = {
    Text = "調査第2章「蝋人形の名において」クリアで解放"
  },
  CollectionHall_57653_Title = {
    Text = "ジョージ"
  },
  CollectionHall_57654_Desc = {
    Text = "<Title:紹介>\nリリアン貧民救済院の孤児であり、ジェンキンの最も親しい仲間。\nかつて彫刻家協会に改造され、他の孤児たちが無残に死ぬ様を目の当たりにし、自分が生き残ったことと沈黙を守ったことに深い罪悪感を抱いていた。\n最後は時計塔から身を投げ、完全な解放を得た。\n常に小さなぬいぐるみのクマを抱きしめており、彼女はそれを「ボビー」と名付けた。\n贈り物、小さなスカート、金色のキャンディーが好き。\n少し暗闇が苦手で、いつも「ボビー」を抱きしめないと眠れない。もしあなたが彼女のためにクレードルを歌ってあげられるなら、その少女はあなたをずっと感謝し、愛し続けるだろう。\nかつてジェンキンが彼女にしてあげたように。"
  },
  CollectionHall_57654_LockTip = {
    Text = "「アイギス」を召喚すると解放"
  },
  CollectionHall_57654_Title = {
    Text = "アイギス"
  },
  CollectionHall_57716_Desc = {
    Text = "<Title:紹介>\nもともとはオートマタの制作に没頭する研究員であり、ダフォダイルからシルバーコアを核とするエネルギーコンポーネントを得た。\nだが、研究員の友人がそのコンポーネントを狙い、多くの争いの末、最終的に激怒し奪い合って実験室で爆発が起こった。なぜか人形の体の中で目覚めた彼女は、無生命であるはずのオートマタの中にもう一つの意識が存在することに恐怖を覚えた。\n彼女が燃えさかる廃墟から友人を救い出すために抱いた信念、そして郊外に向かう信念は誰も知らない。この無名の機械の天才は姿を消し、爆発に関するニュースと散在する部品、そして一つのシルバーコアだけが残った。\nそこから目覚めたのは一体何者か？"
  },
  CollectionHall_57716_LockTip = {
    Text = "意識潜行「歪みの核」クリアで解放"
  },
  CollectionHall_57716_Title = {Text = "エリカ"},
  CollectionHall_57717_Desc = {
    Text = "<Title:紹介>\n@2の使者であり、代行者。しばしば人の姿をとって世を歩く。\n純粋なる悪魔――未来も、信念も、理想も持たない。\n欲望を餌にし、混乱を糧とし、人間を欺き誘惑するのに熱中している。\nルールを操るのが得意で、契約を結んだ人間は最後にすべてを失う。\n最も抜け目のない弁護士でさえ、彼から利益を得ることはできない。\n時折子供の姿を装うこともあるが、それで警戒を緩めてはならない。\n結局、彼の恐ろしさは、決してその外見にあるわけではないのだから。"
  },
  CollectionHall_57717_LockTip = {
    Text = "特務記録「薔薇の讃歌」クリアで解放"
  },
  CollectionHall_57718_Desc = {
    Text = "<Title:紹介>\n精神科医で、意識障害、ヒステリー、不安や不眠症を専門とする。\n催眠を使って患者の心の声を引き出すのが得意。\n彼女の患者は皆、非常に「芸術的」な自殺をすることで知られているが、警察が訪れる前に身分を変え、新たに開業する。\n多くの名士が彼女の診療所に訪れ、「ロンディニウムの半分の秘密を知る女性」と評された。\nロジャーズは彼女の長期的なクライアントだった——彼の異常な芸術的情熱もこの医師と無関係ではなさそうだ。"
  },
  CollectionHall_57718_LockTip = {
    Text = "調査第1章「東区の秘め事」クリアで解放"
  },
  CollectionHall_57718_Title = {
    Text = "クレメンタイン"
  },
  CollectionHall_57719_Desc = {
    Text = "<Title:紹介>\n卓越を追求する蝋人形師、ロジャーズ蝋人形館の現任館長。\n幼少時に吃音でいじめられ、「金だけしかない」と嘲笑われたことがあった。\n高い地位にいる父、精神錯乱の母、そして全国を震撼させた誘拐事件…\n数々の悲惨な要因の下で、ロジャーズは母を超え、スカボローでトップクラスの狂人になった。\n彫刻家協会で女性に最も人気のあるメンバーで、感情が非常に安定している紳士——芸術の話をしなければ。"
  },
  CollectionHall_57719_LockTip = {
    Text = "調査第2章「蝋人形の名において」クリアで解放"
  },
  CollectionHall_57719_Title = {
    Text = "ロジャーズ"
  },
  CollectionHall_57720_Desc = {
    Text = "<Title:紹介>\n機械工の母親を持つ。父親は出航後行方不明、母と修理店を経営。\n母の夢であるモノホイールバイクの製作を試みる。\n母の死後、部品を得るため高報酬の船の仕事を引き受け。\n嵐のため大きな渦に巻き込まれてしまった。船に残っていた唯一の潜水服を友人に譲った後、母の形見を握りながら融蝕された海流で死亡。残骸とシルバーコアだけが漂流中。"
  },
  CollectionHall_57720_LockTip = {
    Text = "「ナウティラ」を召喚すると解放"
  },
  CollectionHall_57720_Title = {
    Text = "ナウティラ"
  },
  CollectionHall_58148_Desc = {
    Text = "<Title:紹介>\n海踊教団の祭司が育てた小さな姫君。「聖女」とも呼ばれる。\n幼いころから大切に育てられ、名実ともに淑女として成長した。\n彼女の手にある小さな日傘は、白く柔らかな肌を守るだけでなく、あらゆる不浄や不吉を遠ざける結界でもあった。\n\nしかし、彼女は自分自身も「不吉」の産物であることを知っている——彼女の誕生は自然の理ではなく、「母」となるため、予言の子を産むために用意されたものだった。\n食べきれないお菓子、最新の洋服、彼女を囲む無数の従者…………彼女はきらびやかな物質世界を渡り歩きながら、心の奥底にある不安と惑いを必死に封じ込めていた。\nしかしその試みは結局失敗に終わった。\n自由な心は妥協を受け入れることはできなかったのだ。"
  },
  CollectionHall_58148_LockTip = {
    Text = "「マーフィー」を召喚すると解放"
  },
  CollectionHall_58148_Title = {
    Text = "マーフィー"
  },
  CollectionHall_59454_Desc = {
    Text = "<Title:紹介>\n沿岸の漁村出身の小さな女の子で、両親は遠洋漁船の乗組員。祖母と二人三脚で生活し、祖母が作ったおとぎ話を無邪気に信じていた——彼女たちはアトランティスの子孫であり、彼女が素直に成長し、たくさんの友達を作れば、友達たちが彼女を海底の故郷へ連れて帰ってくれると。\n祖母が亡くなった後、ある水族館のオーナーが魚を取りに来た際、明るく活発な彼女をガイドとして雇い、幸運にも色彩豊かな幼少期を過ごした。\n融蝕した魚が水族館全体を汚染した後、水族館は破産を宣言し、失業した彼女は最愛のクラゲを瓶に入れて辺鄙な村へ持ち帰ったが、すぐに融蝕が彼女を侵食し、村全体を侵食してしまった……\n召喚後、記憶が少し混乱しており、いわゆる「海底人」だと固く信じ、友達を故郷に招待しようとひたむきに取り組んでいる。"
  },
  CollectionHall_59454_LockTip = {
    Text = "意識潜行「いつも通り」クリアで解放"
  },
  CollectionHall_59454_Title = {
    Text = "オレッタ"
  },
  CollectionHall_59455_Desc = {
    Text = "<Title:紹介>\n「絶対的な強運」を持つと言われる男。\nそのような才能があるからこそ、ギャンブラーになるのは当然だった。\nそれとは別に、彼は優秀な探偵でもある。\nさらに、彼は賭けに勝った金をすぐに浪費してしまう貧乏人でもある。\n矛盾していて複雑。この男について言えることはこれだけだ。\n運命の女神は彼を寵愛し、正体不明の「N」も彼に好意を持ち、ケチな酒場の主人でさえ彼には喜んでツケを許した。\n誰もが彼を気に入っているが、彼はそれでも歩みを止めない。\n代わりに、彼は新たなゲームを始める。\n彼はいつだって未知を好んでいる。"
  },
  CollectionHall_59455_LockTip = {
    Text = "特務記録「良き狩りを！」クリアで解放"
  },
  CollectionHall_59455_Title = {
    Text = "ライカー"
  },
  CollectionHall_59456_Desc = {
    Text = "<Title:紹介>\n没落貴族の出身、生まれつき重度の喘息に苦しみ、両親から十分な愛情を受けて育つ。\n病による苦痛で外に出られず、しばしば自殺を考える。両親は心を癒すため遠出に連れて行ったが、思いがけず融蝕に感染。\n帰郷後、罪悪感を抱く両親に療養所に送られ、海で商売をする傍ら、治療法を探し続ける。\n融蝕が進むにつれて、死への渇望は強くなるが、両親を悲しませたくない一心で自殺を耐える。\n両親が見舞いに来る途中、船の事故で亡くなったことを知り、人間界への未練を断ち、夜中に療養所を離れ、海へ向かって歩む。\n海水に浸かるその瞬間、三角の融蝕痕から滴る黒い液体が散り、長く苦しんだ体が解放され——それが唯一深呼吸できた瞬間だった。"
  },
  CollectionHall_59456_LockTip = {
    Text = "「ニムフィーア」を召喚すると解放"
  },
  CollectionHall_59456_Title = {
    Text = "ニムフィーア"
  },
  CollectionHall_61045_LockTip = {
    Text = "調査8-1クリアで解放"
  },
  CollectionHall_61045_Title = {
    Text = "イ短調：終末交響曲"
  },
  CollectionHall_62183_Title = {
    Text = "08 終末交響曲"
  },
  CollectionHall_62184_Desc = {
    Text = "<Title:紹介>\n世界に名を轟かす指揮者にして音楽家。若くして彼の指揮する交響楽は世界各地を巡り、どの公演も街中の人々が押し寄せた。\nクラシック音楽界最高の天才でありながら、ハムリンの私的な情報は一切不明——それが審査会の注目を引いた。長期にわたる調査の末、彼の公演会場が提灯教会の行動軌跡と高度に一致していることが判明した。\n彼らが真実を掴む前に、真実の方が動いた。提灯教会のミサゴ侵攻事件において、ハムリンが極めて重要な役割を果たしていたことが明らかになったのだ。\nその時、人々はようやく悟った。この天才指揮者の真の舞台は、はじめから劇場の外にあった。"
  },
  CollectionHall_62184_LockTip = {
    Text = "調査第8章「終末交響曲」クリアで解放"
  },
  CollectionHall_62184_Title = {
    Text = "ハムリン"
  },
  CollectionHall_65503_Title = {
    Text = "雪山への帰還"
  },
  CollectionHall_65509_Desc = {
    Text = "<Title:紹介>\n東区出身の小悪党、「24」の妹。\n特技は盗み、喧嘩、やばいと逃げること。\n誰も彼女から利益を得られない。\nそう、彼女には「ブラウン」という親しい鼠がいる。\nブラウンは成熟して落ち着いており、ジェンキンの性格とよくマッチしている。\n東区では鼠を料理する悲惨な事件があるが、ジェンキンはその気になったことはない。"
  },
  CollectionHall_65509_LockTip = {
