  },
  CollectionHall_70555_Title = {
    Text = "春が散る前：花園の思い出"
  },
  CollectionHall_70839_Desc = {
    Text = "<Title:紹介>\nお世辞、商人、偽善。リリアンワークハウスの院長は、ロンディニウムの名声の場で卑しい乞食のように振舞う愚かな役者のようだ。\n\n彼女は奔走し、不器用なお世辞を使って名士達に小銭を乞い、ワークハウスの運営を維持していた。\n彼女は嘲笑や侮辱を独りで飲み込み、恵まれない者の館の子供たちを柔らかい歌声で眠りへと誘った。\nロンディニウムは彼らを見捨てたが、リリーの恵みを受けた館は見捨てられてはいない。\nサラは準備を整え、これらの子供たちを守るために尽力し、ロンディニウムの霧と寒風の中で無事に生き延びさせようとしていた。\n\nだが、彼女の理想は失敗に終わり、彼女と子供たちは彫刻家協会の陰謀の中で命を落とした。\n彫刻家協会にとって、彼女と彼女が大切にしていた子供たちは、その壮大な建物の中で取るに足らない砂のような存在であり、価値も美しさも欠如していた。\n彼らの命には重さがなく、彼らの死はどうでもよいことだった。\n\n彼女はすべてを燃やし尽くした。\nだが、その火はすぐに消え、ただロンディニウムの風は骨まで冷たく吹きすさぶだけ。"
  },
  CollectionHall_70839_LockTip = {
    Text = "第一章クリアで解放"
  },
  CollectionHall_70839_Title = {Text = "サラ"},
  CollectionHall_70884_Desc = {
    Text = "<Title:A.F.185>\n各国代表はコンスタン連邦にて《ミスティア協定》を締結し、共に災厄に抗し、融蝕の裂け目を抑圧することを決定する。一方では、各国は隠された災厄の存在と融蝕現象の方針について合意に至る。\n本協定の決定により、学院は独立を保ち、いかなる国家にも帰属せず、各国に支部を設立し、各国の指導者と直接連絡を取り、各国の災厄および融蝕に関する情報を取得する権利を持つこととなった。\nこれにより、ミサゴ学院は正式に完全中立の国際組織となる。\n\n<Title:A.F.186>\nミスティア協定の改正と署名に関与した関係者はミスティアに常駐の審査会を設立し、審査会は自身の行動部隊を持ち、協定の実施を確保する権限を持った。密室議会が設立され、組織の基本的な構造が確立された。\n\n<Title:A.F.187>\nミサゴ学院は正式にミサゴ大学に改名される。\n以後、融蝕現象はますます頻繁に、多様化していく。\nミサゴ大学は第一線に立ち、人類の融蝕への対抗の要となる。"
  },
  CollectionHall_70884_LockTip = {
    Text = "調査9-13クリアで解放"
  },
  CollectionHall_70885_Desc = {
    Text = "<Title:A.F.75>\nアリステアはレオ王国内に巨大な裂け目が現れることを予見し、ワードは調査員たちを率いてその対応に向かった。\nこの事故において、多くの調査員が命を落とした。\n\n<Title:A.F.77>\n裂け目は閉鎖できなかったものの、次第に安定へと向かった。\n政府の協力と支援のもと、ワードは巨大な裂け目の上に「真理の視線」の拠点を建設した。\n巨大な裂け目は正式にL-01と番号付けされ、「昏き海」と呼ばれるようになった。\n\n<Title:A.F.88>\n「昏き海」に突発的な異変が発生し、外部へと拡散を始める。\nこの時点で周辺地域に展開していた「真理の視線」は甚大な損失を被り、ワード自身も対応の最中に負傷した。\n昏き海が閉鎖不可能であったため、タヴィは自らその中へと沈み、自ら制御することで昏き海の一時的な安定を保った。\n\n<Title:A.F.90>\n「真理の視線」の拠点が拡張され、ミサゴ学院が設立される。\nワードは初代学院長に就任した。\nこれを機に、人々は十分な精神力を持つ調査員を体系的に育成し始め、激化する融蝕の危機に、より効果的に対抗する体制が整えられていく。\n\n<Title:A.F.92>\nワードが昏き海事件で受けた傷はさらに悪化し、その影響で死亡した。\nワードの遺骸は学院内に埋葬され、墓碑は「鍵」を模した形で造られ、これが後のミサゴ大学の鍵塚の伝統の始まりとなる。\n死後に析出したシルバーコアはアリステアによってシルバーキーに加工され、番号K-0001が付けられた。\nこれにより、アリステアは初代守秘者となり、以後、外界において活動することとなる。\n同年、ワードを救う方法を求めてヴォルムワヒで調査を行ったクラークシュが失踪し、以後その行方は分からなくなった。"
  },
  CollectionHall_70885_LockTip = {
    Text = "調査9-13クリアで解放"
  },
  CollectionHall_70886_Desc = {
    Text = "<Title:A.F.306>\nハーバートはグリーン財団の資金を受け取り、提灯教会の助けを得て、彫刻家協会を設立する。\n同年、ドールがミサゴ大学に入学する。天才学者として、ドールは入学直後からすぐに大学院生や博士課程の研究に直接関与し、その後大いにミサゴ大学のシルバーコアテクノロジーの発展を推進する。\n\n<Title:A.F.307>\nハーバートは提灯教会と共にミサゴ大学を襲撃し、かつて提灯教会ですり替えられた「聖女」を取り戻そうとする。\n\n<Title:A.F.309>\nある融蝕事件の生存者ウィリアムが調査員フィンゴルの紹介を受け、ミサゴ大学に加入する。\n\n<Title:A.F.310>\nミサゴ大学共同審査会は、彫刻家協会の成長を阻止するために、その構成員の大半を逮捕、拘束した。\nハーバートと数人の中核構成員は逃げ、地下で活動を開始する。\nその後、ハーバートはロジャーズに接触し、協力関係を築いた。\n同年、サルバドルが大聖堂区司教を継承し、ハレトが学長代理となる。\n\n<Title:A.F.313>\nハーバートの指示で、ロジャーズはリリアンワークハウスに寄付を行い、ワークハウスの唯一の資金提供者となる。\n\n<Title:A.F.314>\nアクートで大爆発が発生する。\nアリステアの派遣により、ウィリアムとラモンナがアクートに向かい、爆発後の遺跡ですべての記憶を失った@3を見つけ、ミサゴ大学に連れ帰って、特別訓練を施すこととなった。"
  },
  CollectionHall_70886_LockTip = {
    Text = "調査9-13クリアで解放"
  },
  CollectionHall_70887_Desc = {
    Text = "<Title:A.F.263>\nフランシス誕生。\n\n<Title:A.F.289>\n娘を失った後、フランシスは探検隊に参加し、アイズルワースに向かう。\n同年、探検隊全員が壊滅する。\n\n<Title:A.F.290>\nロジャーズ誕生。\n同年、フランシスはアイズルワースで偶然にもリリーを覚醒召喚させる。\nその後、財団の支援を受けてライに精神病院を設立し、停滞した時空を構築する。\n\n<Title:A.F.292>\nドール誕生。\n\n<Title:A.F.297>\nハーバートが新入生としてミサゴ大学に入学、当時17歳。\n\n<Title:A.F.298>\n提灯教会が双子の神子を用いて降神の儀式を行う。\nデクスターは儀式に潜入し、降神の器とされる予定だったラモンナを密かに連れ去り、提灯教会の儀式を阻止する。\n儀式は失敗に終わり、ラモンナはデクスターの養女となる。\n\n<Title:A.F.300>\nロジャーズが「蝋人形」に誘拐される。\nその後「蝋人形」は死亡し、ロジャーズは救出される。\n同年、サルバドルが当時の大聖堂区司教によって覚醒召喚され、助任司祭として大聖堂区に仕える。\n\n<Title:A.F.304>\nハレトが新入生としてミサゴ大学に入学。\n\n<Title:A.F.305>\nミサゴ大学覚醒学部の学生ハーバートが規則違反で実験体を製造。\n行為の発覚後、ハーバートは自身の指導教授クロウリーを殺害して逃亡。当時25歳。"
  },
  CollectionHall_70887_LockTip = {
    Text = "調査9-13クリアで解放"
  },
  CollectionHall_70888_Desc = {
    Text = "<Title:B.F.？？？>\n世界を席巻した大災厄は、広大な陸地を破壊した。\n地震、洪水、磁場の乱れ、気候の異常などが次々に起こり、都市や集落は水の中に沈み、海底に埋まっていた堅固な岩々は新たな山脈となった。\n人類文明は甚大な打撃を受けたのである。\n\n<Title:A.F.0>\n古き大地は海水に呑み込まれ、新たな大地が水面に姿を現した。\n姿を一変させた世界の中で、人々は旧来の暦を捨てて、文明の残骸を抱えながら困難にも再建の道を歩み、新たな紀元である「洪積」へと踏み出した。"
  },
  CollectionHall_70888_LockTip = {
    Text = "調査9-13クリアで解放"
  },
  CollectionHall_70889_Desc = {
    Text = "<Title:A.F.55>\nクラークシュは自身の調査などを通じて銀の鍵秘密結社に自ら参加し、その力を借りて人類の再建を支援することを望んでいた。\n同年、クラークシュはワードとタヴィの行動に気付き、その動向を注視し始めた。\n\n<Title:A.F.58>\nクラークシュは使い捨てのシルバーキーを制作し、新たな結社の指導者として鍵職人となり、結社を利用し、静かに知識を広めて、人類再建を支援した。\n同年、クラークシュはワードとタヴィと接触し、ワードに対して一定の資金と人手を提供することを約束した。\n\n<Title:A.F.62>\nアリステア・オーウィンズはロンディニウム郊外のごく普通の田舎医師の家庭に生まれる。\n\n<Title:A.F.64>\n調査を完了したクラークシュはワードの志を認め、結社の規則に束縛されたくないワードに対して、タヴィの提案と立ち会いのもと、双方は対等な協力関係を結ぶ。\n結社からの資金や人手などの支援を受けた後、ワードの研究はさらに進展し、融蝕の特徴と融蝕と変異体との関係を確認した。そして、融蝕侵蝕における段階的な特徴を初歩的に整理した。\n\n<Title:A.F.65>\nクラークシュ、ワード、タヴィは、数名の結社メンバーと共に融蝕の追跡と拡散阻止を使命とする最初の調査員小隊を結成し、これを「真理の視線」と名付けた。\n\n<Title:A.F.70>\nワードは、再び融蝕および融蝕侵蝕の特性と法則性を総括し、融蝕における地域的特性を初めて記録する。\nそれらをまとめた書『融蝕と融蝕法則の初考』を著し、新たに調査隊へ加わる隊員の参考資料とした。\n\n<Title:A.F.72>\nワードは融蝕によって崩壊した一家の中からアリステアを救出し、弟子として迎え入れる。\n同年、ワードおよびその率いる『真理の視線』は次第に規模を拡大し、ついに当局の注意を引く存在となった。"
  },
  CollectionHall_70889_LockTip = {
    Text = "調査9-13クリアで解放"
  },
  CollectionHall_70890_Desc = {
    Text = "<Title:A.F.30>\nワード・フィリップスはアグロ共和国東部の古い都市シャロームの裕福な商人の家に生まれた。\n\n<Title:A.F.38>\nクラークシュが誕生。生後間もなく両親を亡くし、姉と身を寄せ合いながら、懸命に生き抜く日々を送る。\n\n<Title:A.F.48>\nワードは幼い頃から化学や物理の才能を発揮し、18歳でモスウェイトセ州立大学の化学科に合格し、著名な化学者ナサニエル・ミルトンの門下生となる。\n\n<Title:A.F.50>\nワードの祖父ロジャー・フィリップス神父が亡くなり、その後父親が失踪。ワードは本家の邸宅を調査し、父親の足跡を追いレオ王国に到着し、そこで家族が長い間隠してきた秘密——魔女狩り時代に異教徒（銀の鍵秘密結社）の手から奪った神秘的な製法を発見した。\nその古い製法は羊皮紙の巻物に記載されており、多くの部分が破損していた。ワードは長年の実験を経て、それをなんとか補完した。\n\n<Title:A.F.53>\n補完された製法に基づき、ワードは最初のシルバーキーを作ることに成功した。しかし製法の欠陥により、このシルバーキーは一度使用すると壊れてしまい、再び使用できなくなった。\nそれでもなお、この一度きりのシルバーキーのおかげで、ワードは知識の神子の代行者タヴィに面会し、タヴィからこの世界が間もなく「漆黒の災厄」に直面するということを知らされた。\n災難を阻止しようと決心したワードはタヴィと交渉を行い、タヴィとリンクして覚醒体の作り方と完全なシルバーキーの製法を得た。\nその後、ワードは各地を巡り、融蝕と裂け目の研究を進め、それらに名称を与えながら、融蝕に抗う術を見出そうと試み続けた。"
  },
  CollectionHall_70890_LockTip = {
    Text = "調査9-13クリアで解放"
  },
  CollectionHall_70891_Desc = {
    Text = "1年間の予科学習と訓練を経て、@3は正式に守秘者として任命され、覚醒体や他の校内の力と共に融蝕に関する事件の調査を始めました。\n同年、提灯教会はミサゴ内の鬼と再び連携して侵入し、昏き海の動乱を引き起こし、窮地の門を開いて、至高の意志の目を引き寄せました。\nカダスが融蝕に捕食されそうになったとき、@3は三大神子の権柄を吸収し、扉の内で至高の意志の視線と対決しました。\n最終的に、至高の意志は再び眠り、カダスは救われました。\n@3は殉死しました。\nそのすべての関連記録は融蝕され、保持できないため、ミサゴは例外的に彼の生前に使用していたシルバーキーを封印し、校史記念館に保管してその功績を顕彰することにしました。\n%hisorher%の名前は誰も知らないが、K-0617という番号は永遠に残るでしょう。"
  },
  CollectionHall_70891_LockTip = {
    Text = "調査9-13クリアで解放"
  },
