  CollectionHall_71059_Desc = {
    Text = "これは劇のクライマックス、小さな狂想曲。\nオーケストラが激しく演奏する——\nたとえ今夜、私が死ぬとしても。\n最後の場面まで精一杯歌い続ける。"
