  },
  CollectionHall_71060_Desc = {
    Text = "かつて優しく彼女を見つめていたお父様の目は、ろうそくの光のようだった。彼女はずっとその目が温かいものだと自分を騙していた。\nしかし、火が消えたとき、それはただの醜い蝋の塊だったことがわかる。\nその視線の温かさは遠い記憶の中に冷めていた。"
