  },
  CollectionHall_84341_Title = {
    Text = "最後の誘導"
  },
  CollectionHall_84377_LockTip = {
    Text = "期間限定イベント「お掃除奇旅：除塵手当」の掃除ツールが1000に到達するミッションを完了する必要があります"
  },
  CollectionHall_84377_Title = {
    Text = "掃除の奇旅"
  },
  CollectionHall_89341_Desc = {
    Text = "我々は帽子を脱ぎ、逝きし者たちへ、勇敢なる者たちへ、偉大なる者たちへ、そして小さき者たちへ――我々の友へ、最も深い哀悼と敬意を捧げる。"
  },
  CollectionHall_89341_LockTip = {
    Text = "調査行動 星辰篇2–18をクリアして解放"
  },
  CollectionHall_89341_Title = {Text = "黙祷"},
  CollectionHall_89342_Desc = {
    Text = "忍耐強く、注意して、色とりどりの光に目をくらまされないようにしてください。"
  },
  CollectionHall_89342_LockTip = {
    Text = "調査5-15を完了で解放"
  },
  CollectionHall_89342_Title = {
    Text = "怪しき光の帳"
  },
  CollectionHall_89343_Desc = {
    Text = "魂の奥底からの繋がりが呼び声を上げる。\n騎士は約束に応え、主あなたの元へやってくる。"
  },
  CollectionHall_89343_LockTip = {
    Text = "特務記録「血の色」を完了する"
  },
  CollectionHall_89343_Title = {
    Text = "遠方からの呼び声"
  },
  CollectionHall_89344_Desc = {
    Text = "慟哭のレコードは粘つく喉を裂き、高揚した無感情な慟哭を呼び起こす。"
  },
  CollectionHall_89344_LockTip = {
    Text = "調査星辰篇1-14を完了で解放"
  },
  CollectionHall_89344_Title = {
    Text = "慟哭のレコード"
  },
  CollectionHall_89345_Desc = {
    Text = "彼女は人間として死ぬことを選んだ。その魂の灰は、この人形の棺の中でついに眠りについた。"
  },
  CollectionHall_89345_LockTip = {
    Text = "意識潜行「歪みの核」高難度を完了する"
  },
  CollectionHall_89345_Title = {
    Text = "魂の燃えかす"
  },
  CollectionHall_89346_Desc = {
    Text = "怪物を縛る枷はすでに破壊された。殺すことも、逃れることもできない狩人が、やって来た。"
  },
  CollectionHall_89346_LockTip = {
    Text = "調査4-16を完了で解放"
  },
  CollectionHall_89346_Title = {
    Text = "次元を裂いて来たる"
  },
  CollectionHall_89347_Desc = {
    Text = "人々は競い合って殺し合うことで自らの罪を清め、汚れなき神の国へ最初に入ることができると信じている。"
  },
  CollectionHall_89347_LockTip = {
    Text = "特務記録「血の色」を完了する"
  },
  CollectionHall_89348_Desc = {
    Text = "美麗なり！豊かなり！理想郷リモリア！\n強大なり！強靭なり！神王の守護せしリモリア！\n偉大なり！偉大なり！永遠の王国リモリア！"
  },
  CollectionHall_89348_LockTip = {
    Text = "調査5-10高難度を完了で解放"
  },
  CollectionHall_89348_Title = {
    Text = "永遠の王国"
  },
  CollectionHall_89349_Desc = {
    Text = "高い地位にある者にとって、見捨てられ、裏切られるのは日常茶飯事だ。彼らの最後の光と温もりとならないように、背を向けてはいけない。"
  },
  CollectionHall_89349_LockTip = {
    Text = "調査3-10高難度を完了で解放"
  },
  CollectionHall_89349_Title = {
    Text = "見捨てられし者"
  },
  CollectionHall_89350_Desc = {
    Text = "彼女の魂はあなたの背後にある。あなた一人こそが今、唯一の城壁だ。そして運命の無力感があなたをしっかりと捕らえ、あなたはその結末を変えられない。\n彼女が黒い波に飲み込まれる、その結末を。"
  },
  CollectionHall_89350_LockTip = {
    Text = "意識潜行「歪みの核」を完了する"
  },
  CollectionHall_89350_Title = {
    Text = "孤独な救出"
  },
  CollectionHall_89351_Desc = {
    Text = "誰かが耳元で絶え間なく柔らかく囁いているのが聞こえる。唇と歯の間の呟きがサラサラと響く。\n耳を澄まし、その曖昧な言葉を聞き分けようとした時、同じサラサラという音が鼓膜の内側、頭蓋の中で響き始め、ようやく気づく――それは億万の蟲の翅が一斉に密集して共振する音だと。ザワザワ、ザワザワザワ、帰ろう、帰ろう。"
  },
  CollectionHall_89351_LockTip = {
    Text = "調査行動 星辰篇2–18をクリアして解放"
  },
  CollectionHall_89351_Title = {
    Text = "億万の蟲の声"
  },
  CollectionHall_89352_Desc = {
    Text = "人生の重要な局面には、いつも霧雨がつきまとうようだ。\n霧雨の中の思い出に別れを告げ、醸した苦い酒を心の奥底にしまい込み、手中の銀の鍵を強く握り、新たな旅に出よう。\n銀の鍵の導きがあらんことを"
  },
  CollectionHall_89352_LockTip = {
    Text = "調査星辰篇1-10高難度を完了で解放"
  },
  CollectionHall_89352_Title = {
    Text = "さようなら、しとしと降る雨"
  },
  CollectionHall_89353_Desc = {
    Text = "春の暖かい日差し、夢のような宮殿、舞い踊るドレス、笑い声に満ちた舞踏会、そして美しく優しい姫。\nこれらが騎士が守りたいすべてなのだ。"
  },
  CollectionHall_89353_LockTip = {
    Text = "意識潜行「騎士の願い」を完了する"
  },
  CollectionHall_89353_Title = {
    Text = "宮殿での春の饗宴"
  },
  CollectionHall_89354_Desc = {
    Text = "鮮血、殺戮、変革……果てしない黄砂の下に埋もれているのは、時間の河に流れる残酷でよくある歴史だ。"
  },
  CollectionHall_89354_LockTip = {
    Text = "意識潜行「蒼白の末裔」高難度を完了する"
  },
  CollectionHall_89354_Title = {
    Text = "黄砂の下"
  },
  CollectionHall_89355_Desc = {
    Text = "どう答えたらいいかわからない時は、ただ可愛らしく振る舞えばいいの、えへっ～"
  },
  CollectionHall_89355_LockTip = {
    Text = "調査3-14を完了で解放"
  },
  CollectionHall_89355_Title = {
    Text = "えへっ～"
  },
  CollectionHall_89356_Desc = {
    Text = "戦略的撤退は恥ずべきことではあるが、有用である。"
  },
  CollectionHall_89356_LockTip = {
    Text = "意識潜行「蒼白の末裔」を完了する"
  },
  CollectionHall_89356_Title = {
    Text = "迷宮からの逃亡"
  },
  CollectionHall_89357_Desc = {
    Text = "深淵で咲き誇る純白の花が、しっかりと皆の前に立ちはだかる。\n「たとえそうでも、彼女は私にとって唯一のママなんだ」\n「私のママを――返して！」"
  },
  CollectionHall_89357_LockTip = {
    Text = "調査4-12高難度を完了で解放"
  },
  CollectionHall_89357_Title = {
    Text = "悲愴な開花"
  },
  CollectionHall_89358_Desc = {
    Text = "彼女が冷たい機械になる前、生きた魂を持っていた。"
  },
  CollectionHall_89358_LockTip = {
    Text = "意識潜行「歪みの核」を完了する"
  },
  CollectionHall_89358_Title = {
    Text = "機械の心臓"
  },
  CollectionHall_89359_Desc = {
    Text = "少女は薄い服をまとい雪の上を歩き、温かい抱擁を求めている。"
  },
  CollectionHall_89359_LockTip = {
    Text = "調査3-14を完了で解放"
  },
  CollectionHall_89359_Title = {
    Text = "雪の中の少女"
  },
  CollectionHall_89360_Desc = {
    Text = "住民たちは熱心に、招待客と交流していた。"
  },
  CollectionHall_89360_LockTip = {
    Text = "調査3-14を完了で解放"
  },
  CollectionHall_89360_Title = {
    Text = "“おもてなし”の住民"
  },
  CollectionHall_89361_Desc = {
    Text = "神は、私たちを神の王国へ導くために、聖なる神母を私たちに与えてくださいました。\n「我が主」を讃えよ！"
  },
  CollectionHall_89361_LockTip = {
    Text = "調査5-15を完了で解放"
  },
  CollectionHall_89361_Title = {
    Text = "尊き神母"
  },
  CollectionHall_89362_Desc = {
    Text = "忠実で勇敢な子犬は自ら訓練計画を立てる。そして、すべての悲しみと疲労を癒すには、あなたの励ましの眼差し一つで十分だ。"
  },
  CollectionHall_89362_LockTip = {
    Text = "意識潜行「騎士の願い」を完了する"
  },
  CollectionHall_89362_Title = {
    Text = "子犬の訓練"
  },
  CollectionHall_89363_Desc = {
    Text = "その幼い騎士は、まだ長槍にも及ばない体躯ながら、姫に立てた誓いの言葉を一つ一つ守った。"
  },
  CollectionHall_89363_LockTip = {
    Text = "意識潜行「騎士の願い」を完了する"
  },
  CollectionHall_89363_Title = {
    Text = "栄光に値する"
  },
  CollectionHall_89364_Desc = {
    Text = "遥か遠くへ航海する船は、皆をどこへ連れて行くのだろうか？\n純白の女神は、高いマストに座って歌っている。\n貪欲、迷い、闘争、裏切り、彼女は見て見ぬふりをする。彼女は運命の浮き沈みを歌うことはなく、ただ、あの老船長の帰航を歌う。"
  },
  CollectionHall_89364_LockTip = {
    Text = "調査5-15を完了で解放"
  },
  CollectionHall_89364_Title = {
    Text = "深港の幽霊船"
  },
  CollectionHall_89365_Desc = {
    Text = "助けて……誰でもいい……助けて……"
  },
  CollectionHall_89365_LockTip = {
    Text = "調査3-10高難度を完了で解放"
  },
  CollectionHall_89365_Title = {
    Text = "家なき子"
  },
  CollectionHall_89366_Desc = {
    Text = "偉大な父よ、あなたの光が世界を照らしますように。"
  },
  CollectionHall_89366_LockTip = {
    Text = "特務記録「血の色」を完了する"
  },
  CollectionHall_89366_Title = {
    Text = "蒼白の聖徒"
  },
  CollectionHall_89367_Desc = {
    Text = "波が押し寄せ、金切り声が響き渡る。苦痛の記憶が心に押し寄せ、少女の精神を粉々に引き裂く。目尻から流れる黒い涙は、彼女の無言の助けを求める叫びだった。"
  },
  CollectionHall_89367_LockTip = {
    Text = "調査3-10高難度を完了で解放"
  },
  CollectionHall_89367_Title = {
    Text = "苦痛の記憶"
  },
  CollectionHall_89368_Desc = {
    Text = "彼女がいかに筆を走らせようとも、日記に残るのは黒い跡だけだった。"
  },
  CollectionHall_89368_LockTip = {
    Text = "調査4-16を完了で解放"
  },
  CollectionHall_89368_Title = {
    Text = "降らない雪"
  },
  CollectionHall_89369_Desc = {
    Text = "月の光が夜空に降り注ぎ、波は永遠にささやき、まだら模様の船はゆっくりと進む。\n霧立ち込める甲板に立ち、あなたは一人、曖昧な夜想曲を紡ぐ。"
  },
  CollectionHall_89369_LockTip = {
    Text = "調査5-15を完了で解放"
  },
  CollectionHall_89369_Title = {
    Text = "遠洋航海"
  },
  CollectionHall_89370_Desc = {
    Text = "それは一つ一つが生きた墓碑、すべての卵鞘に彼らの墓碑銘が刻まれている。\n彼らは希望に満ち、敬虔にひしめき合う墓の中へと歩んでいった。"
  },
  CollectionHall_89370_LockTip = {
    Text = "調査行動 星辰篇2–18をクリアして解放"
  },
  CollectionHall_89370_Title = {
    Text = "粘性の墓碑"
  },
  CollectionHall_89371_Desc = {
    Text = "淡い清らかな香り、きらびやかな商品。だが、水仙夫人が提示する価格を支払える者が、いったいどれほどいるだろうか？"
  },
  CollectionHall_89371_LockTip = {
    Text = "調査3-14を完了で解放"
  },
  CollectionHall_89371_Title = {
    Text = "水仙の小屋"
  },
  CollectionHall_89372_Desc = {
    Text = "温かい手が少女の頭をそっと撫で、その不安な心を慰めた。"
  },
  CollectionHall_89372_LockTip = {
    Text = "調査3-14を完了で解放"
  },
  CollectionHall_89372_Title = {
    Text = "心配しないで、私がいるから"
  },
  CollectionHall_89373_Desc = {
    Text = "時間が叫び、時間が咆哮し、時間が三度獲物となった者を追いかける。逃げようとするな、なぜなら結果はすでに定められているのだから。"
  },
  CollectionHall_89373_LockTip = {
    Text = "調査4-12高難度を完了で解放"
  },
  CollectionHall_89373_Title = {
    Text = "因果の怪物"
  },
  CollectionHall_89374_Desc = {
    Text = "審判は止まらず、必ず執行される。\n鏡から怪物が生まれ、自らの血肉を灯芯として、世界中に浄化の火を撒き散らした。"
  },
  CollectionHall_89374_LockTip = {
    Text = "特務記録「血の色」高難度を完了する"
  },
  CollectionHall_89374_Title = {
    Text = "血肉の灯火"
  },
  CollectionHall_89375_Desc = {
    Text = "立場と意志が衝突するとき、人間は往々にして自らの規範だけを固く信じる。\nほとんどの人にとって、自分が信じるものが唯一の正義なのだ。"
  },
  CollectionHall_89375_LockTip = {
    Text = "調査4-16を完了で解放"
  },
  CollectionHall_89375_Title = {
    Text = "対立する正義"
  },
  CollectionHall_89376_Desc = {
    Text = "出会いはあまりにも早く、真実はあまりにも遅すぎた。残酷な現実に引き裂かれた心は、幼い手の中で徐々に癒されていく。雪の中を追いかけ合った二人は、時を超えた狭間で、抱き合って涙を流した。"
  },
  CollectionHall_89376_LockTip = {
    Text = "調査4-16を完了で解放"
  },
  CollectionHall_89376_Title = {
    Text = "不意の再会"
  },
  CollectionHall_89377_Desc = {
    Text = "淑女として、常に優雅でなければなりません！\nもちろん、私が言いたいのは、淑女がすること、それがすべて優雅だということです！"
  },
  CollectionHall_89377_LockTip = {
    Text = "調査5-15を完了で解放"
  },
  CollectionHall_89377_Title = {
    Text = "淵海の淑女"
  },
  CollectionHall_89378_Desc = {
    Text = "暖炉の温かい火がお客様をお迎えします。ただし、夜は凶暴な犬が出没するので、外出はお控えください。"
  },
  CollectionHall_89378_LockTip = {
    Text = "調査3-14を完了で解放"
  },
  CollectionHall_89378_Title = {
    Text = "雪夜の小さな町"
  },
  CollectionHall_89379_Desc = {
    Text = "時間さえ閉じ込めるこの扉の裏には、愛しい娘を守るために母親が下した最後の決断がある。\n「愛してるわ、リリー」"
  },
  CollectionHall_89379_LockTip = {
    Text = "調査4-12高難度を完了で解放"
  },
  CollectionHall_89379_Title = {
    Text = "永遠の檻"
  },
  CollectionHall_89380_Desc = {
    Text = "追跡、逃走、凝り固まった母性、生と死を超えた抱擁。"
  },
  CollectionHall_89380_LockTip = {
    Text = "調査4-16を完了で解放"
  },
  CollectionHall_89380_Title = {
    Text = "歪んだ狂人の館"
  },
  CollectionHall_89381_Desc = {
    Text = "全能の主よ、私にふさわしい罰をお与えください。"
  },
  CollectionHall_89381_LockTip = {
    Text = "特務記録「血の色」を完了する"
  },
  CollectionHall_89381_Title = {
    Text = "盲目の聖徒"
  },
  CollectionHall_89382_Desc = {
    Text = "その時、母はページの端をめくりながら、子供に童話を聞かせていた。\n午後の温かさが時間を超え、この狭い空間と時間に優しく流れていく。"
  },
  CollectionHall_89382_LockTip = {
    Text = "調査4-16を完了で解放"
  },
  CollectionHall_89382_Title = {
    Text = "午後の童話"
  },
  CollectionHall_89383_Desc = {
    Text = "どうすれば自分を欺けるのか、消えた燃え殻の中で命がまだ続いていると幻想できるのか。\n彼女は漆黒の蛹と粘つく赤の中で眠り、夢の中で遥かな星空を見つめる。\n「あまりにも冷たい、でもかつての温もりはどこへ行ったの？」"
  },
  CollectionHall_89383_LockTip = {
    Text = "調査行動 星辰篇2–18をクリアして解放"
  },
  CollectionHall_89383_Title = {
    Text = "灰燼の臆想"
  },
  CollectionHall_89384_Desc = {
    Text = "高らかに歌え、高らかに歌え！\n溶融した機械の奏鳴を宇宙に響かせ、永遠の闇という名の終末を讃えよ！"
  },
  CollectionHall_89384_LockTip = {
    Text = "調査星辰篇1-10高難度を完了で解放"
  },
  CollectionHall_89384_Title = {
    Text = "溶融する終末賛歌"
  },
  CollectionHall_89385_Desc = {
    Text = "血肉が飛び散り、鋭い刃が狂ったように舞う。怪物は理解不能な言葉で高らかに歌う。荒れ狂う脳内には一つの思考だけが残っている――彼女を捕らえろ、どんな犠牲を払っても、彼女を捕らえろ。"
  },
  CollectionHall_89385_LockTip = {
    Text = "調査3-10高難度を完了で解放"
  },
  CollectionHall_89385_Title = {
    Text = "狂気の執念"
  },
  CollectionHall_89386_Desc = {
    Text = "見よ、深紅の月が昇った、すべての罪人は浄化されるだろう。"
  },
  CollectionHall_89386_LockTip = {
