  CollectionHall_89393_LockTip = {
    Text = "調査3-14を完了で解放"
  },
  CollectionHall_89394_Desc = {
    Text = "あなたが戦っているのは、無数の心と体を一つにした魂だ。彼らはあなたを拒み、彼らはあなたを招く。無意味な自我を捨てよ、無知な脳を、永遠に孤独にならない集合体に加えよ。"
