  },
  CollectionHall_89395_Title = {
    Text = "無私の優しさ"
  },
  CollectionHall_89396_Desc = {
    Text = "私の手を掴んで、記憶の中の決して色褪せない花を受け取って。\n振り返らずに進もう、私たちはきっとたどり着くから、あの銀色に輝く扉に。"
