  CollectionHall_89397_LockTip = {
    Text = "調査星辰篇1-14を完了で解放"
  },
  CollectionHall_89397_Title = {
    Text = "脳髄製造"
  },
  CollectionHall_89398_Desc = {
    Text = "遥かなる空の黒い終末は、あたかも天空の穴のようだ。\nそれは未だ明かされていない場所からのトーテムだ。"
