  },
  CollectionHall_89398_Title = {
    Text = "黒い太陽のトーテム"
  },
  CollectionHall_89399_Desc = {
    Text = "灰色の霧が黒い太陽を覆い、粉塵が口や鼻を満たす。\n口を開けて呼吸してはならない――希望はすでにその前に埋葬されたのだ。"
  },
  CollectionHall_89399_LockTip = {
    Text = "調査星辰篇1-14を完了で解放"
  },
  CollectionHall_89399_Title = {
    Text = "窒息する煙塵"
  },
  CollectionHall_89400_Desc = {
    Text = "頭蓋の中を開き、万の脳缶と共鳴せよ。\n答えはそこに隠されているかもしれません。"
  },
  CollectionHall_89400_LockTip = {
    Text = "調査星辰篇1-10高難度を完了で解放"
  },
  CollectionHall_89400_Title = {
    Text = "頭蓋共鳴"
  },
  CollectionHall_89401_Desc = {
    Text = "冬の日、魔女、子供たち、そして止まない雪。"
  },
  CollectionHall_89401_LockTip = {
    Text = "調査3-14を完了で解放"
  },
  CollectionHall_89401_Title = {
    Text = "雪降る影を呑む町"
  },
  CollectionHall_89402_Desc = {
    Text = "奇妙なささやきが空中に響き渡り、黒い粘液が供物を飲み込む。古き日の存在が、神の帰還を待ち望んでいる。"
  },
  CollectionHall_89402_LockTip = {
    Text = "調査4-16を完了で解放"
  },
  CollectionHall_89402_Title = {
    Text = "極地の祭壇"
  },
  CollectionHall_89403_Desc = {
    Text = "光は闇を払い、すべての子供たちを平等に照らします。\nそれは青白く、弱々しいですが、この上なく暖かく、力に満ちています。\n我が子よ、この微かな光が、あなたの苦難を消し去り、あなたの心を癒しますように。"
  },
  CollectionHall_89403_LockTip = {
    Text = "特務記録「血の色」高難度を完了する"
  },
  CollectionHall_89403_Title = {
    Text = "救済の白き炎"
  },
  CollectionHall_89404_Desc = {
    Text = "列車は突然止まり、双子は血の匂いを追ってやって来た。"
  },
  CollectionHall_89404_LockTip = {
    Text = "調査3-14を完了で解放"
  },
  CollectionHall_89404_Title = {
    Text = "急ブレーキ"
  },
  CollectionHall_89405_Desc = {
    Text = "王よ、私は予言に従い一万年待ち続けてきましたが、なぜ未来はまだこんなに遠いのでしょうか。\n私は祈り続けるべきでしたが、どうかお許しください。もうこれ以上待つことはできません。"
  },
  CollectionHall_89405_LockTip = {
    Text = "調査5-15を完了で解放"
  },
  CollectionHall_89405_Title = {
    Text = "億万の祈り"
  },
  CollectionHall_89406_Desc = {
    Text = "卑しき盗人が王の力を盗み、偉大な儀式を妨害しようとしました。\n不敬なる贋作者よ、死をもって罪を償え！"
  },
  CollectionHall_89406_LockTip = {
    Text = "調査5-10高難度を完了で解放"
  },
  CollectionHall_89406_Title = {
    Text = "冒涜的な誓い"
  },
  CollectionHall_89407_Desc = {
    Text = "日の光すら遮る濃密な霧の中、我はただ独り未知の道へと踏み出す。\nその霧の中から塵土、鮮血、炎を掬い上げ、孤独な、茫然とした、憂いに満ちた涙を鎮める。\n我はもう恐れない。永遠の太陽がとうに我が心の中に高く懸かっているのだから。"
  },
  CollectionHall_89407_LockTip = {
    Text = "調査行動 星辰篇2–18をクリアして解放"
  },
  CollectionHall_89407_Title = {
    Text = "我は行き着く"
  },
  CollectionHall_89408_Desc = {
    Text = "子供たちはこう聞いています。太陽を肉眼で直接見てはいけない。\nたとえ今、彼がすでに陥落していようとも。"
  },
  CollectionHall_89408_LockTip = {
    Text = "調査星辰篇1-14を完了で解放"
  },
  CollectionHall_89408_Title = {
    Text = "暗黒の太陽の復活"
  },
  CollectionHall_89409_Desc = {
    Text = "クレメンタイン医師のプライベート神経療養院へようこそ。医師の導きに従い、心のすべての苦痛を解き放ち、最終的な治癒へと向かいましょう。"
  },
  CollectionHall_89409_LockTip = {
    Text = "調査行動 星辰篇2–18をクリアして解放"
  },
  CollectionHall_89409_Title = {
    Text = "迷幻蟲巣の夢"
  },
  CollectionHall_89410_Desc = {
    Text = "かつての輝きは過ぎ去り、記憶の中には廃墟だけが残っている。"
  },
  CollectionHall_89410_LockTip = {
    Text = "意識潜行「蒼白の末裔」を完了する"
  },
  CollectionHall_89410_Title = {
    Text = "過ぎし日の残照"
  },
  CollectionHall_89411_Desc = {
    Text = "あなたは深淵の中に沈み、あなたのポケットから、彼女の最後の伝言が飛び出した。こうしてあなたは果てしない闇の中で、一瞬の光明を見た。"
  },
  CollectionHall_89411_LockTip = {
    Text = "調査行動·困難 星辰篇2–12をクリアして解放"
  },
  CollectionHall_89411_Title = {Text = "羽化"},
  CollectionHall_89412_Desc = {
    Text = "かつてあなたの前にいた者は、今はあなたの後ろにいる。\nあなたはずっと信じている、全力で走り抜けた先の、時空の果てで待っているのは、きっとあの馴染み深い、温かな手だと。"
  },
  CollectionHall_89412_LockTip = {
    Text = "調査行動·困難 星辰篇2–12をクリアして解放"
  },
  CollectionHall_89412_Title = {
    Text = "変わらない選択"
  },
  CollectionHall_89413_Desc = {
    Text = "地下鉄で襲われるのは不運ではあったが、少女の好奇心を満たす余興としてはちょうどよかった。"
  },
  CollectionHall_89413_LockTip = {
    Text = "調査3-14を完了で解放"
  },
  CollectionHall_89413_Title = {
    Text = "トンネルアドベンチャー"
  },
  CollectionHall_89414_Desc = {
    Text = "英雄と姫は夜空の下を駆け抜け、足元の砂利が生の喜びを物語る。千年もの間、閉ざされていたその心も、流星が流れ去ると共に、ゆっくりと鼓動を始めた。"
  },
  CollectionHall_89414_LockTip = {
    Text = "意識潜行「蒼白の末裔」高難度を完了する"
  },
  CollectionHall_89414_Title = {
    Text = "二人の流星"
  },
  CollectionHall_89415_Desc = {
    Text = "言葉は要らない。ここに来れば、最も誠実な助けが得られる。\n微笑む導き手はすでにあなたへ手を差し伸べている。彼女はあなた自身さえも見通せなかった、心の密林の奥深くへとあなたを導くだろう。"
  },
  CollectionHall_89415_LockTip = {
    Text = "調査行動 星辰篇2–18をクリアして解放"
  },
  CollectionHall_89415_Title = {
    Text = "心の密林"
  },
  CollectionHall_89416_Desc = {
    Text = "谷間の夜明けの光が迷宮を照らした時、千の足と千の子を持ち千年も眠っていた姫は、最後の信徒を迎えた。"
  },
  CollectionHall_89416_LockTip = {
    Text = "意識潜行「蒼白の末裔」を完了する"
  },
  CollectionHall_89416_Title = {
    Text = "カンブリアの暁"
  },
  CollectionHall_89417_Desc = {
    Text = "天才の脳回路はいつも少しばかり入り組んでいて、曲がりくねって、人と違う。だが、それこそが彼女の可愛らしいところじゃないか？"
  },
  CollectionHall_89417_LockTip = {
    Text = "意識潜行「歪みの核」を完了する"
  },
  CollectionHall_89417_Title = {
    Text = "天才の悩み"
  },
  CollectionHall_89418_Desc = {
    Text = "私とゲームをしないか？大丈夫、そんなに危険じゃない。ただ、この退屈な時間を潰すためだ。"
  },
  CollectionHall_89418_LockTip = {
    Text = "意識潜行「蒼白の末裔」を完了する"
  },
  CollectionHall_89418_Title = {
    Text = "なぞなぞゲーム"
  },
  CollectionHall_89419_Desc = {
    Text = "幻光の潮が天体の引力によって帳を織りなし、海を渡る怪しきものが波に乗ってやって来る。"
  },
  CollectionHall_89419_LockTip = {
    Text = "調査5-15を完了で解放"
  },
  CollectionHall_89419_Title = {
    Text = "幻海の潮流"
  },
  CollectionHall_89420_Desc = {
    Text = "王は至高であり、無限の権威を持ち、王は輝きの座に遥かに座し、孤独に自らの王国を見下ろす。"
  },
  CollectionHall_89420_LockTip = {
    Text = "調査5-15を完了で解放"
  },
  CollectionHall_89420_Title = {
    Text = "深淵に眠る王"
  },
  CollectionHall_89706_Desc = {
    Text = "<Title:紹介>\n孤児、出自不明、自分の記憶が始まった時からクルーに育てられ、船の上で生活している。\nそんな経験から、コーパサントは幼い頃から海に対する渇望と好奇心に満ちていた。\n成長した彼女は、当然のように海や船に関連する職業——パイロットを選んだ。\nこれ以降、海を愛する少女は永遠に海を漂流し、星々に囲まれながら船の方向を指し示す。\n彼女は海の中で、船の上で「生まれた」。\n彼女はまた、海の中で、船の上で「死ぬ」ことを恐れない。\nこれが彼女の生活である。"
  },
  CollectionHall_89706_LockTip = {
    Text = "「コーパサント」を召喚すると解放"
  },
  CollectionHall_89706_Title = {
    Text = "コーパサント"
  },
  CollectionHall_89968_Desc = {
    Text = "殺戮、憎悪、狂気、そして苦痛。戦場でこれらが尽きることはない。怪物のテーブルで命を賭ける時、どれほど深紅の渦が巻き起こるか、覚悟すべきだったろう。"
  },
  CollectionHall_89968_LockTip = {
    Text = "意識潜行「血と砂」を完了する"
  },
  CollectionHall_89968_Title = {
    Text = "深紅の渦"
  },
  CollectionHall_89969_Desc = {
    Text = "伝説では、航海士は死後、マストの上で青白い閃光となり、船の航行を導き続けるという。\nでは、彼女がマストの最上部で自らの命を燃やした時、あの希望の帰路を見ることができたのだろうか？"
  },
  CollectionHall_89969_LockTip = {
    Text = "意識潜行「最後の導航」をクリア"
  },
  CollectionHall_89969_Title = {
    Text = "セントエルモの火"
  },
  CollectionHall_89970_Desc = {
    Text = "生まれながらの宿命は、憎悪と殺戮、果てしない争いに満ちていた。\n温かく柔らかな幻影をすべて捨て、武器を手に取ったその時、運命の凱歌はすでに彼女のために奏でられていた。\n彼女は戦士となる運命にあった。敵の血で憎悪を洗い流し、栄光とは言えずとも、恐れを知らず、後悔のない一生を送った。"
  },
  CollectionHall_89970_LockTip = {
    Text = "特務記録「雪山への帰還」を完了"
  },
  CollectionHall_89970_Title = {
    Text = "憎悪を血で洗い流す"
  },
  CollectionHall_89971_Desc = {
    Text = "血のように赤い夕陽の下には、血に浸された黄砂が広がる。\n最強の戦士が夜に沈みゆく戦場で立ち尽くし、過ぎし日の黄金の炎と栄光を思い出す。\n無数の叫ぶハゲワシが舞い上がり、最後の陽光を遮る。東方遠征の際、砂漠は彼とともに埋葬された死者の魂で満たされた。"
  },
  CollectionHall_89971_LockTip = {
    Text = "意識潜行「血と砂」高難度を完了する"
  },
  CollectionHall_89971_Title = {
    Text = "血に染まった赤い太陽"
  },
  CollectionHall_89972_Desc = {
    Text = "もしこの世界が闇に沈むならば、我は最後の炬火となろう。\nもし人々の中にもはや正義がないならば、我は最も弱き者のために声を上げよう。"
  },
  CollectionHall_89972_LockTip = {
    Text = "意識潜行「最後の導航」をクリア"
  },
  CollectionHall_89972_Title = {
    Text = "長夜の炬火"
  },
  CollectionHall_89973_Desc = {
    Text = "それは彼女の宿命の戦い、それは向かわねばならない戦場。\n臆病も、ためらいも、恐怖も、すべて過去と共に捨て去った。\n彼女は決して後悔しない。すでにこの生涯の戦いの真の意味を、理解しているからだ。\n彼女は孤独ではない。手中の剣に映るのは——\nもう一人の自分の、傲慢な顔だったのだから。"
  },
  CollectionHall_89973_LockTip = {
    Text = "特務記録「雪山への帰還」高難度を完了"
  },
  CollectionHall_89973_Title = {
    Text = "山々に問いかける"
  },
  CollectionHall_89974_Desc = {
    Text = "えいほー、えいほー、錨を上げろ、帆を張れ、最後の纜を解け。\n我らが航海士はマストに登り、鮮やかな旗が高々と掲げられた。\n出航だ、出航だ、彼女が指し示す方角へ、我らはいざ出航する！"
  },
  CollectionHall_89974_LockTip = {
    Text = "意識潜行「最後の導航」をクリア"
  },
  CollectionHall_89974_Title = {
    Text = "航海手記"
  },
  CollectionHall_89975_Desc = {
    Text = "彼女は出航のたびに、最新の遺書を用意していた。\n代々受け継がれてきたあの歌は、夢の中の子守唄のように、彼女の魂を優しく抱きしめる。\n鮮やかな旗が風にはためく中、彼女の肉体は崩れ、朽ち、深海に沈むかもしれない。だが彼女の魂は必ずや船の上に立ち続け、星と海に向けて永遠の光を放つだろう。"
  },
  CollectionHall_89975_LockTip = {
    Text = "意識潜行「最後の導航」をクリア"
  },
  CollectionHall_89975_Title = {
    Text = "航海士の挽歌"
  },
  CollectionHall_89976_Desc = {
    Text = "クシ砂漠では、砂嵐が絶えず吹き荒れる。舞い散る砂は生きる者の口や鼻を満たし、名もなき屍を砂に埋める。\nただ、血肉を求める野獣だけが、風の中で甘美な饗宴の匂いを嗅ぎ続ける。"
  },
  CollectionHall_89976_LockTip = {
    Text = "意識潜行「血と砂」を完了する"
  },
  CollectionHall_89976_Title = {
    Text = "黄砂と野獣"
  },
  CollectionHall_89977_Desc = {
    Text = "砂漠の太陽は、他の場所の太陽とは違う。それは青白く、刺すように眩しく、そして酷烈で、決して穏やかではありません。野獣には、あなたが口にする春が想像できないから、代わりに彼のために、本当の太陽を見に来てください。"
  },
  CollectionHall_89977_LockTip = {
    Text = "意識潜行「血と砂」を完了する"
  },
  CollectionHall_89977_Title = {
    Text = "無還の血と砂"
  },
  CollectionHall_89978_Desc = {
    Text = "大雪が際限なく、しんしんと降りしきり、戦士の髪を霜のように白く染めた。\n今この時、彼女の一生の記憶が流れ出す。人の心の奥底を通り抜け、雄大な山々へと向かった。\n裏切られ、見捨てられ、そして守り抜いたもの。すべての苦痛と怒りは、繰り返される戦いに過ぎなかった。\n人との戦い、山との戦い、己との戦い。\n彼女は自らの導き手と見知らぬようで馴染み深い新しい仲間を見つめ、不慣れな笑顔を浮かべた。\n彼女はいつか凱旋するかもしれない、あるいは永遠に戦場に倒れるかもしれない。だが、天国に昇ろうと地獄に堕ちようと、その瞬間でさえ、彼女は手中の刃を手放すことはない。\nこれらすべてを二度と失わぬため、今回彼女は、復讐に先立ち、守護という名の剣を掲げ、ただ一人、己の戦場へと向かうことを選んだ。"
  },
  CollectionHall_89978_LockTip = {
    Text = "特務記録「雪山への帰還」を完了"
  },
  CollectionHall_89978_Title = {
    Text = "二度と失わない明日のために"
  },
  CollectionHall_89998_LockTip = {
    Text = "期間限定イベント「神国を窺う影：異動海潮」のいずれかのステージをクリアする必要があります"
  },
  CollectionHall_89998_Title = {
    Text = "神国を窺う影：異動海潮"
  },
  CollectionHall_89999_LockTip = {
    Text = "期間限定キャラクターイベント「鏡の囚人：青空を越えて」の任意のステージをクリアすると開放"
  },
  CollectionHall_89999_Title = {
    Text = "鏡の囚人：青空を越えて"
  },
  CollectionHall_90245_LockTip = {
    Text = "異夢視界「天の果て·上」のいずれかのステージをクリアで解放"
  },
  CollectionHall_90245_Title = {
    Text = "鳥がまだ墜ちぬ時"
  },
  CollectionHall_90415_Title = {
    Text = "空の彼方・上"
  },
  CollectionHall_90416_Desc = {
    Text = "<Title:概要>\n提灯教会の降神の儀式のために育てられた一連の実験体の一つで、双子として幸運にも生まれたため、ゴミ捨て場に捨てられる運命を免れた。\n弟のポリュクスと共に幼少期から聖子と称えられ、厳格な訓練を受け、日々光の持ち主に関する神学を叩き込まれ、唯一外の世界に関する情報に触れたのは、信者によって供養された美しく重厚な手書きの本だけだった。\n少年時代、弟が教会に残酷な改造の儀式を施された後、二人は自由を求めて共に逃げる決意をしたが、すぐに捕まってしまった。\n彼は「罪の池」と呼ばれる融蝕の水槽に浸され、「罪悪療法」で傷を癒され、長い苦痛を経験した。\n最終的に、ユリエット以外の人々に忘れ去られ、ポリュクスとの関係もぎこちなくなった。\nそれ以来、潜伏し、表面上は教会に従順を装いながらも、心の中では再び弟を連れて逃げるという執念を決して忘れず、自由を取り戻す機会を待ち続けている。"
  },
  CollectionHall_90416_LockTip = {
    Text = "「カストル」を召喚すると解放"
  },
  CollectionHall_90416_Title = {
    Text = "カストル"
  },
  CollectionHall_94552_LockTip = {
    Text = "期間限定キャラクターイベント「偉大なる征服：神聖な狩り」の任意のステージをクリアすると開放"
  },
  CollectionHall_94552_Title = {
    Text = "偉大なる征服：神聖な狩り"
  },
  CollectionHall_94553_Desc = {
    Text = "<Title:紹介>\n提灯教会が降神の儀式のために育成した人造双子の実験体。実験失敗と判定され、残酷に廃棄されようとしていたその時、兄の血肉から分裂して誕生した。\nそのような生への執着は幸運などではなく、二人の運命を短い悲劇から、より長い悲劇へと書き換えたに過ぎなかった。\nおそらく双子の神秘に由来するのか、彼と兄の肌の色も性格もまるで正反対だった。双子の中でより活発で利発な方として、常に規律に反する悪戯を繰り返していた。まるで平凡な家庭のやんちゃな少年のように――神格の器として選ばれ、定期的に苦痛と血にまみれた「神聖改造」の儀式を受けるようになるまでは。\n苦痛に満ちた絶望的な運命に耐えきれず、彼の懇願と策略のもと、兄弟二人は暗号を使って数年にわたり計画を練り、ついに幾重もの障害を突破して脱出に成功した。\nしかし喜びも束の間、教会の追手に捕らえられ、リエットの命令により自由の翼をもがれ、極端な洗脳を施された結果、最終的に兄の存在を完全に忘れ去り、聖子として人々に崇められる感覚を享受するようになった。\n二度目の脱出の後、兄の死と降神の儀式の作用によって記憶を取り戻し、憎悪と怒りがあの「聖心」に火を灯し、提灯教会への対抗を人生の新たな目標とするに至った。"
  },
  CollectionHall_94553_LockTip = {
    Text = "異夢視界「空の彼方・下」クリアで解放"
  },
  CollectionHall_94553_Title = {
    Text = "ポリュクス"
  },
  CollectionHall_95436_Desc = {
    Text = "飛べ、飛べ、鳥はその翼で重力に抗い、ひたすら上昇し、上昇し、幾重もの乱気流と渦を突き抜け、より高い場所へと飛んでいく。\nしかし彼は知らなかった。その足にはずっと見えない糸が結ばれていたことを。彼はおそらく、真の飛鳥になったことなど一度もなく、たとえ飛んでいても、哀れな凧に過ぎなかったのだ。\n今、凧の糸が引き絞られた。"
  },
  CollectionHall_95436_LockTip = {
    Text = "異夢視界「天の果て·上」をクリア"
  },
  CollectionHall_95436_Title = {Text = "凧"},
  CollectionHall_95437_Desc = {
    Text = "あなたはその顔を見た、優しく、静かで、美しい顔。\nそれはすぐに記憶から消えるが、長い夜の雨が終わった後の朝の柔らかな光の色をあなたは覚えている。"
  },
  CollectionHall_95437_LockTip = {
    Text = "特務記録「雨の町に潜む影」完了"
  },
  CollectionHall_95437_Title = {
    Text = "雨幕の奥で"
  },
  CollectionHall_95438_Desc = {
    Text = "猫になりたい。\n無邪気な猫になりたい。\n愛する人と一緒にいて、毎日彼女のそばで日向ぼっこをする。\nこれは彼女の心の中の小さな美しい夢。\nしかし夢というものは、いつも脆く壊れやすいものだ。"
  },
  CollectionHall_95438_LockTip = {
    Text = "特務記録「静かな分裂」を完了"
  },
  CollectionHall_95438_Title = {
    Text = "猫の願い"
  },
  CollectionHall_95439_Desc = {
    Text = "たとえ世界が灰となり、すべてが融蝕液に染まっても、無邪気なクラゲは永遠に自分の夢に浸ることができる。\nそこでは、すべてがはじまりのまま。\n笑い声だけ。\n喜びだけ。"
  },
  CollectionHall_95439_LockTip = {
    Text = "意識潜行「いつも通り」高難度を完了する"
  },
  CollectionHall_95439_Title = {
    Text = "混沌なる爛漫への沈溺"
  },
  CollectionHall_95440_Desc = {
    Text = "ロンディニウムの冬はあまり雪が降らず、雪が降るたびに子供たちは興奮して狂喜する。\nあなたは優しい長い夢から目覚め、手を窓の外に伸ばす。雪の結晶が手のひらに落ち、温もりの中で甘んじて溶ける。\n舞い降りる雪の結晶は、空の短い旅を経て、大地へ、暗い川へ、すべての水滴の故郷と輪廻へと還っていく。\n今年の初雪の中で、また一人の彼女も彼女たちの家に帰った。\nおやすみ、雪。\nおやすみ、「24」。"
  },
  CollectionHall_95440_LockTip = {
    Text = "特務記録「静かな分裂」を完了"
  },
  CollectionHall_95440_Title = {
    Text = "おやすみ、雪"
  },
  CollectionHall_95441_Desc = {
    Text = "白い珊瑚が枝を伸ばし、純白の宮殿を形づくる。\n奇妙な柱の間を、色とりどりの魚たちが自在に行き交う。\n体は沈み、魂は漂う。\nあなたは自ら息を手放し、彼女と共に沈み、沈み、白い夢に溺れる。\nそれは海の奇跡、温かい青の故郷。"
  },
  CollectionHall_95441_LockTip = {
    Text = "意識潜行「歌のような彫刻」を完了する"
  },
  CollectionHall_95441_Title = {
    Text = "純白の宮殿"
  },
  CollectionHall_95442_Desc = {
    Text = "ポッポー、小さな列車が出発！\nさあ、友だちみんなを連れて、苦しみのない、永遠に楽しい童話の王国へ行こう。"
  },
  CollectionHall_95442_LockTip = {
    Text = "意識潜行「いつも通り」を完了する"
  },
  CollectionHall_95442_Title = {
    Text = "無邪気な夢"
  },
  CollectionHall_95443_Desc = {
    Text = "彼女は殺人者か？彼女は久しぶりに再会した恋人のようにも見える。\n雨水、枯葉、そして幻惑的な花の香り、あなたは鼻を動かし、その湿った香りから血の匂いを嗅ぎ取ろうとするが、何も感じない。\n彼女は説明する気もなく、ぼんやりとした霧の中で、あなたは彼女の灰色の夢に落ちる。"
  },
  CollectionHall_95443_LockTip = {
    Text = "特務記録「雨の町に潜む影」完了"
  },
  CollectionHall_95443_Title = {Text = "容疑者"},
  CollectionHall_95444_Desc = {
    Text = "彼女も同じ飢えと渇きを経験した。\n無知で野蛮、そして孤独。\n彼女は幸運だった。\n長い放浪を終え、一生噛みしめる温かい思い出を手に入れた。\n今、彼女は仲間の手を取り、この彷徨う魂を静かな夢へと送り出す。"
  },
  CollectionHall_95444_LockTip = {
    Text = "特務記録「雨の町に潜む影」高難度を完了"
  },
  CollectionHall_95444_Title = {Text = "獣の夢"},
  CollectionHall_95445_Desc = {
    Text = "私の鋭い刃が、私の心臓を突き刺す。\n無情な運命、苦しい生活の前で、私はなんと小さく、弱く、無力なのか。\n私は何をもって私であるのか？\n私は、私でありきれているのか？\n私自身からの問いに、私は答えることができない。"
  },
  CollectionHall_95445_LockTip = {
    Text = "特務記録「静かな分裂」を完了"
  },
  CollectionHall_95445_Title = {
    Text = "私に問う"
  },
  CollectionHall_95446_Desc = {
    Text = "あら？あなた、さっきと違う感じがするわね？\n目が輝いている？動きが活発になった？それとも、この平凡な体の中で、魂の持ち主が変わったのかしら？"
  },
  CollectionHall_95446_LockTip = {
    Text = "意識潜行「歌のような彫刻」を完了する"
  },
  CollectionHall_95446_Title = {
    Text = "魂の転移"
  },
  CollectionHall_95447_Desc = {
    Text = "雪が降ろうと、雨が降ろうと、晴れようと、曇ろうと、今日もまた、川は静かに流れている。"
  },
  CollectionHall_95447_LockTip = {
    Text = "特務記録「静かな分裂」を完了"
  },
  CollectionHall_95447_Title = {
    Text = "静かな川"
  },
  CollectionHall_95448_Desc = {
    Text = "潮が押し寄せ、頭蓋骨が叫ぶ。\n無数の目があなたを見つめ、無数の口があなたを叱責する。\nそれらはあなたを飲み込み、あなたを呑み込もうとしている。\n恐怖で目を閉じ、再び開けると、それらはあなたのすぐそばにいる。"
  },
  CollectionHall_95448_LockTip = {
    Text = "特務記録「雨の町に潜む影」完了"
  },
  CollectionHall_95448_Title = {
    Text = "頭蓋骨の海"
  },
  CollectionHall_95449_Desc = {
    Text = "彼女は約束した、必ずあなたを一緒に家に帰ろうと。\n——永遠の姿のまま、静かな、奇跡と美の故郷へ。"
  },
  CollectionHall_95449_LockTip = {
    Text = "意識潜行「歌のような彫刻」を完了する"
  },
  CollectionHall_95449_Title = {
    Text = "石化の芸術"
  },
  CollectionHall_95450_Desc = {
    Text = "あの高貴な客人はかつて、希望に満ちたカストルの背中を見つめ、月光の下で宿命の予言を静かに呟いた。「彼は歩み出すだろう、嵐の中で必死にもがくだろう。彼を高く飛ばせたものが、必ずや彼を墜落させる。」"
  },
  CollectionHall_95450_LockTip = {
    Text = "異夢視界「天の果て·上」をクリア"
  },
  CollectionHall_95450_Title = {
    Text = "嵐の中で"
  },
  CollectionHall_95451_Desc = {
    Text = "美に生まれ、美に死す。\n彼女は天才、狂人、悪魔、冷酷な処刑人であり、あなたの優しい家族でもある。\n彼女は熱い愛で、あなたを完璧な作品に仕立てる。\n彼女は君を抱きしめ、冷たい手を引く。彼女はあなたを連れて、共に芸術の故郷へ帰るのだ。"
  },
  CollectionHall_95451_LockTip = {
    Text = "意識潜行「歌のような彫刻」高難度を完了する"
  },
  CollectionHall_95451_Title = {Text = "美の死"},
  CollectionHall_95452_Desc = {
    Text = "大海は私の呼び声を聞き、あなたを私のもとに送ってくれた。\nこうして私たちは、語り合い、戯れ、笑い騒ぎ、世界でいちばんの友だちになることを運命づけられた。\nこの融蝕に満ちた死寂の街で。"
  },
  CollectionHall_95452_LockTip = {
    Text = "意識潜行「いつも通り」を完了する"
  },
  CollectionHall_95452_Title = {
    Text = "私の友だちになって"
  },
  CollectionHall_95453_Desc = {
    Text = "帰っておいで。\n勇敢な、臆病な、賢い、愚かな、強い、弱い私たち。\nすべての楽しい、悲しい、腹立たしい、苦しい、疲れた心を溶かそう。\n私たちは一緒にいる。\n彼女たちは永遠に一緒にいる。"
  },
  CollectionHall_95453_LockTip = {
    Text = "特務記録「静かな分裂」高難度を完了"
  },
  CollectionHall_95453_Title = {
    Text = "彼女に帰る"
  },
  CollectionHall_95454_Desc = {
    Text = "魂に生じた空虚と裂け目を満たせるのは、無垢な童話だけ。\nいつの日か彼女は苦痛に別れを告げ、童話の中の楽しい「故郷」に還っていく。"
  },
  CollectionHall_95454_LockTip = {
    Text = "意識潜行「いつも通り」を完了する"
  },
  CollectionHall_95454_Title = {
    Text = "無垢な恐怖の童話"
  },
  CollectionHall_95455_Desc = {
    Text = "闇が潜む、奥深く狭い路地は、いつも多くの運命の転換点を抱えている。再会、口論、決裂、さらには暴力、いじめ、殺人。\n幸いなことに、今日の物語では後半の血生臭い場面は起こらなかった。だが、前者がもたらすものこそが真の悲劇ではないと、誰が言えるだろうか？"
  },
  CollectionHall_95455_LockTip = {
    Text = "異夢視界「天の果て·上」をクリア"
  },
  CollectionHall_95455_Title = {Text = "裏路地"},
  CollectionHall_95469_LockTip = {
    Text = "期間限定イベント「黒き太陽と永遠の夏：真夏の狂宴」で1日目の報酬を受け取る"
  },
  CollectionHall_95469_Title = {
    Text = "黒き太陽と永遠の夏"
  },
  CollectionHall_95981_LockTip = {
    Text = "期間限定キャラクターイベント「死霊の美学：魂の饗宴」の任意のステージをクリアすると開放"
  },
  CollectionHall_95981_Title = {
    Text = "死霊の美学：魂の饗宴"
  },
  CollectionHall_95982_LockTip = {
    Text = "調査行動·星辰篇3-11をクリアで解放"
  },
  CollectionHall_95982_Title = {
