  },
  CollectionHall_96314_Title = {Text = "餍饗"},
  CollectionHall_96790_LockTip = {
    Text = "調査星辰篇3-1クリアで解放"
  },
  CollectionHall_96790_Title = {
    Text = "王邸の夜宴"
  },
  CollectionHall_97150_LockTip = {
    Text = "期間限定キャラクターイベント「キャンバスの闇：異界画巻」の任意のステージをクリアすると開放"
  },
  CollectionHall_97150_Title = {
    Text = "キャンバスの闇：異界図巻"
  },
  CollectionHall_97158_LockTip = {
    Text = "期間限定キャラクターイベント「降り注ぐ幾千の光：灰燼の追跡」の任意のステージをクリアすると開放"
  },
  CollectionHall_97158_Title = {
    Text = "降り注ぐ幾千の光：灰燼の追跡"
  },
  CollectionHall_97208_LockTip = {
    Text = "意識潜游「畸世絵」のいずれかのステージをクリアして解放"
  },
  CollectionHall_97208_Title = {
    Text = "真の芸術"
  },
  CollectionHall_97736_LockTip = {
    Text = "期間限定キャラクターイベント「神誕の儀：創生の七日間」の任意のステージをクリアすると開放"
  },
  CollectionHall_97736_Title = {
    Text = "神誕の儀：創生の七日間"
  },
  CollectionHall_97896_LockTip = {
    Text = "期間限定キャラクターイベント「すべてがいつも通りなら：日差しの下で」の任意のステージをクリアすると開放"
  },
  CollectionHall_97896_Title = {
    Text = "すべてがいつも通りなら"
  },
  CollectionHall_98502_LockTip = {
    Text = "意識潜游「不朽の極昼」のいずれかのステージをクリアで解放"
  },
  CollectionHall_98502_Title = {
    Text = "永燃不尽の追猟"
  },
  CollectionHall_98636_Desc = {
    Text = "冒涜者が幽き蒼の津波を巻き起こし、華奢な王はただ一人、千メートルの巨浪に立ち向かう。\n風に髪がたなびき、その骨と血こそが荘厳なる宣言。軽蔑の微笑みの中で、彼は己もまた死と月に捧げた。\nその瞬間、海全体が凝結し、逆さの氷河が満月の下で静止する。すべてが静寂に帰し、すべての安寧が彼の国に戻った。"
  },
  CollectionHall_98636_LockTip = {
    Text = "調査行動·困難 星辰篇3-10クリアで解放"
  },
  CollectionHall_98636_Title = {
    Text = "満月の祭礼"
  },
  CollectionHall_98637_Desc = {
    Text = "死者を調理すること、それは荘厳なる芸術。\n彼は刀と鍋返しで果たされなかった遺言を問い、彼は水と火で最後の遺願を叶える。\n一つ一つの堪え難い、苦しい、酸い記憶は、すべて輝かしく芳しい作品となり、人々に味わい珍蔵される。"
  },
  CollectionHall_98637_LockTip = {
    Text = "調査行動 星辰篇3–11をクリアして解放"
  },
  CollectionHall_98637_Title = {
    Text = "食卓の主"
  },
  CollectionHall_98638_Desc = {
    Text = "子供は泣きわめき、叫び、理不尽に暴れる。彼は宇宙の中心であり、この地のあらゆる法そのもの。\n彼の目が届くすべてのものは、彼を中心に巡り、従い、捧げられねばならない。"
  },
  CollectionHall_98638_LockTip = {
    Text = "調査6-10高難度を完了で解放"
  },
  CollectionHall_98638_Title = {
    Text = "神の降臨"
  },
  CollectionHall_98639_Desc = {
    Text = "彼が一つ一つの死を弔う時、無情に鎌を振るっているわけではない。\n彼にもかつて温かな両手があり、繊細な心があった。\n魂の悲しみを味わう時、彼もまた共に涙を流す。\n骨身に刻まれた憎悪を味わう時、彼は代わりに裁きを下す。\n彼は葬骸の主の名において誓う――死を冒涜する者はすべて、冷たき濃霧の中に消え去ると。"
  },
  CollectionHall_98639_LockTip = {
    Text = "調査行動 星辰篇3–11をクリアして解放"
  },
  CollectionHall_98639_Title = {
    Text = "死神の伏し目"
  },
  CollectionHall_98640_Desc = {
    Text = "血肉の甘腥い味わいと腱が断ち切れる食感は、彼にとって最も馴染み深く、最も骨身に刻まれた記憶。\n彼はとうに悟っていた。この葬骸城が今日まで続いてきたのは、生者の力ではなく、亡者の犠牲によるものだと。\nまた一筋の深紅が喉を通り過ぎる。彼は目を閉じ、一つ一つ異なる香りを丁寧に味わい、すべての魂の味をしっかりと刻みつける。こうして彼の親族と民は、彼の身体の中で永遠に生き続ける。\n彼らは永遠に共にあると誓い合った。"
  },
  CollectionHall_98640_LockTip = {
    Text = "調査行動·困難 星辰篇3-10クリアで解放"
  },
  CollectionHall_98640_Title = {
    Text = "血色の契約"
  },
  CollectionHall_98641_Desc = {
    Text = "月光の下で祭祀刀が魅惑的に輝いている。\n彼女はひとつの決然たる死によって、夢にまで見た自由意志を証明した。"
  },
  CollectionHall_98641_LockTip = {
    Text = "調査6-15を完了で解放"
  },
  CollectionHall_98641_Title = {
    Text = "冷たい月光"
  },
  CollectionHall_98642_Desc = {
    Text = "彼は仲間に戦い方、殺し方、生き残り方を教えたが、数倍の強敵に直面したときの逃げ方は教えなかった。\nだから彼も逃げない。\nただの首だ、持っていけ！\n彼はすでに見抜いていた。\n力を追い求める野心家が追求の途中で死ぬのは、あらかじめ定められた結末であり、宿命にほかならないと。"
  },
  CollectionHall_98642_LockTip = {
    Text = "意識潜行「巨人の墜落」を完了する"
  },
  CollectionHall_98642_Title = {
    Text = "我は死を恐れず"
  },
  CollectionHall_98643_Desc = {
    Text = "グシャ、ブチッ。\n神は口を裂き、喜びに満ちて受け入れた。\n信徒のすべての敬虔なる祈りを。\nそして、その信徒自身までも。"
  },
  CollectionHall_98643_LockTip = {
    Text = "調査6-15を完了で解放"
  },
  CollectionHall_98643_Title = {
    Text = "第一の晩餐"
  },
  CollectionHall_98644_Desc = {
    Text = "かつての仲間たちは一斉に襲いかかり、敗北し流浪する指導者を殺そうとした。しかし、ペリシテ史上最も勇猛な指導者であり、不屈の意志を持つ巨人は、殺戮で応えた。\n終わりなき悲鳴の中、巨刃は血を渇望し、次々と不完全な死体で彼の戦闘様式を示した——傲慢、狂気、野蛮、残虐。\n敵に対して、憐れみは不要。\nそれらは彼が再び権力の頂点に戻るための、必要な階段に過ぎない。"
  },
  CollectionHall_98644_LockTip = {
    Text = "意識潜行「巨人の墜落」を完了する"
  },
  CollectionHall_98644_Title = {
    Text = "必要な戦い"
  },
  CollectionHall_98645_Desc = {
    Text = "背を向けて歩き出したその瞬間、エルトンはまるで、再び航海に出たあの少年に戻ったかのようだった。\n青空と果てしない海がひとつに繋がり、世界はすべての志と夢を包み込めるほどに広かった。\nただひとつ違うのは、今回は、夢が叶う光景をこの目で確かに見たということ。\nそして彼はもう、白鳥たちの舞う郷へと続く帰り道を手にしていた。"
  },
  CollectionHall_98645_LockTip = {
    Text = "調査6-10高難度を完了で解放"
  },
  CollectionHall_98645_Title = {
    Text = "白鳥の郷"
  },
  CollectionHall_98646_Desc = {
    Text = "時は来た、銀月が高く懸かる。\nさあ硬くなったつま先を立てて、今宵はこの宴のひとときを楽しもう。\n彼女は最後の旅路を歩み終えた、そして我らは胃袋で彼女を弔う。\n一口はあなたに、一口は私に、これからは誰も忘れることはない。"
  },
  CollectionHall_98646_LockTip = {
    Text = "調査行動 星辰篇3–11をクリアして解放"
  },
  CollectionHall_98646_Title = {
    Text = "安息の舞曲"
  },
  CollectionHall_98647_Desc = {
    Text = "もし、神の奇跡に形があるなら、\n彼女が手を合わせて祈る、その姿のようであろう。\nもし、神に姿かたちがあるなら、\n彼女の安らかなる、その面差しのようであろう。"
  },
  CollectionHall_98647_LockTip = {
    Text = "調査6-15を完了で解放"
  },
  CollectionHall_98647_Title = {
    Text = "純白の巫女"
  },
  CollectionHall_98648_Desc = {
    Text = "祝おう、我が友よ♪\n月光の下で骸骨がひそかに咲き誇り、一人の愛しき者が皿に捧げられる♪\nすべての客人が集った！歌え、踊れ♪\n我らは亡霊のために祈らない、我らは屍のために哀悼しない♪\n彼女は記憶を我に託し、彼女は涙を我に託した♪\n彼女の魂と腐肉を飲み下そう♪\n死の饗宴の中で、我らは再び一つになる♪"
  },
  CollectionHall_98648_LockTip = {
    Text = "調査行動 星辰篇3–11をクリアして解放"
  },
  CollectionHall_98648_Title = {
    Text = "屍食鬼の歌"
  },
  CollectionHall_98649_Desc = {
    Text = "人々は彼の強さを恐れ、崇拝し、彼の残酷さを憎み、唾棄し、彼の敗北を嘲笑し、追放した。\nしかし、弱者の騒音は無意味であり、巨人の目は強者にのみ留まる。\n荒れ果てた流浪の海で、彼は命を賭け、絶対的な力を求める旅に出る。"
  },
  CollectionHall_98649_LockTip = {
    Text = "意識潜行「巨人の墜落」を完了する"
  },
  CollectionHall_98649_Title = {
    Text = "新たな旅路"
  },
  CollectionHall_98650_Desc = {
    Text = "彼は彼女をずっと覚えていた。嵐の中、自らの腕の中にしっかりと抱きしめていた幼子。そしてついには、自らの手で深淵へと送り出したあの子を——\n自らの良心と引き換えに、白鳥が大空を翔けるあの夢を交換した。\n　\n彼が生涯をかけて祈り続けた美しい夢は、すでに果たされた。\n故にこれからは——\n残された命のすべてをもって、黒き罪を贖う時だ。"
  },
  CollectionHall_98650_LockTip = {
    Text = "調査6-15を完了で解放"
  },
  CollectionHall_98650_Title = {Text = "償い"},
  CollectionHall_98651_Desc = {
    Text = "別離と死――どちらも世の中で逃れられない常。\n数えきれない犠牲と死から離れ、茫漠たる前途へと歩み出す。淡い悲しみが胸に漂う。しかし、死の中に生きる人々を目の当たりにし、死に優しい結末を与える王を見届けた今、あなたはもう未知の結末を恐れはしない。\n一輪の紫の勿忘草が肩にふわりと舞い降りる。彼に代わって、遥かに見送るように。\nあなたは知っている――何があろうと、帰り道は決して孤独ではないと。"
  },
  CollectionHall_98651_LockTip = {
    Text = "調査行動·困難 星辰篇3-10クリアで解放"
  },
  CollectionHall_98651_Title = {
    Text = "勿忘草の見送り"
  },
  CollectionHall_98652_Desc = {
    Text = "「あなたたちの友、王、この安息の地の主の名において、招く――目覚めよ！愛しき故郷へ還れ！我らの親しき者の安寧を乱す輩を、永遠に追放せよ！」"
  },
  CollectionHall_98652_LockTip = {
    Text = "調査行動 星辰篇3–11をクリアして解放"
  },
  CollectionHall_98652_Title = {
    Text = "万霊の怒り"
  },
  CollectionHall_98653_Desc = {
    Text = "彼女と神は共存できなかった。\n故に一本の短剣が二つの心臓を貫いた。\nそれが彼女から神への捧げものであった。"
  },
  CollectionHall_98653_LockTip = {
    Text = "調査6-15を完了で解放"
  },
  CollectionHall_98653_Title = {
    Text = "神の誕生の日"
  },
  CollectionHall_98654_Desc = {
    Text = "王との対話がダンスから始まるとは、思いもしなかった。\n力強い踏み込み、揺れる駆け引き、攻撃と防御、対峙と譲歩――翻るスカートの中で密かに火花を散らす。\n取引は最後の礼で優雅に幕を閉じ、王の髪がひらりと舞い落ちる。霧に包まれたその瞳に、愉悦の笑みが煌めいているのが見えた。\nあれ？さっき、あの人に手のひらで踊らされていたのでは？"
  },
  CollectionHall_98654_LockTip = {
    Text = "調査行動 星辰篇3–11をクリアして解放"
  },
  CollectionHall_98654_Title = {
    Text = "タンゴ外交"
  },
  CollectionHall_98655_Desc = {
    Text = "あなたが見た最も恐ろしく冒涜的な貪食は、彼らの人生で最も優しい再会だった。"
  },
  CollectionHall_98655_LockTip = {
    Text = "調査行動 星辰篇3–11をクリアして解放"
  },
  CollectionHall_98655_Title = {
    Text = "骸骨が眠る場所"
  },
  CollectionHall_98656_Desc = {
    Text = "星々は、ただいつものようにその軌道を巡っている。しかし、塵の中に生まれた生命は、そのために幾度も深い奈落へと沈んでいった。"
  },
  CollectionHall_98656_LockTip = {
    Text = "調査6-15を完了で解放"
  },
  CollectionHall_98656_Title = {
    Text = "倒錯した星"
  },
  CollectionHall_98657_Desc = {
    Text = "瞬時に人を死に至らしめる魔女に対し、弱者は恐れ、崇拝し、帰依し、庇護を祈る。\nだが彼は決してそうではない。\n彼はこの力を見て、その力を渇望し、どんな代償を払ってでも手に入れようとする。\nそして、彼は再び立ち上がり、再び自分の名をペリシテ人が踏み入れたすべての土地に轟かせる。"
  },
  CollectionHall_98657_LockTip = {
    Text = "意識潜行「巨人の墜落」高難度を完了する"
  },
  CollectionHall_98657_Title = {
    Text = "巨人の野望"
  },
  CollectionHall_99651_Desc = {
    Text = "<Bold:銀ダラ24>\nあのフィッシュフライの店を通るたびに、叫びたくなるの。\n\nどうして、いつも傷つくのは銀ダラなの？あたしたちは本物のタラですらないのに！\n\n身が締まっていて美味しいのはあたしたちの罪だっていうの？\n\n<Bold:にゃんこ24>\nズルズル……ニャー、ニャーニャー（同意）！\n\n<Bold:銀ダラ24>\nレオ王国では、毎分1匹の銀ダラが非業の死を遂げ、人間の皿に乗せられている。\n\nそう、今こうして話している間にも、すでに10匹の銀ダラが壮絶に犠牲になったの。\nまるまる10匹！\n父なる神よ、彼らの悲鳴が聞こえますか？\n\n<Bold:にゃんこ24>\nエッ……ニャ？\nニャーニャーニャー、ニャーニャー（どこで）？\n\n<Bold:銀ダラ24>\nただの比喩よ、バカね。\nあなたはちょっとおバカだけど金のような心を持っていて、猫の本能と近視眼的な欲望に打ち勝てる。\n\n聞いて、計画があるの。これから一緒に実行してほしい……\n\n——《ビッグジョンのフィッシュフライ店爆発事件・事件概要：証言B-03》より抜粋。\n\n当時ベツレヘム精神病院は満床のため、容疑者は収容を拒否され、ロンディニウムタワーに23日間拘留された後、釈放された。"
  },
  CollectionHall_99651_Title = {
    Text = "銀ダラの決意"
  },
  CollectionHall_99653_Desc = {
    Text = "「その刻」を待つため、少女は氷河の底で眠りについた。\n\nアイズルワースの千フィートの厚い氷が彼女の肉体を凍結させたが、その意識を完全に閉じ込めることはできなかった。\n\nその意識は、一人の子供のものであり、また、一人の母親のものであった。\n\n娘の暗き胎内では、神が永遠の長い夢を見続けていた。\n\n25年の歳月の中で、彼女は何を考え、何を恋い慕い、何を期待したのだろうか？\n\n今となっては、これらの問いに答えられる者はいない。\n\nそして、その少女自身については……彼女は身近な人々に本心を打ち明けるのだろうか？\n\n今はすべてを委ねよう……これから訪れる時の流れと未来に。"
  },
  CollectionHall_99653_Title = {
    Text = "氷河の眠り"
  },
  CollectionHall_99654_Desc = {
    Text = "静かに死んだ魂だけが、じっくりと味わう価値がある。生者のもがきは味を乱すだけだ。\n皿が運ばれてきたとき、まだ温かさが残っており、心臓が中央に安らかに横たわっていた。表面はわずかに膨らみ、まるで最後の一拍を終えたばかりのようだった。二つの眼球が傍らを飾り、瞳孔には死の直前の驚愕が封じ込められ、煮込まれて温順な乳白色になっていた。\n彼はナイフを持ち上げ、心尖をゆっくりと切り開こうとしたが、突然止まった。\nその魂はまだかすれた叫び声を上げており、その執念が血管に留まって完全に消えていなかった。彼はナイフを置き、手を合わせて、静かに亡霊の声を聞いた。\nこの心臓は、生前に病苦に苦しんだ詩人から来たもので、長い失意の中で死によって解放されたが、生への未練が残っていた。彼は知っていた、この心を本当に「味わい深く」するためには、美食に十分な敬意を払う必要があり、唯一の方法は待つことだった——\n肉に纏着した執念が死の中で完全に崩壊するのを待つこと；亡者の記憶の最後の共鳴が沈香に変わり、血管壁に静かに染み出すのを待つこと。\n彼は優雅に手を膝に重ね、目を閉じて深く息を吸った。\n香りが空気中にゆっくりと広がり、それは複雑で優しい香りであり、恋人の震えや別れの苦さを含んでいた。墨の香り、薬草の香り、そして朝露のような一抹の怯えが混ざっていた。\n彼は生命の枝葉の茂る木の下に静かに座り、成熟した果実が予定通りに落ちるのを待っていた。"
  },
  CollectionHall_99654_Title = {Text = "珍味"},
  CollectionHall_99655_Desc = {
    Text = "長い間放置されて枯れ果てた花束。\nその主人を永遠に待っている。"
  },
  CollectionHall_99655_Title = {
    Text = "届かない花"
  },
  CollectionHall_99656_Desc = {
    Text = "生まれた時から、双子は自由に翼を使って飛ぶことを許されず、背中に生えた第二の腕は、神子の威厳を示す礼器のように、常にあるべき姿勢が規定されていた。\n幼い頃、ポリュクスは二人の中で最もその翼を大切にしており、毎日羽を梳き、精油を塗り、その羽を絹のように輝かせていた。\n彼はいつも短い無人の時間を利用して、こっそりとその翼を羽ばたかせ、カストルの驚愕の中でふらふらと地面を離れ、装飾が施された天井に触れようとした。\nポリュクスが翼を使って様々な舞踊のような動きをするのに対し、カストルは自分の翼が木の板のように不器用だと感じていた。双子が毎晩就寝後の秘密の時間に、カストルはポリュクスが暗闇の中で跳ね回り、狭い檻の中で飛翔を模倣するのを静かに見つめていた。\n「弟の翼は本当に美しい。でも僕は一生飛ぶことを学べないかもしれない。」カストルは思った。\nそして後に彼らが逃亡した夜、カストルは初めて夜風が翼を持ち上げる涼しさと軽やかさを感じた。より熟練したポリュクスは、ふらふらと飛ぶ兄をしっかりと掴み、高空で心から笑い、急降下や旋回の弧を描き、まるで本物の空に属する鳥のようだった。\nカストルは頭を傾け、月光がポリュクスの細長く力強い翼に輝き、羽の間に目眩がするような青緑色の光輪を反射しているのを見た。\n「それは世界で最も美しいものだ。どんなことがあっても、僕はポリュクスを守り、その翼を守る。」\nやがて、厳しい野外生活でポリュクスの翼が野獣に傷つけられ、カストルはポリュクスの落ちた羽を拾い上げ、胸にしまい、二度とこんなことが起こらないようにと静かに誓った。しかし彼は知らなかった、その後この孤独な羽が彼にとって最も貴重なものとなり、その翼に関する最後の遺物となることを。"
  },
  CollectionHall_99656_Title = {
    Text = "孤高の羽"
  },
  CollectionHall_99657_Desc = {
    Text = "ブオ——ブオ——\n汽笛の音の中、遊覧船はコーパサントの指示で安全に接岸した。\n乗客たちは笑いながらタラップを降り、帽子を取って彼女に感謝し、水夫たちは集まって称賛を表した。\n「よくやった、コーパサント。君が事前に警告してくれなかったら、嵐に飲み込まれていたよ。」\n「そうだね、君の正しい指示のおかげで、海で迷わずに済んだよ！」\n水夫たちは笑いながら彼女の肩を叩き、親指を立てた。\n実際、コーパサントはこうした近距離の社交に慣れることができず、彼女の古風で理性的な頭脳には「仕事」と「職務」以外の考えはなかった。\nそこで、彼女はこれも「仕事」と「職務」の一部とみなすしかなかった。\n「私はただ自分の仕事を果たしただけです。航海士としての私の職務は、皆さんを安全に帰港させることです。」\n形式的で退屈な返答だが、彼女の人柄を知る水夫たちは大笑いし、彼女に別れを告げ、船歌を歌いながら肩を組んで港を去った。\n「ノーチラス号がついに出航できる。出発だ、ノーチラス号。」\n歌声は次第に遠ざかり、コーパサントはまだ岸辺に残っていた。彼女は未来の出航に備えていた。\n海は気まぐれで、どの航海士も毎回勝利を保証することはできず、彼女もそうだった。しかし、彼女はわずかでも勝算を増やすために無数の時間を費やすことをいとわなかった。\n点検、巡回、学習、確認、彼女の生命には「仕事」だけが残っているようだった。\nしかし、彼女はそれを喜んで受け入れた。なぜなら、それはすべてその瞬間のため、成功した航海で皆を安全に帰港させるその瞬間のためだった。"
  },
  CollectionHall_99657_Title = {
    Text = "海上の導き手"
  },
  CollectionHall_99658_Desc = {
    Text = "無限の深淵に、青い玉座がそびえ立ち、天幕が低く垂れ、星々が震え、万物が沈黙する。\n\n古く神秘的な存在はすでに消え去り、世代を超えて、生き物たちは夢の中で賛美歌を歌う。\n\n暗い水域、封じられた秘密。\nあなたの囁きは波のように押し寄せ、心の溝を埋め尽くす。\n\nその無辺の夢境で、先知と狂人が共に遊び、無形の魂を追い求め、恐怖と畏敬が交錯する。\n\n青藻が纏う軌跡は、運命の編纂のように、迷える者の心を徐々に青い玉座へと導く。\n\nああ、宇宙の不条理と真理、夢と現実が交錯する場所で、永遠の輝きが閃く。"
  },
  CollectionHall_99658_Title = {
    Text = "青石の玉座"
  },
  CollectionHall_99660_Desc = {
    Text = "誰もが運命に打ち勝ちたいと思い、誰もが運命を恐れている。\n\n勇者は戦いの怒号を上げ、臆病者は従順の唸り声を発するが、彼だけが運命に勝つ秘密を見つけた。\nそれは運命を賭けに誘い続け、次のゲームを開くよう促すことだ。\n\n彼は運命を恐れたことがない、なぜなら自分が負けないと信じているからだ。\n彼は何を賭けるかを問わず、どんな賭け金でも躊躇なく差し出す、自分の命さえも。\n\nルーレットの銃を手に、彼は多くの賭け狂いの敗者を退け、ロンディニウムで悪名高い賭け狂いとなった。\n本当に残念だ、対等な相手がいないのはどれほど寂しいことか。\n\nそして、彼はその男に出会った。\n彼は無数の凡人を打ち負かし、ついにその男との運命の賭けのテーブルに座った。\nすぐに彼はすべてを失い、またすべてを取り戻した。\n\n獣として生まれ変わったとき、彼は地面に最後の弾丸を撃ち出した銃を見た。\n彼は弾丸を再装填し、自分の頭に再び引き金を引いた。\n無音の中で、彼は口を開いた。\n\n彼はまだ負けていない、だからいつか必ず勝つと信じている。\n彼は常にそう信じている、たとえすべてを賭けることになっても。"
  },
  CollectionHall_99660_Title = {
    Text = "運命のルーレット"
  },
  CollectionHall_99663_Desc = {
    Text = "その神秘的な女性は、葬儀の後に彼女を訪ねてきた。\n\n「お気の毒に……」彼女は言った。\n\n「あなたはこの悲劇に巻き込まれるべきではなかったのに」\n\n「知りませんでしたか？彼がミリーを殺した後、トンプソンが彼を追い詰めたの。あのエドワードという名のクズは、去年それで死ぬはずでした。なのに彼を助けた人がいるんです」\n\n「そうした理由？ああ、それは私にも分かりません。もしかしたら、彼らは最初から共犯だったのかもしれません。\nあるいは……その罪人自身が、自分の行いが罪だと気づいていないのかも。\nあの人は何て言ってたかしら？\nそう、赦し。罪人への赦し、彼らが犯した罪への赦し」\n\n「あの人は、人には二度目のチャンスがあるべきだと信じていましたが、あなたはどう思います？\n私たちはエドワードにもう一度チャンスを与えるべきでしょうか？\nミリーを、あなたの姉を殺し、母親まで殺したあの男に？」\n\n「そう、こういう人間は変わらない。絶対に。だからあなたはもう分かっているでしょう？」\n\nその通りだ……こういう人間は変わらない。このような人間、このような罪、このような悲劇を終わらせるには……\n\n彼らの欲望を暴露し、醜態をさらさせ、互いに殺し合い争わせそして完全に浄化する——\n\n罪なき地を迎えるために。"
  },
  CollectionHall_99663_Title = {
    Text = "鏡の中の人"
  },
  CollectionHall_99666_Desc = {
    Text = "広大な草原に羊の群れがさまよう。\nこの世にはあまりにも多くの羊がいて、羊は生まれつき牧者に導かれる必要がある。\n彼女は常にこの世界の先知であり、手に知識の杖を握っている。\n彼女は常に良い牧者であり、羊の群れを正しい道へ導く決意を持っている。\n彼女はその杖で子羊を教え、その杖で狼を追い払う。\n彼女は羊飼いの杖を高く掲げ、常に前方の道を見通すことができる。\nかつて彼女は羊の群れを豊かな水源や新鮮な草地へ導いた。\n今、彼女は世界の真実を目撃し、羊の群れを究極の抱擁へ導く。\nこちらへ来て、振り返らないで。\n彼女は笑いながら知恵の杖を振る。\nすると羊たちは前方の崖を見えない。\n一匹、二匹。\n羊が落ち、牧者は歌う。\n無私の羊飼いに従ってください、彼女はあなたに最も真実の道を示してくれた。\n恐れることはない、死の陰の谷を行くときも、彼女の杖はあなたと共にある。\n一緒に消滅の深淵へ入るまで。\n"
  },
  CollectionHall_99666_Title = {
    Text = "羊飼いの杖"
  },
  CollectionHall_99667_Desc = {
    Text = "彼の神は、果てなき混沌の中を這い進み、時折、地に伏す万物に一瞥を投げかける。\n\n目に留まる者、例えばソレールのような者には、拒絶しがたい「契約条項」が与えられた。\n\n粗野で退屈な者に対しては、彼の神は肉体を剥ぎ取り、涙も流せない眼だけを残す。\n\nこれらの眼は寵愛を受けし者——「寵愛者」と呼ばれる。\n\nそれらは洞窟の中で、明滅する光に佇み、希望と絶望を抱き、彼の神に呼ばれるのを待つ。\n\nだが千年、一万年が過ぎても、寵愛者は闇の隅に置き去りにされたままだ。\n\n「それで……君たちは、何か理由があって残されたのだろう。君たちの使命は何？」\n「私たちは待っている」\n\n「何を待っているの？」\n「ただ……待っているだけ」\n\n「苦しくはないの？」\n「むしろ逆だ。彼の神への愛が私たちの全身を満たしている。これが唯一できることだから」\n\n「それを理解して初めて、真の信徒になれる」"
  },
  CollectionHall_99667_Title = {
    Text = "百万の寵愛の眼差し"
  },
  CollectionHall_99668_Desc = {
    Text = "彼女の名前は知恵の化身。\n彼女は世のすべての知識を知り、ミサゴのすべての学者が憧れる究極の存在。\n少しでも彼女の言葉を聞けば、悟りを得ることができる。\nしかし彼女は、自分はただの門番だと言う。\nそれはどんな門なのか？\n誰もその門を見たことがないため、学者たちはそれを真理と呼ぶ。\n彼女は真理の門番であり、ミサゴを守るアテナである。\nタヴィはその推測を否定せず、常にここを見守り、この世界を見つめている。\n無言で哀れみを持って。\nもしあなたがいつかその門を見たなら、門には非常に見覚えのある目があるだろう。\nその目は静かで永遠。\n時間を超え、あなたの魂を貫く。"
  },
  CollectionHall_99668_Title = {
    Text = "真理の門"
  },
  CollectionHall_99670_Desc = {
    Text = "黒き血に身を浸し、再び生を得た少女は、砂漠に千年にわたり渦巻く風砂の中で、豊穣母樹の神聖な血の種を掲げた。\n\n「この種が生き続ける限り、樹の血脈は途絶えることはない」\n\nそれからまた千年が過ぎた。\nこの種は樹の末裔と共に、栄光と屈辱、興隆と衰退を見届け、流浪と喪失を味わい、消滅と再生を繰り返した。\n\nそして、奔流する河が粘り気のある黒き血へと変わるとき、種は最後の継承を果たした。\n\nそれは熱く燃え上がり、絡みつくような口づけだった。\n\n満たされぬ渇望と、言葉にできぬ別れの哀しみを孕み、温かな心臓の鼓動と共に、新たな継承者を深く包み込んだ。\n\nその瑪瑙のような色彩、白翡翠のような光沢は、生命の鼓動と共に黒い終末を乗り越えていく。\n\nそして新世界の最初の樹の種は彼女の祝福のもと、大地から立ち上がり、天と地を覆う巨樹となるだろう。"
  },
  CollectionHall_99670_Title = {
    Text = "熱い別れのキス"
  },
  CollectionHall_99671_Desc = {
    Text = "新生を得たクレメンタインは、まるで無知な幼虫のように、人間界を歩き回り、自分の種族に属さない繁栄した世界をさまよい、困惑していた。\nその時、啓示のような声が響いた——\n「すみません、あなたはシャーロット医師ですか？私はシャーロット医師に心理相談をお願いしたくて……」\nクレメンタインはようやく我に返った。彼女はシャーロットが誰か気にしなかったが、来訪者の口から出た新しい言葉「心理相談」に興味を持った。\nしかし彼女は成熟したハンターで、自分の無知を露呈することは決してなかったので、彼女は笑った。まるで彼女がシャーロットであり、来訪者の口にする救いであるかのように。\n涙、苦痛、無力感、何も誘わずとも、来訪者は魂の奥底の苦しみを絞り出した。\n去る前に、相手は軽やかな顔でクレメンタインを見て、感慨深く言った。「聞いてくれてありがとう。気分がとても良くなった」\nそして、ドアが閉まる音と、クレメンタインが初めて甘美を味わったことによる笑い声が響いた。\nその笑い声は最初は微かで、幼虫の羽音のようだったが、次第に大きくなり、成虫の叫びのようになった。\nその笑い声の中で、クレメンタインという名の虫族も急速に成熟した。\nその後のすべては、当然の成り行きだった。彼女は精神科医師となり、笑顔と振り子を持って、患者の心の奥深くに入り込んだ。\n彼女は依然として人間界を歩き回り、この繁栄した世界に属していないが、もはや迷うことも困惑することもなかった。\nなぜなら、すべての人間界と世界が、彼女の催眠の狩場だからだ。"
  },
  CollectionHall_99671_Title = {
    Text = "催眠ペンデュラム"
  },
  CollectionHall_99672_Desc = {
    Text = "太陽は毎秒300ゼタジュール以上のエネルギーを放出し、その数十億分の一が光と熱の形で、147億メートル以上の距離を超えて宇宙から地球に届く。\nこれらのエネルギーは地球上のすべての生物のニーズを満たし、この複雑で巨大で混沌とした三つの領域のすべての種が繁殖と進化を順調に行うことを可能にしている。\n\n「これは世界の真理であり、どんな状況でも変わることはない。」\n彼は自分にそう言い聞かせ続け、精神の安定を保っていた。\n「でもなぜ……こんなに暑く、こんなに明るいのか。」\nそれは147億メートル先のものが、彼の瞳をゆっくりと占めていたからだ。\n光と熱が彼の瞳孔から放たれ、彼の華麗な体の隅々を焼いていた。\n「理解した、理解した、なぜ光が8分20秒後に地球に届くのかを理解した。」\n「私たちは光を直視する代償を支払うことができないからだ。」\n彼がすべてを受け入れたとき、彼は声を上げて笑い始めた。\n「私はイカロスよりも太陽に近い。」"
  },
  CollectionHall_99672_Title = {
    Text = "迫り来る太陽"
  },
  CollectionHall_99673_Desc = {
    Text = "「まだ完璧ではない。今夜もう十回練習しなさい。\nお前の才能は平凡だ。楽団に入りたければ、もっと努力することだ。わかったか？」\n「はい、父さん」\n\nどんな演奏が完璧と言えるのか？\n彼の手は止まることなく舞い、ひとつの失音も許さなかった。\n雑念を叱り、平凡な自分を軽蔑した。\n無数の音符が目の前を巡り、毎日、毎日、彼の人生は音楽だけだった。\n\n幸い、完璧な演奏へと日々近づいていた。\n夢の中の道の果てに光を見た。永遠に届かないとわかっていながら。\n\n完璧への渇望は、すでに魂に刻まれていた。\nだが、誰もがそう望むわけではなかった。\n\n「陛下のため、世のために最も完璧な音楽を——それが楽団の責務ではないのか？」\n不満を滲ませた顔々を見渡し、彼はかつての自分を見るように、静かに軽蔑した。\n\n父さん、宮廷楽団もその程度か。\n\nかつて仰ぎ見た目標を捨て、彼は頑なに完璧を追い求める道を歩み続けた。\n手を止めて彼らを引き留めることも、かつての自分を止めることも、彼にはできなかった。\n\n毎日、毎日、演奏は続く。\n音楽こそが、彼の命だった。\n音楽以外、彼には何もなかった。"
  },
  CollectionHall_99673_Title = {
    Text = "永劫の演奏"
  },
  CollectionHall_99674_Desc = {
    Text = "山頂に立ち、黒い刺を掲げた。\n天を覆い尽くす吹雪の中で、彼女はあの狂気の山脈に向かった。捨てられ、裏切られ、踏みにじられた己の運命に。\n\n必ず勝利する。\n氷雪は必ず溶ける。\nそのとき、自分は新たな姿でこの世に再び現れる——\n彼女はそう言った。\n\nアイズルワースは極寒の地。\nそこでは風雪が一年中消えることがない。周知の事実だ。\nいかなる強者とて、崇高な存在には抗えず、運命には勝てないように。\nだが——\nあの雪山は、ついに溶けた。"
  },
  CollectionHall_99674_Title = {
    Text = "雪山が溶けるまで"
  },
  CollectionHall_99676_Desc = {
    Text = "最初の王配は、イサラウの出身だった。\n\n彼はイサラウ人特有の淡い金色の瞳を持ち、漆黒の夜空の遥か遠くの微光を放っていた。\n\nだが、その光はイサラウの陥落と共に消え失せた。\nワンダは漆黒の泥沼から最後の遺物をすくい上げ、大切にしまい込んだ。\n\n\n彼女は第二、第三の王配とは、フラン高地で出会った。\n\nその二人は双子の貪欲な領主でワンダは彼らの力を使う事で、失われた湖中の城を再建したいと望んでいた。\n\nしかし彼女は裏切られた。\nそのため、脊椎針を彼らの骨髄に深く埋め込んだ。\n麻痺の中、ワンダはその卑しく無礼な両目を取り出し、自分がいた痕跡としてそこに残した。\n\n\n第四の王配——ワンダは、彼の名を「ジョン」と覚えていた。\n\n彼は無口で退屈だったが、彼女の機嫌をとるのは上手だった。\nさらに彼女を喜ばせたのは、「ジョン」もまた淡い金色の目をしており、彼女のものとほとんど同じだったことだ。\n\n\n「王配の目を抉り出しな」\n\n「畏まりました……\nしかし、王配様は何か間違いを犯したのでしょうか？」\n\nワンダは杯の中の、濁った水を揺らしながら、舌の上を毒が巡るのを感じていた。\n\n本当に愚か者だ。毒を盛ることさえ、こんなに粗雑だなんて。\n\n\n融蝕に蝕まれた「ジョン」を見て、彼女は思い出した——遥か彼方の星の外にいた頃、故郷を離れる彼女を見送った、死んだような無数の瞳を。\n\nそれは、今の「ジョン」の瞳と瓜二つだった。\n\n「……あえて言うなら、ユーモアのセンスが足りなかった」"
  },
  CollectionHall_99676_Title = {
    Text = "イサラウの眼差し"
  },
  CollectionHall_99678_Desc = {
    Text = "彼女の詩がシディで人気を博して以来、友人はますます熱心に花を贈ってくれるようになった。\n「こんなにたくさんの花はいらないわ、コレット。無駄になってしまうもの」\n\n今日持ってきた薔薇は昨日、一昨日、その前の日のものと一緒に積み重ねられ、古い花は窮屈さに耐えられなかったのか、腐り始めている。\n\n「どうして無駄になるの？私たちは前に約束したじゃない、私の花とあなたの詩を交換するって」\n\nコレットは頭を振り、少し気まずそうに彼女を見つめた。\nそう、花と詩を交換する、それが彼女たちの約束だった。\n彼女は何かが変わったように感じたが、それ以上は考えたくなかった。\n\n彼女は詩を書き続けた。\n昼夜を問わず詩を書いた。\n以前は自然にペン先から流れ出ていた詩が、今では少し詰まるようになっていた。\n\n友人が花を持ってくるときの目つきがますます見知らぬものに変わっていく。\n彼女は部屋いっぱいの腐っていく薔薇を見て、その枯れゆく匂いを嗅ぎながら、それを心から惜しみ、もの悲しさを感じた。\n\nしかし、彼女は決してペンを止めることはなかった。\n\n「この土地に咲く花で、私たちは服も食べ物も買える。いつかは、あの上に建っている建物の部屋だって、きっと買ってみせるわ！」\n\n「人にはそれぞれ、生まれついて果たすべき役目があるの。私はこの花園と、あの家のために生きる。……そしてあなたは、生まれながらに詩を書く人なのよ」\n\n「信じてるわ、オルラ。今日から、あなたの詩は全部、私が大切に保管する。これからは――私の花で、あなたの詩を交換するの」\n\n花と詩。\nそれは彼女たちがお互いに交わした約束だった。\n\n彼女は決してペンを止めることはなかった。"
  },
  CollectionHall_99678_Title = {
    Text = "昔日の花と詩"
  },
  CollectionHall_99679_Desc = {
    Text = "魔女とつば広帽子の因果関係は時に鶏と卵の関係のようで、帽子が魔女を成したのか、魔女が帽子を成したのか分からない。\n\nともあれダフォダイルはそんな優雅なつば広帽子を所持する。\n\nこの帽子は元々、かつての店主のもので、その頃ダフォダイルの名はまだダフォダイルではなく彼女は支配されたばかりの迷える幽霊、無垢な野獣だった。\n\nいつも微笑んでいたあの女性はまるで子どもを育てるように、彼女に「人になる方法」と「人と接する秘訣」を、少しずつ教えてくれた。\n\n港町は商業が繁栄し、当時の人類文化の結晶が集まっていた。商店のある通りにはさまざまな店が立ち並び、店主は不思議とどの店の主人とも旧友のように話せた。\n\n「本当にすごい人」\n当時のダフォダイルは思った。\n「でも不思議じゃない。誰だってあの人を好きになる」\n\n店主は街歩きが好きだった。だからこそ、千年もの間、人間の首を刈る役割を担ってきたダフォダイルが、初めて「自分の意見」を求められたのだった。\n\n「どっちがいいと思う？\nこの小さな帽子、それともこのつば広帽子？」\n\n女性は鏡の前で、さまざまな帽子を試しながら言った。\nダフォダイルにとって帽子とは体を包み、ただ人間らしく見せるための道具にすぎなかった。\n\nしかしその日、店主の頭にある大きな花のようなつば広帽子を見て、ふと、自分とその帽子をかぶった店主が海辺を散歩する姿が頭に浮かんだ。\n\n「これがいい」\n彼女は突然言った。\n\n「この帽子がいい」\n\n店主は少し驚いて振り返った。\n彼女がこれほどはっきりと好みを示すとは思わなかったようだった。\n\n「いいわね確かに素敵な帽子。あなたが選んでくれたから、大切にするわ」\n\nダフォダイルを励ますためか、この帽子は店主の言葉通り、彼女の頭に常に飾られ続けた。\n\n最期の彼女の手から滑り落ちる時、微笑む彼女の首と共にダフォダイルに手渡された。\n\n「本当に素敵な帽子。\nちゃんと大切にするわ」\n艶やかに咲き誇る紫黒の花は、新しい主人の頭に咲き誇った。"
  },
  CollectionHall_99679_Title = {
    Text = "魔女のつば広帽子"
  },
  CollectionHall_99683_Desc = {
    Text = "王座の幻夢の中で、王は神の啓示に耳を傾ける——\n\nリモリアの嵐は静まる。\nリモリアの深淵は消え去る。\n\n夢を庭とし、星を燭台とせよ。\n\n王はその善良なる民を庇護し、神の王国をもたらすだろう。\n\n我が主の信徒よ、汝の心を開き主を受け入れよ。\n\n遥かなる暗き深淵にて、古の偉大なる魂は眠りにつき、諸神のささやきに耳を傾ける。\n\nその意志は、星々の網のごとく交差し、永遠なる虚無の中で、汝が夢に至るのを待つ。\n\n嵐は静まり、水面は波立たず、地震は収まり大地は安らかに。\n\n災厄は、主の静寂なる夢の中で虚無へと変わり、民はその庇護のもと、安らぎを得る。\n\n願わくば、我らの歌声が深海を越え、主が我らに神託を授けんことを。\n災いより逃れ、果てなき安寧と至福の地へと導かれんことを。\n\n我らの信仰は主と共にある。\n星々が消え、時の終わるまで。"
  },
  CollectionHall_99683_Title = {
    Text = "深海の呼び声"
  },
  CollectionHall_99684_Desc = {
    Text = "食屍鬼に変わり始めてから七日目、彼は四肢が日々腐敗していく激痛にうめいていた。微細な動き一つ一つが敏感な神経を引き裂くような痛みを引き起こし……そして戦慄するような啓示の閃き。\nしかし、恐怖の影はこの芸術家を常に覆っていた——どんな筆があれば、最も極致の真実を描けるのか？\nピックマンは弱った目で周囲を探し、邸宅の脇の煉瓦から墓の上の枝まで、ついに彼の萎縮し腐敗した右脚の露出した白骨に目を留めた。\n何か神聖な呼び声を聞いたかのように、ピックマンは脚の骨を取り出し、指先で粘着した血肉を何度も磨き、硬い筆に仕立てた。\n彼は筆先を鋭い牙のように磨いたが、筆先がキャンバスに噛みつく前に、まず主人の痩せた指先に刺さった。ピックマンは痛みに手を離し、筆は彼の制御を逃れた。\n飛び跳ね！跳躍！回転！それはキャンバス上で狂舞し、錯乱した異次元級の線を刻んだ。線は増殖し、膨張し続ける奇怪な暗色の汚れを引きずり、ゆっくりと確実にピックマンの喉を噛み砕いた。\n瞬間の狂喜が彼の残された心臓を鋭く貫いた——その膨れ上がった器官、混沌とした形態は彼を震え上がらせたが、同時に枯れかけた感覚を蘇らせた。それらは逆転した無秩序な方法で、直接的で鋭く痛み、怪異、欲望を示し、隠すことのない衝撃的な力を爆発させた。\nこの倒錯の中で、ピックマンは「美」の聖域により近づいたかのようだった。\nすべてが静まった後、ピックマンは腐食した爪を伸ばし、その白い筆を何度も撫でた。このまだ人形を保つ躯殻の中から、より熱く、より切実な渇望が噴き出した。\n彼はこの筆と共に、その世紀の大作の最後の一筆を完成させるだろう。"
  },
  CollectionHall_99684_Title = {
    Text = "渇望の筆"
  },
  CollectionHall_99687_Desc = {
    Text = "「神子は灯を持つ者に見守られ、生まれながらにしてその恩恵を受ける。」\n「神子はその意志を広め、光を信仰深い義人に授けるべきである。」\n「神子は魂の清浄を保つべきである。」\n「神子は俗欲を断ち、信仰を修行し、全心で光に仕えるべきである。」\n「神子は多言を慎み、妄言を慎むべきである。」\n「神子は罪を遠ざけ、罪ある者を遠ざけ、汚れた魂に汚されてはならない。」\n「神子……」\n彼が記憶を持つようになってから、戒律の一つ一つが鎖のように彼を縛り、彼を尊崇の高台に捧げ、失礼を許さず、頭を下げることを許さず、喜怒を放縦することを許さなかった。\n彼は広大で華麗な衣をまとい、無数の従者に囲まれ、要求に従ってその神聖な代表を演じ、信仰深い信者がひれ伏し、慎重に彼の衣の裾に口づけるのを見下ろした。\n神子は本来そうあるべきであり、その高慢で変わらない顔の下にどんな感情や好みがあるかを気にする者はいなかった。\n彼はその高慢な笑顔に慣れ、人がいない時でも自分がどんな表情をしたいのか分からなかった。\n「神子ポリュクス、あなたは祝福の儀式に向かうべきです。」頭を垂れた侍女が彼の変わらない生活を敬意を持って手配した。\n彼は振り返り、頭を上げ、同じく変わらない笑顔を見せた。それはまるで自ら神聖な仮面をかぶるようだった。\nその仮面の下には、迷い、虚無、孤独が隠されており、まるで存在しなかったかのようだった。"
  },
  CollectionHall_99687_Title = {
    Text = "神子の尊顔"
  },
  CollectionHall_99691_Desc = {
    Text = "物語には魔法がある——と以前フランシスはリリーに教えた。\n\nそのとき、彼女は窓際に座って物語の本を抱えていた。\n初夏の陽光が白衣を少し温め、柔らかで優しい、心地よい香りを放っていた。\n\n彼女は穏やかな調子で、物語をゆっくりと語っていた。\n\nしかし、昨夜の手術で長時間集中し続けた疲労の蓄積がたたり物語が終わる前にフランシスは深く眠りについてしまった。\n\nリリーはそれで母を責めたことはない。\n窓枠に寄りかかって疲れて眠る母の寝顔は、とても安心感を与えてくれたからだ。\n\n\n——今やフィルムが本に代わり物語と魔法を運んでいる。\n\nそれは、子供たちの不注意で、露光して壊れたフィルムを新しく代えるように……\n新しい仲間たちのはしゃぎ声がかつての暖かさと痛みが入り混じった、短い休息の時間に取って代わる。\n\nしかし、埋もれた記憶は、露光したフィルムのように、誰も知らない片隅で眠り続けている。\n\nたとえ永遠に光が当たらずともずっと、輝きを放ち続ける。"
  },
  CollectionHall_99691_Title = {
    Text = "35mmの魔法"
  }
